    'class PackLayout(QW.QLayout):\n'
    '    """Ordered edge packing, including mixed top/bottom/left/right children."""\n'
    '    def __init__(self, parent):\n'
    '        super().__init__(parent)\n'
    '        self.entries = []\n'
    '        self.setContentsMargins(2, 2, 2, 2)\n'
    '    def addItem(self, item): self.entries.append((item, {}))\n'
    '    def addPacked(self, widget, options):\n'
    '        self.addChildWidget(widget)\n'
    '        item = QW.QWidgetItem(widget)\n'
    "        before = options.get('before')\n"
    '        index = next((i for i, (it, _) in enumerate(self.entries) if before and it.widget() is before.q), len(self.entries))\n'
    '        self.entries.insert(index, (item, options))\n'
    '        self.invalidate()\n'
    '    def count(self): return len(self.entries)\n'
    '    def itemAt(self, i): return self.entries[i][0] if 0 <= i < self.count() else None\n'
    '    def takeAt(self, i): return self.entries.pop(i)[0] if 0 <= i < self.count() else None\n'
    '    def sizeHint(self):\n'
    '        w = h = 0\n'
    '        for item, opt in self.entries:\n'
    '            s = item.sizeHint()\n'
    "            if opt.get('side', 'top') in ('left', 'right'):\n"
    '                w += s.width() + 4; h = max(h, s.height() + 4)\n'
    '            else:\n'
    '                w = max(w, s.width() + 4); h += s.height() + 4\n'
    '        return QC.QSize(max(80, w), max(30, h))\n'
    '    def minimumSize(self): return QC.QSize(80, 30)\n'
    '    def setGeometry(self, rect):\n'
    '        super().setGeometry(rect)\n'
    '        r = QC.QRect(rect).marginsRemoved(self.contentsMargins())\n'
    '        def pad(v): return sum(v) if isinstance(v, (tuple, list)) else 2 * int(v or 0)\n'
    '        for index, (item, opt) in enumerate(self.entries):\n'
    "            side = opt.get('side', 'top'); horiz = side in ('left', 'right')\n"
    "            s = item.sizeHint(); px = pad(opt.get('padx', 0)); py = pad(opt.get('pady', 0))\n"
    '            future = self.entries[index + 1:]\n'
    "            reserve = sum((it.sizeHint().width() + pad(o.get('padx', 0)) if horiz else it.sizeHint().height() + pad(o.get('pady', 0))) for it,o in future if (o.get('side','top') in ('left','right')) == horiz and not o.get('expand'))\n"
    "            expands = 1 + sum(bool(o.get('expand')) for _,o in future if (o.get('side','top') in ('left','right')) == horiz)\n"
    '            available = r.width() if horiz else r.height()\n'
    '            desired = s.width() + px if horiz else s.height() + py\n'
    "            extent = max(1, (available - reserve) // expands) if opt.get('expand') else min(max(1, desired), max(1, available))\n"
    '            if horiz:\n'
    "                box = QC.QRect(r.left() if side == 'left' else r.right()-extent+1, r.top(), extent, r.height())\n"
    "                if side == 'left': r.setLeft(r.left()+extent)\n"
    '                else: r.setRight(r.right()-extent)\n'
    '            else:\n'
    "                box = QC.QRect(r.left(), r.top() if side == 'top' else r.bottom()-extent+1, r.width(), extent)\n"
    "                if side == 'top': r.setTop(r.top()+extent)\n"
    '                else: r.setBottom(r.bottom()-extent)\n'
    '            box.adjust(px//2, py//2, -(px-px//2), -(py-py//2))\n'
    "            fill = opt.get('fill', '')\n"
    "            if fill not in ('x','both'): box.setWidth(min(box.width(), max(1,s.width())))\n"
    "            if fill not in ('y','both'): box.setHeight(min(box.height(), max(1,s.height())))\n"
    '            item.setGeometry(box)\n'
