    '\n'
    'def ascii_sentence_type(line: str) -> str:\n'
    '    text = str(line or "").strip()\n'
    '    if not text:\n'
    '        return ""\n'
    '    if text.startswith("$"):\n'
    '        body = text.split("*", 1)[0]\n'
    '        fields = body.split(",")\n'
    '        header = fields[0].lstrip("$").upper()\n'
    '        if len(header) >= 5:\n'
    '            return header\n'
    '        return header or "NMEA"\n'
    '    first = re.split(r"[,\\s]+", text, maxsplit=1)[0].strip().upper()\n'
    '    cleaned = re.sub(r"[^A-Z0-9_./:-]+", "", first)\n'
    '    if not cleaned:\n'
    '        return "NON_NMEA"\n'
    '    if re.fullmatch(r"[-+]?\\d+(?:\\.\\d+)?", cleaned):\n'
    '        return "PLAIN_DEPTH"\n'
    '    return cleaned[:32]\n'
