    '            try:\n'
    '                candidates.extend([item for item in root.iterdir() if item.is_dir()])\n'
    '            except Exception:\n'
    '                pass\n'
    '        for candidate in candidates:\n'
    '            try:\n'
    '                if not candidate.exists() or not candidate.is_dir():\n'
    '                    continue\n'
    '                has_project_shape = any((candidate / name).exists() for name in PROJECT_SUBFOLDERS) or any(candidate.glob("*.json"))\n'
    '                if candidate == DEFAULT_PROJECT_FOLDER or has_project_shape:\n'
    '                    key = str(candidate.resolve()).lower()\n'
    '                    if key not in seen:\n'
    '                        seen.add(key)\n'
    '                        found.append(str(candidate))\n'
    '            except Exception:\n'
    '                continue\n'
    '    return found\n'
    '\n'
    '\n'
    'GRID_FILE_EXTENSIONS = (".grd", ".grid", ".gtx", ".gsb", ".ktd", ".csv", ".xyz", ".brd", ".lnw", ".dxf", ".dwg", ".000", ".enc", ".s57", ".kmz", ".kml")\n'
    '\n'
    '\n'
    'def discover_grid_options(project_folder: str | Path | None = None) -> list[str]:\n'
    '    """Find available grid/background/support files in the selected project and common project folders."""\n'
    '    roots = []\n'
    '    if project_folder:\n'
    '        roots.append(project_root_from_raw_folder(project_folder))\n'
    '    roots.extend(Path(item) for item in discover_project_options())\n'
    '    roots.extend([APP_DIR, Path(r"C:\\HYPACK 2018\\Projects")])\n'
    '    found: list[str] = []\n'
    '    seen: set[str] = set()\n'
    '    for root in roots:\n'
    '        try:\n'
    '            if not root.exists() or not root.is_dir():\n'
    '                continue\n'
    '            for item in root.rglob("*"):\n'
    '                if not item.is_file() or item.suffix.lower() not in GRID_FILE_EXTENSIONS:\n'
    '                    continue\n'
    '                key = str(item.resolve()).lower()\n'
