    '\n'
    '\n'
    'class CardinalPoint(str, Enum):\n'
    '    NORTH = "N"\n'
    '    SOUTH = "S"\n'
    '    EAST = "E"\n'
    '    WEST = "W"\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class Satellite:\n'
    '    prn: Optional[int] = None\n'
    '    elevation: Optional[int] = None\n'
    '    azimuth: Optional[int] = None\n'
    '    signal_to_noise_ratio: Optional[int] = None\n'
    '    satellite_type: str = "GPS"\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class GPSPosition:\n'
    '    latitude: Optional[float] = None\n'
    '    longitude: Optional[float] = None\n'
    '    altitude_m: Optional[float] = None\n'
    '    speed_knots: Optional[float] = None\n'
    '    course_degrees: Optional[float] = None\n'
    '    heading_degrees: Optional[float] = None\n'
    '    altitude_m: Optional[float] = None\n'
    '    ktd_cell_k: Optional[float] = None\n'
    '    rtk_reduced_height: Optional[float] = None\n'
    '    rtk_reduced_depth: Optional[float] = None\n'
