    '    mode1: Optional[str] = None\n'
    '    mode2: Optional[str] = None\n'
    '    raw_sentences: list[str] = field(default_factory=list)\n'
    '\n'
    '    @property\n'
    '    def is_fix(self) -> bool:\n'
    '        if self.fix_quality is not None:\n'
    '            return self.fix_quality > 0\n'
    '        if self.mode2 is not None:\n'
    '            return self.mode2.upper() in {"A", "D", "E", "F", "R"}\n'
    '        return self.latitude is not None and self.longitude is not None\n'
    '\n'
    '    @property\n'
    '    def speed_kmh(self) -> Optional[float]:\n'
    '        return knots_to_kmh(self.speed_knots) if self.speed_knots is not None else None\n'
    '\n'
    '    def latitude_dms(self) -> Optional[tuple[int, int, float, CardinalPoint]]:\n'
    '        if self.latitude is None:\n'
    '            return None\n'
    '        return decimal_degrees_to_dms(self.latitude, CardinalPoint.NORTH, CardinalPoint.SOUTH)\n'
    '\n'
    '    def longitude_dms(self) -> Optional[tuple[int, int, float, CardinalPoint]]:\n'
    '        if self.longitude is None:\n'
    '            return None\n'
    '        return decimal_degrees_to_dms(self.longitude, CardinalPoint.EAST, CardinalPoint.WEST)\n'
    '\n'
    '    def distance_to_km(self, other: "GPSPosition") -> Optional[float]:\n'
    '        if None in (self.latitude, self.longitude, other.latitude, other.longitude):\n'
    '            return None\n'
    '        return distance_km(self.latitude, self.longitude, other.latitude, other.longitude)\n'
    '\n'
    '    def bearing_to(self, other: "GPSPosition") -> Optional[float]:\n'
    '        if None in (self.latitude, self.longitude, other.latitude, other.longitude):\n'
    '            return None\n'
    '        return bearing_degrees(self.latitude, self.longitude, other.latitude, other.longitude)\n'
    '\n'
    '    def clone(self) -> "GPSPosition":\n'
    '        copied = GPSPosition(**{key: value for key, value in self.__dict__.items() if key != "raw_sentences"})\n'
    '        copied.raw_sentences = list(self.raw_sentences)\n'
    '        return copied\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class Offsets:\n'
    '    antenna_x: float = 0.0\n'
    '    antenna_y: float = 0.0\n'
    '    antenna_z: float = 0.0\n'
    '    transducer_x: float = 0.0\n'
    '    transducer_y: float = 0.0\n'
    '    transducer_z: float = 0.0\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class SoundVelocityProfile:\n'
    '    default_velocity_mps: float = DEFAULT_SOUND_SPEED\n'
    '    source_file: Optional[str] = None\n'
    '    points: list[tuple[float, float]] = field(default_factory=list)\n'
    '\n'
    '    def velocity_at_depth(self, depth_m: float) -> float:\n'
    '        if not self.points:\n'
    '            return self.default_velocity_mps\n'
    '        points = sorted((float(depth), float(velocity)) for depth, velocity in self.points)\n'
    '        if depth_m <= points[0][0]:\n'
    '            return points[0][1]\n'
    '        if depth_m >= points[-1][0]:\n'
    '            return points[-1][1]\n'
    '        for (d1, v1), (d2, v2) in zip(points, points[1:]):\n'
    '            if d1 <= depth_m <= d2:\n'
    '                ratio = 0.0 if d2 == d1 else (depth_m - d1) / (d2 - d1)\n'
    '                return v1 + ratio * (v2 - v1)\n'
    '        return self.default_velocity_mps\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class BathymetrySample:\n'
    '    x: float\n'
    '    y: float\n'
    '    depth: float\n'
    '    time_utc: Optional[str] = None\n'
    '    tide: float = 0.0\n'
    '    draft: float = 0.0\n'
    '    sound_velocity_mps: Optional[float] = None\n'
    '    corrected_depth: Optional[float] = None\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class MapShape:\n'
    '    kind: str\n'
    '    points: list[tuple[float, float]]\n'
    '    text: str = ""\n'
    '    color: str = "#1f2937"\n'
    '    width: int = 2\n'
    '    attrs: dict[str, object] = field(default_factory=dict)\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class HydroProject:\n'
    '    name: str = "SurveyPlan Project"\n'
    '    offsets: Offsets = field(default_factory=Offsets)\n'
    '    svp: SoundVelocityProfile = field(default_factory=SoundVelocityProfile)\n'
    '    shapes: list[MapShape] = field(default_factory=list)\n'
    '    bathymetry: list[BathymetrySample] = field(default_factory=list)\n'
    '\n'
    '    def to_dict(self) -> dict[str, object]:\n'
    '        return {\n'
    '            "name": self.name,\n'
    '            "offsets": self.offsets.__dict__,\n'
    '            "svp": {\n'
    '                "default_velocity_mps": self.svp.default_velocity_mps,\n'
    '                "source_file": self.svp.source_file,\n'
    '                "points": self.svp.points,\n'
    '            },\n'
    '            "shapes": [shape.__dict__ for shape in self.shapes],\n'
    '            "bathymetry": [sample.__dict__ for sample in self.bathymetry],\n'
    '        }\n'
    '\n'
    '    @classmethod\n'
    '    def from_dict(cls, payload: dict[str, object]) -> "HydroProject":\n'
    '        offsets = Offsets(**dict(payload.get("offsets", {})))\n'
    '        svp_payload = dict(payload.get("svp", {}))\n'
    '        svp = SoundVelocityProfile(\n'
    '            default_velocity_mps=float(svp_payload.get("default_velocity_mps", DEFAULT_SOUND_SPEED)),\n'
    '            source_file=svp_payload.get("source_file"),\n'
    '            points=[tuple(point) for point in svp_payload.get("points", [])],\n'
    '        )\n'
    '        shapes = [\n'
    '            MapShape(\n'
    '                kind=item.get("kind", "line"),\n'
    '                points=[tuple(point) for point in item.get("points", [])],\n'
    '                text=item.get("text", ""),\n'
    '                color=item.get("color", "#1f2937"),\n'
    '                width=int(item.get("width", 2)),\n'
    '                attrs=dict(item.get("attrs", {})),\n'
    '            )\n'
    '            for item in payload.get("shapes", [])\n'
    '        ]\n'
    '        bathymetry = [BathymetrySample(**item) for item in payload.get("bathymetry", [])]\n'
    '        return cls(\n'
    '            name=str(payload.get("name", "SurveyPlan Project")),\n'
    '            offsets=offsets,\n'
    '            svp=svp,\n'
    '            shapes=shapes,\n'
    '            bathymetry=bathymetry,\n'
    '        )\n'
    '\n'
    '\n'
    'def _direction_sign(direction: CardinalPoint | str) -> int:\n'
    '    value = CardinalPoint(str(direction).upper())\n'
    '    return -1 if value in (CardinalPoint.SOUTH, CardinalPoint.WEST) else 1\n'
    '\n'
    '\n'
    'def float_mod(value: float, modulus: float) -> float:\n'
    '    return value - floor(value / modulus) * modulus\n'
    '\n'
    '\n'
    'def dms_to_decimal_degrees(\n'
    '    degrees_value: int,\n'
    '    minutes: int,\n'
    '    seconds: float,\n'
    '    direction: CardinalPoint | str,\n'
    ') -> float:\n'
    '    return _direction_sign(direction) * (abs(degrees_value) + minutes / 60.0 + seconds / 3600.0)\n'
    '\n'
    '\n'
    'def dm_to_dms(dm_value: float) -> tuple[int, int, float]:\n'
    '    degrees_value = int(abs(dm_value) // 100)\n'
    '    minute_value = abs(dm_value) - degrees_value * 100\n'
    '    minutes = int(minute_value)\n'
    '    seconds = (minute_value - minutes) * 60.0\n'
    '    return degrees_value, minutes, seconds\n'
    '\n'
    '\n'
    'def dms_to_dm(degrees_value: int, minutes: int, seconds: float) -> float:\n'
    '    return abs(degrees_value) * 100.0 + minutes + seconds / 60.0\n'
    '\n'
    '\n'
    'def decimal_degrees_to_dms(\n'
    '    value: float,\n'
    '    positive_direction: CardinalPoint,\n'
    '    negative_direction: CardinalPoint,\n'
    ') -> tuple[int, int, float, CardinalPoint]:\n'
    '    direction = positive_direction if value >= 0 else negative_direction\n'
    '    value = abs(value)\n'
    '    degrees_value = int(value)\n'
    '    minute_float = (value - degrees_value) * 60.0\n'
    '    minutes = int(minute_float)\n'
    '    seconds = (minute_float - minutes) * 60.0\n'
    '    return degrees_value, minutes, seconds, direction\n'
    '\n'
    '\n'
    'def knots_to_kmh(value: float) -> float:\n'
    '    return value * 1.852\n'
    '\n'
    '\n'
    'def kmh_to_knots(value: float) -> float:\n'
    '    return value / 1.852\n'
    '\n'
    '\n'
    'def km_to_nautical_miles(value: float) -> float:\n'
    '    return value / 1.852\n'
    '\n'
    '\n'
    'def nautical_miles_to_km(value: float) -> float:\n'
    '    return value * 1.852\n'
    '\n'
    '\n'
    'def meters_to_feet(value: float) -> float:\n'
    '    return value * 3.28083989501312\n'
    '\n'
    '\n'
    'def feet_to_meters(value: float) -> float:\n'
    '    return value / 3.28083989501312\n'
    '\n'
    '\n'
    'def distance_km(lat1: float, lon1: float, lat2: float, lon2: float) -> float:\n'
    '    phi1 = radians(lat1)\n'
    '    phi2 = radians(lat2)\n'
    '    d_phi = radians(lat2 - lat1)\n'
    '    d_lambda = radians(lon2 - lon1)\n'
    '    a = sin(d_phi / 2.0) ** 2 + cos(phi1) * cos(phi2) * sin(d_lambda / 2.0) ** 2\n'
    '    return 2.0 * EARTH_RADIUS_KM * atan2(sqrt(a), sqrt(1.0 - a))\n'
    '\n'
    '\n'
    'def bearing_degrees(lat1: float, lon1: float, lat2: float, lon2: float) -> float:\n'
    '    phi1 = radians(lat1)\n'
    '    phi2 = radians(lat2)\n'
    '    d_lambda = radians(lon2 - lon1)\n'
    '    y = sin(d_lambda) * cos(phi2)\n'
    '    x = cos(phi1) * sin(phi2) - sin(phi1) * cos(phi2) * cos(d_lambda)\n'
    '    return (degrees(atan2(y, x)) + 360.0) % 360.0\n'
    '\n'
    '\n'
    'def make_utc_datetime(\n'
    '    date_value: Optional[tuple[int, int, int]],\n'
    '    time_value: Optional[tuple[int, int, float]],\n'
    ') -> Optional[datetime]:\n'
    '    if date_value is None or time_value is None:\n'
    '        return None\n'
    '    day, month, year = date_value\n'
    '    hour, minute, second_float = time_value\n'
    '    second = int(second_float)\n'
    '    microsecond = int(round((second_float - second) * 1_000_000))\n'
    '    return datetime(year, month, day, hour, minute, second, microsecond, tzinfo=timezone.utc)\n'
    '\n'
    '\n'
    'def correct_depth(\n'
    '    raw_depth_m: float,\n'
    '    draft_m: float = 0.0,\n'
    '    tide_m: float = 0.0,\n'
    '    measured_velocity_mps: Optional[float] = None,\n'
    '    profile_velocity_mps: float = DEFAULT_SOUND_SPEED,\n'
    '    reference_velocity_mps: float = DEFAULT_SOUND_SPEED,\n'
    ') -> float:\n'
    '    velocity = measured_velocity_mps or profile_velocity_mps or reference_velocity_mps\n'
    '    velocity_scale = velocity / reference_velocity_mps if reference_velocity_mps else 1.0\n'
    '    return raw_depth_m * velocity_scale + draft_m - tide_m\n'
    '\n'
    '\n'
    'def process_bathymetry_samples(samples: list[BathymetrySample], svp: SoundVelocityProfile) -> list[BathymetrySample]:\n'
    '    processed: list[BathymetrySample] = []\n'
    '    for sample in samples:\n'
    '        velocity = sample.sound_velocity_mps or svp.velocity_at_depth(sample.depth)\n'
    '        processed.append(\n'
    '            BathymetrySample(\n'
    '                x=sample.x,\n'
    '                y=sample.y,\n'
    '                depth=sample.depth,\n'
    '                time_utc=sample.time_utc,\n'
    '                tide=sample.tide,\n'
    '                draft=sample.draft,\n'
    '                sound_velocity_mps=velocity,\n'
    '                corrected_depth=correct_depth(\n'
    '                    sample.depth,\n'
    '                    draft_m=sample.draft,\n'
    '                    tide_m=sample.tide,\n'
    '                    measured_velocity_mps=velocity,\n'
    '                ),\n'
    '            )\n'
    '        )\n'
    '    return processed\n'
    '\n'
    '\n'
    'def save_project(path: str | Path, project: HydroProject) -> None:\n'
    '    Path(path).write_text(json.dumps(project.to_dict(), indent=2), encoding="utf-8")\n'
    '\n'
    '\n'
    'def load_project(path: str | Path) -> HydroProject:\n'
    '    return HydroProject.from_dict(json.loads(Path(path).read_text(encoding="utf-8")))\n'
    '\n'
    '\n'
    'def _strip_sentence(sentence: str) -> str:\n'
    '    return sentence.strip().lstrip("$!")\n'
    '\n'
    '\n'
    'def nmea_checksum(sentence: str) -> int:\n'
    '    body = _strip_sentence(sentence).split("*", 1)[0]\n'
    '    value = 0\n'
    '    for char in body:\n'
    '        value ^= ord(char)\n'
    '    return value\n'
    '\n'
    '\n'
    'def nmea_checksum_str(sentence: str) -> str:\n'
    '    return f"{nmea_checksum(sentence):02X}"\n'
    '\n'
    '\n'
    'def add_nmea_checksum(sentence: str, terminator: bool = True) -> str:\n'
    '    body = _strip_sentence(sentence).split("*", 1)[0]\n'
    '    result = f"${body}*{nmea_checksum(body):02X}"\n'
    '    return result + ("\\r\\n" if terminator else "")\n'
    '\n'
    '\n'
    'def is_nmea_checksum_ok(sentence: str) -> bool:\n'
    '    if "*" not in sentence:\n'
    '        return True\n'
    '    body, given = sentence.strip().rsplit("*", 1)\n'
    '    return nmea_checksum_str(body) == given[:2].upper()\n'
    '\n'
    '\n'
    'def extract_nmea_sentences(raw: str) -> list[str]:\n'
    '    return [match.group(0).strip() for match in NMEA_RE.finditer(raw)]\n'
    '\n'
    '\n'
    'def legacy_float(value: str) -> Optional[float]:\n'
    '    if value == "":\n'
    '        return None\n'
    '    try:\n'
    '        return float(value)\n'
    '    except ValueError:\n'
    '        return None\n'
    '\n'
    '\n'
    'def legacy_int(value: str) -> Optional[int]:\n'
    '    if value == "":\n'
    '        return None\n'
    '    try:\n'
    '        return int(value)\n'
    '    except ValueError:\n'
    '        return None\n'
    '\n'
    '\n'
    'def parse_legacy_coord(value: str, direction: str) -> Optional[float]:\n'
    '    raw = legacy_float(value)\n'
    '    if raw is None or not direction:\n'
    '        return None\n'
    '    degrees_value = int(raw // 100)\n'
    '    minutes = raw - degrees_value * 100\n'
    '    decimal = degrees_value + minutes / 60.0\n'
    '    return -decimal if direction.upper() in {"S", "W"} else decimal\n'
    '\n'
    '\n'
    'def parse_utc_time(value: str) -> Optional[tuple[int, int, float]]:\n'
    '    if not value or len(value.strip()) < 6:\n'
    '        return None\n'
    '    value = value.strip()\n'
    '    try:\n'
    '        return int(value[0:2]), int(value[2:4]), float(value[4:])\n'
    '    except ValueError:\n'
    '        return None\n'
    '\n'
    '\n'
    'def parse_utc_date(value: str) -> Optional[tuple[int, int, int]]:\n'
    '    if not value or len(value) != 6:\n'
    '        return None\n'
    '    try:\n'
    '        day = int(value[0:2])\n'
    '        month = int(value[2:4])\n'
    '        year = int(value[4:6])\n'
    '    except ValueError:\n'
    '        return None\n'
    '    year += 2000 if year < 80 else 1900\n'
    '    return day, month, year\n'
    '\n'
    '\n'
    'def nmea_fields(sentence: str) -> tuple[str, list[str]]:\n'
    '    body = _strip_sentence(sentence).split("*", 1)[0]\n'
    '    parts = body.split(",")\n'
    '    return parts[0].upper(), parts[1:]\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class NMEAParser:\n'
    '    position: GPSPosition = field(default_factory=GPSPosition)\n'
    '    satellites: list[Satellite] = field(default_factory=list)\n'
    '    track: list[GPSPosition] = field(default_factory=list)\n'
    '\n'
    '    def parse(self, sentence: str) -> Optional[GPSPosition]:\n'
    '        if not is_nmea_checksum_ok(sentence):\n'
    '            return None\n'
    '        command, fields = nmea_fields(sentence)\n'
    '        handler = getattr(self, f"_parse_{command[-3:].lower()}", None)\n'
    '        if handler is None:\n'
    '            return None\n'
    '        before = self.position.clone()\n'
    '        result = handler(fields)\n'
    '        if result and self.position.latitude is not None and self.position.longitude is not None:\n'
    '            self.position.raw_sentences.append(sentence.strip())\n'
    '            if (\n'
    '                before.latitude != self.position.latitude\n'
    '                or before.longitude != self.position.longitude\n'
    '                or before.utc_datetime != self.position.utc_datetime\n'
    '            ):\n'
    '                self.track.append(self.position.clone())\n'
    '        return self.position if result else None\n'
    '\n'
    '    def feed(self, raw: str) -> list[GPSPosition]:\n'
    '        results: list[GPSPosition] = []\n'
    '        for sentence in extract_nmea_sentences(raw):\n'
    '            parsed = self.parse(sentence)\n'
    '            if parsed is not None:\n'
    '                results.append(parsed.clone())\n'
    '        return results\n'
    '\n'
    '    def _parse_gga(self, fields: list[str]) -> bool:\n'
    '        if len(fields) < 9:\n'
    '            return False\n'
    '        time_value = parse_utc_time(fields[0])\n'
    '        lat = parse_legacy_coord(fields[1], fields[2])\n'
    '        lon = parse_legacy_coord(fields[3], fields[4])\n'
    '        if lat is not None:\n'
    '            self.position.latitude = lat\n'
    '        if lon is not None:\n'
    '            self.position.longitude = lon\n'
    '        self.position.fix_quality = legacy_int(fields[5])\n'
    '        self.position.satellites_used = legacy_int(fields[6])\n'
    '        self.position.hdop = legacy_float(fields[7])\n'
    '        self.position.altitude_m = legacy_float(fields[8])\n'
    '        if len(fields) > 10:\n'
    '            self.position.geo_height_m = legacy_float(fields[10])\n'
    '        if time_value and self.position.utc_datetime:\n'
    '            old = self.position.utc_datetime\n'
    '            self.position.utc_datetime = make_utc_datetime((old.day, old.month, old.year), time_value)\n'
    '        return True\n'
    '\n'
    '    def _parse_rmc(self, fields: list[str]) -> bool:\n'
    '        if len(fields) < 9:\n'
    '            return False\n'
    '        time_value = parse_utc_time(fields[0])\n'
    '        self.position.mode2 = fields[1] or None\n'
    '        lat = parse_legacy_coord(fields[2], fields[3])\n'
    '        lon = parse_legacy_coord(fields[4], fields[5])\n'
    '        if lat is not None:\n'
    '            self.position.latitude = lat\n'
    '        if lon is not None:\n'
    '            self.position.longitude = lon\n'
    '        self.position.speed_knots = legacy_float(fields[6])\n'
    '        self.position.course_degrees = legacy_float(fields[7])\n'
    '        self.position.utc_datetime = make_utc_datetime(parse_utc_date(fields[8]), time_value) or self.position.utc_datetime\n'
    '        return True\n'
    '\n'
    '    def _parse_gll(self, fields: list[str]) -> bool:\n'
    '        if len(fields) < 5:\n'
    '            return False\n'
    '        lat = parse_legacy_coord(fields[0], fields[1])\n'
    '        lon = parse_legacy_coord(fields[2], fields[3])\n'
    '        if lat is not None:\n'
    '            self.position.latitude = lat\n'
    '        if lon is not None:\n'
    '            self.position.longitude = lon\n'
    '        self.position.mode2 = fields[5] if len(fields) > 5 and fields[5] else fields[4] or None\n'
    '        return True\n'
    '\n'
    '    def _parse_vtg(self, fields: list[str]) -> bool:\n'
    '        if len(fields) < 7:\n'
    '            return False\n'
    '        self.position.course_degrees = legacy_float(fields[0])\n'
    '        self.position.speed_knots = legacy_float(fields[4])\n'
    '        speed_kmh = legacy_float(fields[6])\n'
    '        if self.position.speed_knots is None and speed_kmh is not None:\n'
    '            self.position.speed_knots = kmh_to_knots(speed_kmh)\n'
    '        return True\n'
    '\n'
    '    def _parse_gsa(self, fields: list[str]) -> bool:\n'
    '        if len(fields) < 15:\n'
    '            return False\n'
    '        self.position.mode1 = fields[0] or None\n'
    '        self.position.mode2 = fields[1] or None\n'
    '        self.position.pdop = legacy_float(fields[14]) if len(fields) > 14 else None\n'
    '        self.position.hdop = legacy_float(fields[15]) if len(fields) > 15 else self.position.hdop\n'
    '        self.position.vdop = legacy_float(fields[16]) if len(fields) > 16 else self.position.vdop\n'
    '        return True\n'
    '\n'
    '    def _parse_gsv(self, fields: list[str]) -> bool:\n'
    '        if len(fields) < 3:\n'
    '            return False\n'
    '        total = legacy_int(fields[2])\n'
    '        if total == 0:\n'
    '            self.satellites.clear()\n'
    '        for index in range(3, len(fields), 4):\n'
    '            chunk = fields[index : index + 4]\n'
    '            if len(chunk) < 4:\n'
    '                continue\n'
    '            self.satellites.append(\n'
    '                Satellite(\n'
    '                    prn=legacy_int(chunk[0]),\n'
    '                    elevation=legacy_int(chunk[1]),\n'
    '                    azimuth=legacy_int(chunk[2]),\n'
    '                    signal_to_noise_ratio=legacy_int(chunk[3]),\n'
    '                )\n'
    '            )\n'
    '        return True\n'
    '\n'
    '\n'
    'def export_gpx(track: Iterable[GPSPosition], path: str | Path, name: str = "SurveyPlan Track") -> None:\n'
    '    lines = [\n'
    '        \'<?xml version="1.0" encoding="UTF-8"?>\',\n'
    '        \'<gpx version="1.1" creator="surveyplan" xmlns="http://www.topografix.com/GPX/1/1">\',\n'
    '        "  <trk>",\n'
    '        f"    <name>{escape(name)}</name>",\n'
    '        "    <trkseg>",\n'
    '    ]\n'
    '    for point in track:\n'
    '        if point.latitude is None or point.longitude is None:\n'
    '            continue\n'
    '        lines.append(f\'      <trkpt lat="{point.latitude:.10f}" lon="{point.longitude:.10f}">\')\n'
    '        if point.altitude_m is not None:\n'
    '            lines.append(f"        <ele>{point.altitude_m:.3f}</ele>")\n'
    '        if isinstance(point.utc_datetime, datetime):\n'
    '            lines.append(f"        <time>{point.utc_datetime.isoformat().replace(\'+00:00\', \'Z\')}</time>")\n'
    '        lines.append("      </trkpt>")\n'
    '    lines.extend(["    </trkseg>", "  </trk>", "</gpx>", ""])\n'
    '    Path(path).write_text("\\n".join(lines), encoding="utf-8")\n'
    '\n'
    '\n'
    'def gps_position_to_dict(position: GPSPosition) -> dict[str, object]:\n'
    '    return {\n'
    '        "latitude": position.latitude,\n'
    '        "longitude": position.longitude,\n'
    '        "altitude_m": position.altitude_m,\n'
    '        "speed_knots": position.speed_knots,\n'
    '        "speed_kmh": position.speed_kmh,\n'
    '        "course_degrees": position.course_degrees,\n'
    '        "heading_degrees": position.heading_degrees,\n'
    '        "hdop": position.hdop,\n'
    '        "vdop": position.vdop,\n'
    '        "pdop": position.pdop,\n'
    '        "fix_quality": position.fix_quality,\n'
    '        "satellites_used": position.satellites_used,\n'
    '        "is_fix": position.is_fix,\n'
    '        "utc_datetime": position.utc_datetime.isoformat() if position.utc_datetime else None,\n'
    '    }\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class SerialSettings:\n'
    '    title: str\n'
    '    port: str = "COM1"\n'
    '    baud_rate: int = 4800\n'
    '    data_width: int = 8\n'
    '    stop_bits: float = 1.0\n'
    '    parity: str = "None"\n'
    '    nmea_log: str = ""\n'
    '    enabled: bool = True\n'
    '    recording_rate_hz: float = 1.0\n'
    '    sentence_options: list[str] = field(default_factory=list)\n'
    '    selected_sentences: list[str] = field(default_factory=list)\n'
    '\n'
    '    def to_dict(self) -> dict[str, object]:\n'
    '        return {\n'
    '            "title": self.title,\n'
    '            "port": self.port,\n'
    '            "baud_rate": self.baud_rate,\n'
    '            "data_width": self.data_width,\n'
    '            "stop_bits": self.stop_bits,\n'
    '            "parity": self.parity,\n'
    '            "nmea_log": self.nmea_log,\n'
    '            "enabled": self.enabled,\n'
    '            "recording_rate_hz": self.recording_rate_hz,\n'
    '            "sentence_options": list(self.sentence_options),\n'
    '            "selected_sentences": list(self.selected_sentences),\n'
    '        }\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class SensorSettings(SerialSettings):\n'
    '    sbes_message: str = "NMEA DPT"\n'
    '    sbes_format: str = "DPT"\n'
    '\n'
    '    def to_dict(self) -> dict[str, object]:\n'
    '        data = super().to_dict()\n'
    '        data.update({"sbes_message": self.sbes_message, "sbes_format": self.sbes_format})\n'
    '        return data\n'
    '\n'
    '\n'
    'RTK_TIDE_METHODS = [\n'
    '    "Not using RTK tide",\n'
    '    "(K-N) from KTD file",\n'
    '    "N from geoid model, K from KTD file",\n'
    '    "N from geoid model, K from VDatum",\n'
    '    "N from geoid model, K from user value",\n'
    '    "(K-N) from user value",\n'
    ']\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class GeodeticSettings:\n'
    '    use_projection: bool = True\n'
    '    use_tm_projection: bool = True\n'
    '    use_lcc_projection: bool = False\n'
    '    projection_name: str = "WGS84 / UTM Zone 42"\n'
    '    datum_name: str = "WGS84"\n'
    '    ellipsoid: str = "WGS84"\n'
    '    utm_zone: str = "42"\n'
    '    fixed_utm_reference_zone: bool = False\n'
    '    lcc_zone: str = ""\n'
    '    central_meridian: float = 69.0\n'
    '    latitude_origin: float = 0.0\n'
    '    scale_factor: float = 0.9996\n'
    '    false_easting: float = 500000.0\n'
    '    false_northing: float = 0.0\n'
    '    selected_grid_path: str = ""\n'
    '    grid_name: str = "UTM North"\n'
    '    zone_label: str = "Zone 42(66E-72E)"\n'
    '    distance_unit: str = "Meter"\n'
    '    depth_unit: str = "same as horizontal"\n'
    '    elevation_mode_positive_up: bool = False\n'
    '    semi_major_axis: float = 6378137.0\n'
    '    flattening: float = 298.257223563\n'
    '    delta_x: float = 0.0\n'
    '    delta_y: float = 0.0\n'
    '    delta_z: float = 0.0\n'
    '    delta_rx: float = 0.0\n'
    '    delta_ry: float = 0.0\n'
    '    delta_rz: float = 0.0\n'
    '    delta_scale: float = 0.0\n'
    '    datum_shift_file: str = ""\n'
    '    projection_method: str = "Transverse Mercator"\n'
    '    reference_latitude: float = 0.0\n'
    '    local_grid_adjustment: bool = False\n'
    '    local_grid_file: str = ""\n'
    '    rtk_tide_method: str = "Not using RTK tide"\n'
    '    ellipsoidal_height_reference: float = 0.0\n'
    '    chart_datum_level: float = 0.0\n'
    '    geoid_separation_n: float = 0.0\n'
    '    ktd_k_value: float = 0.0\n'
    '    ktd_file_path: str = ""\n'
    '    geoid_model_file: str = ""\n'
    '    vdatum_zone: str = ""\n'
    '    vdatum_surface_file: str = ""\n'
    '    itrf_wgs84_epoch: str = ""\n'
    '    vdatum_k_value: float = 0.0\n'
    '    user_k_value: float = 0.0\n'
    '    user_k_minus_n: float = 0.0\n'
    '\n'
    '    def to_dict(self) -> dict[str, object]:\n'
    '        return {\n'
    '            "use_projection": self.use_projection,\n'
    '            "use_tm_projection": self.use_tm_projection,\n'
    '            "use_lcc_projection": self.use_lcc_projection,\n'
    '            "projection_name": self.projection_name,\n'
    '            "datum_name": self.datum_name,\n'
    '            "ellipsoid": self.ellipsoid,\n'
    '            "utm_zone": self.utm_zone,\n'
    '            "fixed_utm_reference_zone": self.fixed_utm_reference_zone,\n'
