    '\n'
    '@dataclass\n'
    'class AppSettings:\n'
    '    gps: SerialSettings\n'
    '    sensor: SensorSettings\n'
    '    geodetic: GeodeticSettings\n'
    '    raw_folder: str = field(default_factory=lambda: str(default_raw_folder()))\n'
    '    dxf_background_path: str = ""\n'
    '    enc_background_path: str = ""\n'
    '    kmz_background_path: str = ""\n'
    '    nav_view_scale: str = "1:200"\n'
    '    ui_font_size: int = 10\n'
    '    ui_button_font_size: int = 10\n'
    '    ui_menu_font_size: int = 10\n'
    '    ui_contrast: str = "Standard"\n'
    '    ui_color_scheme: str = "Nautical Light"\n'
    '    share_gnss_sbes_input: bool = False\n'
    '    extra_devices: list[SerialSettings] = field(default_factory=list)\n'
    '    locked: bool = False\n'
    '\n'
    '    @classmethod\n'
    '    def defaults(cls) -> "AppSettings":\n'
    '        return cls(\n'
    '            gps=SerialSettings(\n'
    '                "GNSS",\n'
    '                port="COM1",\n'
    '                baud_rate=115200,\n'
    '                data_width=8,\n'
    '                stop_bits=1,\n'
    '                parity="N",\n'
    '                nmea_log="HYDRO_GNSS.raw",\n'
    '                recording_rate_hz=1.0,\n'
    '                sentence_options=list(GNSS_SENTENCE_OPTIONS),\n'
    '                selected_sentences=list(GNSS_SENTENCE_OPTIONS),\n'
    '            ),\n'
    '            sensor=SensorSettings(\n'
    '                "SBES",\n'
    '                port="COM2",\n'
    '                baud_rate=38400,\n'
    '                data_width=8,\n'
    '                stop_bits=1,\n'
    '                parity="N",\n'
    '                nmea_log="HYDRO_SBES.raw",\n'
    '                recording_rate_hz=1.0,\n'
    '                sbes_message="NMEA DPT",\n'
    '                sbes_format="DPT",\n'
    '                sentence_options=list(SBES_SENTENCE_OPTIONS),\n'
    '                selected_sentences=["DPT", "DBT", "DBS", "DBK", "PLAIN_DEPTH"],\n'
    '            ),\n'
    '            geodetic=GeodeticSettings(),\n'
    '        )\n'
    '\n'
    '    def to_dict(self) -> dict[str, object]:\n'
    '        return {\n'
    '            "locked": self.locked,\n'
    '            "gps": self.gps.to_dict(),\n'
    '            "sensor": self.sensor.to_dict(),\n'
    '            "geodetic": self.geodetic.to_dict(),\n'
    '            "raw_folder": self.raw_folder,\n'
    '            "dxf_background_path": self.dxf_background_path,\n'
    '            "enc_background_path": self.enc_background_path,\n'
    '            "kmz_background_path": self.kmz_background_path,\n'
    '            "nav_view_scale": self.nav_view_scale,\n'
    '            "ui_font_size": self.ui_font_size,\n'
    '            "ui_button_font_size": self.ui_button_font_size,\n'
    '            "ui_menu_font_size": self.ui_menu_font_size,\n'
    '            "ui_contrast": self.ui_contrast,\n'
    '            "ui_color_scheme": self.ui_color_scheme,\n'
    '            "share_gnss_sbes_input": self.share_gnss_sbes_input,\n'
    '            "extra_devices": [device.to_dict() for device in self.extra_devices],\n'
    '        }\n'
    '\n'
    '    def save(self, path: Path) -> None:\n'
    '        path.parent.mkdir(parents=True, exist_ok=True)\n'
    '        path.write_text(json.dumps(self.to_dict(), indent=2), encoding="utf-8")\n'
    '\n'
    '    @classmethod\n'
    '    def load(cls, path: Path) -> "AppSettings":\n'
    '        data = json.loads(path.read_text(encoding="utf-8"))\n'
    '        settings = cls.defaults()\n'
    '        settings.locked = bool(data.get("locked", False))\n'
    '        settings.raw_folder = str(data.get("raw_folder", settings.raw_folder))\n'
    '        settings.dxf_background_path = str(data.get("dxf_background_path", getattr(settings, "dxf_background_path", "")) or "")\n'
    '        settings.enc_background_path = str(data.get("enc_background_path", getattr(settings, "enc_background_path", "")) or "")\n'
    '        settings.kmz_background_path = str(data.get("kmz_background_path", getattr(settings, "kmz_background_path", "")) or "")\n'
    '        settings.nav_view_scale = str(data.get("nav_view_scale", getattr(settings, "nav_view_scale", "1:200")) or "1:200")\n'
    '        settings.ui_font_size = int(data.get("ui_font_size", getattr(settings, "ui_font_size", 10)) or 10)\n'
    '        settings.ui_button_font_size = int(data.get("ui_button_font_size", getattr(settings, "ui_button_font_size", 10)) or 10)\n'
    '        settings.ui_menu_font_size = int(data.get("ui_menu_font_size", getattr(settings, "ui_menu_font_size", 10)) or 10)\n'
    '        settings.ui_contrast = str(data.get("ui_contrast", getattr(settings, "ui_contrast", "Standard")) or "Standard")\n'
    '        settings.ui_color_scheme = str(data.get("ui_color_scheme", getattr(settings, "ui_color_scheme", "Nautical Light")) or "Nautical Light")\n'
    '        settings.share_gnss_sbes_input = bool(data.get("share_gnss_sbes_input", getattr(settings, "share_gnss_sbes_input", False)))\n'
    '        for target, source in [(settings.gps, data.get("gps", {})), (settings.sensor, data.get("sensor", {}))]:\n'
    '            for key, value in source.items():\n'
    '                if hasattr(target, key):\n'
    '                    setattr(target, key, value)\n'
    '        settings.gps.title = "GNSS"\n'
    '        geo = data.get("geodetic", {})\n'
    '        for key, value in geo.items():\n'
    '            if hasattr(settings.geodetic, key):\n'
    '                setattr(settings.geodetic, key, value)\n'
    '        settings.extra_devices = []\n'
    '        for item in data.get("extra_devices", []):\n'
    '            if not isinstance(item, dict):\n'
    '                continue\n'
    '            device = SerialSettings(\n'
    '                title=str(item.get("title", f"Device {len(settings.extra_devices) + 1}")),\n'
    '                port=str(item.get("port", "COM1")),\n'
    '                baud_rate=int(item.get("baud_rate", 4800)),\n'
    '                data_width=int(item.get("data_width", 8)),\n'
    '                stop_bits=float(item.get("stop_bits", 1)),\n'
    '                parity=str(item.get("parity", "N")),\n'
    '                nmea_log=str(item.get("nmea_log", "")),\n'
    '                enabled=bool(item.get("enabled", True)),\n'
    '                recording_rate_hz=float(item.get("recording_rate_hz", 1.0) or 1.0),\n'
    '                sentence_options=list(item.get("sentence_options", GENERIC_DEVICE_SENTENCE_OPTIONS)),\n'
    '                selected_sentences=list(item.get("selected_sentences", item.get("sentence_options", GENERIC_DEVICE_SENTENCE_OPTIONS))),\n'
    '            )\n'
    '            settings.extra_devices.append(device)\n'
    '        return settings\n'
    '\n'
    '\n'
    'def load_app_settings() -> AppSettings:\n'
    '    if DEFAULT_SETTINGS_PATH.exists():\n'
    '        try:\n'
    '            return AppSettings.load(DEFAULT_SETTINGS_PATH)\n'
    '        except Exception:\n'
    '            return AppSettings.defaults()\n'
    '    return AppSettings.defaults()\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class MBESHardwareSetup:\n'
    '    project_folder: str = field(default_factory=lambda: str(DEFAULT_PROJECT_FOLDER))\n'
    '    survey_name: str = "MBES Survey"\n'
    '    vessel_name: str = ""\n'
    '    operator_name: str = ""\n'
    '    hardware_raw_profile: str = "Kongsberg ALL/KMALL"\n'
    '    sonar_make_model: str = "Kongsberg / Teledyne / Norbit MBES"\n'
    '    native_raw_format: str = "KMALL / ALL / S7K / XTF"\n'
    '    positioning_model: str = "GNSS / INS"\n'
    '    motion_model: str = "MRU / INS"\n'
    '    heading_model: str = "Gyro / INS"\n'
    '    svp_sensor_model: str = "SVP / surface sound speed"\n'
    '    tide_source: str = "Tide gauge / RTK tide"\n'
    '    time_sync_source: str = "GNSS UTC / PPS / NTP"\n'
    '    horizontal_crs: str = "WGS84 / UTM"\n'
    '    vertical_datum: str = "Chart Datum"\n'
    '    require_sonar: bool = True\n'
    '    require_positioning: bool = True\n'
    '    require_motion: bool = True\n'
    '    require_heading: bool = True\n'
    '    require_svp: bool = True\n'
    '    require_tide: bool = False\n'
    '    require_time_sync: bool = True\n'
    '    sonar_udp_port: int = 4001\n'
    '    nmea_udp_port: int = 4002\n'
    '    motion_udp_port: int = 4003\n'
    '    heading_udp_port: int = 4004\n'
    '    log_sonar: bool = True\n'
    '    log_nmea: bool = True\n'
    '    log_motion: bool = True\n'
    '    log_heading: bool = True\n'
    '    gnss_route_enabled: bool = True\n'
    '    gnss_serial_port: str = "COM1"\n'
    '    gnss_baud_rate: int = 115200\n'
    '    gnss_output_protocol: str = "UDP"\n'
    '    gnss_output_host: str = "127.0.0.1"\n'
    '    gnss_output_port: int = 4002\n'
    '    sbes_route_enabled: bool = False\n'
    '    sbes_serial_port: str = "COM2"\n'
    '    sbes_baud_rate: int = 38400\n'
    '    sbes_output_protocol: str = "UDP"\n'
    '    sbes_output_host: str = "127.0.0.1"\n'
    '    sbes_output_port: int = 4010\n'
    '    transducer_x_m: float = 0.0\n'
    '    transducer_y_m: float = 0.0\n'
    '    transducer_z_m: float = 0.0\n'
    '    antenna_x_m: float = 0.0\n'
    '    antenna_y_m: float = 0.0\n'
    '    antenna_z_m: float = 0.0\n'
    '    roll_bias_deg: float = 0.0\n'
    '    pitch_bias_deg: float = 0.0\n'
    '    heading_bias_deg: float = 0.0\n'
    '    latency_s: float = 0.0\n'
    '    draft_m: float = 0.0\n'
    '    tide_m: float = 0.0\n'
    '    sound_speed_mps: float = DEFAULT_SOUND_SPEED\n'
    '    svp_file: str = ""\n'
    '    tide_file: str = ""\n'
    '    notes: str = ""\n'
    '\n'
    '    def to_dict(self) -> dict[str, object]:\n'
    '        return dict(self.__dict__)\n'
    '\n'
    '    @classmethod\n'
    '    def from_dict(cls, payload: dict[str, object]) -> "MBESHardwareSetup":\n'
    '        setup = cls()\n'
    '        for key, value in payload.items():\n'
    '            if hasattr(setup, key):\n'
    '                current = getattr(setup, key)\n'
    '                try:\n'
    '                    if isinstance(current, bool):\n'
    '                        setattr(setup, key, bool(value))\n'
    '                    elif isinstance(current, int) and not isinstance(current, bool):\n'
    '                        setattr(setup, key, int(value))\n'
    '                    elif isinstance(current, float):\n'
    '                        setattr(setup, key, float(value))\n'
    '                    else:\n'
    '                        setattr(setup, key, str(value))\n'
    '                except Exception:\n'
    '                    setattr(setup, key, value)\n'
    '        return setup\n'
    '\n'
    '\n'
    'def mbes_utc_stamp() -> str:\n'
    '    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")\n'
    '\n'
    '\n'
    'def mbes_file_stamp() -> str:\n'
    '    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")\n'
    '\n'
    '\n'
    'def mbes_packet_hash(payload: bytes) -> str:\n'
    '    return hashlib.sha256(payload).hexdigest()\n'
    '\n'
    '\n'
    'def mbes_project_paths(project_folder: str | Path) -> dict[str, Path]:\n'
    '    base = Path(project_folder or DEFAULT_PROJECT_FOLDER)\n'
    '    paths = {\n'
    '        "base": base,\n'
    '        "raw": base / "RAW" / "MBES",\n'
    '        "processed": base / "PROCESSED" / "MBES",\n'
    '        "exports": base / "EXPORT" / "MBES",\n'
    '        "logs": base / "LOGS" / "MBES",\n'
    '        "sort": base / "SORTED" / "MBES",\n'
    '        "matrix": base / "MATRIX" / "MBES",\n'
    '        "svp": base / "SVP",\n'
    '        "tide": base / "TIDE",\n'
    '        "backup": base / "BACKUP" / "MBES",\n'
    '    }\n'
    '    for path in paths.values():\n'
    '        path.mkdir(parents=True, exist_ok=True)\n'
    '    return paths\n'
    '\n'
    '\n'
    'HYSWEEP_COLLECT_WORKFLOW = [\n'
    '    "Create or select the project and confirm RAW, LOGS, SVP, TIDE, MATRIX, SORTED, EXPORT, and BACKUP folders.",\n'
    '    "Configure HYPACK/HYSWEEP hardware drivers: MBES sonar, GNSS/INS, MRU, gyro/heading, SVP or surface sound speed, tide/water level, and time sync.",\n'
    '    "Enter vessel geometry, sonar head offsets, antenna offsets, draft, latency, and patch-test roll/pitch/yaw values in one place only.",\n'
    '    "Set serial-to-UDP/TCP routing for GNSS or SBES feeds when the MBES workflow needs network streams; use Generic Attitude-style ASCII parsing where required.",\n'
    '    "Run static configuration checks for required components, ports, CRS, datum, correction files, offsets, and sound-speed ranges.",\n'
    '    "Run live data checks with systems powered: sonar packets, navigation, motion/heave-pitch-roll, heading, and routed feeds should all show packet counts.",\n'
    '    "Open live survey views: main navigation, profile, waterfall, coverage/cross section, QC, time series, TPU, message/status, device control, and MRU display.",\n'
    '    "During acquisition, log native sonar packets plus navigation, motion, heading, tide/draft, sound velocity, offsets, and UTC/PPS/NTP timing metadata.",\n'
    '    "Use matrix/coverage, targets, water column when needed, and backup/overlap rules to protect line data during long survey days.",\n'
    ']\n'
    '\n'
    '\n'
    'HYSWEEP_PROCESS_WORKFLOW = [\n'
    '    "Preserve native RAW/HSX files, then load the survey line set or catalog into the editor/processor.",\n'
    '    "Review read parameters: device selections, survey information, presort/GPS filters, sonar processing options, matrix/cloud settings, TPU, and offsets.",\n'
    '    "Apply or verify tide/RTK tide, dynamic draft, sound velocity/refraction, heave/iHeave, heading, pitch, roll, latency, and patch-test corrections.",\n'
    '    "Run patch-test review on dedicated lines before applying final roll, pitch, yaw, and latency corrections to production data.",\n'
    '    "Clean in stages: basic filters, GPS filters, sweep filters, matrix filters, manual point/area editing, and flagged/golden sounding review.",\n'
    '    "Calculate TPU and gridded uncertainty surfaces; use CUBE-style node review where available to resolve multiple hypotheses and low-confidence cells.",\n'
    '    "Run crossline, coverage, density, uncertainty, and statistics checks before final deliverables.",\n'
    '    "Save edited data to HS2/HS2X or project-native format, then export cleaned XYZ/CSV, matrix/grid, CUBE surface values, GeoTIFF/BAG/S-102 where supported, metadata, and QC/certification reports.",\n'
    ']\n'
    '\n'
    '\n'
