    '            "Export to supported hydrographic processor format for refraction, offsets, TPU, cleaning, side scan/backscatter, and deliverables.",\n'
    '            "Preserve original vendor raw plus exported processing files.",\n'
    '        ],\n'
    '        "exports": ["XTF", "S7K/GSF where available", "Cleaned XYZ/CSV", "GeoTIFF imagery", "QC report"],\n'
    '        "internal_support": "HYDROGEOMATICS internal processor supports only converted CSV/ASCII soundings for this profile.",\n'
    '    },\n'
    '    "WASSP": {\n'
    '        "hardware": "WASSP multibeam systems",\n'
    '        "raw_formats": ["WASSP vendor data", "GSF", "ASCII/XYZ after conversion"],\n'
    '        "preferred_processors": ["WASSP vendor processor", "Qimera 2", "CARIS HIPS & SIPS", "HYPACK/HYSWEEP"],\n'
    '        "default_processor": "Vendor software",\n'
    '        "workflow": [\n'
    '            "Process first with WASSP/vendor tools when proprietary corrections or format conversion are required.",\n'
    '            "Export GSF/ASCII/XYZ for third-party cleaning, gridding, and reporting.",\n'
    '            "Run coverage, crossline, uncertainty, and metadata checks before final delivery.",\n'
    '        ],\n'
    '        "exports": ["GSF", "Cleaned XYZ/CSV", "Grid/GeoTIFF", "QC report"],\n'
    '        "internal_support": "HYDROGEOMATICS internal processor supports GSF only after conversion to CSV/ASCII soundings.",\n'
    '    },\n'
    '    "Cerulean Surveyor 240-16": {\n'
    '        "hardware": "Cerulean Sonar Surveyor 240-16 compact 240 kHz MBES",\n'
    '        "raw_formats": ["SonarView SVLOG", "SonarView SVLZ compressed log", "CSV point cloud", "GSF beta export"],\n'
    '        "preferred_processors": ["SonarView", "HYDROGEOMATICS Internal Processor", "ReefMaster", "CloudCompare/MeshLab", "Qimera 2 or MB-System via verified GSF/CSV"],\n'
    '        "default_processor": "HYDROGEOMATICS Internal",\n'
