    '\n'
    'def mbes_enabled_sources(setup: MBESHardwareSetup) -> list[tuple[str, int, bool]]:\n'
    '    return [\n'
    '        ("sonar_native", int(setup.sonar_udp_port), bool(setup.log_sonar)),\n'
    '        ("nmea_nav", int(setup.nmea_udp_port), bool(setup.log_nmea)),\n'
    '        ("motion_mru", int(setup.motion_udp_port), bool(setup.log_motion)),\n'
    '        ("heading", int(setup.heading_udp_port), bool(setup.log_heading)),\n'
    '    ]\n'
    '\n'
    '\n'
    'def mbes_check_udp_port_available(port: int) -> tuple[bool, str]:\n'
    '    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n'
    '    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\n'
    '    try:\n'
    '        sock.bind(("0.0.0.0", int(port)))\n'
    '        return True, "UDP port can be opened for listening"\n'
    '    except Exception as exc:\n'
    '        return False, f"UDP port cannot be opened: {exc}"\n'
    '    finally:\n'
    '        sock.close()\n'
    '\n'
    '\n'
    'def mbes_add_check(checks: list[dict[str, str]], status: str, item: str, detail: str) -> None:\n'
    '    checks.append({"status": status, "item": item, "detail": detail})\n'
    '\n'
    '\n'
    'def mbes_validate_hardware_setup(setup: MBESHardwareSetup) -> list[dict[str, str]]:\n'
    '    checks: list[dict[str, str]] = []\n'
    '    paths = mbes_project_paths(setup.project_folder)\n'
    '    try:\n'
    '        test_path = paths["logs"] / ".mbes_write_test"\n'
    '        test_path.write_text("ok", encoding="utf-8")\n'
    '        test_path.unlink(missing_ok=True)\n'
    '        mbes_add_check(checks, "PASS", "Project folders", f"Writable project structure at {paths[\'base\']}")\n'
    '    except Exception as exc:\n'
    '        mbes_add_check(checks, "FAIL", "Project folders", f"Cannot write to project folder: {exc}")\n'
    '\n'
    '    required_text = [\n'
    '        ("Survey name", setup.survey_name),\n'
    '        ("Hardware/raw profile", getattr(setup, "hardware_raw_profile", "")),\n'
    '        ("Sonar make/model", setup.sonar_make_model),\n'
    '        ("Native raw format", setup.native_raw_format),\n'
    '        ("Horizontal CRS", setup.horizontal_crs),\n'
    '        ("Vertical datum", setup.vertical_datum),\n'
    '    ]\n'
    '    for label, value in required_text:\n'
    '        if str(value or "").strip():\n'
    '            mbes_add_check(checks, "PASS", label, str(value))\n'
    '        else:\n'
    '            mbes_add_check(checks, "FAIL", label, "Required field is blank")\n'
    '\n'
    '    if setup.require_sonar and not setup.log_sonar:\n'
    '        mbes_add_check(checks, "FAIL", "Sonar component", "Required sonar logging is disabled")\n'
    '    elif setup.require_sonar:\n'
    '        mbes_add_check(checks, "PASS", "Sonar component", setup.sonar_make_model or "Selected")\n'
    '    if setup.require_positioning and not setup.log_nmea:\n'
    '        mbes_add_check(checks, "FAIL", "Positioning component", "Required GNSS/NMEA logging is disabled")\n'
    '    elif setup.require_positioning:\n'
    '        mbes_add_check(checks, "PASS", "Positioning component", setup.positioning_model or "Selected")\n'
    '    if setup.require_motion and not setup.log_motion:\n'
    '        mbes_add_check(checks, "WARN", "Motion component", "Motion/MRU expected but logging is disabled")\n'
    '    elif setup.require_motion:\n'
    '        mbes_add_check(checks, "PASS", "Motion component", setup.motion_model or "Selected")\n'
    '    if setup.require_heading and not setup.log_heading:\n'
    '        mbes_add_check(checks, "WARN", "Heading component", "Heading expected but logging is disabled")\n'
    '    elif setup.require_heading:\n'
    '        mbes_add_check(checks, "PASS", "Heading component", setup.heading_model or "Selected")\n'
    '\n'
    '    active_ports: dict[int, list[str]] = {}\n'
    '    for name, port, enabled in mbes_enabled_sources(setup):\n'
    '        if not enabled:\n'
    '            mbes_add_check(checks, "INFO", f"{name} UDP", "Disabled")\n'
    '            continue\n'
    '        if not (1 <= int(port) <= 65535):\n'
    '            mbes_add_check(checks, "FAIL", f"{name} UDP", f"Invalid port {port}")\n'
    '            continue\n'
    '        active_ports.setdefault(int(port), []).append(name)\n'
    '        ok, detail = mbes_check_udp_port_available(int(port))\n'
    '        mbes_add_check(checks, "PASS" if ok else "FAIL", f"{name} UDP {port}", detail)\n'
    '    for port, names in active_ports.items():\n'
    '        if len(names) > 1:\n'
    '            mbes_add_check(checks, "FAIL", f"Duplicate UDP port {port}", ", ".join(names))\n'
    '\n'
    '    route_ports: dict[tuple[str, str, int], list[str]] = {}\n'
    '    for label, enabled, serial_port, baud_rate, protocol, host, out_port in [\n'
    '        ("GNSS serial route", setup.gnss_route_enabled, setup.gnss_serial_port, setup.gnss_baud_rate, setup.gnss_output_protocol, setup.gnss_output_host, setup.gnss_output_port),\n'
    '        ("SBES serial route", setup.sbes_route_enabled, setup.sbes_serial_port, setup.sbes_baud_rate, setup.sbes_output_protocol, setup.sbes_output_host, setup.sbes_output_port),\n'
    '    ]:\n'
    '        if not enabled:\n'
    '            mbes_add_check(checks, "INFO", label, "Disabled")\n'
    '            continue\n'
    '        if not str(serial_port or "").strip():\n'
    '            mbes_add_check(checks, "FAIL", label, "Serial port is blank")\n'
    '        else:\n'
    '            mbes_add_check(checks, "PASS", label, f"Input {serial_port} at {baud_rate} baud")\n'
    '        try:\n'
    '            int(baud_rate)\n'
    '            if int(baud_rate) <= 0:\n'
    '                raise ValueError("baud must be positive")\n'
    '        except Exception:\n'
    '            mbes_add_check(checks, "FAIL", label, f"Invalid baud rate {baud_rate}")\n'
    '        proto = str(protocol or "").upper()\n'
    '        try:\n'
    '            output_port_value = int(out_port)\n'
    '        except Exception:\n'
    '            output_port_value = -1\n'
    '        if proto not in {"UDP", "TCP"}:\n'
    '            mbes_add_check(checks, "FAIL", label, f"Output protocol must be UDP or TCP, got {protocol}")\n'
    '        elif not str(host or "").strip():\n'
    '            mbes_add_check(checks, "FAIL", label, "Output host is blank")\n'
    '        elif not (1 <= output_port_value <= 65535):\n'
    '            mbes_add_check(checks, "FAIL", label, f"Invalid output port {out_port}")\n'
    '        else:\n'
    '            route_ports.setdefault((proto, str(host), output_port_value), []).append(label)\n'
    '            mbes_add_check(checks, "PASS", f"{label} output", f"{proto} {host}:{output_port_value}")\n'
    '    for (proto, host, port), labels in route_ports.items():\n'
    '        if len(labels) > 1:\n'
    '            mbes_add_check(checks, "WARN", f"Duplicate route output {proto} {host}:{port}", ", ".join(labels))\n'
    '\n'
    '    for label, value in [\n'
    '        ("Draft", setup.draft_m),\n'
    '        ("Tide", setup.tide_m),\n'
    '        ("Latency", setup.latency_s),\n'
    '        ("Roll bias", setup.roll_bias_deg),\n'
    '        ("Pitch bias", setup.pitch_bias_deg),\n'
    '        ("Heading bias", setup.heading_bias_deg),\n'
    '        ("Transducer X", setup.transducer_x_m),\n'
    '        ("Transducer Y", setup.transducer_y_m),\n'
    '        ("Transducer Z", setup.transducer_z_m),\n'
    '        ("Antenna X", setup.antenna_x_m),\n'
    '        ("Antenna Y", setup.antenna_y_m),\n'
    '        ("Antenna Z", setup.antenna_z_m),\n'
    '    ]:\n'
    '        try:\n'
    '            float(value)\n'
    '            mbes_add_check(checks, "PASS", label, f"{float(value):.4f}")\n'
    '        except Exception:\n'
    '            mbes_add_check(checks, "FAIL", label, "Value is not numeric")\n'
    '\n'
    '    try:\n'
    '        sound_speed = float(setup.sound_speed_mps)\n'
    '        if 1350.0 <= sound_speed <= 1650.0:\n'
    '            mbes_add_check(checks, "PASS", "Sound speed", f"{sound_speed:.2f} m/s")\n'
    '        else:\n'
    '            mbes_add_check(checks, "WARN", "Sound speed", f"{sound_speed:.2f} m/s is outside the normal seawater range")\n'
    '    except Exception:\n'
    '        mbes_add_check(checks, "FAIL", "Sound speed", "Value is not numeric")\n'
    '\n'
    '    if setup.require_svp:\n'
    '        if setup.svp_file and Path(setup.svp_file).exists():\n'
    '            mbes_add_check(checks, "PASS", "SVP file", setup.svp_file)\n'
    '        else:\n'
    '            mbes_add_check(checks, "WARN", "SVP file", "SVP is required but no existing file is selected")\n'
    '    elif setup.svp_file and not Path(setup.svp_file).exists():\n'
    '        mbes_add_check(checks, "WARN", "SVP file", "Selected SVP file does not exist")\n'
    '    if setup.require_tide:\n'
    '        if setup.tide_file and Path(setup.tide_file).exists():\n'
    '            mbes_add_check(checks, "PASS", "Tide file", setup.tide_file)\n'
    '        else:\n'
    '            mbes_add_check(checks, "WARN", "Tide file", "Tide is required but no existing file is selected")\n'
    '    elif setup.tide_file and not Path(setup.tide_file).exists():\n'
    '        mbes_add_check(checks, "WARN", "Tide file", "Selected tide file does not exist")\n'
    '    if setup.require_time_sync and not str(setup.time_sync_source or "").strip():\n'
    '        mbes_add_check(checks, "WARN", "Time sync", "Select GNSS UTC, PPS, or NTP source")\n'
    '    elif setup.require_time_sync:\n'
    '        mbes_add_check(checks, "PASS", "Time sync", setup.time_sync_source)\n'
    '    return checks\n'
    '\n'
    '\n'
    'def mbes_probe_udp_connectivity(setup: MBESHardwareSetup, duration_s: float = 5.0) -> list[dict[str, str]]:\n'
    '    checks: list[dict[str, str]] = []\n'
    '    sockets: dict[socket.socket, tuple[str, int]] = {}\n'
    '    try:\n'
    '        for source_name, port, enabled in mbes_enabled_sources(setup):\n'
    '            if not enabled:\n'
    '                mbes_add_check(checks, "INFO", f"{source_name} live data", "Disabled")\n'
    '                continue\n'
    '            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n'
    '            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\n'
    '            sock.setblocking(False)\n'
    '            try:\n'
    '                sock.bind(("0.0.0.0", int(port)))\n'
    '                sockets[sock] = (source_name, int(port))\n'
    '            except Exception as exc:\n'
    '                sock.close()\n'
    '                mbes_add_check(checks, "FAIL", f"{source_name} UDP {port}", f"Cannot listen: {exc}")\n'
    '        counts = {source_name: 0 for source_name, _port in sockets.values()}\n'
    '        bytes_seen = {source_name: 0 for source_name, _port in sockets.values()}\n'
    '        started = time.monotonic()\n'
    '        while sockets and time.monotonic() - started < max(0.2, float(duration_s)):\n'
    '            remaining = max(0.05, min(0.5, float(duration_s) - (time.monotonic() - started)))\n'
    '            readable, _w, _x = select.select(list(sockets), [], [], remaining)\n'
    '            for sock in readable:\n'
    '                source_name, _port = sockets[sock]\n'
    '                try:\n'
    '                    payload, _addr = sock.recvfrom(65535)\n'
    '                except BlockingIOError:\n'
    '                    continue\n'
    '                counts[source_name] += 1\n'
    '                bytes_seen[source_name] += len(payload)\n'
    '        for _sock, (source_name, port) in sockets.items():\n'
    '            count = counts.get(source_name, 0)\n'
    '            total_bytes = bytes_seen.get(source_name, 0)\n'
    '            if count > 0:\n'
    '                mbes_add_check(checks, "PASS", f"{source_name} live data", f"{count} packet(s), {total_bytes} byte(s) on UDP {port}")\n'
    '            else:\n'
    '                mbes_add_check(checks, "WARN", f"{source_name} live data", f"No packets seen on UDP {port} during {duration_s:.1f} s")\n'
    '    finally:\n'
    '        for sock in list(sockets):\n'
    '            sock.close()\n'
    '    return checks\n'
    '\n'
    '\n'
    'class MBESRawLogger:\n'
    '    """Small UDP logger that preserves native MBES packets and writes a JSONL audit index."""\n'
    '\n'
    '    def __init__(self, setup: MBESHardwareSetup, status_callback: Optional[Any] = None, rotate_mb: int = 512) -> None:\n'
    '        self.setup = setup\n'
    '        self.paths = mbes_project_paths(setup.project_folder)\n'
    '        self.status_callback = status_callback\n'
    '        self.rotate_bytes = max(1, int(rotate_mb)) * 1024 * 1024\n'
    '        self.stop_event = threading.Event()\n'
    '        self.errors: queue.Queue[str] = queue.Queue()\n'
    '        self.threads: list[threading.Thread] = []\n'
    '        self.files: dict[str, tuple[Any, Path, int, int]] = {}\n'
    '        self.lock = threading.Lock()\n'
    '        self.index_path = self.paths["logs"] / f"mbes_acquisition_{mbes_file_stamp()}.jsonl"\n'
    '        self.metadata_path = self.paths["logs"] / f"mbes_session_{mbes_file_stamp()}.json"\n'
    '        self.index_handle: Optional[Any] = None\n'
    '\n'
    '    def sources(self) -> list[tuple[str, int]]:\n'
    '        return [(name, port) for name, port, enabled in mbes_enabled_sources(self.setup) if enabled]\n'
    '\n'
    '    def start(self) -> None:\n'
    '        self.stop_event.clear()\n'
    '        self.paths = mbes_project_paths(self.setup.project_folder)\n'
    '        self.metadata_path.write_text(json.dumps(self.setup.to_dict(), indent=2), encoding="utf-8")\n'
    '        self.index_handle = self.index_path.open("a", encoding="utf-8")\n'
    '        for source_name, port in self.sources():\n'
    '            thread = threading.Thread(target=self._udp_worker, args=(source_name, port), daemon=True)\n'
    '            thread.start()\n'
    '            self.threads.append(thread)\n'
    '        self._status(f"MBES logging started: {len(self.threads)} UDP source(s), index {self.index_path}")\n'
    '\n'
    '    def stop(self) -> None:\n'
    '        self.stop_event.set()\n'
    '        for thread in self.threads:\n'
    '            thread.join(timeout=1.5)\n'
    '        self.threads.clear()\n'
    '        with self.lock:\n'
    '            for handle, _path, _size, _sequence in self.files.values():\n'
    '                try:\n'
    '                    handle.close()\n'
    '                except Exception:\n'
    '                    pass\n'
    '            self.files.clear()\n'
    '            if self.index_handle is not None:\n'
    '                try:\n'
    '                    self.index_handle.close()\n'
    '                except Exception:\n'
    '                    pass\n'
    '                self.index_handle = None\n'
    '        self._status("MBES logging stopped.")\n'
    '\n'
    '    def _status(self, message: str) -> None:\n'
    '        if self.status_callback is not None:\n'
    '            try:\n'
    '                self.status_callback(message)\n'
    '            except Exception:\n'
    '                pass\n'
    '\n'
    '    def _open_source_file(self, source_name: str) -> tuple[Any, Path, int, int]:\n'
    '        current = self.files.get(source_name)\n'
    '        if current is not None and current[2] < self.rotate_bytes:\n'
    '            return current\n'
    '        if current is not None:\n'
    '            try:\n'
    '                current[0].close()\n'
    '            except Exception:\n'
    '                pass\n'
    '        sequence = 1 if current is None else current[3] + 1\n'
    '        source_dir = self.paths["raw"] / source_name\n'
    '        source_dir.mkdir(parents=True, exist_ok=True)\n'
    '        raw_path = source_dir / f"{mbes_file_stamp()}_{source_name}_{sequence:04d}.bin"\n'
    '        handle = raw_path.open("ab")\n'
    '        opened = (handle, raw_path, 0, sequence)\n'
    '        self.files[source_name] = opened\n'
    '        return opened\n'
    '\n'
    '    def _write_packet(self, source_name: str, payload: bytes, address: str) -> None:\n'
    '        if self.index_handle is None:\n'
    '            return\n'
    '        with self.lock:\n'
    '            handle, raw_path, size, sequence = self._open_source_file(source_name)\n'
    '            offset = handle.tell()\n'
    '            handle.write(payload)\n'
    '            handle.flush()\n'
    '            record = {\n'
    '                "received_utc": mbes_utc_stamp(),\n'
    '                "source": source_name,\n'
    '                "transport": "udp",\n'
    '                "address": address,\n'
    '                "raw_file": str(raw_path),\n'
    '                "offset": offset,\n'
    '                "length": len(payload),\n'
    '                "sha256": mbes_packet_hash(payload),\n'
    '                "sequence": sequence,\n'
    '            }\n'
    '            self.index_handle.write(json.dumps(record, separators=(",", ":")) + "\\n")\n'
    '            self.index_handle.flush()\n'
    '            self.files[source_name] = (handle, raw_path, size + len(payload), sequence)\n'
    '\n'
    '    def _udp_worker(self, source_name: str, port: int) -> None:\n'
    '        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n'
    '        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\n'
    '        sock.settimeout(0.5)\n'
    '        try:\n'
    '            sock.bind(("0.0.0.0", int(port)))\n'
    '            self._status(f"Listening for {source_name} on UDP {port}")\n'
    '            while not self.stop_event.is_set():\n'
    '                try:\n'
    '                    payload, addr = sock.recvfrom(65535)\n'
    '                except socket.timeout:\n'
    '                    continue\n'
    '                self._write_packet(source_name, payload, f"{addr[0]}:{addr[1]}")\n'
    '        except Exception as exc:\n'
    '            self.errors.put(f"{source_name} UDP {port}: {exc}")\n'
    '            self._status(f"MBES logger error: {source_name} UDP {port}: {exc}")\n'
    '        finally:\n'
    '            sock.close()\n'
    '\n'
    '\n'
    'def mbes_float_from_row(row: dict[str, str], names: Iterable[str]) -> Optional[float]:\n'
    '    lowered = {str(key).strip().lower(): value for key, value in row.items()}\n'
    '    for name in names:\n'
    '        value = lowered.get(str(name).lower())\n'
    '        if value in (None, ""):\n'
    '            continue\n'
    '        try:\n'
    '            return float(str(value).strip())\n'
    '        except Exception:\n'
    '            continue\n'
    '    return None\n'
    '\n'
    '\n'
    'def mbes_grid_cell(x: float, y: float, cell_size: float) -> tuple[int, int]:\n'
    '    cell = max(float(cell_size), 0.001)\n'
    '    return floor(x / cell), floor(y / cell)\n'
    '\n'
    '\n'
    'def mbes_process_sounding_csv(\n'
    '    input_path: str | Path,\n'
    '    cleaned_path: str | Path,\n'
    '    grid_path: str | Path,\n'
    '    report_path: str | Path,\n'
    '    draft_m: float = 0.0,\n'
    '    tide_m: float = 0.0,\n'
    '    min_depth: Optional[float] = None,\n'
    '    max_depth: Optional[float] = None,\n'
    '    cell_size: float = 1.0,\n'
    ') -> dict[str, object]:\n'
    '    input_path = Path(input_path)\n'
    '    cleaned_path = Path(cleaned_path)\n'
    '    grid_path = Path(grid_path)\n'
    '    report_path = Path(report_path)\n'
    '    cleaned_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    grid_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    report_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    total = 0\n'
    '    kept = 0\n'
    '    rejected = 0\n'
    '    depths: list[float] = []\n'
    '    grid: dict[tuple[int, int], list[float]] = {}\n'
    '\n'
    '    with input_path.open("r", encoding="utf-8-sig", newline="") as src, cleaned_path.open("w", encoding="utf-8", newline="") as dst:\n'
    '        sample = src.read(4096)\n'
    '        src.seek(0)\n'
    '        try:\n'
    '            dialect = csv.Sniffer().sniff(sample, delimiters=",;\\t ")\n'
    '        except Exception:\n'
    '            dialect = csv.excel\n'
    '        reader = csv.DictReader(src, dialect=dialect)\n'
    '        fieldnames = ["x", "y", "raw_depth_m", "corrected_depth_m", "accepted", "rejected_reason"]\n'
    '        writer = csv.DictWriter(dst, fieldnames=fieldnames)\n'
    '        writer.writeheader()\n'
    '        for row in reader:\n'
    '            total += 1\n'
    '            x = mbes_float_from_row(row, ["x", "easting", "east", "lon", "longitude"])\n'
    '            y = mbes_float_from_row(row, ["y", "northing", "north", "lat", "latitude"])\n'
    '            depth = mbes_float_from_row(row, ["depth", "depth_m", "z", "sounding", "sounding_m", "corrected_depth"])\n'
    '            reason = ""\n'
    '            corrected: Optional[float] = None\n'
    '            if x is None or y is None or depth is None:\n'
    '                reason = "missing_x_y_or_depth"\n'
    '            else:\n'
    '                corrected = float(depth) + float(draft_m) - float(tide_m)\n'
    '                if min_depth is not None and corrected < float(min_depth):\n'
    '                    reason = "shallower_than_min_depth"\n'
    '                elif max_depth is not None and corrected > float(max_depth):\n'
    '                    reason = "deeper_than_max_depth"\n'
    '            accepted = not reason\n'
    '            if accepted and x is not None and y is not None and corrected is not None:\n'
    '                kept += 1\n'
    '                depths.append(corrected)\n'
    '                grid.setdefault(mbes_grid_cell(x, y, cell_size), []).append(corrected)\n'
    '            else:\n'
    '                rejected += 1\n'
    '            writer.writerow(\n'
    '                {\n'
    '                    "x": "" if x is None else f"{x:.8f}",\n'
    '                    "y": "" if y is None else f"{y:.8f}",\n'
    '                    "raw_depth_m": "" if depth is None else f"{depth:.4f}",\n'
    '                    "corrected_depth_m": "" if corrected is None else f"{corrected:.4f}",\n'
    '                    "accepted": "1" if accepted else "0",\n'
    '                    "rejected_reason": reason,\n'
    '                }\n'
    '            )\n'
    '\n'
    '    with grid_path.open("w", encoding="utf-8", newline="") as grid_file:\n'
    '        writer = csv.writer(grid_file)\n'
    '        writer.writerow(["x", "y", "mean_depth_m", "minimum_depth_m", "maximum_depth_m", "count"])\n'
    '        for (ix, iy), values in sorted(grid.items()):\n'
    '            cx = (ix + 0.5) * float(cell_size)\n'
    '            cy = (iy + 0.5) * float(cell_size)\n'
    '            writer.writerow([f"{cx:.3f}", f"{cy:.3f}", f"{statistics.mean(values):.4f}", f"{min(values):.4f}", f"{max(values):.4f}", len(values)])\n'
    '\n'
    '    report = {\n'
    '        "input": str(input_path),\n'
    '        "cleaned_csv": str(cleaned_path),\n'
    '        "grid_csv": str(grid_path),\n'
    '        "created_utc": mbes_utc_stamp(),\n'
    '        "draft_m": draft_m,\n'
    '        "tide_m": tide_m,\n'
    '        "min_depth": min_depth,\n'
    '        "max_depth": max_depth,\n'
    '        "cell_size": cell_size,\n'
    '        "total_soundings": total,\n'
    '        "accepted_soundings": kept,\n'
    '        "rejected_soundings": rejected,\n'
    '        "grid_cells": len(grid),\n'
    '        "minimum_depth_m": min(depths) if depths else None,\n'
    '        "maximum_depth_m": max(depths) if depths else None,\n'
    '        "mean_depth_m": statistics.mean(depths) if depths else None,\n'
    '    }\n'
    '    report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")\n'
    '    return report\n'
    '\n'
    '\n'
    'def mbes_export_xyz_from_cleaned(cleaned_path: str | Path, xyz_path: str | Path) -> int:\n'
    '    cleaned_path = Path(cleaned_path)\n'
    '    xyz_path = Path(xyz_path)\n'
    '    xyz_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    count = 0\n'
    '    with cleaned_path.open("r", encoding="utf-8-sig", newline="") as src, xyz_path.open("w", encoding="utf-8", newline="\\n") as dst:\n'
    '        reader = csv.DictReader(src)\n'
    '        for row in reader:\n'
    '            if str(row.get("accepted", "1")).strip() in {"0", "False", "false"}:\n'
    '                continue\n'
    '            x = mbes_float_from_row(row, ["x"])\n'
    '            y = mbes_float_from_row(row, ["y"])\n'
    '            z = mbes_float_from_row(row, ["corrected_depth_m", "depth_m", "z"])\n'
    '            if x is None or y is None or z is None:\n'
    '                continue\n'
    '            dst.write(f"{x:.3f} {y:.3f} {z:.3f}\\n")\n'
    '            count += 1\n'
    '    return count\n'
    '\n'
    '\n'
    'def mbes_export_geojson_from_cleaned(cleaned_path: str | Path, geojson_path: str | Path) -> int:\n'
    '    cleaned_path = Path(cleaned_path)\n'
    '    geojson_path = Path(geojson_path)\n'
    '    geojson_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    features: list[dict[str, object]] = []\n'
    '    with cleaned_path.open("r", encoding="utf-8-sig", newline="") as src:\n'
    '        reader = csv.DictReader(src)\n'
    '        for row in reader:\n'
    '            if str(row.get("accepted", "1")).strip() in {"0", "False", "false"}:\n'
    '                continue\n'
    '            x = mbes_float_from_row(row, ["x"])\n'
    '            y = mbes_float_from_row(row, ["y"])\n'
    '            z = mbes_float_from_row(row, ["corrected_depth_m", "depth_m", "z"])\n'
    '            if x is None or y is None or z is None:\n'
    '                continue\n'
    '            features.append(\n'
    '                {\n'
    '                    "type": "Feature",\n'
    '                    "geometry": {"type": "Point", "coordinates": [x, y, z]},\n'
    '                    "properties": {"depth_m": z},\n'
    '                }\n'
    '            )\n'
    '    geojson_path.write_text(json.dumps({"type": "FeatureCollection", "features": features}, indent=2), encoding="utf-8")\n'
    '    return len(features)\n'
    '\n'
    '\n'
    'HYDROGEOMATICS_TPU_ORDERS: dict[str, tuple[float, float]] = {\n'
    '    "Special": (0.25, 0.0075),\n'
    '    "1a": (0.50, 0.0130),\n'
    '    "1b": (0.50, 0.0130),\n'
    '    "2": (1.00, 0.0230),\n'
    '    "User": (0.50, 0.0130),\n'
    '}\n'
    '\n'
    '\n'
    'def HYDROGEOMATICS_allowed_tvu(depth_m: float, order: str = "1a", user_a: float = 0.50, user_b: float = 0.013) -> float:\n'
    '    a, b = HYDROGEOMATICS_TPU_ORDERS.get(str(order), HYDROGEOMATICS_TPU_ORDERS["1a"])\n'
    '    if str(order) == "User":\n'
    '        a, b = float(user_a), float(user_b)\n'
    '    return math.sqrt(a * a + (b * float(depth_m)) ** 2)\n'
    '\n'
    '\n'
    'def HYDROGEOMATICS_read_beam_csv(input_path: str | Path) -> list[dict[str, float | str]]:\n'
    '    source = Path(input_path)\n'
    '    records: list[dict[str, float | str]] = []\n'
    '    with source.open("r", encoding="utf-8-sig", newline="") as handle:\n'
    '        sample = handle.read(4096)\n'
    '        handle.seek(0)\n'
    '        try:\n'
    '            dialect = csv.Sniffer().sniff(sample, delimiters=",;\\t ")\n'
    '        except Exception:\n'
    '            dialect = csv.excel\n'
    '        reader = csv.DictReader(handle, dialect=dialect)\n'
    '        for row_index, row in enumerate(reader, 1):\n'
    '            x = mbes_float_from_row(row, ["x", "easting", "east", "lon", "longitude"])\n'
    '            y = mbes_float_from_row(row, ["y", "northing", "north", "lat", "latitude"])\n'
    '            depth = mbes_float_from_row(row, ["corrected_depth_m", "depth_m", "depth", "z", "sounding", "range_depth"])\n'
    '            if x is None or y is None or depth is None:\n'
    '                continue\n'
    '            beam_angle = mbes_float_from_row(row, ["beam_angle", "beam_angle_deg", "angle", "across_angle"]) or 0.0\n'
    '            beam_number = mbes_float_from_row(row, ["beam", "beam_number", "beam_id"]) or float(row_index)\n'
    '            quality = mbes_float_from_row(row, ["quality", "quality_flag", "q"]) or 1.0\n'
    '            records.append(\n'
    '                {\n'
    '                    "x": float(x),\n'
    '                    "y": float(y),\n'
    '                    "depth_m": float(depth),\n'
    '                    "beam_angle_deg": float(beam_angle),\n'
    '                    "beam_number": float(beam_number),\n'
    '                    "quality": float(quality),\n'
    '                    "source_row": float(row_index),\n'
    '                    "time_utc": str(row.get("time_utc", row.get("time", "")) or ""),\n'
    '                }\n'
    '            )\n'
    '    return records\n'
    '\n'
    '\n'
    'def HYDROGEOMATICS_internal_mbes_process(\n'
    '    input_path: str | Path,\n'
    '    output_cleaned_csv: str | Path,\n'
    '    output_grid_csv: str | Path,\n'
    '    output_cert_json: str | Path,\n'
    '    order: str = "1a",\n'
    '    user_a: float = 0.50,\n'
    '    user_b: float = 0.013,\n'
    '    cell_size: float = 1.0,\n'
    '    density_required: int = 5,\n'
    '    median_reject_m: float = 0.75,\n'
    '    angle_limit_deg: float = 70.0,\n'
    '    min_depth: Optional[float] = None,\n'
    '    max_depth: Optional[float] = None,\n'
    ') -> dict[str, object]:\n'
    '    records = HYDROGEOMATICS_read_beam_csv(input_path)\n'
    '    cell = max(float(cell_size), 0.001)\n'
    '    cells: dict[tuple[int, int], list[dict[str, float | str]]] = {}\n'
    '    for rec in records:\n'
    '        cells.setdefault(mbes_grid_cell(float(rec["x"]), float(rec["y"]), cell), []).append(rec)\n'
    '\n'
    '    medians: dict[tuple[int, int], float] = {}\n'
    '    for key, values in cells.items():\n'
    '        depths = [float(item["depth_m"]) for item in values]\n'
    '        medians[key] = statistics.median(depths) if depths else 0.0\n'
    '\n'
    '    cleaned_path = Path(output_cleaned_csv)\n'
    '    grid_path = Path(output_grid_csv)\n'
    '    cert_path = Path(output_cert_json)\n'
    '    cleaned_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    grid_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    cert_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '\n'
    '    accepted = 0\n'
    '    rejected = 0\n'
    '    uncertainty_pass = 0\n'
    '    density_pass_cells = 0\n'
    '    accepted_cells: dict[tuple[int, int], list[dict[str, float | str]]] = {}\n'
    '    rejected_reasons: dict[str, int] = {}\n'
    '\n'
    '    with cleaned_path.open("w", encoding="utf-8", newline="") as handle:\n'
    '        writer = csv.DictWriter(\n'
    '            handle,\n'
    '            fieldnames=[\n'
    '                "x",\n'
    '                "y",\n'
    '                "depth_m",\n'
    '                "beam_number",\n'
    '                "beam_angle_deg",\n'
    '                "quality",\n'
    '                "tpu_m",\n'
    '                "allowed_tvu_m",\n'
    '                "residual_to_cell_median_m",\n'
    '                "accepted",\n'
    '                "rejected_reason",\n'
    '                "time_utc",\n'
    '            ],\n'
    '        )\n'
    '        writer.writeheader()\n'
    '        for rec in records:\n'
    '            x = float(rec["x"])\n'
    '            y = float(rec["y"])\n'
    '            depth = float(rec["depth_m"])\n'
    '            angle = float(rec["beam_angle_deg"])\n'
    '            quality = float(rec["quality"])\n'
    '            key = mbes_grid_cell(x, y, cell)\n'
    '            median_depth = medians.get(key, depth)\n'
    '            residual = depth - median_depth\n'
    '            allowed_tvu = HYDROGEOMATICS_allowed_tvu(depth, order, user_a, user_b)\n'
    '            angle_component = abs(math.sin(math.radians(angle))) * max(depth, 0.0) * 0.004\n'
    '            tpu = math.sqrt((0.15 + abs(depth) * 0.002) ** 2 + angle_component ** 2)\n'
    '            reason = ""\n'
    '            if min_depth is not None and depth < float(min_depth):\n'
    '                reason = "shallower_than_min_depth"\n'
    '            elif max_depth is not None and depth > float(max_depth):\n'
    '                reason = "deeper_than_max_depth"\n'
    '            elif abs(angle) > float(angle_limit_deg):\n'
    '                reason = "beam_angle_exceeds_limit"\n'
    '            elif quality <= 0:\n'
    '                reason = "quality_flag_rejected"\n'
    '            elif abs(residual) > float(median_reject_m):\n'
    '                reason = "cell_median_residual_exceeds_limit"\n'
    '            elif tpu > allowed_tvu:\n'
    '                reason = "tpu_exceeds_allowed_tvu"\n'
    '            if reason:\n'
    '                rejected += 1\n'
    '                rejected_reasons[reason] = rejected_reasons.get(reason, 0) + 1\n'
    '            else:\n'
    '                accepted += 1\n'
    '                uncertainty_pass += 1\n'
    '                accepted_cells.setdefault(key, []).append(rec)\n'
    '            writer.writerow(\n'
    '                {\n'
    '                    "x": f"{x:.8f}",\n'
    '                    "y": f"{y:.8f}",\n'
    '                    "depth_m": f"{depth:.4f}",\n'
    '                    "beam_number": f"{float(rec[\'beam_number\']):.0f}",\n'
    '                    "beam_angle_deg": f"{angle:.3f}",\n'
    '                    "quality": f"{quality:.3f}",\n'
    '                    "tpu_m": f"{tpu:.4f}",\n'
    '                    "allowed_tvu_m": f"{allowed_tvu:.4f}",\n'
    '                    "residual_to_cell_median_m": f"{residual:.4f}",\n'
    '                    "accepted": "1" if not reason else "0",\n'
    '                    "rejected_reason": reason,\n'
    '                    "time_utc": rec.get("time_utc", ""),\n'
    '                }\n'
    '            )\n'
    '\n'
    '    with grid_path.open("w", encoding="utf-8", newline="") as grid_file:\n'
    '        writer = csv.writer(grid_file)\n'
    '        writer.writerow(["x", "y", "mean_depth_m", "minimum_depth_m", "maximum_depth_m", "count", "density_pass"])\n'
    '        for (ix, iy), values in sorted(accepted_cells.items()):\n'
    '            depths = [float(item["depth_m"]) for item in values]\n'
    '            density_pass = len(depths) >= int(density_required)\n'
    '            if density_pass:\n'
    '                density_pass_cells += 1\n'
    '            writer.writerow(\n'
    '                [\n'
    '                    f"{(ix + 0.5) * cell:.3f}",\n'
    '                    f"{(iy + 0.5) * cell:.3f}",\n'
    '                    f"{statistics.mean(depths):.4f}",\n'
    '                    f"{min(depths):.4f}",\n'
    '                    f"{max(depths):.4f}",\n'
    '                    len(depths),\n'
    '                    "1" if density_pass else "0",\n'
    '                ]\n'
    '            )\n'
    '\n'
    '    total_cells = len(accepted_cells)\n'
    '    certification = {\n'
    '        "processor": "HYDROGEOMATICS Internal MBES Processor",\n'
    '        "created_utc": mbes_utc_stamp(),\n'
    '        "input": str(input_path),\n'
    '        "cleaned_csv": str(cleaned_path),\n'
    '        "grid_csv": str(grid_path),\n'
    '        "order": order,\n'
    '        "order_a": HYDROGEOMATICS_TPU_ORDERS.get(str(order), (user_a, user_b))[0] if order != "User" else user_a,\n'
    '        "order_b": HYDROGEOMATICS_TPU_ORDERS.get(str(order), (user_a, user_b))[1] if order != "User" else user_b,\n'
    '        "cell_size": cell,\n'
    '        "density_required_per_cell": int(density_required),\n'
    '        "total_soundings": len(records),\n'
    '        "accepted_soundings": accepted,\n'
    '        "rejected_soundings": rejected,\n'
    '        "accepted_ratio": accepted / max(len(records), 1),\n'
    '        "grid_cells": total_cells,\n'
    '        "density_pass_cells": density_pass_cells,\n'
    '        "density_pass_ratio": density_pass_cells / max(total_cells, 1),\n'
    '        "uncertainty_pass_soundings": uncertainty_pass,\n'
    '        "rejected_reasons": rejected_reasons,\n'
    '        "certification_result": "PASS" if accepted > 0 and total_cells > 0 and density_pass_cells == total_cells else "REVIEW",\n'
    '        "limitations": [\n'
    '            "CSV/ASCII beam decoder implemented. Native vendor binary decoders require official packet specifications or SDK access.",\n'
    '            "TPU model is configurable and deterministic; verify constants against project authority requirements before certification use.",\n'
    '            "Final certification should include independent crossline, coverage, datum, metadata, and deliverable review.",\n'
    '        ],\n'
    '    }\n'
    '    cert_path.write_text(json.dumps(certification, indent=2), encoding="utf-8")\n'
    '    return certification\n'
    '\n'
    '\n'
    'def wgs84_tm_to_xy(\n'
    '    latitude: float,\n'
    '    longitude: float,\n'
    '    central_meridian: float,\n'
    '    scale_factor: float = 0.9996,\n'
    '    false_easting: float = 500000.0,\n'
    '    false_northing: float = 0.0,\n'
    ') -> tuple[float, float]:\n'
    '    a = 6378137.0\n'
    '    f = 1.0 / 298.257223563\n'
    '    e2 = f * (2.0 - f)\n'
    '    ep2 = e2 / (1.0 - e2)\n'
    '    lat = math.radians(latitude)\n'
    '    lon = math.radians(longitude)\n'
    '    lon0 = math.radians(central_meridian)\n'
    '    n = a / math.sqrt(1.0 - e2 * math.sin(lat) ** 2)\n'
    '    t = math.tan(lat) ** 2\n'
    '    c = ep2 * math.cos(lat) ** 2\n'
    '    aa = math.cos(lat) * (lon - lon0)\n'
    '    m = a * (\n'
    '        (1.0 - e2 / 4.0 - 3.0 * e2 ** 2 / 64.0 - 5.0 * e2 ** 3 / 256.0) * lat\n'
    '        - (3.0 * e2 / 8.0 + 3.0 * e2 ** 2 / 32.0 + 45.0 * e2 ** 3 / 1024.0) * math.sin(2.0 * lat)\n'
    '        + (15.0 * e2 ** 2 / 256.0 + 45.0 * e2 ** 3 / 1024.0) * math.sin(4.0 * lat)\n'
    '        - (35.0 * e2 ** 3 / 3072.0) * math.sin(6.0 * lat)\n'
    '    )\n'
    '    easting = false_easting + scale_factor * n * (\n'
    '        aa\n'
    '        + (1.0 - t + c) * aa ** 3 / 6.0\n'
    '        + (5.0 - 18.0 * t + t ** 2 + 72.0 * c - 58.0 * ep2) * aa ** 5 / 120.0\n'
    '    )\n'
    '    northing = false_northing + scale_factor * (\n'
    '        m\n'
    '        + n\n'
    '        * math.tan(lat)\n'
    '        * (\n'
    '            aa ** 2 / 2.0\n'
    '            + (5.0 - t + 9.0 * c + 4.0 * c ** 2) * aa ** 4 / 24.0\n'
    '            + (61.0 - 58.0 * t + t ** 2 + 600.0 * c - 330.0 * ep2) * aa ** 6 / 720.0\n'
    '        )\n'
    '    )\n'
    '    return easting, northing\n'
    '\n'
    '\n'
    'def lambert_conformal_conic_to_xy(\n'
    '    latitude: float,\n'
    '    longitude: float,\n'
    '    central_meridian: float,\n'
    '    latitude_origin: float,\n'
    '    standard_parallel_1: Optional[float] = None,\n'
    '    standard_parallel_2: Optional[float] = None,\n'
    '    false_easting: float = 500000.0,\n'
    '    false_northing: float = 0.0,\n'
    ') -> tuple[float, float]:\n'
    '    a = 6378137.0\n'
    '    lat = math.radians(latitude)\n'
    '    lon = math.radians(longitude)\n'
    '    lon0 = math.radians(central_meridian)\n'
    '    lat0 = math.radians(latitude_origin)\n'
    '    sp1 = math.radians(standard_parallel_1 if standard_parallel_1 is not None else latitude_origin)\n'
    '    sp2 = math.radians(standard_parallel_2 if standard_parallel_2 is not None else standard_parallel_1 if standard_parallel_1 is not None else latitude_origin)\n'
    '    if abs(sp1 - sp2) < 1e-12:\n'
    '        n = math.sin(sp1)\n'
    '    else:\n'
    '        n = math.log(math.cos(sp1) / max(math.cos(sp2), 1e-12)) / math.log(\n'
    '            max(math.tan(math.pi / 4.0 + sp2 / 2.0), 1e-12) / max(math.tan(math.pi / 4.0 + sp1 / 2.0), 1e-12)\n'
    '        )\n'
    '    f_value = math.cos(sp1) * (math.tan(math.pi / 4.0 + sp1 / 2.0) ** n) / max(n, 1e-12)\n'
    '    rho = a * f_value / max(math.tan(math.pi / 4.0 + lat / 2.0) ** n, 1e-12)\n'
    '    rho0 = a * f_value / max(math.tan(math.pi / 4.0 + lat0 / 2.0) ** n, 1e-12)\n'
    '    theta = n * (lon - lon0)\n'
    '    return false_easting + rho * math.sin(theta), false_northing + rho0 - rho * math.cos(theta)\n'
    '\n'
    '\n'
    'def lambert_conformal_conic_to_latlon(\n'
    '    easting: float,\n'
    '    northing: float,\n'
    '    central_meridian: float,\n'
    '    latitude_origin: float,\n'
    '    standard_parallel_1: Optional[float] = None,\n'
    '    standard_parallel_2: Optional[float] = None,\n'
    '    false_easting: float = 500000.0,\n'
    '    false_northing: float = 0.0,\n'
    ') -> tuple[float, float]:\n'
    '    a = 6378137.0\n'
    '    lon0 = math.radians(central_meridian)\n'
    '    lat0 = math.radians(latitude_origin)\n'
    '    sp1 = math.radians(standard_parallel_1 if standard_parallel_1 is not None else latitude_origin)\n'
    '    sp2 = math.radians(standard_parallel_2 if standard_parallel_2 is not None else standard_parallel_1 if standard_parallel_1 is not None else latitude_origin)\n'
    '    if abs(sp1 - sp2) < 1e-12:\n'
    '        n = math.sin(sp1)\n'
    '    else:\n'
    '        n = math.log(math.cos(sp1) / max(math.cos(sp2), 1e-12)) / math.log(\n'
    '            max(math.tan(math.pi / 4.0 + sp2 / 2.0), 1e-12) / max(math.tan(math.pi / 4.0 + sp1 / 2.0), 1e-12)\n'
    '        )\n'
    '    f_value = math.cos(sp1) * (math.tan(math.pi / 4.0 + sp1 / 2.0) ** n) / max(n, 1e-12)\n'
    '    rho0 = a * f_value / max(math.tan(math.pi / 4.0 + lat0 / 2.0) ** n, 1e-12)\n'
    '    x = float(easting) - false_easting\n'
    '    y = rho0 - (float(northing) - false_northing)\n'
    '    rho = math.copysign(math.hypot(x, y), n)\n'
    '    theta = math.atan2(x, y)\n'
    '    lat = 2.0 * math.atan((a * f_value / max(abs(rho), 1e-12)) ** (1.0 / max(n, 1e-12))) - math.pi / 2.0\n'
    '    lon = lon0 + theta / max(n, 1e-12)\n'
    '    return math.degrees(lat), math.degrees(lon)\n'
    '\n'
    '\n'
    'def utm_projection_preset(zone: int, hemisphere: str = "N") -> dict[str, object]:\n'
    '    """Parameters for a fixed WGS84 UTM survey grid."""\n'
    '    if not 1 <= zone <= 60 or hemisphere not in ("N", "S"):\n'
    '        raise ValueError("Choose UTM zone 1-60 and hemisphere N or S.")\n'
    '    return {\n'
    '        "use_projection": True, "use_tm_projection": True,\n'
    '        "use_lcc_projection": False, "datum_name": "WGS84",\n'
    '        "ellipsoid": "WGS84", "utm_zone": str(zone),\n'
    '        "fixed_utm_reference_zone": True, "lcc_zone": "",\n'
    '        "central_meridian": zone * 6.0 - 183.0,\n'
    '        "latitude_origin": 0.0, "reference_latitude": 0.0,\n'
    '        "scale_factor": 0.9996, "false_easting": 500000.0,\n'
    '        "false_northing": 10000000.0 if hemisphere == "S" else 0.0,\n'
    '        "grid_name": "UTM South" if hemisphere == "S" else "UTM North",\n'
    '        "zone_label": f"Zone {zone}{hemisphere}",\n'
    '        "projection_method": "Transverse Mercator",\n'
    '    }\n'
    '\n'
    '\n'
    'def selected_utm_zone(geodetic: "GeodeticSettings", longitude: Optional[float] = None) -> Optional[int]:\n'
    '    text = str(getattr(geodetic, "utm_zone", "") or "").strip()\n'
    '    match = re.search(r"\\d+", text)\n'
    '    fixed_reference = bool(getattr(geodetic, "fixed_utm_reference_zone", False))\n'
    '    if match and (fixed_reference or longitude is None):\n'
    '        zone = int(match.group(0))\n'
    '        if 1 <= zone <= 60:\n'
    '            return zone\n'
    '    if longitude is not None:\n'
    '        return max(1, min(60, int((float(longitude) + 180.0) // 6.0) + 1))\n'
    '    if match:\n'
    '        zone = int(match.group(0))\n'
    '        if 1 <= zone <= 60:\n'
    '            return zone\n'
    '    return None\n'
    '\n'
    '\n'
    'def project_lat_lon_to_selected_xy(\n'
    '    latitude: Optional[float],\n'
    '    longitude: Optional[float],\n'
    '    geodetic: "GeodeticSettings",\n'
    ') -> tuple[Optional[float], Optional[float]]:\n'
    '    if latitude is None or longitude is None:\n'
    '        return None, None\n'
    '    if not getattr(geodetic, "use_projection", True):\n'
    '        return longitude, latitude\n'
    '    if getattr(geodetic, "use_tm_projection", True):\n'
    '        zone = selected_utm_zone(geodetic, longitude)\n'
    '        central = float(getattr(geodetic, "central_meridian", 0.0) or 0.0)\n'
    '        if zone is not None:\n'
    '            central = zone * 6.0 - 183.0\n'
    '        false_northing = float(getattr(geodetic, "false_northing", 0.0) or 0.0)\n'
    '        if latitude < 0.0 and false_northing == 0.0:\n'
    '            false_northing = 10000000.0\n'
    '        return wgs84_tm_to_xy(\n'
    '            float(latitude),\n'
    '            float(longitude),\n'
    '            central,\n'
    '            float(getattr(geodetic, "scale_factor", 0.9996) or 0.9996),\n'
    '            float(getattr(geodetic, "false_easting", 500000.0) or 500000.0),\n'
    '            false_northing,\n'
    '        )\n'
    '    return longitude, latitude\n'
    '\n'
    '\n'
    'def ensure_projected_xy(point: "SurveyPoint", geodetic: "GeodeticSettings") -> "SurveyPoint":\n'
    '    if point.easting is None or point.northing is None:\n'
    '        easting, northing = project_lat_lon_to_selected_xy(point.latitude, point.longitude, geodetic)\n'
    '        if point.easting is None:\n'
    '            point.easting = easting\n'
    '        if point.northing is None:\n'
    '            point.northing = northing\n'
    '    return point\n'
    '\n'
    '\n'
    'KTD_NODE_CACHE: dict[str, tuple[float, list[tuple[float, float, float]]]] = {}\n'
    'KTD_GRID_META_CACHE: dict[str, tuple[float, dict[str, float | int | str]]] = {}\n'
    'KTD_MATRIX_CACHE: dict[str, tuple[float, dict[str, object]]] = {}\n'
    'KTD_NODATA_VALUE = 999.99\n'
    '\n'
    '\n'
    'def is_ktd_nodata(value: float) -> bool:\n'
    '    return abs(float(value) - KTD_NODATA_VALUE) < 0.005\n'
    '\n'
    '\n'
    'def load_ktd_grid_meta(path: Path) -> Optional[dict[str, float | int | str]]:\n'
    '    cache_key = str(path)\n'
    '    try:\n'
    '        mtime = path.stat().st_mtime\n'
    '        cached = KTD_GRID_META_CACHE.get(cache_key)\n'
    '        if cached and cached[0] == mtime:\n'
    '            return dict(cached[1])\n'
    '    except Exception:\n'
    '        mtime = 0.0\n'
    '    if not path.exists():\n'
    '        return None\n'
    '    try:\n'
    '        first_line = ""\n'
    '        with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '            for raw_line in handle:\n'
    '                first_line = raw_line.strip()\n'
    '                if first_line:\n'
    '                    break\n'
    '        all_lines = [line.strip() for line in path.read_text(encoding="utf-8", errors="replace").splitlines() if line.strip()]\n'
    '        first = [part for part in re.split(r"[,\\t ]+", all_lines[0] if all_lines else first_line) if part]\n'
    '        values = [parse_float(part) for part in first]\n'
    '        if len(values) >= 6 and all(value is not None for value in values[:6]):\n'
    '            first_count = int(values[0] or 0)\n'
    '            second_count = int(values[1] or 0)\n'
    '            if first_count > 1 and second_count > 1:\n'
    '                # HYPACK KTD matrix files commonly store:\n'
    '                # row_count column_count minX minY maxX maxY.\n'
    '                # Treat this as the default so wrapped matrix rows still parse correctly.\n'
    '                header_order = "rows_cols"\n'
    '                y_count = first_count\n'
    '                x_count = second_count\n'
    '                meta: dict[str, float | int | str] = {\n'
    '                    "x_count": x_count,\n'
    '                    "y_count": y_count,\n'
    '                    "min_x": float(values[2] or 0.0),\n'
    '                    "min_y": float(values[3] or 0.0),\n'
    '                    "max_x": float(values[4] or 0.0),\n'
    '                    "max_y": float(values[5] or 0.0),\n'
    '                    "row_order": "bottom_up",\n'
    '                    "header_order": header_order,\n'
    '                }\n'
    '                KTD_GRID_META_CACHE[cache_key] = (mtime, dict(meta))\n'
    '                return meta\n'
    '    except Exception:\n'
    '        return None\n'
    '    return None\n'
    '\n'
    '\n'
    'def load_ktd_nodes(path: Path) -> list[tuple[float, float, float]]:\n'
    '    nodes: list[tuple[float, float, float]] = []\n'
    '    if not path.exists():\n'
    '        return nodes\n'
    '    cache_key = str(path)\n'
    '    try:\n'
    '        mtime = path.stat().st_mtime\n'
    '        cached = KTD_NODE_CACHE.get(cache_key)\n'
    '        if cached and cached[0] == mtime:\n'
    '            return list(cached[1])\n'
    '    except Exception:\n'
    '        mtime = 0.0\n'
    '\n'
    '    raw_text = path.read_text(encoding="utf-8", errors="replace")\n'
    '    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]\n'
    '    if lines:\n'
    '        first = [part for part in re.split(r"[,\\t ]+", lines[0]) if part]\n'
    '        header_values = [parse_float(part) for part in first]\n'
    '        if (\n'
    '            len(header_values) >= 6\n'
    '            and all(value is not None for value in header_values[:6])\n'
    '            and int(header_values[0] or 0) > 1\n'
    '            and int(header_values[1] or 0) > 1\n'
    '        ):\n'
    '            first_count = int(header_values[0] or 0)\n'
    '            second_count = int(header_values[1] or 0)\n'
    '            min_x = float(header_values[2] or 0.0)\n'
    '            min_y = float(header_values[3] or 0.0)\n'
    '            max_x = float(header_values[4] or min_x)\n'
    '            max_y = float(header_values[5] or min_y)\n'
    '            data_lines = lines[1:]\n'
    '            header_order = "rows_cols"\n'
    '            y_count = first_count\n'
    '            x_count = second_count\n'
    '            dx = (max_x - min_x) / max(x_count - 1, 1)\n'
    '            dy = (max_y - min_y) / max(y_count - 1, 1)\n'
    '            KTD_GRID_META_CACHE[cache_key] = (\n'
    '                mtime,\n'
    '                {\n'
    '                    "x_count": x_count,\n'
    '                    "y_count": y_count,\n'
    '                    "min_x": min_x,\n'
    '                    "min_y": min_y,\n'
    '                    "max_x": max_x,\n'
    '                    "max_y": max_y,\n'
    '                    "row_order": "bottom_up",\n'
    '                    "header_order": header_order,\n'
    '                },\n'
    '            )\n'
    '            value_tokens = [token for token in re.split(r"[,\\t\\s]+", "\\n".join(data_lines).strip()) if token]\n'
    '            limit = min(len(value_tokens), x_count * y_count)\n'
    '            for index in range(limit):\n'
    '                value = parse_float(value_tokens[index])\n'
    '                if value is None or is_ktd_nodata(value):\n'
    '                    continue\n'
    '                row = index // x_count\n'
    '                col = index % x_count\n'
    '                nodes.append((min_x + col * dx, min_y + row * dy, float(value)))\n'
    '            KTD_NODE_CACHE[cache_key] = (mtime, list(nodes))\n'
    '            return nodes\n'
    '\n'
    '    for line in lines:\n'
    '        if line.startswith("#") or line.startswith(";"):\n'
    '            continue\n'
    '        parts = [part for part in re.split(r"[,\\t ]+", line) if part]\n'
    '        if parts and parts[0].upper() in {"KTD", "NODE", "XYZ"}:\n'
    '            parts = parts[1:]\n'
    '        if len(parts) < 3:\n'
    '            continue\n'
    '        x = parse_float(parts[0])\n'
    '        y = parse_float(parts[1])\n'
    '        value = parse_float(parts[2])\n'
    '        if x is not None and y is not None and value is not None and not is_ktd_nodata(value):\n'
    '            nodes.append((float(x), float(y), float(value)))\n'
    '    KTD_NODE_CACHE[cache_key] = (mtime, list(nodes))\n'
    '    return nodes\n'
    '\n'
    '\n'
    '\n'
    'def load_ktd_matrix(path: Path) -> Optional[dict[str, object]]:\n'
    '    cache_key = str(path)\n'
    '    try:\n'
    '        mtime = path.stat().st_mtime\n'
    '        cached = KTD_MATRIX_CACHE.get(cache_key)\n'
    '        if cached and cached[0] == mtime:\n'
    '            return dict(cached[1])\n'
    '    except Exception:\n'
    '        mtime = 0.0\n'
    '    meta = load_ktd_grid_meta(path)\n'
    '    if not meta:\n'
    '        return None\n'
    '    x_count = int(meta.get("x_count", 0) or 0)\n'
    '    y_count = int(meta.get("y_count", 0) or 0)\n'
    '    if x_count <= 1 or y_count <= 1:\n'
    '        return None\n'
    '    try:\n'
    '        lines = [line.strip() for line in path.read_text(encoding="utf-8", errors="replace").splitlines() if line.strip()]\n'
    '    except Exception:\n'
    '        return None\n'
    '    data_lines = lines[1:]\n'
    '    rows: list[list[Optional[float]]] = []\n'
    '    tokens = [token for token in re.split(r"[,\\t\\s]+", "\\n".join(data_lines).strip()) if token]\n'
    '    source_rows = [" ".join(tokens[row * x_count : (row + 1) * x_count]) for row in range(y_count)]\n'
    '    for raw_row in source_rows:\n'
    '        row_values: list[Optional[float]] = []\n'
    '        for token in [part for part in re.split(r"[,\\t ]+", raw_row) if part][:x_count]:\n'
    '            value = parse_float(token)\n'
    '            row_values.append(None if value is None else float(value))\n'
    '        while len(row_values) < x_count:\n'
    '            row_values.append(None)\n'
    '        rows.append(row_values)\n'
    '    while len(rows) < y_count:\n'
    '        rows.append([None] * x_count)\n'
    '    matrix: dict[str, object] = {"meta": dict(meta), "rows": rows}\n'
    '    KTD_MATRIX_CACHE[cache_key] = (mtime, matrix)\n'
    '    return dict(matrix)\n'
    '\n'
    '\n'
    'def ktd_cell_value_at(path_text: str, easting: Optional[float], northing: Optional[float]) -> Optional[float]:\n'
    '    path_text = str(path_text or "").strip()\n'
    '    if not path_text or easting is None or northing is None:\n'
    '        return None\n'
    '    matrix = load_ktd_matrix(Path(path_text))\n'
    '    if not matrix:\n'
    '        return ktd_value_at(path_text, easting, northing)\n'
    '    meta = matrix.get("meta", {})\n'
    '    rows = matrix.get("rows", [])\n'
    '    if not isinstance(meta, dict) or not isinstance(rows, list):\n'
    '        return None\n'
    '    x_count = int(meta.get("x_count", 0) or 0)\n'
    '    y_count = int(meta.get("y_count", 0) or 0)\n'
    '    min_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '    min_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '    max_x = float(meta.get("max_x", min_x) or min_x)\n'
    '    max_y = float(meta.get("max_y", min_y) or min_y)\n'
    '    if x_count <= 1 or y_count <= 1:\n'
    '        return None\n'
    '    dx = (max_x - min_x) / max(x_count - 1, 1)\n'
    '    dy = (max_y - min_y) / max(y_count - 1, 1)\n'
    '    col = int(round((float(easting) - min_x) / max(dx, 1e-12)))\n'
    '    row = int(round((float(northing) - min_y) / max(dy, 1e-12)))\n'
    '    if col < 0 or col >= x_count or row < 0 or row >= y_count:\n'
    '        return None\n'
    '    try:\n'
    '        value = rows[row][col]\n'
    '        if value is None or is_ktd_nodata(float(value)):\n'
    '            return None\n'
    '        return float(value)\n'
    '    except Exception:\n'
    '        return None\n'
    '\n'
    '\n'
    'def apply_ktd_rtk_postprocess_to_point(point: "SurveyPoint", geodetic: "GeodeticSettings") -> bool:\n'
    '    ell_h = getattr(point, "altitude_m", None)\n'
    '    if ell_h is None:\n'
    '        return False\n'
    '    k_value = ktd_cell_value_at(getattr(geodetic, "ktd_file_path", ""), point.x, point.y)\n'
    '    if k_value is None:\n'
    '        return False\n'
    '    reduced_height = float(ell_h) - float(k_value)\n'
    '    point.ktd_cell_k = float(k_value)\n'
    '    point.rtk_reduced_height = reduced_height\n'
    '    point.tide = reduced_height\n'
    '    if point.raw_depth is not None:\n'
    '        speed_factor = point.sound_speed / DEFAULT_SOUND_SPEED if point.sound_speed else 1.0\n'
    '        point.rtk_reduced_depth = point.raw_depth * speed_factor + point.draft - reduced_height\n'
    '    else:\n'
    '        point.rtk_reduced_depth = None\n'
    '    return True\n'
    '\n'
    '\n'
    'def save_ktd_nodes(\n'
    '    path: Path,\n'
    '    nodes: list[tuple[float, float, float]],\n'
    '    mode: str = "K",\n'
    '    grid_meta: Optional[dict[str, float | int | str]] = None,\n'
    ') -> None:\n'
    '    path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    value_by_xy = {(round(float(x), 3), round(float(y), 3)): float(value) for x, y, value in nodes}\n'
    '    if grid_meta:\n'
    '        x_count = int(grid_meta.get("x_count", 0) or 0)\n'
    '        y_count = int(grid_meta.get("y_count", 0) or 0)\n'
    '        min_x = float(grid_meta.get("min_x", 0.0) or 0.0)\n'
    '        min_y = float(grid_meta.get("min_y", 0.0) or 0.0)\n'
    '        max_x = float(grid_meta.get("max_x", min_x) or min_x)\n'
    '        max_y = float(grid_meta.get("max_y", min_y) or min_y)\n'
    '        if x_count > 1 and y_count > 1:\n'
    '            dx = (max_x - min_x) / max(x_count - 1, 1)\n'
    '            dy = (max_y - min_y) / max(y_count - 1, 1)\n'
    '            with path.open("w", encoding="utf-8", newline="\\n") as handle:\n'
    '                if str(grid_meta.get("header_order", "rows_cols")) == "cols_rows":\n'
    '                    handle.write(f"{x_count} {y_count} {min_x:.2f} {min_y:.2f} {max_x:.2f} {max_y:.2f}\\n")\n'
    '                else:\n'
    '                    handle.write(f"{y_count} {x_count} {min_x:.2f} {min_y:.2f} {max_x:.2f} {max_y:.2f}\\n")\n'
    '                row_values: list[str] = []\n'
    '                for row in range(y_count):\n'
    '                    y = round(min_y + row * dy, 3)\n'
    '                    for col in range(x_count):\n'
    '                        x = round(min_x + col * dx, 3)\n'
    '                        value = value_by_xy.get((x, y), KTD_NODATA_VALUE)\n'
    '                        row_values.append(f"{value:.2f}")\n'
    '                    handle.write(" ".join(row_values) + "\\n")\n'
    '                    row_values = []\n'
    '            KTD_NODE_CACHE.pop(str(path), None)\n'
    '            KTD_GRID_META_CACHE.pop(str(path), None)\n'
    '            KTD_MATRIX_CACHE.pop(str(path), None)\n'
    '            return\n'
    '\n'
    '    unique_x = sorted({round(float(x), 3) for x, _y, _value in nodes})\n'
    '    unique_y = sorted({round(float(y), 3) for _x, y, _value in nodes})\n'
    '    can_write_grid = len(unique_x) >= 2 and len(unique_y) >= 2 and len(unique_x) * len(unique_y) <= max(len(nodes) * 2, len(nodes) + 20)\n'
    '    with path.open("w", encoding="utf-8", newline="\\n") as handle:\n'
    '        if can_write_grid:\n'
    '            handle.write(f"{len(unique_y)} {len(unique_x)} {unique_x[0]:.2f} {unique_y[0]:.2f} {unique_x[-1]:.2f} {unique_y[-1]:.2f}\\n")\n'
    '            row_values: list[str] = []\n'
    '            for y in unique_y:\n'
    '                for x in unique_x:\n'
    '                    value = value_by_xy.get((x, y), KTD_NODATA_VALUE)\n'
    '                    row_values.append(f"{value:.2f}")\n'
    '                    if len(row_values) >= 12:\n'
    '                        handle.write(" ".join(row_values) + "\\n")\n'
    '                        row_values = []\n'
    '            if row_values:\n'
    '                handle.write(" ".join(row_values) + "\\n")\n'
    '        else:\n'
    '            handle.write("# HYDROGEOMATICS KTD FILE\\n")\n'
    '            handle.write("# Columns: EASTING NORTHING VALUE\\n")\n'
    '            handle.write(f"# VALUE_MODE {mode}\\n")\n'
    '            handle.write("# If using a geoid model, VALUE is K. Without geoid, VALUE can be K-N.\\n")\n'
    '            for x, y, value in nodes:\n'
    '                handle.write(f"KTD {float(x):.3f} {float(y):.3f} {float(value):.4f}\\n")\n'
    '    try:\n'
    '        KTD_NODE_CACHE.pop(str(path), None)\n'
    '        KTD_GRID_META_CACHE.pop(str(path), None)\n'
    '        KTD_MATRIX_CACHE.pop(str(path), None)\n'
    '    except Exception:\n'
    '        pass\n'
    '\n'
    '\n'
    'def ktd_value_at(path_text: str, easting: Optional[float], northing: Optional[float]) -> Optional[float]:\n'
    '    path_text = str(path_text or "").strip()\n'
    '    if not path_text:\n'
    '        return None\n'
    '    nodes = load_ktd_nodes(Path(path_text))\n'
    '    if not nodes:\n'
    '        return None\n'
    '    if easting is None or northing is None:\n'
    '        return sum(value for _x, _y, value in nodes) / max(len(nodes), 1)\n'
    '    x0 = float(easting)\n'
    '    y0 = float(northing)\n'
    '    distances: list[tuple[float, float]] = []\n'
    '    for x, y, value in nodes:\n'
    '        distance_sq = (x - x0) ** 2 + (y - y0) ** 2\n'
    '        if distance_sq <= 1e-12:\n'
    '            return value\n'
    '        distances.append((distance_sq, value))\n'
    '    distances.sort(key=lambda item: item[0])\n'
    '    selected = distances[: min(6, len(distances))]\n'
    '    weight_sum = 0.0\n'
    '    value_sum = 0.0\n'
    '    for distance_sq, value in selected:\n'
    '        weight = 1.0 / max(distance_sq, 1e-9)\n'
    '        weight_sum += weight\n'
    '        value_sum += value * weight\n'
    '    return value_sum / weight_sum if weight_sum else None\n'
    '\n'
    '\n'
    'def rtk_tide_offset(\n'
    '    geodetic: "GeodeticSettings",\n'
    '    easting: Optional[float] = None,\n'
    '    northing: Optional[float] = None,\n'
    ') -> Optional[float]:\n'
    '    method = str(getattr(geodetic, "rtk_tide_method", "Not using RTK tide") or "Not using RTK tide")\n'
    '    if method == "Not using RTK tide":\n'
    '        return None\n'
    '    n_value = float(getattr(geodetic, "geoid_separation_n", 0.0) or 0.0)\n'
    '    ktd_value = ktd_value_at(getattr(geodetic, "ktd_file_path", ""), easting, northing)\n'
    '    if method == "(K-N) from user value":\n'
    '        return float(getattr(geodetic, "user_k_minus_n", 0.0) or 0.0)\n'
    '    if method == "(K-N) from KTD file":\n'
    '        return ktd_value if ktd_value is not None else float(getattr(geodetic, "ktd_k_value", 0.0) or 0.0) - n_value\n'
    '    if method == "N from geoid model, K from KTD file":\n'
    '        k_value = ktd_value if ktd_value is not None else float(getattr(geodetic, "ktd_k_value", 0.0) or 0.0)\n'
    '        return k_value - n_value\n'
    '    if method == "N from geoid model, K from VDatum":\n'
    '        return float(getattr(geodetic, "vdatum_k_value", 0.0) or 0.0) - n_value\n'
    '    if method == "N from geoid model, K from user value":\n'
    '        return float(getattr(geodetic, "user_k_value", 0.0) or 0.0) - n_value\n'
    '    return None\n'
    '\n'
    '\n'
    'def compute_rtk_tide_from_ellipsoidal_height(\n'
    '    ellipsoidal_height: Optional[float],\n'
    '    geodetic: "GeodeticSettings",\n'
    '    easting: Optional[float] = None,\n'
    '    northing: Optional[float] = None,\n'
    ') -> Optional[float]:\n'
    '    if ellipsoidal_height is None:\n'
    '        return None\n'
    '    offset = rtk_tide_offset(geodetic, easting, northing)\n'
    '    if offset is None:\n'
    '        return None\n'
    '    reference_height = float(getattr(geodetic, "ellipsoidal_height_reference", 0.0) or 0.0)\n'
    '    chart_datum = float(getattr(geodetic, "chart_datum_level", 0.0) or 0.0)\n'
    '    return float(ellipsoidal_height) - reference_height - offset - chart_datum\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class SurveyPoint:\n'
    '    time: str = ""\n'
    '    latitude: Optional[float] = None\n'
    '    longitude: Optional[float] = None\n'
    '    easting: Optional[float] = None\n'
    '    northing: Optional[float] = None\n'
    '    raw_depth: Optional[float] = None\n'
    '    tide: float = 0.0\n'
    '    draft: float = 0.0\n'
    '    sound_speed: float = DEFAULT_SOUND_SPEED\n'
    '    quality: str = ""\n'
    '    source: str = ""\n'
    '    speed_knots: Optional[float] = None\n'
    '    course_degrees: Optional[float] = None\n'
    '    heading_degrees: Optional[float] = None\n'
    '    altitude_m: Optional[float] = None\n'
    '    ktd_cell_k: Optional[float] = None\n'
    '    rtk_reduced_height: Optional[float] = None\n'
    '    rtk_reduced_depth: Optional[float] = None\n'
    '\n'
    '    @property\n'
    '    def corrected_depth(self) -> Optional[float]:\n'
    '        if self.raw_depth is None:\n'
    '            return None\n'
    '        speed_factor = self.sound_speed / DEFAULT_SOUND_SPEED if self.sound_speed else 1.0\n'
    '        if self.rtk_reduced_depth is not None:\n'
    '            return self.rtk_reduced_depth\n'
    '        return self.raw_depth * speed_factor + self.draft - self.tide\n'
    '\n'
    '    @property\n'
    '    def x(self) -> Optional[float]:\n'
    '        return self.easting if self.easting is not None else self.longitude\n'
    '\n'
    '    @property\n'
    '    def y(self) -> Optional[float]:\n'
    '        return self.northing if self.northing is not None else self.latitude\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class RunLine:\n'
    '    name: str\n'
    '    start_x: float\n'
    '    start_y: float\n'
    '    end_x: float\n'
    '    end_y: float\n'
    '    enabled: bool = True\n'
    '\n'
    '    @property\n'
    '    def dx(self) -> float:\n'
    '        return self.end_x - self.start_x\n'
    '\n'
    '    @property\n'
    '    def dy(self) -> float:\n'
    '        return self.end_y - self.start_y\n'
    '\n'
    '    @property\n'
    '    def length(self) -> float:\n'
    '        return math.hypot(self.dx, self.dy)\n'
    '\n'
    '    @property\n'
    '    def bearing_degrees(self) -> float:\n'
    '        return (math.degrees(math.atan2(self.dx, self.dy)) + 360.0) % 360.0\n'
    '\n'
    '    def point_at(self, distance: float) -> tuple[float, float]:\n'
    '        length = self.length\n'
    '        if length == 0.0:\n'
    '            return self.start_x, self.start_y\n'
    '        scale = distance / length\n'
    '        return self.start_x + self.dx * scale, self.start_y + self.dy * scale\n'
    '\n'
    '    def navigation(self, x: float, y: float) -> "NavigationSolution":\n'
    '        length = self.length\n'
    '        if length == 0.0:\n'
    '            distance = math.hypot(x - self.start_x, y - self.start_y)\n'
    '            return NavigationSolution(self, 0.0, 0.0, distance, distance, "ON", self.start_x, self.start_y)\n'
    '        ux = self.dx / length\n'
    '        uy = self.dy / length\n'
    '        vx = x - self.start_x\n'
    '        vy = y - self.start_y\n'
    '        along = vx * ux + vy * uy\n'
    '        cross = vx * uy - vy * ux\n'
    '        nearest_distance = min(max(along, 0.0), length)\n'
    '        nearest_x, nearest_y = self.point_at(nearest_distance)\n'
    '        distance_to_start = math.hypot(x - self.start_x, y - self.start_y)\n'
    '        distance_to_end = math.hypot(x - self.end_x, y - self.end_y)\n'
    '        side = "RIGHT" if cross > 0.0 else "LEFT" if cross < 0.0 else "ON"\n'
    '        return NavigationSolution(\n'
    '            line=self,\n'
    '            along_track=along,\n'
    '            cross_track=cross,\n'
    '            distance_to_start=distance_to_start,\n'
    '            distance_to_end=distance_to_end,\n'
    '            side=side,\n'
    '            nearest_x=nearest_x,\n'
    '            nearest_y=nearest_y,\n'
    '        )\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class NavigationSolution:\n'
    '    line: RunLine\n'
    '    along_track: float\n'
    '    cross_track: float\n'
    '    distance_to_start: float\n'
    '    distance_to_end: float\n'
    '    side: str\n'
    '    nearest_x: float\n'
    '    nearest_y: float\n'
    '\n'
    '    @property\n'
    '    def absolute_cross_track(self) -> float:\n'
    '        return abs(self.cross_track)\n'
    '\n'
    '    @property\n'
    '    def percent_complete(self) -> float:\n'
    '        length = self.line.length\n'
    '        if length == 0.0:\n'
    '            return 0.0\n'
    '        return max(0.0, min(100.0, self.along_track / length * 100.0))\n'
    '\n'
    '\n'
    'class RunLineSet:\n'
    '    def __init__(self) -> None:\n'
    '        self.lines: list[RunLine] = []\n'
    '\n'
    '    def clear(self) -> None:\n'
    '        self.lines.clear()\n'
    '\n'
    '    def add(self, line: RunLine) -> None:\n'
    '        self.lines.append(line)\n'
    '\n'
    '    def nearest(self, x: float, y: float) -> Optional[NavigationSolution]:\n'
    '        solutions = [line.navigation(x, y) for line in self.lines if line.enabled]\n'
    '        if not solutions:\n'
    '            return None\n'
    '        return min(solutions, key=lambda item: item.absolute_cross_track)\n'
    '\n'
    '    def generate_parallel(\n'
    '        self,\n'
    '        start_x: float,\n'
    '        start_y: float,\n'
    '        end_x: float,\n'
    '        end_y: float,\n'
    '        spacing: float,\n'
    '        count_each_side: int,\n'
    '        prefix: str = "RL",\n'
    '        include_center: bool = True,\n'
    '    ) -> None:\n'
    '        base_dx = end_x - start_x\n'
    '        base_dy = end_y - start_y\n'
    '        base_len = math.hypot(base_dx, base_dy)\n'
    '        if base_len == 0.0:\n'
    '            raise ValueError("Runline baseline has zero length")\n'
    '        nx = -base_dy / base_len\n'
    '        ny = base_dx / base_len\n'
    '        offsets: list[int] = []\n'
    '        if include_center:\n'
    '            offsets.append(0)\n'
    '        for index in range(1, count_each_side + 1):\n'
    '            offsets.extend([index, -index])\n'
    '        for offset_index in offsets:\n'
    '            offset = offset_index * spacing\n'
    '            label = f"{prefix}{offset_index:+03d}" if offset_index else f"{prefix}000"\n'
    '            self.add(\n'
    '                RunLine(\n'
    '                    name=label,\n'
    '                    start_x=start_x + nx * offset,\n'
    '                    start_y=start_y + ny * offset,\n'
    '                    end_x=end_x + nx * offset,\n'
    '                    end_y=end_y + ny * offset,\n'
    '                )\n'
    '            )\n'
    '\n'
    '    def load_csv(self, path: Path) -> int:\n'
    '        before = len(self.lines)\n'
    '        if path.suffix.lower() == ".lnw":\n'
    '            for line in load_hypack_lnw(path):\n'
    '                self.add(line)\n'
    '            return len(self.lines) - before\n'
    '        with path.open("r", encoding="utf-8-sig", errors="replace", newline="") as handle:\n'
    '            sample = handle.read(4096)\n'
    '            handle.seek(0)\n'
    '            dialect = csv.Sniffer().sniff(sample) if sample.strip() else csv.excel\n'
    '            reader = csv.DictReader(handle, dialect=dialect)\n'
    '            if reader.fieldnames:\n'
    '                for row in reader:\n'
    '                    line = runline_from_row(row)\n'
    '                    if line is not None:\n'
    '                        self.add(line)\n'
    '                return len(self.lines) - before\n'
    '            handle.seek(0)\n'
    '            for row in csv.reader(handle, dialect=dialect):\n'
    '                line = runline_from_sequence(row)\n'
    '                if line is not None:\n'
    '                    self.add(line)\n'
    '        return len(self.lines) - before\n'
    '\n'
    '    def export_csv(self, path: Path) -> int:\n'
    '        if path.suffix.lower() == ".lnw":\n'
    '            return write_hypack_lnw(path, self.lines)\n'
    '        with path.open("w", encoding="utf-8", newline="") as handle:\n'
    '            writer = csv.DictWriter(\n'
    '                handle,\n'
    '                fieldnames=[\n'
    '                    "name",\n'
    '                    "start_x",\n'
    '                    "start_y",\n'
    '                    "end_x",\n'
    '                    "end_y",\n'
    '                    "length",\n'
    '                    "bearing_degrees",\n'
    '                    "enabled",\n'
    '                ],\n'
    '            )\n'
    '            writer.writeheader()\n'
    '            for line in self.lines:\n'
    '                writer.writerow(\n'
    '                    {\n'
    '                        "name": line.name,\n'
    '                        "start_x": f"{line.start_x:.3f}",\n'
    '                        "start_y": f"{line.start_y:.3f}",\n'
    '                        "end_x": f"{line.end_x:.3f}",\n'
    '                        "end_y": f"{line.end_y:.3f}",\n'
    '                        "length": f"{line.length:.3f}",\n'
    '                        "bearing_degrees": f"{line.bearing_degrees:.3f}",\n'
    '                        "enabled": int(line.enabled),\n'
    '                    }\n'
    '                )\n'
    '        return len(self.lines)\n'
    '\n'
    '\n'
    'class SurveyModel:\n'
    '    def __init__(self) -> None:\n'
    '        self.points: list[SurveyPoint] = []\n'
    '        self.tide = 0.0\n'
    '        self.draft = 0.0\n'
    '        self.sound_speed = DEFAULT_SOUND_SPEED\n'
    '\n'
    '    def clear(self) -> None:\n'
    '        self.points.clear()\n'
    '\n'
    '    def apply_offsets(self) -> None:\n'
    '        for point in self.points:\n'
    '            point.tide = self.tide\n'
    '            point.draft = self.draft\n'
    '            point.sound_speed = self.sound_speed\n'
    '\n'
    '    def add(self, point: SurveyPoint) -> None:\n'
    '        if point.tide == 0.0:\n'
    '            point.tide = self.tide\n'
    '        if point.draft == 0.0:\n'
    '            point.draft = self.draft\n'
    '        if not point.sound_speed:\n'
    '            point.sound_speed = self.sound_speed\n'
    '        self.points.append(point)\n'
    '\n'
    '    def load_file(self, path: Path) -> int:\n'
    '        before = len(self.points)\n'
    '        suffix = path.suffix.lower()\n'
    '        preserves_hypack_corrections = False\n'
    '        if is_hypack_raw_file(path):\n'
    '            preserves_hypack_corrections = True\n'
    '            for point in load_hypack_raw_points(path):\n'
    '                self.add(point)\n'
    '        elif is_hypack_edited_file(path):\n'
    '            preserves_hypack_corrections = True\n'
    '            for point in load_hypack_edited_points(path):\n'
    '                self.add(point)\n'
    '        elif suffix in {".xyz", ".txt"}:\n'
    '            self._load_xyz(path)\n'
    '        else:\n'
    '            self._load_csv(path)\n'
    '        if not preserves_hypack_corrections:\n'
    '            self.apply_offsets()\n'
    '        return len(self.points) - before\n'
    '\n'
    '    def _load_xyz(self, path: Path) -> None:\n'
    '        with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '            for line_no, line in enumerate(handle, 1):\n'
    '                line = line.strip()\n'
    '                if not line or line.startswith("#"):\n'
    '                    continue\n'
    '                parts = line.replace(",", " ").split()\n'
    '                if len(parts) < 3:\n'
    '                    continue\n'
    '                try:\n'
    '                    x, y, depth = map(float, parts[:3])\n'
    '                except ValueError:\n'
    '                    continue\n'
    '                self.add(\n'
    '                    SurveyPoint(\n'
    '                        easting=x,\n'
    '                        northing=y,\n'
    '                        raw_depth=depth,\n'
    '                        source=f"{path.name}:{line_no}",\n'
    '                    )\n'
    '                )\n'
    '\n'
    '    def _load_csv(self, path: Path) -> None:\n'
    '        with path.open("r", encoding="utf-8-sig", errors="replace", newline="") as handle:\n'
    '            sample = handle.read(4096)\n'
    '            handle.seek(0)\n'
    '            dialect = csv.Sniffer().sniff(sample) if sample.strip() else csv.excel\n'
    '            reader = csv.DictReader(handle, dialect=dialect)\n'
    '            if reader.fieldnames:\n'
    '                for row_no, row in enumerate(reader, 2):\n'
    '                    point = point_from_row(row)\n'
    '                    point.source = f"{path.name}:{row_no}"\n'
    '                    if has_position_or_depth(point):\n'
    '                        self.add(point)\n'
    '                return\n'
    '\n'
    '            handle.seek(0)\n'
    '            for row_no, row in enumerate(csv.reader(handle, dialect=dialect), 1):\n'
    '                point = point_from_sequence(row)\n'
    '                point.source = f"{path.name}:{row_no}"\n'
    '                if has_position_or_depth(point):\n'
    '                    self.add(point)\n'
    '\n'
    '    def export_xyz(self, path: Path) -> int:\n'
    '        count = 0\n'
    '        with path.open("w", encoding="utf-8", newline="") as handle:\n'
    '            for point in self.points:\n'
    '                z = point.corrected_depth\n'
    '                if point.x is None or point.y is None or z is None:\n'
    '                    continue\n'
    '                handle.write(f"{point.x:.6f} {point.y:.6f} {z:.3f}\\n")\n'
    '                count += 1\n'
    '        return count\n'
    '\n'
    '    def export_csv(self, path: Path) -> int:\n'
    '        fields = [\n'
    '            "time",\n'
    '            "latitude",\n'
    '            "longitude",\n'
    '            "easting",\n'
    '            "northing",\n'
    '            "raw_depth",\n'
    '            "tide",\n'
    '            "draft",\n'
    '            "sound_speed",\n'
    '            "corrected_depth",\n'
    '            "altitude_m",\n'
    '            "ktd_cell_k",\n'
    '            "rtk_reduced_height",\n'
    '            "rtk_reduced_depth",\n'
    '            "quality",\n'
    '            "source",\n'
    '        ]\n'
    '        with path.open("w", encoding="utf-8", newline="") as handle:\n'
    '            writer = csv.DictWriter(handle, fieldnames=fields)\n'
    '            writer.writeheader()\n'
    '            for point in self.points:\n'
    '                writer.writerow(\n'
    '                    {\n'
    '                        "time": point.time,\n'
    '                        "latitude": point.latitude,\n'
    '                        "longitude": point.longitude,\n'
    '                        "easting": point.easting,\n'
    '                        "northing": point.northing,\n'
    '                        "raw_depth": point.raw_depth,\n'
    '                        "tide": point.tide,\n'
    '                        "draft": point.draft,\n'
    '                        "sound_speed": point.sound_speed,\n'
    '                        "corrected_depth": point.corrected_depth,\n'
    '                        "altitude_m": point.altitude_m,\n'
    '                        "ktd_cell_k": point.ktd_cell_k,\n'
    '                        "rtk_reduced_height": point.rtk_reduced_height,\n'
    '                        "rtk_reduced_depth": point.rtk_reduced_depth,\n'
    '                        "quality": point.quality,\n'
    '                        "source": point.source,\n'
    '                    }\n'
    '                )\n'
    '        return len(self.points)\n'
    '\n'
    '    def export_hypack_raw(self, path: Path) -> int:\n'
    '        count = 0\n'
    '        now = datetime.now()\n'
    '        with path.open("w", encoding="utf-8", newline="\\n") as handle:\n'
    '            handle.write("FTP NEW 2\\n")\n'
    '            handle.write("VER HYDROGEOMATICS-SBES-0607\\n")\n'
    '            handle.write(\'INF "" "" "" "" 1.000000 0.000000 0.000000\\n\')\n'
    '            handle.write("ELL WGS-84 6378137.000 298.257223563\\n")\n'
    '            handle.write("PRO TME -63.000000 0.999600 0.000000 0.000000 0.000000 500000.0000 0.0000\\n")\n'
    '            handle.write("DTM 0.00 0.00 0.00 0.00000 0.00000 0.00000 0.00000\\n")\n'
    '            handle.write("GEO WGS84 0.000\\n")\n'
    '            handle.write("HVU 1.0000000000 1.0000000000\\n")\n'
    '            handle.write(f"TND {now:%H:%M:%S} {now:%m/%d/%Y} 300\\n")\n'
    '            handle.write(\'DEV 0 15 "GNSS" 1 ""\\n\')\n'
    '            handle.write("OFF 0 0.000000 0.000000 0.000000 0.000000 0.000000 0.000000 0.000000\\n")\n'
    '            handle.write(\'DEV 1 16 "SBES" 1 ""\\n\')\n'
    '            handle.write("OFF 1 0.000000 0.000000 0.000000 0.000000 0.000000 0.000000 0.000000\\n")\n'
    '            handle.write("EOH\\n")\n'
    '            for index, point in enumerate(self.points, 1):\n'
    '                timestamp = display_time_to_hypack(point.time, index)\n'
    '                if point.x is not None and point.y is not None:\n'
    '                    handle.write(f"POS 0 {timestamp:.3f} {float(point.x):.3f} {float(point.y):.3f}\\n")\n'
    '                if point.tide:\n'
    '                    handle.write(f"TID 0 {timestamp:.3f} {float(point.tide):.3f}\\n")\n'
    '                if point.raw_depth is not None:\n'
    '                    handle.write(f"EC1 1 {timestamp:.3f} {float(point.raw_depth):.3f}\\n")\n'
    '                    count += 1\n'
    '                if point.heading_degrees is not None:\n'
    '                    handle.write(f"GYR 0 {timestamp:.3f} {float(point.heading_degrees):.3f}\\n")\n'
    '            handle.write("EOX\\n")\n'
    '        return count\n'
    '\n'
    '    def stats(self) -> dict[str, float | int | None]:\n'
    '        depths = [p.corrected_depth for p in self.points if p.corrected_depth is not None]\n'
    '        if not depths:\n'
    '            return {"count": len(self.points), "min": None, "max": None, "mean": None}\n'
    '        return {\n'
    '            "count": len(self.points),\n'
    '            "min": min(depths),\n'
    '            "max": max(depths),\n'
    '            "mean": statistics.fmean(depths),\n'
    '        }\n'
    '\n'
    '\n'
    'class EchogramModel:\n'
    '    def __init__(self, max_depth: Optional[float] = None, depth_bins: int = 160) -> None:\n'
    '        self.max_depth = max_depth\n'
    '        self.depth_bins = depth_bins\n'
    '        self.pings: list[list[int]] = []\n'
    '        self.bottom_depths: list[Optional[float]] = []\n'
    '\n'
    '    def build_from_points(self, points: list[SurveyPoint]) -> None:\n'
    '        depths = [p.corrected_depth for p in points if p.corrected_depth is not None]\n'
    '        if not depths:\n'
    '            self.pings = []\n'
    '            self.bottom_depths = []\n'
    '            return\n'
    '        max_depth = self.max_depth or max(depths) * 1.15 or 1.0\n'
    '        self.pings = []\n'
    '        self.bottom_depths = []\n'
    '        for point in points:\n'
    '            depth = point.corrected_depth\n'
    '            self.bottom_depths.append(depth)\n'
    '            self.pings.append(synthetic_ping(depth, max_depth, self.depth_bins))\n'
    '\n'
    '    def load_matrix_csv(self, path: Path) -> int:\n'
    '        self.pings = []\n'
    '        self.bottom_depths = []\n'
    '        with path.open("r", encoding="utf-8-sig", errors="replace", newline="") as handle:\n'
    '            reader = csv.reader(handle)\n'
    '            for row in reader:\n'
    '                values = [parse_float(item) for item in row]\n'
    '                samples = [int(max(0, min(255, value))) for value in values if value is not None]\n'
    '                if samples:\n'
    '                    self.pings.append(samples)\n'
    '                    self.bottom_depths.append(None)\n'
    '        if self.pings:\n'
    '            self.depth_bins = max(len(ping) for ping in self.pings)\n'
    '        return len(self.pings)\n'
    '\n'
    '    def export_ppm(self, path: Path) -> int:\n'
    '        if not self.pings:\n'
    '            raise ValueError("No echogram pings available")\n'
    '        width = len(self.pings)\n'
    '        height = max(len(ping) for ping in self.pings)\n'
    '        with path.open("w", encoding="ascii", newline="\\n") as handle:\n'
    '            handle.write(f"P3\\n{width} {height}\\n255\\n")\n'
    '            for y in range(height):\n'
    '                row: list[str] = []\n'
    '                for ping in self.pings:\n'
    '                    value = ping[y] if y < len(ping) else 0\n'
    '                    row.extend(str(channel) for channel in waterfall_color(value))\n'
    '                handle.write(" ".join(row) + "\\n")\n'
    '        return width\n'
    '\n'
    '\n'
    'def synthetic_ping(depth: Optional[float], max_depth: float, bins: int) -> list[int]:\n'
    '    if depth is None or max_depth <= 0.0:\n'
    '        return [0] * bins\n'
    '    bottom = max(0, min(bins - 1, int(depth / max_depth * (bins - 1))))\n'
    '    samples: list[int] = []\n'
    '    for index in range(bins):\n'
    '        surface = max(0, 45 - index * 2)\n'
    '        bottom_echo = int(235 * math.exp(-((index - bottom) / 2.8) ** 2))\n'
    '        sub_bottom = int(90 * math.exp(-((index - bottom - 8) / 7.0) ** 2)) if index > bottom else 0\n'
    '        texture = int(18 * (1.0 + math.sin(index * 0.37 + depth * 0.19)))\n'
    '        samples.append(max(0, min(255, surface + bottom_echo + sub_bottom + texture)))\n'
    '    return samples\n'
    '\n'
    '\n'
    'def waterfall_color(value: int) -> tuple[int, int, int]:\n'
    '    value = max(0, min(255, int(value)))\n'
    '    if value < 64:\n'
    '        return 0, value * 2, 64 + value * 2\n'
    '    if value < 128:\n'
    '        return 0, 128 + (value - 64) * 2, 255 - (value - 64)\n'
    '    if value < 192:\n'
    '        return (value - 128) * 4, 255, 64\n'
    '    return 255, 255 - (value - 192) * 3, max(0, 64 - (value - 192))\n'
    '\n'
    '\n'
    'def has_position_or_depth(point: SurveyPoint) -> bool:\n'
    '    return point.raw_depth is not None or point.x is not None or point.y is not None\n'
    '\n'
    '\n'
    'def first_value(row: dict[str, str], names: Iterable[str]) -> str:\n'
    '    normalized = {clean_key(k): v for k, v in row.items() if k is not None}\n'
    '    for name in names:\n'
    '        value = normalized.get(clean_key(name), "")\n'
    '        if value not in (None, ""):\n'
    '            return str(value).strip()\n'
    '    return ""\n'
    '\n'
    '\n'
    'def clean_key(key: str) -> str:\n'
    '    return "".join(ch for ch in str(key).lower() if ch.isalnum())\n'
    '\n'
    '\n'
    'def parse_float(value: object) -> Optional[float]:\n'
    '    if value is None:\n'
    '        return None\n'
    '    text = str(value).strip()\n'
    '    if not text:\n'
    '        return None\n'
    '    text = text.replace(",", "")\n'
    '    try:\n'
    '        return float(text)\n'
    '    except ValueError:\n'
    '        return None\n'
    '\n'
    '\n'
    'def point_from_row(row: dict[str, str]) -> SurveyPoint:\n'
    '    raw_depth = parse_float(\n'
    '        first_value(row, ["depth", "raw_depth", "rawdepth", "sound", "sounding", "z"])\n'
    '    )\n'
    '    latitude = parse_float(first_value(row, ["lat", "latitude"]))\n'
    '    longitude = parse_float(first_value(row, ["lon", "long", "longitude"]))\n'
    '    easting = parse_float(first_value(row, ["x", "east", "easting"]))\n'
    '    northing = parse_float(first_value(row, ["y", "north", "northing"]))\n'
    '    tide = parse_float(first_value(row, ["tide", "waterlevel", "water_level"]))\n'
    '    draft = parse_float(first_value(row, ["draft", "draught", "transducerdraft"]))\n'
    '    sv = parse_float(first_value(row, ["sv", "svp", "soundspeed", "sound_speed"]))\n'
    '    return SurveyPoint(\n'
    '        time=first_value(row, ["time", "date", "datetime", "timestamp"]),\n'
    '        latitude=latitude,\n'
    '        longitude=longitude,\n'
    '        easting=easting,\n'
    '        northing=northing,\n'
    '        raw_depth=raw_depth,\n'
    '        tide=tide if tide is not None else 0.0,\n'
    '        draft=draft if draft is not None else 0.0,\n'
    '        sound_speed=sv if sv is not None else DEFAULT_SOUND_SPEED,\n'
    '        quality=first_value(row, ["quality", "fix", "status"]),\n'
    '    )\n'
    '\n'
    '\n'
    'def point_from_sequence(row: list[str]) -> SurveyPoint:\n'
    '    values = [parse_float(value) for value in row]\n'
    '    nums = [value for value in values if value is not None]\n'
    '    if len(nums) >= 3:\n'
    '        return SurveyPoint(easting=nums[0], northing=nums[1], raw_depth=nums[2])\n'
    '    if len(nums) == 2:\n'
    '        return SurveyPoint(easting=nums[0], northing=nums[1])\n'
    '    if len(nums) == 1:\n'
    '        return SurveyPoint(raw_depth=nums[0])\n'
    '    return SurveyPoint()\n'
    '\n'
    '\n'
    'def runline_from_row(row: dict[str, str]) -> Optional[RunLine]:\n'
    '    name = first_value(row, ["name", "line", "runline", "id"]) or "RUNLINE"\n'
    '    start_x = parse_float(first_value(row, ["start_x", "startx", "x1", "sx", "from_x"]))\n'
    '    start_y = parse_float(first_value(row, ["start_y", "starty", "y1", "sy", "from_y"]))\n'
    '    end_x = parse_float(first_value(row, ["end_x", "endx", "x2", "ex", "to_x"]))\n'
    '    end_y = parse_float(first_value(row, ["end_y", "endy", "y2", "ey", "to_y"]))\n'
    '    enabled_text = first_value(row, ["enabled", "active", "use"])\n'
    '    enabled = enabled_text.lower() not in {"0", "false", "no", "off"}\n'
    '    if None in {start_x, start_y, end_x, end_y}:\n'
    '        return None\n'
    '    return RunLine(name, float(start_x), float(start_y), float(end_x), float(end_y), enabled)\n'
    '\n'
    '\n'
    'def runline_from_sequence(row: list[str]) -> Optional[RunLine]:\n'
    '    cleaned = [item.strip() for item in row if item.strip()]\n'
    '    if len(cleaned) < 4:\n'
    '        return None\n'
    '    if len(cleaned) >= 5:\n'
    '        name = cleaned[0]\n'
    '        values = [parse_float(item) for item in cleaned[1:5]]\n'
    '    else:\n'
    '        name = "RUNLINE"\n'
    '        values = [parse_float(item) for item in cleaned[:4]]\n'
    '    if any(value is None for value in values):\n'
    '        return None\n'
    '    return RunLine(name, float(values[0]), float(values[1]), float(values[2]), float(values[3]))\n'
    '\n'
    '\n'
    '\n'
    'def hypack_time_to_display(value: str) -> str:\n'
    '    parsed = parse_float(value)\n'
    '    if parsed is None:\n'
    '        return str(value).strip()\n'
    '    seconds = float(parsed)\n'
    '    hours = int(seconds // 3600) % 24\n'
    '    minutes = int((seconds % 3600) // 60)\n'
    '    secs = seconds - hours * 3600 - minutes * 60\n'
    '    return f"{hours:02d}:{minutes:02d}:{secs:06.3f}"\n'
    '\n'
    '\n'
    'def display_time_to_hypack(value: str, fallback_index: int = 0) -> float:\n'
    '    text = str(value or "").strip()\n'
    '    parts = text.split(":")\n'
    '    try:\n'
    '        if len(parts) == 3:\n'
    '            return int(parts[0]) * 3600.0 + int(parts[1]) * 60.0 + float(parts[2])\n'
    '        if len(parts) == 2:\n'
    '            return int(parts[0]) * 60.0 + float(parts[1])\n'
    '        if text:\n'
    '            return float(text)\n'
    '    except ValueError:\n'
    '        pass\n'
    '    return float(fallback_index)\n'
    '\n'
    '\n'
    'def load_hypack_raw_points(path: Path) -> list[SurveyPoint]:\n'
    '    points: list[SurveyPoint] = []\n'
    '    last_position: Optional[SurveyPoint] = None\n'
    '    last_tide = 0.0\n'
    '    with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '        for line_no, raw_line in enumerate(handle, 1):\n'
    '            line = raw_line.strip()\n'
    '            if not line:\n'
    '                continue\n'
    '            parts = line.replace(",", " ").split()\n'
    '            if not parts:\n'
    '                continue\n'
    '            tag = parts[0].upper()\n'
    '            if tag == "TID" and len(parts) >= 4:\n'
    '                tide = parse_float(parts[3])\n'
    '                if tide is not None:\n'
    '                    last_tide = tide\n'
    '                    if last_position is not None:\n'
    '                        last_position.tide = tide\n'
    '                continue\n'
    '            if tag == "POS" and len(parts) >= 5:\n'
    '                point = SurveyPoint(\n'
    '                    time=hypack_time_to_display(parts[2]),\n'
    '                    easting=parse_float(parts[3]),\n'
    '                    northing=parse_float(parts[4]),\n'
    '                    tide=last_tide,\n'
    '                    source=f"{path.name}:{line_no}",\n'
    '                )\n'
    '                points.append(point)\n'
    '                last_position = point\n'
    '                continue\n'
    '            if tag in {"EC1", "EC2", "DEP", "RAW"}:\n'
    '                if tag == "RAW" and "$" in line:\n'
    '                    sentence = line[line.find("$"):]\n'
    '                    parsed = parse_nmea_sentence(sentence)\n'
    '                    if parsed is None:\n'
    '                        continue\n'
    '                    parsed.source = f"{path.name}:{line_no}"\n'
    '                    parsed.time = parsed.time or hypack_time_to_display(parts[2] if len(parts) > 2 else "")\n'
    '                    if parsed.latitude is not None and parsed.longitude is not None:\n'
    '                        ensure_projected_xy(parsed, GeodeticSettings())\n'
    '                        parsed.tide = last_tide\n'
    '                        points.append(parsed)\n'
    '                        last_position = parsed\n'
    '                    elif parsed.raw_depth is not None:\n'
    '                        point = parsed\n'
    '                        point.tide = last_tide\n'
    '                        if last_position is not None:\n'
    '                            point.easting = last_position.easting\n'
    '                            point.northing = last_position.northing\n'
    '                            point.latitude = last_position.latitude\n'
    '                            point.longitude = last_position.longitude\n'
    '                            point.altitude_m = last_position.altitude_m\n'
    '                            point.quality = last_position.quality\n'
    '                        points.append(point)\n'
    '                    continue\n'
    '                if tag == "RAW" and len(parts) >= 3:\n'
    '                    depth = parse_float(parts[2])\n'
    '                    time_text = parts[1]\n'
    '                elif len(parts) >= 4:\n'
    '                    depth = parse_float(parts[3])\n'
    '                    time_text = parts[2]\n'
    '                else:\n'
    '                    continue\n'
    '                if depth is None:\n'
    '                    continue\n'
    '                if last_position is not None and last_position.raw_depth is None:\n'
    '                    last_position.raw_depth = depth\n'
    '                    last_position.time = last_position.time or hypack_time_to_display(time_text)\n'
    '                    last_position.tide = last_tide\n'
    '                else:\n'
    '                    point = SurveyPoint(\n'
    '                        time=hypack_time_to_display(time_text),\n'
    '                        raw_depth=depth,\n'
    '                        tide=last_tide,\n'
    '                        source=f"{path.name}:{line_no}",\n'
    '                    )\n'
    '                    if last_position is not None:\n'
    '                        point.easting = last_position.easting\n'
    '                        point.northing = last_position.northing\n'
    '                        point.latitude = last_position.latitude\n'
    '                        point.longitude = last_position.longitude\n'
    '                        point.altitude_m = last_position.altitude_m\n'
    '                    points.append(point)\n'
    '    return points\n'
    '\n'
    '\n'
    'def load_hypack_edited_points(path: Path) -> list[SurveyPoint]:\n'
    '    points: list[SurveyPoint] = []\n'
    '    in_data = False\n'
    '    with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '        for line_no, raw_line in enumerate(handle, 1):\n'
    '            line = raw_line.strip()\n'
    '            if not line:\n'
    '                continue\n'
    '            if line.upper().startswith("EOH"):\n'
    '                in_data = True\n'
    '                continue\n'
    '            if not in_data and re.match(r"^[A-Z]{2,4}\\b", line, re.I):\n'
    '                continue\n'
    '            row = [item.strip() for item in line.split(",")]\n'
    '            if len(row) < 5:\n'
    '                continue\n'
    '            x = parse_float(row[1])\n'
    '            y = parse_float(row[2])\n'
    '            depth = parse_float(row[4])\n'
    '            if x is None or y is None or depth is None:\n'
    '                continue\n'
    '            tide = parse_float(row[10]) if len(row) > 10 else None\n'
    '            points.append(\n'
    '                SurveyPoint(\n'
    '                    time=row[3],\n'
    '                    easting=x,\n'
    '                    northing=y,\n'
    '                    raw_depth=depth,\n'
    '                    tide=tide or 0.0,\n'
    '                    quality=row[0],\n'
    '                    source=f"{path.name}:{line_no}",\n'
    '                )\n'
    '            )\n'
    '    return points\n'
    '\n'
    '\n'
    'def load_hypack_tide_file(path: Path) -> list[tuple[int, float]]:\n'
    '    """Load simple HYPACK-style tide files plus manual TID/TDX date,time,height rows."""\n'
    '    values: list[tuple[int, float]] = []\n'
    '    with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '        for index, line in enumerate(handle):\n'
    '            text = line.strip()\n'
    '            if not text or text.startswith("#") or text.startswith(";"):\n'
    '                continue\n'
    '            lowered = text.lower()\n'
    '            if lowered.startswith("date") or lowered.startswith("time"):\n'
    '                continue\n'
    '            parts = [part for part in re.split(r"[,\\t ]+", text) if part]\n'
    '            if not parts:\n'
    '                continue\n'
    '            if parts[0].upper() == "TID" and len(parts) >= 4:\n'
    '                value = parse_float(parts[3])\n'
    '            else:\n'
    '                numeric = [parse_float(part) for part in parts]\n'
    '                numeric = [value for value in numeric if value is not None]\n'
    '                value = numeric[-1] if numeric else parse_float(text)\n'
    '            if value is None:\n'
    '                continue\n'
    '            # Legacy one-number HYPACK tide rows are commonly stored as centimeters.\n'
    '            if len(parts) == 1 and abs(value) > 50:\n'
    '                value = value / 100.0\n'
    '            values.append((len(values), float(value)))\n'
    '    return values\n'
    '\n'
    '\n'
    'def load_hypack_lnw(path: Path) -> list[RunLine]:\n'
    '    lines: list[RunLine] = []\n'
    '    current_points: list[tuple[float, float]] = []\n'
    '    current_name = ""\n'
    '    with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '        for raw_line in handle:\n'
    '            line = raw_line.strip()\n'
    '            if not line:\n'
    '                continue\n'
    '            parts = line.split()\n'
    '            tag = parts[0].upper()\n'
    '            if tag == "LIN":\n'
    '                current_points = []\n'
    '                current_name = ""\n'
    '            elif tag == "PTS" and len(parts) >= 3:\n'
    '                x = parse_float(parts[1])\n'
    '                y = parse_float(parts[2])\n'
    '                if x is not None and y is not None:\n'
    '                    current_points.append((x, y))\n'
    '            elif tag == "LNN" and len(parts) >= 2:\n'
    '                current_name = " ".join(parts[1:]).strip(\'"\')\n'
    '            elif tag == "EOL":\n'
    '                if len(current_points) >= 2:\n'
    '                    start = current_points[0]\n'
    '                    end = current_points[-1]\n'
    '                    lines.append(RunLine(current_name or str(len(lines) + 1), start[0], start[1], end[0], end[1]))\n'
    '                current_points = []\n'
    '                current_name = ""\n'
    '    return lines\n'
    '\n'
    '\n'
    'def write_hypack_lnw(path: Path, lines: list[RunLine]) -> int:\n'
    '    with path.open("w", encoding="utf-8", newline="\\n") as handle:\n'
    '        handle.write(f"LNS {len(lines)}\\n")\n'
    '        for index, line in enumerate(lines, 1):\n'
    '            name = line.name or str(index)\n'
    '            handle.write("LIN 2\\n")\n'
    '            handle.write(f"PTS {line.start_x:.2f} {line.start_y:.2f}\\n")\n'
    '            handle.write(f"PTS {line.end_x:.2f} {line.end_y:.2f}\\n")\n'
    '            handle.write(f"LNN {name}\\n")\n'
    '            handle.write("EOL\\n")\n'
    '    return len(lines)\n'
    '\n'
    '\n'
    'def load_hypack_brd(path: Path) -> list[MapShape]:\n'
    '    points = load_hypack_brd_points(path)\n'
    '    if len(points) < 2:\n'
    '        return []\n'
    '    return [MapShape("line", points, text=path.stem, color="#0f766e", width=2)]\n'
    '\n'
    '\n'
    '\n'
    'def load_hypack_brd_points(path: Path) -> list[tuple[float, float]]:\n'
    '    points: list[tuple[float, float]] = []\n'
    '    with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '        for line in handle:\n'
    '            parts = line.replace(",", " ").split()\n'
    '            if len(parts) < 2:\n'
    '                continue\n'
    '            x = parse_float(parts[0])\n'
    '            y = parse_float(parts[1])\n'
    '            if x is not None and y is not None:\n'
    '                points.append((float(x), float(y)))\n'
    '    return points\n'
    '\n'
    '\n'
    'def save_hypack_brd_points(path: Path, points: list[tuple[float, float]]) -> int:\n'
    '    with path.open("w", encoding="utf-8", newline="\\n") as handle:\n'
    '        for x, y in points:\n'
    '            handle.write(f"{float(x):010.2f} {float(y):011.2f}\\n")\n'
    '    return len(points)\n'
    '\n'
    '\n'
    'def point_in_polygon(x: float, y: float, polygon: list[tuple[float, float]]) -> bool:\n'
    '    if len(polygon) < 3:\n'
    '        return False\n'
    '    inside = False\n'
    '    j = len(polygon) - 1\n'
    '    for i, (xi, yi) in enumerate(polygon):\n'
    '        xj, yj = polygon[j]\n'
    '        intersects = ((yi > y) != (yj > y)) and (\n'
    '            x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-12) + xi\n'
    '        )\n'
    '        if intersects:\n'
    '            inside = not inside\n'
    '        j = i\n'
    '    return inside\n'
    '\n'
    '\n'
    'def _cross(ax: float, ay: float, bx: float, by: float) -> float:\n'
    '    return ax * by - ay * bx\n'
    '\n'
    '\n'
    'def clip_segment_by_polygon(\n'
    '    start: tuple[float, float],\n'
    '    end: tuple[float, float],\n'
    '    polygon: list[tuple[float, float]],\n'
    '    keep_inside: bool = True,\n'
    ') -> list[tuple[tuple[float, float], tuple[float, float]]]:\n'
    '    if len(polygon) < 3:\n'
    '        return []\n'
    '    x1, y1 = start\n'
    '    x2, y2 = end\n'
    '    dx = x2 - x1\n'
    '    dy = y2 - y1\n'
    '    if abs(dx) < 1e-12 and abs(dy) < 1e-12:\n'
    '        return []\n'
    '    t_values = [0.0, 1.0]\n'
    '    ring = polygon[:]\n'
    '    if ring[0] != ring[-1]:\n'
    '        ring.append(ring[0])\n'
    '    for (x3, y3), (x4, y4) in zip(ring, ring[1:]):\n'
    '        ex = x4 - x3\n'
    '        ey = y4 - y3\n'
    '        denom = _cross(dx, dy, ex, ey)\n'
    '        if abs(denom) < 1e-12:\n'
    '            continue\n'
    '        qpx = x3 - x1\n'
    '        qpy = y3 - y1\n'
    '        t = _cross(qpx, qpy, ex, ey) / denom\n'
    '        u = _cross(qpx, qpy, dx, dy) / denom\n'
    '        if -1e-9 <= t <= 1.0 + 1e-9 and -1e-9 <= u <= 1.0 + 1e-9:\n'
    '            t_values.append(max(0.0, min(1.0, t)))\n'
    '    t_values = sorted(set(round(t, 12) for t in t_values))\n'
    '    pieces: list[tuple[tuple[float, float], tuple[float, float]]] = []\n'
    '    for t0, t1 in zip(t_values, t_values[1:]):\n'
    '        if t1 - t0 <= 1e-9:\n'
    '            continue\n'
    '        tm = (t0 + t1) / 2.0\n'
    '        mx = x1 + dx * tm\n'
    '        my = y1 + dy * tm\n'
    '        inside = point_in_polygon(mx, my, polygon)\n'
    '        if inside == keep_inside:\n'
    '            pieces.append(((x1 + dx * t0, y1 + dy * t0), (x1 + dx * t1, y1 + dy * t1)))\n'
    '    return pieces\n'
    '\n'
    '\n'
    'def clip_runlines_to_polygon(\n'
    '    lines: list[RunLine],\n'
    '    polygon: list[tuple[float, float]],\n'
    '    keep_inside: bool = True,\n'
    ') -> list[RunLine]:\n'
    '    clipped: list[RunLine] = []\n'
    '    for line in lines:\n'
    '        pieces = clip_segment_by_polygon(\n'
    '            (line.start_x, line.start_y),\n'
    '            (line.end_x, line.end_y),\n'
    '            polygon,\n'
    '            keep_inside=keep_inside,\n'
    '        )\n'
    '        for index, (start, end) in enumerate(pieces, 1):\n'
    '            suffix = "" if len(pieces) == 1 else f"_{index}"\n'
    '            clipped.append(RunLine(f"{line.name}{suffix}", start[0], start[1], end[0], end[1], line.enabled))\n'
    '    return clipped\n'
    '\n'
    '\n'
    'def clip_map_shapes_to_polygon(\n'
    '    shapes: list[MapShape],\n'
    '    polygon: list[tuple[float, float]],\n'
    '    keep_inside: bool = True,\n'
    ') -> list[MapShape]:\n'
    '    clipped: list[MapShape] = []\n'
    '    for shape in shapes:\n'
    '        if shape.kind.lower() != "line" or len(shape.points) < 2:\n'
    '            kept_points = [\n'
    '                (float(x), float(y))\n'
    '                for x, y in shape.points\n'
    '                if point_in_polygon(float(x), float(y), polygon) == keep_inside\n'
    '            ]\n'
    '            if kept_points:\n'
    '                clipped.append(MapShape(shape.kind, kept_points, text=shape.text, color=shape.color, width=shape.width, attrs=dict(shape.attrs)))\n'
    '            continue\n'
    '\n'
    '        pieces: list[tuple[tuple[float, float], tuple[float, float]]] = []\n'
    '        for start, end in zip(shape.points, shape.points[1:]):\n'
    '            pieces.extend(\n'
    '                clip_segment_by_polygon(\n'
    '                    (float(start[0]), float(start[1])),\n'
    '                    (float(end[0]), float(end[1])),\n'
    '                    polygon,\n'
    '                    keep_inside=keep_inside,\n'
    '                )\n'
    '            )\n'
    '        for index, (start, end) in enumerate(pieces, 1):\n'
    '            label = shape.text if len(pieces) == 1 else f"{shape.text}_{index}"\n'
    '            clipped.append(MapShape("line", [start, end], text=label, color=shape.color, width=shape.width, attrs=dict(shape.attrs)))\n'
    '    return clipped\n'
    '\n'
    '\n'
    'def clip_survey_points_to_polygon(\n'
    '    points: list[SurveyPoint],\n'
    '    polygon: list[tuple[float, float]],\n'
    '    keep_inside: bool = True,\n'
    ') -> list[SurveyPoint]:\n'
    '    clipped: list[SurveyPoint] = []\n'
    '    for point in points:\n'
    '        x = point.x\n'
    '        y = point.y\n'
    '        if x is None or y is None:\n'
    '            continue\n'
    '        if point_in_polygon(float(x), float(y), polygon) == keep_inside:\n'
    '            clipped.append(point)\n'
    '    return clipped\n'
    '\n'
    '\n'
    '\n'
    'DXF_COLOR_TABLE = {\n'
    '    1: "#ef4444", 2: "#f59e0b", 3: "#22c55e", 4: "#06b6d4",\n'
    '    5: "#2563eb", 6: "#d946ef", 7: "#e5e7eb", 8: "#64748b", 9: "#94a3b8",\n'
    '}\n'
    '\n'
    '\n'
    'CHART_BACKGROUND_COLOR = "#f8fbff"\n'
    'CHART_GRID_COLOR = "#b8c3c9"\n'
    'CHART_TEXT_COLOR = "#202020"\n'
    'CHART_LAND_FILL = "#f2c46d"\n'
    'CHART_BUILTUP_FILL = "#b89b57"\n'
    'CHART_SHALLOW_WATER_FILL = "#9ee7f2"\n'
    'CHART_VERY_SHALLOW_FILL = "#78d7e8"\n'
    'CHART_DEEP_WATER_FILL = "#fbfdff"\n'
    'CHART_DEPTH_CONTOUR = "#72bfe8"\n'
    'CHART_COASTLINE = "#106f8b"\n'
    'CHART_MAGENTA = "#ff4dff"\n'
    'CHART_BROWN = "#8e7040"\n'
    '\n'
    '\n'
    'ENC_LAYER_STYLE = {\n'
    '    "ACHARE": (CHART_MAGENTA, 1),\n'
    '    "ADMARE": (CHART_MAGENTA, 1),\n'
    '    "BCNCAR": ("#111111", 2),\n'
    '    "BCNISD": ("#111111", 2),\n'
    '    "BCNLAT": ("#111111", 2),\n'
    '    "BCNSAW": ("#111111", 2),\n'
    '    "BCNSPP": ("#111111", 2),\n'
    '    "BOYCAR": ("#f97316", 2),\n'
    '    "BOYINB": ("#f97316", 2),\n'
    '    "BOYLAT": ("#22c55e", 2),\n'
    '    "BOYSAW": ("#ef4444", 2),\n'
    '    "BOYSPP": ("#facc15", 2),\n'
    '    "BRIDGE": ("#5f4a26", 2),\n'
    '    "BUAARE": ("#8d7746", 1),\n'
    '    "CBLARE": (CHART_MAGENTA, 1),\n'
    '    "CBLSUB": (CHART_MAGENTA, 1),\n'
    '    "COALNE": (CHART_COASTLINE, 2),\n'
    '    "DEPARE": (CHART_DEPTH_CONTOUR, 1),\n'
    '    "DEPCNT": (CHART_DEPTH_CONTOUR, 1),\n'
    '    "DRGARE": ("#7dd3fc", 1),\n'
    '    "FAIRWY": (CHART_MAGENTA, 1),\n'
    '    "FERYRT": (CHART_MAGENTA, 1),\n'
    '    "HRBARE": ("#7dd3fc", 1),\n'
    '    "LAKARE": (CHART_SHALLOW_WATER_FILL, 1),\n'
    '    "LIGHTS": (CHART_MAGENTA, 2),\n'
    '    "LNDARE": (CHART_COASTLINE, 2),\n'
    '    "LNDELV": (CHART_BROWN, 1),\n'
    '    "LNDMRK": ("#111111", 2),\n'
    '    "M_COVR": ("#999999", 1),\n'
    '    "M_NSYS": (CHART_MAGENTA, 1),\n'
    '    "NAVLNE": (CHART_MAGENTA, 1),\n'
    '    "OBSTRN": ("#111111", 2),\n'
    '    "PILPNT": ("#5f4a26", 1),\n'
    '    "PIPARE": (CHART_MAGENTA, 1),\n'
    '    "PIPSOL": (CHART_MAGENTA, 1),\n'
    '    "RESARE": (CHART_MAGENTA, 1),\n'
    '    "ROADWY": (CHART_BROWN, 1),\n'
    '    "SBDARE": ("#7dd3fc", 1),\n'
    '    "SEAARE": (CHART_DEPTH_CONTOUR, 1),\n'
    '    "SILTNK": ("#111111", 2),\n'
    '    "SLCONS": ("#5f4a26", 2),\n'
    '    "SOUNDG": (CHART_TEXT_COLOR, 1),\n'
    '    "TSELNE": (CHART_MAGENTA, 1),\n'
    '    "TSSBND": (CHART_MAGENTA, 1),\n'
    '    "TSSCRS": (CHART_MAGENTA, 1),\n'
    '    "TSSLPT": (CHART_MAGENTA, 1),\n'
    '    "TSSRON": (CHART_MAGENTA, 1),\n'
    '    "UWTROC": ("#111111", 2),\n'
    '    "WRECKS": ("#111111", 2),\n'
    '}\n'
    '\n'
    'S57_COLOUR_TABLE = {\n'
    '    1: "#ffffff", 2: "#111111", 3: "#ef4444", 4: "#22c55e",\n'
    '    5: "#2563eb", 6: "#facc15", 7: "#9ca3af", 8: CHART_BROWN,\n'
    '    9: "#f59e0b", 10: CHART_MAGENTA, 11: "#f97316", 12: CHART_MAGENTA, 13: "#ff99ff",\n'
    '}\n'
    '\n'
    'S57_OBJECT_CLASS_BY_CODE = {\n'
    '    1: "ADMARE", 4: "ACHARE", 5: "BCNCAR", 6: "BCNISD", 7: "BCNLAT", 8: "BCNSAW",\n'
    '    9: "BCNSPP", 11: "BRIDGE", 13: "BUAARE", 14: "BOYCAR", 15: "BOYINB",\n'
    '    17: "BOYLAT", 18: "BOYSAW", 19: "BOYSPP", 20: "CBLARE", 22: "CBLSUB",\n'
    '    30: "COALNE", 42: "DEPARE", 43: "DEPCNT", 46: "DRGARE", 51: "FAIRWY",\n'
    '    53: "FERYRT", 62: "HRBARE", 68: "LAKARE", 70: "LNDARE", 71: "LNDELV",\n'
    '    73: "LNDMRK", 74: "LIGHTS", 83: "MORFAC", 84: "NAVLNE", 85: "OBSTRN",\n'
    '    90: "PIPARE", 92: "PIPSOL", 95: "PRDARE", 108: "RESARE", 112: "ROADWY",\n'
    '    114: "SBDARE", 115: "SEAARE", 117: "SLCONS", 120: "SOUNDG", 135: "TOPMAR",\n'
    '    136: "TSELNE", 137: "TSSBND", 138: "TSSCRS", 139: "TSSLPT", 140: "TSSRON",\n'
    '    142: "UWTROC", 143: "UNSARE", 147: "WRECKS",\n'
    '}\n'
    '\n'
    '\n'
    'def dxf_color_from_aci(value: object, fallback: str = "#94a3b8") -> str:\n'
    '    try:\n'
    '        return DXF_COLOR_TABLE.get(int(float(str(value))), fallback)\n'
    '    except Exception:\n'
    '        return fallback\n'
    '\n'
    '\n'
    'def s57_colour_from_attr(value: object, fallback: str) -> str:\n'
    '    if value in (None, ""):\n'
    '        return fallback\n'
    '    text = str(value).replace(",", " ").replace(";", " ")\n'
    '    for token in text.split():\n'
    '        parsed = parse_float(token)\n'
    '        if parsed is not None:\n'
    '            colour = S57_COLOUR_TABLE.get(int(parsed))\n'
    '            if colour:\n'
    '                return colour\n'
    '    return fallback\n'
    '\n'
    '\n'
    'def enc_object_class(layer_name: str, attrs: dict[str, object]) -> str:\n'
    '    layer = str(layer_name or attrs.get("LAYER") or "").upper()\n'
    '    if layer and not layer.isdigit() and layer not in {"ISOLATEDNODE", "CONNECTEDNODE", "EDGE", "FACE"}:\n'
    '        return layer\n'
    '    objl = parse_float(attrs.get("OBJL"))\n'
    '    if objl is not None:\n'
    '        return S57_OBJECT_CLASS_BY_CODE.get(int(objl), str(int(objl)))\n'
    '    return layer or str(attrs.get("OBJL") or "").upper()\n'
    '\n'
    '\n'
    'def enc_depth_area_color(attrs: dict[str, object], fallback: str = CHART_DEEP_WATER_FILL) -> str:\n'
    '    shallow = parse_float(attrs.get("DRVAL1"))\n'
    '    deep = parse_float(attrs.get("DRVAL2"))\n'
    '    value = deep if deep is not None else shallow\n'
    '    if value is None:\n'
    '        return fallback\n'
    '    if value <= 2.0:\n'
    '        return CHART_VERY_SHALLOW_FILL\n'
    '    if value <= 5.0:\n'
    '        return CHART_SHALLOW_WATER_FILL\n'
    '    if value <= 10.0:\n'
    '        return "#c9f3f8"\n'
    '    if value <= 20.0:\n'
    '        return "#effbff"\n'
    '    return CHART_DEEP_WATER_FILL\n'
    '\n'
    '\n'
    'def enc_style_for_feature(layer_name: str, attrs: dict[str, object]) -> tuple[str, int]:\n'
    '    name = enc_object_class(layer_name, attrs)\n'
    '    color = "#38bdf8"\n'
    '    width = 1\n'
    '    for key, style in ENC_LAYER_STYLE.items():\n'
    '        if name.startswith(key) or key in name:\n'
    '            color, width = style\n'
    '            break\n'
    '    if name.startswith("DEPARE"):\n'
    '        color = CHART_DEPTH_CONTOUR\n'
    '    elif name.startswith(("LNDARE", "BUAARE")):\n'
    '        color = CHART_COASTLINE if name.startswith("LNDARE") else "#7a663c"\n'
    '        width = max(width, 2 if name.startswith("LNDARE") else 1)\n'
    '    elif name.startswith(("OBSTRN", "WRECKS", "UWTROC")):\n'
    '        color = "#111111"\n'
    '        width = max(width, 2)\n'
    '    elif name.startswith(("SOUNDG",)):\n'
    '        color = CHART_TEXT_COLOR\n'
    '    elif name.startswith(("ACHARE", "RESARE", "CBL", "PIP", "TSS", "NAVLNE", "M_NSYS", "FAIRWY", "FERYRT")):\n'
    '        color = CHART_MAGENTA\n'
    '    elif name.startswith(("DEPCNT", "SEAARE", "SBDARE")):\n'
    '        color = CHART_DEPTH_CONTOUR\n'
    '    color = s57_colour_from_attr(attrs.get("COLOUR") or attrs.get("COLPAT"), color)\n'
    '    if attrs.get("VALSOU") not in (None, ""):\n'
    '        color = CHART_TEXT_COLOR if name.startswith("SOUNDG") else color\n'
    '        width = max(width, 2)\n'
    '    return color, width\n'
    '\n'
    '\n'
    'def enc_fill_for_feature(layer_name: str, attrs: dict[str, object], stroke_color: str) -> str:\n'
    '    name = enc_object_class(layer_name, attrs)\n'
    '    if name.startswith("DEPARE"):\n'
    '        return enc_depth_area_color(attrs, CHART_DEEP_WATER_FILL)\n'
    '    if name.startswith("LNDARE"):\n'
    '        return CHART_LAND_FILL\n'
    '    if name.startswith("BUAARE"):\n'
    '        return CHART_BUILTUP_FILL\n'
    '    if name.startswith(("LAKARE", "HRBARE")):\n'
    '        return CHART_SHALLOW_WATER_FILL\n'
    '    if name.startswith(("DRGARE", "SBDARE", "SEAARE")):\n'
    '        return "#d7f7fb"\n'
    '    if name.startswith(("M_COVR", "FAIRWY", "ACHARE", "RESARE", "CBLARE", "PIPARE")):\n'
    '        return ""\n'
    '    if name.startswith(("OBSTRN", "WRECKS", "UWTROC")):\n'
    '        return ""\n'
    '    return ""\n'
    '\n'
    '\n'
    'def compact_feature_label(layer_name: str, attrs: dict[str, object]) -> str:\n'
    '    parts = [str(layer_name or "").strip()]\n'
    '    for key in ("OBJNAM", "LNAM", "INFORM", "NATSUR", "CATWRK", "CATOBS", "VALSOU", "DRVAL1", "DRVAL2", "COLOUR"):\n'
    '        value = attrs.get(key)\n'
    '        if value not in (None, ""):\n'
    '            parts.append(f"{key}={value}")\n'
    '    return " | ".join(item for item in parts if item)\n'
    '\n'
    'def enc_sound_display(attrs: dict[str, object]) -> str:\n'
    '    for key in ("VALSOU", "DEPTH", "SOUNDING", "ELEVAT"):\n'
    '        value = attrs.get(key)\n'
    '        parsed = parse_float(value)\n'
    '        if parsed is not None:\n'
    '            text = f"{parsed:.1f}".rstrip("0").rstrip(".")\n'
    '            return text\n'
    '    return ""\n'
    '\n'
    '\n'
    'def enc_is_magenta_overlay(shape: MapShape) -> bool:\n'
    '    name = enc_object_class(str(shape.attrs.get("LAYER") or shape.text or ""), shape.attrs)\n'
    '    return name.startswith(("ACHARE", "RESARE", "CBL", "PIP", "TSS", "NAVLNE", "M_NSYS", "FAIRWY", "FERYRT"))\n'
    '\n'
    '\n'
    'def enc_symbol_kind(shape: MapShape) -> str:\n'
    '    return enc_object_class(str(shape.attrs.get("LAYER") or shape.text or ""), shape.attrs)\n'
    '\n'
    '\n'
    '\n'
    'def full_feature_details(shape: MapShape) -> str:\n'
    '    lines = [\n'
    '        f"Feature: {shape.text or shape.kind}",\n'
    '        f"Type: {shape.kind}",\n'
    '        f"Colour: {shape.color}",\n'
    '        f"Points: {len(shape.points)}",\n'
    '        "",\n'
    '        "Attributes:",\n'
    '    ]\n'
    '    if shape.attrs:\n'
    '        for key in sorted(shape.attrs):\n'
    '            lines.append(f"{key}: {shape.attrs[key]}")\n'
    '    else:\n'
    '        lines.append("(No attributes available)")\n'
    '    return "\\n".join(lines)\n'
    '\n'
    '\n'
    'def arc_points(cx: float, cy: float, radius: float, start_deg: float, end_deg: float, steps: int = 32) -> list[tuple[float, float]]:\n'
    '    if radius <= 0:\n'
    '        return []\n'
    '    if end_deg < start_deg:\n'
    '        end_deg += 360.0\n'
    '    count = max(6, min(96, steps))\n'
    '    return [\n'
    '        (cx + math.cos(math.radians(start_deg + (end_deg - start_deg) * i / count)) * radius,\n'
    '         cy + math.sin(math.radians(start_deg + (end_deg - start_deg) * i / count)) * radius)\n'
    '        for i in range(count + 1)\n'
    '    ]\n'
    '\n'
    '\n'
    'def shape_bbox(shape: MapShape) -> Optional[tuple[float, float, float, float]]:\n'
    '    if not shape.points:\n'
    '        return None\n'
    '    xs = [float(x) for x, _y in shape.points]\n'
    '    ys = [float(y) for _x, y in shape.points]\n'
    '    return min(xs), min(ys), max(xs), max(ys)\n'
    '\n'
    '\n'
    'def bbox_intersects(a: tuple[float, float, float, float], b: tuple[float, float, float, float]) -> bool:\n'
    '    return not (a[2] < b[0] or a[0] > b[2] or a[3] < b[1] or a[1] > b[3])\n'
    '\n'
    '\n'
    '\n'
    'def ogr_geometry_points(geom: Any) -> list[tuple[float, float]]:\n'
    '    points: list[tuple[float, float]] = []\n'
    '    if geom is None:\n'
    '        return points\n'
    '    name = str(geom.GetGeometryName() or "").upper()\n'
    '    if name in {"POINT"}:\n'
    '        return [(float(geom.GetX()), float(geom.GetY()))]\n'
    '    if name in {"LINESTRING", "LINEARRING"}:\n'
    '        return [(float(geom.GetX(i)), float(geom.GetY(i))) for i in range(geom.GetPointCount())]\n'
    '    if name == "POLYGON":\n'
    '        ring = geom.GetGeometryRef(0)\n'
    '        return ogr_geometry_points(ring)\n'
    '    for idx in range(geom.GetGeometryCount()):\n'
    '        points.extend(ogr_geometry_points(geom.GetGeometryRef(idx)))\n'
    '    return points\n'
    '\n'
    '\n'
    'def load_ogr_cad_shapes(path: Path) -> list[MapShape]:\n'
    '    """Load CAD vector backgrounds through GDAL/OGR, primarily DWG when supported."""\n'
    '    try:\n'
    '        from osgeo import gdal, ogr  # type: ignore\n'
    '        ogr.UseExceptions()\n'
    '        gdal.UseExceptions()\n'
    '    except Exception as exc:\n'
    '        raise RuntimeError(\n'
    '            "DWG background loading requires GDAL/OGR Python bindings with CAD/DWG driver support."\n'
    '        ) from exc\n'
    '\n'
    '    dataset = gdal.OpenEx(str(path), gdal.OF_VECTOR)\n'
    '    if dataset is None:\n'
    '        dataset = ogr.Open(str(path))\n'
    '    if dataset is None:\n'
    '        raise RuntimeError(\n'
    '            "Could not open DWG/CAD file. This GDAL build may not include a DWG driver; export/save the drawing as DXF if DWG is not supported."\n'
    '        )\n'
    '\n'
    '    shapes: list[MapShape] = []\n'
    '    for layer_index in range(dataset.GetLayerCount()):\n'
    '        layer = dataset.GetLayerByIndex(layer_index)\n'
    '        if layer is None:\n'
    '            continue\n'
    '        layer_name = str(layer.GetName() or path.stem)\n'
    '        try:\n'
    '            layer.ResetReading()\n'
    '        except Exception:\n'
    '            pass\n'
    '        for feature in layer:\n'
    '            geom = feature.GetGeometryRef()\n'
    '            pts = ogr_geometry_points(geom)\n'
    '            if not pts:\n'
    '                continue\n'
    '            attrs: dict[str, object] = {"LAYER": layer_name, "SOURCE": path.name}\n'
    '            for idx in range(feature.GetFieldCount()):\n'
    '                field_def = feature.GetFieldDefnRef(idx)\n'
    '                if field_def is not None:\n'
    '                    name = str(field_def.GetName() or f"FIELD_{idx}")\n'
    '                    attrs[name] = feature.GetField(idx)\n'
    '            label = str(attrs.get("Layer") or attrs.get("LAYER") or layer_name)\n'
    '            geom_name = str(geom.GetGeometryName() if geom is not None else "").upper()\n'
    '            if len(pts) == 1:\n'
    '                shapes.append(MapShape("point", pts, text=label, color="#94a3b8", width=1, attrs=attrs))\n'
    '            elif geom_name == "POLYGON" and pts[0] != pts[-1]:\n'
    '                shapes.append(MapShape("line", pts + [pts[0]], text=label, color="#94a3b8", width=1, attrs=attrs))\n'
    '            else:\n'
    '                shapes.append(MapShape("line", pts, text=label, color="#94a3b8", width=1, attrs=attrs))\n'
    '    return shapes\n'
    '\n'
    '\n'
    'def load_cad_background_shapes(path: Path) -> list[MapShape]:\n'
    '    suffix = path.suffix.lower()\n'
    '    if suffix == ".dwg":\n'
    '        return load_ogr_cad_shapes(path)\n'
    '    if suffix == ".dxf":\n'
    '        try:\n'
    '            return load_dxf_shapes(path)\n'
    '        except Exception:\n'
    '            return load_ogr_cad_shapes(path)\n'
    '    return load_ogr_cad_shapes(path)\n'
    '\n'
    '\n'
    'def find_oda_file_converter() -> Optional[Path]:\n'
    '    """Return the ODA File Converter executable when it is available locally."""\n'
    '    candidates: list[Path] = []\n'
    '    path_hit = shutil.which("ODAFileConverter.exe") or shutil.which("ODAFileConverter")\n'
    '    if path_hit:\n'
    '        candidates.append(Path(path_hit))\n'
    '    for base in (os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)")):\n'
    '        if not base:\n'
    '            continue\n'
    '        root = Path(base) / "ODA"\n'
    '        if root.exists():\n'
    '            candidates.extend(root.glob("ODAFileConverter*/ODAFileConverter.exe"))\n'
    '            candidates.extend(root.glob("**/ODAFileConverter.exe"))\n'
    '    for candidate in candidates:\n'
    '        try:\n'
    '            if candidate.exists():\n'
    '                return candidate\n'
    '        except Exception:\n'
    '            continue\n'
    '    return None\n'
    '\n'
    '\n'
    'def convert_dwg_to_dxf_with_oda(\n'
    '    dwg_path: Path,\n'
    '    output_folder: Optional[Path] = None,\n'
    '    version: str = "ACAD2018",\n'
    '    audit: bool = True,\n'
    ') -> Path:\n'
    '    """Convert one DWG to DXF through ODA, using a short temporary name for reliability."""\n'
    '    converter = find_oda_file_converter()\n'
    '    if converter is None:\n'
    '        raise RuntimeError(\n'
    '            "ODA File Converter was not found. Install ODA File Converter, then retry this conversion."\n'
    '        )\n'
    '    source = Path(dwg_path)\n'
    '    if source.suffix.lower() != ".dwg":\n'
    '        raise ValueError("Select a DWG file for ODA conversion.")\n'
    '    if not source.exists():\n'
    '        raise FileNotFoundError(str(source))\n'
    '    target_folder = Path(output_folder) if output_folder else source.parent\n'
    '    target_folder.mkdir(parents=True, exist_ok=True)\n'
    '    target_path = target_folder / f"{source.stem}.dxf"\n'
    '    with tempfile.TemporaryDirectory(prefix="HYDROGEOMATICS_oda_") as tmp_name:\n'
    '        tmp_root = Path(tmp_name)\n'
    '        tmp_in = tmp_root / "in"\n'
    '        tmp_out = tmp_root / "out"\n'
    '        tmp_in.mkdir()\n'
    '        tmp_out.mkdir()\n'
    '        safe_source = tmp_in / "source.dwg"\n'
    '        shutil.copy2(source, safe_source)\n'
    '        command = [\n'
    '            str(converter),\n'
    '            str(tmp_in),\n'
    '            str(tmp_out),\n'
    '            str(version or "ACAD2018"),\n'
    '            "DXF",\n'
    '            "0",\n'
    '            "1" if audit else "0",\n'
    '            "*.dwg",\n'
    '        ]\n'
    '        result = subprocess.run(command, capture_output=True, text=True, timeout=180)\n'
    '        converted = tmp_out / "source.dxf"\n'
    '        if result.returncode != 0 or not converted.exists():\n'
    '            detail = "\\n".join(part.strip() for part in (result.stdout, result.stderr) if part and part.strip())\n'
    '            raise RuntimeError(detail or f"ODA conversion failed for {source.name}.")\n'
    '        shutil.copy2(converted, target_path)\n'
    '    return target_path\n'
    '\n'
    '\n'
    'def load_dxf_shapes(path: Path) -> list[MapShape]:\n'
    '    try:\n'
    '        import ezdxf  # type: ignore\n'
    '    except Exception:\n'
    '        ezdxf = None\n'
    '\n'
    '    if ezdxf is not None:\n'
    '        try:\n'
    '            doc = ezdxf.readfile(str(path))\n'
    '            shapes: list[MapShape] = []\n'
    '            for entity in doc.modelspace():\n'
    '                kind = entity.dxftype().upper()\n'
    '                color = dxf_color_from_aci(getattr(entity.dxf, "color", 8))\n'
    '                layer = str(getattr(entity.dxf, "layer", path.stem))\n'
    '                if kind == "LINE":\n'
    '                    start = entity.dxf.start\n'
    '                    end = entity.dxf.end\n'
    '                    shapes.append(MapShape("line", [(float(start.x), float(start.y)), (float(end.x), float(end.y))], text=layer, color=color, width=1))\n'
    '                elif kind in {"LWPOLYLINE", "POLYLINE"}:\n'
    '                    pts = [(float(p[0]), float(p[1])) for p in entity.get_points()] if kind == "LWPOLYLINE" else [(float(v.dxf.location.x), float(v.dxf.location.y)) for v in entity.vertices]\n'
    '                    if len(pts) >= 2:\n'
    '                        if bool(getattr(entity, "closed", False)) and pts[0] != pts[-1]:\n'
    '                            pts.append(pts[0])\n'
    '                        shapes.append(MapShape("line", pts, text=layer, color=color, width=1))\n'
    '                elif kind == "CIRCLE":\n'
    '                    c = entity.dxf.center\n'
    '                    pts = arc_points(float(c.x), float(c.y), float(entity.dxf.radius), 0.0, 360.0, 72)\n'
    '                    shapes.append(MapShape("line", pts, text=layer, color=color, width=1))\n'
    '                elif kind == "ARC":\n'
    '                    c = entity.dxf.center\n'
    '                    pts = arc_points(float(c.x), float(c.y), float(entity.dxf.radius), float(entity.dxf.start_angle), float(entity.dxf.end_angle), 48)\n'
    '                    shapes.append(MapShape("line", pts, text=layer, color=color, width=1))\n'
    '                elif kind == "POINT":\n'
    '                    p = entity.dxf.location\n'
    '                    shapes.append(MapShape("point", [(float(p.x), float(p.y))], text=layer, color=color, width=1))\n'
    '                elif kind in {"TEXT", "MTEXT"}:\n'
    '                    p = entity.dxf.insert\n'
    '                    label = str(entity.plain_text() if hasattr(entity, "plain_text") else entity.dxf.text)\n'
    '                    shapes.append(MapShape("text", [(float(p.x), float(p.y))], text=label, color=color, width=1))\n'
    '            if shapes:\n'
    '                return shapes\n'
    '        except Exception:\n'
    '            pass\n'
    '\n'
    '    raw_lines = path.read_text(encoding="utf-8", errors="replace").splitlines()\n'
    '    pairs: list[tuple[str, str]] = []\n'
    '    for index in range(0, len(raw_lines) - 1, 2):\n'
    '        pairs.append((raw_lines[index].strip(), raw_lines[index + 1].strip()))\n'
    '    shapes: list[MapShape] = []\n'
    '    i = 0\n'
    '    while i < len(pairs):\n'
    '        code, value = pairs[i]\n'
    '        entity = value.upper() if code == "0" else ""\n'
    '        if entity == "LINE":\n'
    '            data: dict[str, float] = {}\n'
    '            layer = path.stem\n'
    '            color = "#94a3b8"\n'
    '            i += 1\n'
    '            while i < len(pairs) and pairs[i][0] != "0":\n'
    '                key, item = pairs[i]\n'
    '                if key == "8":\n'
    '                    layer = item or layer\n'
    '                elif key == "62":\n'
    '                    color = dxf_color_from_aci(item, color)\n'
    '                elif key in {"10", "20", "11", "21"}:\n'
    '                    parsed = parse_float(item)\n'
    '                    if parsed is not None:\n'
    '                        data[key] = float(parsed)\n'
    '                i += 1\n'
    '            if {"10", "20", "11", "21"}.issubset(data):\n'
    '                shapes.append(MapShape("line", [(data["10"], data["20"]), (data["11"], data["21"])], text=layer, color=color, width=1))\n'
    '            continue\n'
    '        if entity in {"LWPOLYLINE", "POLYLINE"}:\n'
    '            pts: list[tuple[float, float]] = []\n'
    '            layer = path.stem\n'
    '            color = "#94a3b8"\n'
    '            pending_x: Optional[float] = None\n'
    '            i += 1\n'
    '            while i < len(pairs):\n'
    '                key, item = pairs[i]\n'
    '                if key == "0" and entity == "POLYLINE" and item.upper() == "VERTEX":\n'
    '                    vx = vy = None\n'
    '                    i += 1\n'
    '                    while i < len(pairs) and pairs[i][0] != "0":\n'
    '                        vkey, vitem = pairs[i]\n'
    '                        if vkey == "10":\n'
    '                            vx = parse_float(vitem)\n'
    '                        elif vkey == "20":\n'
    '                            vy = parse_float(vitem)\n'
    '                        i += 1\n'
    '                    if vx is not None and vy is not None:\n'
    '                        pts.append((float(vx), float(vy)))\n'
    '                    continue\n'
    '                if key == "0" and (entity == "LWPOLYLINE" or item.upper() == "SEQEND"):\n'
    '                    if entity == "POLYLINE":\n'
    '                        i += 1\n'
    '                    break\n'
    '                if key == "8":\n'
    '                    layer = item or layer\n'
    '                elif key == "62":\n'
    '                    color = dxf_color_from_aci(item, color)\n'
    '                elif key == "10":\n'
    '                    pending_x = parse_float(item)\n'
    '                elif key == "20" and pending_x is not None:\n'
    '                    parsed_y = parse_float(item)\n'
    '                    if parsed_y is not None:\n'
    '                        pts.append((float(pending_x), float(parsed_y)))\n'
    '                    pending_x = None\n'
    '                i += 1\n'
    '            if len(pts) >= 2:\n'
    '                shapes.append(MapShape("line", pts, text=layer, color=color, width=1))\n'
    '            continue\n'
    '        if entity in {"CIRCLE", "ARC"}:\n'
    '            data: dict[str, float] = {}\n'
    '            layer = path.stem\n'
    '            color = "#94a3b8"\n'
    '            i += 1\n'
    '            while i < len(pairs) and pairs[i][0] != "0":\n'
    '                key, item = pairs[i]\n'
    '                if key == "8":\n'
    '                    layer = item or layer\n'
    '                elif key == "62":\n'
    '                    color = dxf_color_from_aci(item, color)\n'
    '                elif key in {"10", "20", "40", "50", "51"}:\n'
    '                    parsed = parse_float(item)\n'
    '                    if parsed is not None:\n'
    '                        data[key] = float(parsed)\n'
    '                i += 1\n'
    '            if {"10", "20", "40"}.issubset(data):\n'
    '                pts = arc_points(data["10"], data["20"], data["40"], data.get("50", 0.0), data.get("51", 360.0), 72 if entity == "CIRCLE" else 48)\n'
    '                shapes.append(MapShape("line", pts, text=layer, color=color, width=1))\n'
    '            continue\n'
    '        if entity in {"POINT", "TEXT", "MTEXT"}:\n'
    '            data: dict[str, float] = {}\n'
    '            layer = path.stem\n'
    '            label = layer\n'
    '            color = "#94a3b8"\n'
    '            i += 1\n'
    '            while i < len(pairs) and pairs[i][0] != "0":\n'
    '                key, item = pairs[i]\n'
    '                if key == "8":\n'
    '                    layer = item or layer\n'
    '                elif key == "1":\n'
    '                    label = item or label\n'
    '                elif key == "62":\n'
    '                    color = dxf_color_from_aci(item, color)\n'
    '                elif key in {"10", "20"}:\n'
    '                    parsed = parse_float(item)\n'
    '                    if parsed is not None:\n'
    '                        data[key] = float(parsed)\n'
    '                i += 1\n'
    '            if {"10", "20"}.issubset(data):\n'
    '                shapes.append(MapShape("text" if entity != "POINT" else "point", [(data["10"], data["20"])], text=label, color=color, width=1))\n'
    '            continue\n'
    '        i += 1\n'
    '    return shapes\n'
    '\n'
    '\n'
    '\n'
    'def load_enc_s57_shapes(path: Path) -> list[MapShape]:\n'
    '    """Load ENC/S-57 features as colored plan-view background shapes."""\n'
    '    try:\n'
    '        from osgeo import gdal, ogr  # type: ignore\n'
    '        ogr.UseExceptions()\n'
    '        gdal.UseExceptions()\n'
    '    except Exception as exc:\n'
    '        raise RuntimeError(\n'
    '            "ENC/S-57 loading requires GDAL/OGR Python bindings. Install GDAL or run this build in an environment where osgeo.ogr is available."\n'
    '        ) from exc\n'
    '\n'
    '    open_options = [\n'
    '        "SPLIT_MULTIPOINT=ON",\n'
    '        "ADD_SOUNDG_DEPTH=ON",\n'
    '        "RETURN_PRIMITIVES=OFF",\n'
    '        "RETURN_LINKAGES=ON",\n'
    '        "LNAM_REFS=ON",\n'
    '        "LIST_AS_STRING=ON",\n'
    '        "PRESERVE_EMPTY_NUMBERS=ON",\n'
    '    ]\n'
    '    try:\n'
    '        dataset = gdal.OpenEx(str(path), gdal.OF_VECTOR, open_options=open_options)\n'
    '    except Exception:\n'
    '        dataset = ogr.Open(str(path))\n'
    '    if dataset is None:\n'
    '        raise RuntimeError(f"Could not open ENC/S-57 file: {path.name}")\n'
    '\n'
    '    shapes: list[MapShape] = []\n'
    '\n'
    '    def feature_attrs(feature: Any) -> dict[str, object]:\n'
    '        attrs: dict[str, object] = {}\n'
    '        try:\n'
    '            count = feature.GetFieldCount()\n'
    '        except Exception:\n'
    '            return attrs\n'
    '        for index in range(count):\n'
    '            try:\n'
    '                name = feature.GetFieldDefnRef(index).GetNameRef()\n'
    '                try:\n'
    '                    value = feature.GetFieldAsString(index)\n'
    '                except Exception:\n'
    '                    value = feature.GetField(index)\n'
    '            except Exception:\n'
    '                continue\n'
    '            if value not in (None, ""):\n'
    '                attrs[str(name)] = value\n'
    '        return attrs\n'
    '\n'
    '    def add_geometry(geom: Any, label: str, color: str, width: int, attrs: dict[str, object]) -> None:\n'
    '        if geom is None:\n'
    '            return\n'
    '        gtype = geom.GetGeometryName().upper()\n'
    '        if gtype in {"POINT", "MULTIPOINT"}:\n'
    '            if gtype == "POINT":\n'
    '                shapes.append(MapShape("point", [(float(geom.GetX()), float(geom.GetY()))], text=label, color=color, width=max(1, width), attrs=dict(attrs)))\n'
    '            else:\n'
    '                for idx in range(geom.GetGeometryCount()):\n'
    '                    add_geometry(geom.GetGeometryRef(idx), label, color, width, attrs)\n'
    '            return\n'
    '        if gtype in {"LINESTRING", "LINEARRING"}:\n'
    '            pts = [(float(geom.GetX(i)), float(geom.GetY(i))) for i in range(geom.GetPointCount())]\n'
    '            if len(pts) >= 2:\n'
    '                shapes.append(MapShape("line", pts, text=label, color=color, width=max(1, width), attrs=dict(attrs)))\n'
    '            return\n'
    '        if gtype == "POLYGON":\n'
    '            for ring_index in range(geom.GetGeometryCount()):\n'
    '                ring = geom.GetGeometryRef(ring_index)\n'
    '                if ring is None:\n'
    '                    continue\n'
    '                pts = [(float(ring.GetX(i)), float(ring.GetY(i))) for i in range(ring.GetPointCount())]\n'
    '                if len(pts) >= 2:\n'
    '                    shape_attrs = dict(attrs)\n'
    '                    fill_color = enc_fill_for_feature(str(attrs.get("LAYER", "")), attrs, color)\n'
    '                    if fill_color:\n'
    '                        shape_attrs["FILL"] = fill_color\n'
    '                    shapes.append(MapShape("polygon", pts, text=label, color=color, width=max(1, width), attrs=shape_attrs))\n'
    '            return\n'
    '        for idx in range(geom.GetGeometryCount()):\n'
    '            add_geometry(geom.GetGeometryRef(idx), label, color, width, attrs)\n'
    '\n'
    '    for layer_index in range(dataset.GetLayerCount()):\n'
    '        layer = dataset.GetLayerByIndex(layer_index)\n'
    '        if layer is None:\n'
    '            continue\n'
    '        layer_name = layer.GetName() or path.stem\n'
    '        if layer_name.upper() in {"ISOLATEDNODE", "CONNECTEDNODE", "EDGE", "FACE"}:\n'
    '            continue\n'
    '        layer.ResetReading()\n'
    '        for feature in layer:\n'
    '            attrs = feature_attrs(feature)\n'
    '            attrs.setdefault("LAYER", layer_name)\n'
    '            attrs["OBJCLASS"] = enc_object_class(layer_name, attrs)\n'
    '            color, width = enc_style_for_feature(layer_name, attrs)\n'
    '            label = compact_feature_label(layer_name, attrs)\n'
    '            add_geometry(feature.GetGeometryRef(), label, color, width, attrs)\n'
    '    return shapes\n'
    '\n'
    '\n'
    'def _kml_escape(value: object) -> str:\n'
    '    return escape(str(value if value is not None else ""))\n'
    '\n'
    '\n'
    'def write_kmz(path: Path, placemarks: list[str]) -> None:\n'
    '    import zipfile\n'
    '    kml = """<?xml version=\\"1.0\\" encoding=\\"UTF-8\\"?>\n'
    '<kml xmlns=\\"http://www.opengis.net/kml/2.2\\">\n'
    '<Document>\n'
    '<name>HYDROGEOMATICS Export</name>\n'
    '{body}\n'
    '</Document>\n'
    '</kml>\n'
    '""".format(body="\\n".join(placemarks))\n'
    '    path = Path(path).with_suffix(".kmz")\n'
    '    with zipfile.ZipFile(path, "w", compression=zipfile.ZIP_DEFLATED) as archive:\n'
    '        archive.writestr("doc.kml", kml)\n'
    '\n'
    'def _kml_local_name(tag: str) -> str:\n'
    '    return tag.rsplit("}", 1)[-1].lower()\n'
    '\n'
    '\n'
    'def _kml_child_text(element: object, child_name: str) -> str:\n'
    '    for child in list(element):\n'
    '        if _kml_local_name(child.tag) == child_name.lower() and child.text:\n'
    '            return child.text.strip()\n'
    '    return ""\n'
    '\n'
    '\n'
    'def parse_kml_coordinates(text: str) -> list[tuple[float, float]]:\n'
    '    points: list[tuple[float, float]] = []\n'
    '    for token in str(text or "").replace("\\n", " ").replace("\\t", " ").split():\n'
    '        parts = token.split(",")\n'
    '        if len(parts) < 2:\n'
    '            continue\n'
    '        x = parse_float(parts[0])\n'
    '        y = parse_float(parts[1])\n'
    '        if x is not None and y is not None:\n'
    '            points.append((float(x), float(y)))\n'
    '    return points\n'
    '\n'
    '\n'
    'def load_kmz_shapes(path: Path) -> list[MapShape]:\n'
    '    import zipfile\n'
    '    import xml.etree.ElementTree as ET\n'
    '\n'
    '    path = Path(path)\n'
    '    if path.suffix.lower() == ".kmz":\n'
    '        with zipfile.ZipFile(path, "r") as archive:\n'
    '            names = archive.namelist()\n'
    '            kml_names = [name for name in names if name.lower().endswith(".kml")]\n'
    '            if not kml_names:\n'
    '                raise RuntimeError("KMZ does not contain a KML file.")\n'
    '            preferred = "doc.kml" if "doc.kml" in kml_names else kml_names[0]\n'
    '            root = ET.fromstring(archive.read(preferred))\n'
    '    else:\n'
    '        root = ET.fromstring(path.read_text(encoding="utf-8", errors="replace"))\n'
    '\n'
    '    shapes: list[MapShape] = []\n'
    '\n'
    '    def placemark_context(node: object) -> tuple[str, dict[str, object]]:\n'
    '        current = node\n'
    '        # ElementTree has no parent pointer, so this is filled during traversal below.\n'
    '        return path.stem, {"SOURCE": path.name}\n'
    '\n'
    '    def walk(element: object, current_name: str = "") -> None:\n'
    '        local = _kml_local_name(element.tag)\n'
    '        name_here = current_name\n'
    '        if local == "placemark":\n'
    '            name_here = _kml_child_text(element, "name") or current_name or path.stem\n'
    '        if local == "point":\n'
    '            coords = []\n'
    '            for child in list(element):\n'
    '                if _kml_local_name(child.tag) == "coordinates":\n'
    '                    coords = parse_kml_coordinates(child.text or "")\n'
    '                    break\n'
    '            if coords:\n'
    '                shapes.append(MapShape("point", [coords[0]], text=name_here or path.stem, color="#f97316", width=2, attrs={"SOURCE": path.name, "NAME": name_here}))\n'
    '        elif local == "linestring":\n'
    '            coords = []\n'
    '            for child in list(element):\n'
    '                if _kml_local_name(child.tag) == "coordinates":\n'
    '                    coords = parse_kml_coordinates(child.text or "")\n'
    '                    break\n'
    '            if len(coords) >= 2:\n'
    '                shapes.append(MapShape("line", coords, text=name_here or path.stem, color="#f97316", width=2, attrs={"SOURCE": path.name, "NAME": name_here}))\n'
    '        elif local in {"polygon", "linearring"}:\n'
    '            for child in list(element):\n'
    '                if _kml_local_name(child.tag) == "coordinates":\n'
    '                    coords = parse_kml_coordinates(child.text or "")\n'
    '                    if len(coords) >= 2:\n'
    '                        shapes.append(MapShape("line", coords, text=name_here or path.stem, color="#f59e0b", width=2, attrs={"SOURCE": path.name, "NAME": name_here, "KML_TYPE": local}))\n'
    '        elif local == "track":\n'
    '            coords = []\n'
    '            for child in list(element):\n'
    '                if _kml_local_name(child.tag) == "coord" and child.text:\n'
    '                    parts = child.text.split()\n'
    '                    if len(parts) >= 2:\n'
    '                        x = parse_float(parts[0])\n'
    '                        y = parse_float(parts[1])\n'
    '                        if x is not None and y is not None:\n'
    '                            coords.append((float(x), float(y)))\n'
    '            if len(coords) >= 2:\n'
    '                shapes.append(MapShape("line", coords, text=name_here or path.stem, color="#fb923c", width=2, attrs={"SOURCE": path.name, "NAME": name_here, "KML_TYPE": "gx:Track"}))\n'
    '        for child in list(element):\n'
    '            walk(child, name_here)\n'
    '\n'
    '    walk(root, path.stem)\n'
    '    return shapes\n'
    '\n'
    '\n'
    'def load_hypack_tgt(path: Path) -> list[MapShape]:\n'
    '    shapes: list[MapShape] = []\n'
    '    pattern = re.compile(r\'^GPT\\s+"([^"]*)"\\s+([+-]?\\d+(?:\\.\\d+)?)\\s+([+-]?\\d+(?:\\.\\d+)?)\', re.I)\n'
    '    with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '        for line in handle:\n'
    '            match = pattern.match(line.strip())\n'
    '            if not match:\n'
    '                continue\n'
    '            label, x_text, y_text = match.groups()\n'
    '            x = parse_float(x_text)\n'
    '            y = parse_float(y_text)\n'
    '            if x is not None and y is not None:\n'
    '                shapes.append(MapShape("point", [(x, y)], text=label, color="#dc2626", width=2))\n'
    '    return shapes\n'
    '\n'
    '\n'
    '\n'
    'def fit_cad_shapes_to_canvas(shapes: list[MapShape], width: int, height: int, margin: int = 40) -> list[MapShape]:\n'
    '    points = [point for shape in shapes for point in shape.points]\n'
    '    if not points:\n'
    '        return shapes\n'
    '    xs = [float(point[0]) for point in points]\n'
    '    ys = [float(point[1]) for point in points]\n'
    '    min_x, max_x = min(xs), max(xs)\n'
    '    min_y, max_y = min(ys), max(ys)\n'
    '    span_x = max(max_x - min_x, 1e-9)\n'
    '    span_y = max(max_y - min_y, 1e-9)\n'
    '    canvas_w = max(width - margin * 2, 1)\n'
    '    canvas_h = max(height - margin * 2, 1)\n'
    '    scale = min(canvas_w / span_x, canvas_h / span_y)\n'
    '    fitted: list[MapShape] = []\n'
    '    for shape in shapes:\n'
    '        fitted_points = [\n'
    '            (\n'
    '                margin + (float(x) - min_x) * scale,\n'
    '                height - margin - (float(y) - min_y) * scale,\n'
    '            )\n'
    '            for x, y in shape.points\n'
    '        ]\n'
    '        fitted.append(MapShape(shape.kind, fitted_points, text=shape.text, color=shape.color, width=shape.width, attrs=dict(shape.attrs)))\n'
    '    return fitted\n'
    '\n'
    '\n'
    'def is_hypack_raw_file(path: Path) -> bool:\n'
    '    if path.suffix.lower() != ".raw":\n'
    '        return False\n'
    '    try:\n'
    '        sample = path.read_text(encoding="utf-8", errors="replace")[:4096]\n'
    '    except Exception:\n'
    '        return False\n'
    '    return any(tag in sample for tag in ("\\nPOS ", "\\nEC1 ", "\\nTID ", "\\nEOH", "FTP "))\n'
    '\n'
    '\n'
    'def is_hypack_edited_file(path: Path) -> bool:\n'
    '    return path.suffix.lower() in {".1", ".2", ".3"} or re.match(r".*\\.\\d+$", path.name) is not None\n'
    '\n'
    '\n'
    'def parse_nmea_lat_lon(value: str, hemisphere: str) -> Optional[float]:\n'
    '    if not value:\n'
    '        return None\n'
    '    try:\n'
    '        raw = float(value)\n'
    '    except ValueError:\n'
    '        return None\n'
    '    degrees = int(raw // 100)\n'
    '    minutes = raw - degrees * 100\n'
    '    decimal = degrees + minutes / 60.0\n'
    '    if hemisphere.upper() in {"S", "W"}:\n'
    '        decimal = -decimal\n'
    '    return decimal\n'
    '\n'
    '\n'
    'def parse_nmea_sentence(sentence: str) -> Optional[SurveyPoint]:\n'
    '    text = sentence.strip()\n'
    '    if not text.startswith("$"):\n'
    '        return None\n'
    '    body = text.split("*", 1)[0]\n'
    '    parts = body.split(",")\n'
    '    kind = parts[0][-3:]\n'
    '    if kind == "GGA" and len(parts) >= 10:\n'
    '        return SurveyPoint(\n'
    '            time=parts[1],\n'
    '            latitude=parse_nmea_lat_lon(parts[2], parts[3]),\n'
    '            longitude=parse_nmea_lat_lon(parts[4], parts[5]),\n'
    '            quality=parts[6],\n'
    '            altitude_m=parse_float(parts[9]),\n'
    '        )\n'
    '    if kind == "RMC" and len(parts) >= 10:\n'
    '        return SurveyPoint(\n'
    '            time=parts[1],\n'
    '            latitude=parse_nmea_lat_lon(parts[3], parts[4]),\n'
    '            longitude=parse_nmea_lat_lon(parts[5], parts[6]),\n'
    '            quality=parts[2],\n'
    '            speed_knots=parse_float(parts[7]),\n'
    '            course_degrees=parse_float(parts[8]),\n'
    '        )\n'
    '    if kind in {"HDT", "THS"} and len(parts) >= 2:\n'
    '        return SurveyPoint(heading_degrees=parse_float(parts[1]))\n'
    '    if kind == "VTG" and len(parts) >= 6:\n'
    '        return SurveyPoint(course_degrees=parse_float(parts[1]), speed_knots=parse_float(parts[5]))\n'
    '    if kind in {"DBT", "DPT"}:\n'
    '        depth = None\n'
    '        if kind == "DBT" and len(parts) >= 5:\n'
    '            depth = parse_float(parts[3])\n'
    '        elif kind == "DPT" and len(parts) >= 2:\n'
    '            depth = parse_float(parts[1])\n'
    '        return SurveyPoint(raw_depth=depth)\n'
    '    return None\n'
    '\n'
    '\n'
    'def parse_sbes_sentence(sentence: str) -> dict[str, object]:\n'
    '    text = sentence.strip()\n'
    '    result: dict[str, object] = {"raw": text, "format": "", "depth": None}\n'
    '    if not text.startswith("$"):\n'
    '        return result\n'
    '    body = text.split("*", 1)[0]\n'
    '    parts = body.split(",")\n'
    '    kind = parts[0][-3:]\n'
    '    result["format"] = kind\n'
    '    if kind == "DPT" and len(parts) >= 2:\n'
    '        result["depth"] = parse_float(parts[1])\n'
    '        if len(parts) >= 3:\n'
    '            result["offset"] = parse_float(parts[2])\n'
    '    elif kind == "DBT" and len(parts) >= 5:\n'
    '        result["depth_feet"] = parse_float(parts[1])\n'
    '        result["depth"] = parse_float(parts[3])\n'
    '        if len(parts) >= 7:\n'
    '            result["depth_fathoms"] = parse_float(parts[5])\n'
    '    return result\n'
    '\n'
    '\n'
    'def load_nmea(path: Path) -> list[SurveyPoint]:\n'
    '    points: list[SurveyPoint] = []\n'
    '    current_position: Optional[SurveyPoint] = None\n'
    '    with path.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '        for line_no, line in enumerate(handle, 1):\n'
    '            parsed = parse_nmea_sentence(line)\n'
    '            if parsed is None:\n'
    '                continue\n'
    '            if parsed.latitude is not None and parsed.longitude is not None:\n'
    '                current_position = parsed\n'
    '                ensure_projected_xy(current_position, GeodeticSettings())\n'
    '                current_position.source = f"{path.name}:{line_no}"\n'
    '                points.append(current_position)\n'
    '            elif parsed.raw_depth is not None:\n'
    '                if current_position is None:\n'
    '                    parsed.source = f"{path.name}:{line_no}"\n'
    '                    points.append(parsed)\n'
    '                else:\n'
    '                    current_position.raw_depth = parsed.raw_depth\n'
    '    return points\n'
    '\n'
    '\n'
    'def run_nmea_report_cli(args: argparse.Namespace) -> int:\n'
    '    if not args.input:\n'
    '        raise SystemExit("--nmea-report requires an NMEA/log input file")\n'
    '    raw = Path(args.input[0]).read_text(encoding=args.encoding, errors="replace")\n'
    '    parser = NMEAParser()\n'
    '    parser.feed(raw)\n'
    '    if args.gpx:\n'
    '        export_gpx(parser.track, args.gpx, name=args.gpx_name)\n'
    '    payload = {\n'
    '        "last_position": gps_position_to_dict(parser.position),\n'
    '        "track_points": len(parser.track),\n'
    '        "satellites": [satellite.__dict__ for satellite in parser.satellites],\n'
    '    }\n'
    '    print(json.dumps(payload, indent=2))\n'
    '    return 0\n'
    '\n'
    '\n'
    'def run_checksum_cli(args: argparse.Namespace) -> int:\n'
    '    print(nmea_checksum_str(args.checksum))\n'
    '    if args.add_checksum:\n'
    '        print(add_nmea_checksum(args.checksum, terminator=False))\n'
    '    return 0\n'
    '\n'
    '\n'
    'def run_project_template_cli(args: argparse.Namespace) -> int:\n'
    '    project = HydroProject()\n'
    '    for item in args.input:\n'
    '        for point in load_points_from_any(Path(item)):\n'
    '            if point.x is None or point.y is None or point.raw_depth is None:\n'
    '                continue\n'
    '            project.bathymetry.append(\n'
    '                BathymetrySample(\n'
    '                    x=float(point.x),\n'
    '                    y=float(point.y),\n'
    '                    depth=float(point.raw_depth),\n'
    '                    time_utc=point.time or None,\n'
    '                    tide=args.tide,\n'
    '                    draft=args.draft,\n'
    '                    sound_velocity_mps=args.sound_speed,\n'
    '                    corrected_depth=point.corrected_depth,\n'
    '                )\n'
    '            )\n'
    '    output = Path(args.output if args.output != "BS_output.xyz" else "surveyplan_project.json")\n'
    '    if output.suffix.lower() != ".json":\n'
    '        output = output.with_suffix(".json")\n'
    '    save_project(output, project)\n'
    '    print(f"Saved SurveyPlan project template to {output}")\n'
    '    return 0\n'
    '\n'
    '\n'
    'def run_cli(args: argparse.Namespace) -> int:\n'
    '    if args.checksum:\n'
    '        return run_checksum_cli(args)\n'
    '    if args.nmea_report:\n'
    '        return run_nmea_report_cli(args)\n'
    '    if args.project_template:\n'
    '        return run_project_template_cli(args)\n'
    '    if args.settings_template:\n'
    '        output = Path(args.output if args.output != "BS_output.xyz" else "BS_settings.json")\n'
    '        AppSettings.defaults().save(output)\n'
    '        print(f"Saved settings template to {output}")\n'
    '        return 0\n'
    '    if args.generate_runlines:\n'
    '        return run_generate_runlines(args)\n'
    '    if args.navigate:\n'
    '        return run_navigation_cli(args)\n'
    '    if args.echogram:\n'
    '        return run_echogram_cli(args)\n'
    '\n'
    '    model = SurveyModel()\n'
    '    model.tide = args.tide\n'
    '    model.draft = args.draft\n'
    '    model.sound_speed = args.sound_speed\n'
    '    loaded_hypack_corrections = False\n'
    '    for item in args.input:\n'
    '        path = Path(item)\n'
    '        if is_hypack_raw_file(path) or is_hypack_edited_file(path):\n'
    '            loaded_hypack_corrections = True\n'
    '        if path.suffix.lower() in {".nmea", ".log"} and not is_hypack_raw_file(path):\n'
    '            for point in load_nmea(path):\n'
    '                model.add(point)\n'
    '        else:\n'
    '            model.load_file(path)\n'
    '    user_supplied_corrections = args.tide != 0.0 or args.draft != 0.0 or args.sound_speed != DEFAULT_SOUND_SPEED\n'
    '    if user_supplied_corrections or not loaded_hypack_corrections:\n'
    '        model.apply_offsets()\n'
    '    output = Path(args.output).with_suffix(".raw")\n'
    '    count = model.export_hypack_raw(output)\n'
    '    stats = model.stats()\n'
    '    print(f"Saved {count} HYPACK RAW records to {output}")\n'
    '    print(\n'
    '        "Depth stats:",\n'
    '        f"count={stats[\'count\']}",\n'
    '        f"min={format_number(stats[\'min\'])}",\n'
    '        f"max={format_number(stats[\'max\'])}",\n'
    '        f"mean={format_number(stats[\'mean\'])}",\n'
    '    )\n'
    '    return 0\n'
    '\n'
    '\n'
    'def run_echogram_cli(args: argparse.Namespace) -> int:\n'
    '    if not args.input:\n'
    '        raise SystemExit("--echogram requires input survey, XYZ, CSV, NMEA, LOG, or matrix CSV files")\n'
    '    echogram = EchogramModel(max_depth=args.max_depth, depth_bins=args.depth_bins)\n'
    '    if args.matrix:\n'
    '        total = 0\n'
    '        for item in args.input:\n'
    '            total += echogram.load_matrix_csv(Path(item))\n'
    '        if total == 0:\n'
    '            raise SystemExit("No matrix samples found")\n'
    '    else:\n'
    '        points: list[SurveyPoint] = []\n'
    '        for item in args.input:\n'
    '            path = Path(item)\n'
    '            points.extend(load_nmea(path) if path.suffix.lower() in {".nmea", ".log"} else load_points_from_any(path))\n'
    '        echogram.build_from_points(points)\n'
    '    output = Path(args.output)\n'
    '    if output.suffix.lower() not in {".ppm", ".pnm"}:\n'
    '        output = output.with_suffix(".ppm")\n'
    '    count = echogram.export_ppm(output)\n'
    '    print(f"Saved acoustic waterfall with {count} pings to {output}")\n'
    '    return 0\n'
    '\n'
    '\n'
    'def run_generate_runlines(args: argparse.Namespace) -> int:\n'
    '    required = [args.start_x, args.start_y, args.end_x, args.end_y, args.spacing]\n'
    '    if any(value is None for value in required):\n'
    '        raise SystemExit("--generate-runlines requires --start-x --start-y --end-x --end-y --spacing")\n'
    '    runlines = RunLineSet()\n'
    '    runlines.generate_parallel(\n'
    '        start_x=args.start_x,\n'
    '        start_y=args.start_y,\n'
    '        end_x=args.end_x,\n'
    '        end_y=args.end_y,\n'
    '        spacing=args.spacing,\n'
    '        count_each_side=args.count_each_side,\n'
    '        prefix=args.prefix,\n'
    '        include_center=not args.no_center,\n'
    '    )\n'
    '    output = Path(args.output)\n'
    '    count = runlines.export_csv(output)\n'
    '    print(f"Saved {count} runlines to {output}")\n'
    '    return 0\n'
    '\n'
    '\n'
    'def run_navigation_cli(args: argparse.Namespace) -> int:\n'
    '    if args.line_file:\n'
    '        runlines = RunLineSet()\n'
    '        runlines.load_csv(Path(args.line_file))\n'
    '    else:\n'
    '        required = [args.start_x, args.start_y, args.end_x, args.end_y]\n'
    '        if any(value is None for value in required):\n'
    '            raise SystemExit("--navigate requires --line-file or --start-x --start-y --end-x --end-y")\n'
    '        runlines = RunLineSet()\n'
    '        runlines.add(RunLine(args.prefix or "RUNLINE", args.start_x, args.start_y, args.end_x, args.end_y))\n'
    '\n'
    '    if args.position:\n'
    '        x, y = parse_position_pair(args.position)\n'
    '        solution = runlines.nearest(x, y)\n'
    '        if solution is None:\n'
    '            raise SystemExit("No enabled runlines available")\n'
    '        print_navigation_solution(solution)\n'
    '        return 0\n'
    '\n'
    '    if not args.input:\n'
    '        raise SystemExit("--navigate requires --position or input survey/GPS files")\n'
    '\n'
    '    rows: list[dict[str, object]] = []\n'
    '    for item in args.input:\n'
    '        path = Path(item)\n'
    '        points = load_nmea(path) if path.suffix.lower() in {".nmea", ".log"} else load_points_from_any(path)\n'
    '        for point in points:\n'
    '            if point.x is None or point.y is None:\n'
    '                continue\n'
    '            solution = runlines.nearest(float(point.x), float(point.y))\n'
    '            if solution is None:\n'
    '                continue\n'
    '            rows.append(navigation_row(point, solution))\n'
    '\n'
    '    output = Path(args.output)\n'
    '    with output.open("w", encoding="utf-8", newline="") as handle:\n'
    '        fieldnames = [\n'
    '            "time",\n'
    '            "x",\n'
    '            "y",\n'
    '            "line",\n'
    '            "bearing_degrees",\n'
    '            "along_track",\n'
    '            "cross_track",\n'
    '            "side",\n'
    '            "distance_to_start",\n'
    '            "distance_to_end",\n'
    '            "percent_complete",\n'
    '            "nearest_x",\n'
    '            "nearest_y",\n'
    '            "source",\n'
    '        ]\n'
    '        writer = csv.DictWriter(handle, fieldnames=fieldnames)\n'
    '        writer.writeheader()\n'
    '        writer.writerows(rows)\n'
    '    print(f"Saved {len(rows)} realtime navigation rows to {output}")\n'
    '    return 0\n'
    '\n'
    '\n'
    'def load_points_from_any(path: Path) -> list[SurveyPoint]:\n'
    '    model = SurveyModel()\n'
    '    model.load_file(path)\n'
    '    return model.points\n'
    '\n'
    '\n'
    'def parse_position_pair(text: str) -> tuple[float, float]:\n'
    '    parts = text.replace(",", " ").split()\n'
    '    if len(parts) != 2:\n'
    '        raise SystemExit("--position must be \'x,y\' or \'x y\'")\n'
    '    return float(parts[0]), float(parts[1])\n'
    '\n'
    '\n'
    'def navigation_row(point: SurveyPoint, solution: NavigationSolution) -> dict[str, object]:\n'
    '    return {\n'
    '        "time": point.time,\n'
    '        "x": format_number(point.x),\n'
    '        "y": format_number(point.y),\n'
    '        "line": solution.line.name,\n'
    '        "bearing_degrees": f"{solution.line.bearing_degrees:.3f}",\n'
    '        "along_track": f"{solution.along_track:.3f}",\n'
    '        "cross_track": f"{solution.cross_track:.3f}",\n'
    '        "side": solution.side,\n'
    '        "distance_to_start": f"{solution.distance_to_start:.3f}",\n'
    '        "distance_to_end": f"{solution.distance_to_end:.3f}",\n'
    '        "percent_complete": f"{solution.percent_complete:.2f}",\n'
    '        "nearest_x": f"{solution.nearest_x:.3f}",\n'
    '        "nearest_y": f"{solution.nearest_y:.3f}",\n'
    '        "source": point.source,\n'
    '    }\n'
    '\n'
    '\n'
    'def print_navigation_solution(solution: NavigationSolution) -> None:\n'
    '    print(f"Line: {solution.line.name}")\n'
    '    print(f"Bearing: {solution.line.bearing_degrees:.3f} deg")\n'
    '    print(f"Along-track: {solution.along_track:.3f}")\n'
    '    print(f"Cross-track: {solution.cross_track:.3f} ({solution.side})")\n'
    '    print(f"Distance to start: {solution.distance_to_start:.3f}")\n'
    '    print(f"Distance to end: {solution.distance_to_end:.3f}")\n'
    '    print(f"Complete: {solution.percent_complete:.2f}%")\n'
    '\n'
    '\n'
    'def format_number(value: object) -> str:\n'
    '    if value is None:\n'
    '        return "-"\n'
    '    if isinstance(value, float):\n'
    '        return f"{value:.3f}"\n'
    '    return str(value)\n'
    '\n'
    '\n'
    '\n'
    '# ======================================================================\n'
    '# BEGIN GEODETIC_TOOLS_MERGE.py\n'
    '# Added from 0606finalV_surveyplan_merged.py and adapted for 0607 Tkinter UI.\n'
    '# Provides LLH/XYZ, UTM, and datum transformation utilities.\n'
    '# ======================================================================\n'
    '\n'
    'GT_DEG = math.pi / 180.0\n'
    'GT_ARCSEC = GT_DEG / 3600.0\n'
    '\n'
    '\n'
    'class GT_Ellipsoid:\n'
    '    def __init__(self, name: str, a: float, inv_f: float) -> None:\n'
    '        self.name = name\n'
    '        self.a = float(a)\n'
    '        self.inv_f = float(inv_f)\n'
    '\n'
    '    @property\n'
    '    def f(self) -> float:\n'
    '        return 1.0 / self.inv_f\n'
    '\n'
    '    @property\n'
    '    def e2(self) -> float:\n'
    '        return self.f * (2.0 - self.f)\n'
    '\n'
    '    @property\n'
    '    def ep2(self) -> float:\n'
    '        return self.e2 / (1.0 - self.e2)\n'
    '\n'
    '\n'
    'class GT_Datum:\n'
    '    def __init__(\n'
    '        self,\n'
    '        name: str,\n'
    '        ellipsoid: GT_Ellipsoid,\n'
    '        dx: float = 0.0,\n'
    '        dy: float = 0.0,\n'
    '        dz: float = 0.0,\n'
    '        rx_arcsec: float = 0.0,\n'
    '        ry_arcsec: float = 0.0,\n'
    '        rz_arcsec: float = 0.0,\n'
    '        scale_ppm: float = 0.0,\n'
    '    ) -> None:\n'
    '        self.name = name\n'
    '        self.ellipsoid = ellipsoid\n'
    '        self.dx = float(dx)\n'
    '        self.dy = float(dy)\n'
    '        self.dz = float(dz)\n'
    '        self.rx_arcsec = float(rx_arcsec)\n'
    '        self.ry_arcsec = float(ry_arcsec)\n'
    '        self.rz_arcsec = float(rz_arcsec)\n'
    '        self.scale_ppm = float(scale_ppm)\n'
    '\n'
    '\n'
    'GT_ELLIPSOIDS = {\n'
    '    "WGS84": GT_Ellipsoid("WGS84", 6378137.0, 298.257223563),\n'
    '    "GRS80": GT_Ellipsoid("GRS80", 6378137.0, 298.257222101),\n'
    '    "Airy1830": GT_Ellipsoid("Airy1830", 6377563.396, 299.3249646),\n'
    '    "Clarke1866": GT_Ellipsoid("Clarke1866", 6378206.4, 294.9786982),\n'
    '    "Clarke1880": GT_Ellipsoid("Clarke1880", 6378249.145, 293.465),\n'
    '    "International1924": GT_Ellipsoid("International1924", 6378388.0, 297.0),\n'
    '    "Bessel1841": GT_Ellipsoid("Bessel1841", 6377397.155, 299.1528128),\n'
    '    "Krassovsky1940": GT_Ellipsoid("Krassovsky1940", 6378245.0, 298.3),\n'
    '}\n'
    '\n'
    'GT_DATUMS = {\n'
    '    "WGS84": GT_Datum("WGS84", GT_ELLIPSOIDS["WGS84"]),\n'
    '    "NAD83": GT_Datum("NAD83", GT_ELLIPSOIDS["GRS80"]),\n'
    '    "ED50": GT_Datum("ED50", GT_ELLIPSOIDS["International1924"], -87.0, -98.0, -121.0),\n'
    '    "OSGB36": GT_Datum("OSGB36", GT_ELLIPSOIDS["Airy1830"], 446.448, -125.157, 542.060, 0.1502, 0.2470, 0.8421, -20.4894),\n'
    '    "NAD27": GT_Datum("NAD27", GT_ELLIPSOIDS["Clarke1866"], 8.0, -160.0, -176.0),\n'
    '}\n'
    '\n'
    '\n'
    'def GT_parse_angle(text: object) -> float:\n'
    '    s = str(text).strip().upper().replace(":", " ").replace("\'", " ").replace(\'"\', " ")\n'
    '    sign = -1.0 if ("S" in s or "W" in s) else 1.0\n'
    '    for ch in "NSEW":\n'
    '        s = s.replace(ch, " ")\n'
    '    parts = [p for p in s.split() if p]\n'
    '    if not parts:\n'
    '        raise ValueError("empty angle")\n'
    '    if len(parts) == 1:\n'
    '        return float(parts[0])\n'
    '    deg = abs(float(parts[0]))\n'
    '    minutes = float(parts[1]) if len(parts) > 1 else 0.0\n'
    '    seconds = float(parts[2]) if len(parts) > 2 else 0.0\n'
    '    if float(parts[0]) < 0:\n'
    '        sign = -1.0\n'
    '    return sign * (deg + minutes / 60.0 + seconds / 3600.0)\n'
    '\n'
    '\n'
    'def GT_format_dms(decimal_degree: float, is_lat: bool = True) -> str:\n'
    '    hemi = ("N" if decimal_degree >= 0 else "S") if is_lat else ("E" if decimal_degree >= 0 else "W")\n'
    '    value = abs(decimal_degree)\n'
    '    deg = int(value)\n'
    '    minutes_full = (value - deg) * 60.0\n'
    '    minutes = int(minutes_full)\n'
    '    seconds = (minutes_full - minutes) * 60.0\n'
    '    return f"{deg:02d} {minutes:02d} {seconds:09.6f}{hemi}"\n'
    '\n'
    '\n'
    'def GT_geodetic_to_ecef(lat_deg: float, lon_deg: float, h: float = 0.0, ellipsoid: Optional[GT_Ellipsoid] = None) -> tuple[float, float, float]:\n'
    '    ellipsoid = ellipsoid or GT_ELLIPSOIDS["WGS84"]\n'
    '    lat = lat_deg * GT_DEG\n'
    '    lon = lon_deg * GT_DEG\n'
    '    sin_lat = math.sin(lat)\n'
    '    cos_lat = math.cos(lat)\n'
    '    n = ellipsoid.a / math.sqrt(1.0 - ellipsoid.e2 * sin_lat * sin_lat)\n'
    '    x = (n + h) * cos_lat * math.cos(lon)\n'
    '    y = (n + h) * cos_lat * math.sin(lon)\n'
    '    z = (n * (1.0 - ellipsoid.e2) + h) * sin_lat\n'
    '    return x, y, z\n'
    '\n'
    '\n'
    'def GT_ecef_to_geodetic(x: float, y: float, z: float, ellipsoid: Optional[GT_Ellipsoid] = None) -> tuple[float, float, float]:\n'
    '    ellipsoid = ellipsoid or GT_ELLIPSOIDS["WGS84"]\n'
    '    lon = math.atan2(y, x)\n'
    '    p = math.hypot(x, y)\n'
    '    lat = math.atan2(z, p * (1.0 - ellipsoid.e2))\n'
    '    for _ in range(20):\n'
    '        sin_lat = math.sin(lat)\n'
    '        n = ellipsoid.a / math.sqrt(1.0 - ellipsoid.e2 * sin_lat * sin_lat)\n'
    '        h = p / max(math.cos(lat), 1e-30) - n\n'
    '        new_lat = math.atan2(z, p * (1.0 - ellipsoid.e2 * n / (n + h)))\n'
    '        if abs(new_lat - lat) < 1e-14:\n'
    '            lat = new_lat\n'
    '            break\n'
    '        lat = new_lat\n'
    '    sin_lat = math.sin(lat)\n'
    '    n = ellipsoid.a / math.sqrt(1.0 - ellipsoid.e2 * sin_lat * sin_lat)\n'
    '    h = p / max(math.cos(lat), 1e-30) - n\n'
    '    return lat / GT_DEG, lon / GT_DEG, h\n'
    '\n'
    '\n'
    'def GT_meridional_arc(lat_rad: float, ellipsoid: GT_Ellipsoid) -> float:\n'
    '    e2 = ellipsoid.e2\n'
    '    a = ellipsoid.a\n'
    '    return a * (\n'
    '        (1 - e2 / 4 - 3 * e2 ** 2 / 64 - 5 * e2 ** 3 / 256) * lat_rad\n'
    '        - (3 * e2 / 8 + 3 * e2 ** 2 / 32 + 45 * e2 ** 3 / 1024) * math.sin(2 * lat_rad)\n'
    '        + (15 * e2 ** 2 / 256 + 45 * e2 ** 3 / 1024) * math.sin(4 * lat_rad)\n'
    '        - (35 * e2 ** 3 / 3072) * math.sin(6 * lat_rad)\n'
    '    )\n'
    '\n'
    '\n'
    'def GT_utm_zone_from_lon(lon_deg: float) -> int:\n'
    '    return max(1, min(60, int((lon_deg + 180.0) // 6.0) + 1))\n'
    '\n'
    '\n'
    'def GT_utm_central_meridian(zone: int) -> float:\n'
    '    return (int(zone) - 1) * 6.0 - 180.0 + 3.0\n'
    '\n'
    '\n'
    'def GT_latlon_to_utm(lat_deg: float, lon_deg: float, ellipsoid: Optional[GT_Ellipsoid] = None, zone: Optional[int] = None) -> tuple[float, float, int, str]:\n'
    '    ellipsoid = ellipsoid or GT_ELLIPSOIDS["WGS84"]\n'
    '    if zone is None:\n'
    '        zone = GT_utm_zone_from_lon(lon_deg)\n'
    '    zone = max(1, min(60, int(zone)))\n'
    '    hemisphere = "N" if lat_deg >= 0 else "S"\n'
    '    k0 = 0.9996\n'
    '    lat = lat_deg * GT_DEG\n'
    '    lon = lon_deg * GT_DEG\n'
    '    lon0 = GT_utm_central_meridian(zone) * GT_DEG\n'
    '    e2 = ellipsoid.e2\n'
    '    ep2 = ellipsoid.ep2\n'
    '    n = ellipsoid.a / math.sqrt(1.0 - e2 * math.sin(lat) ** 2)\n'
    '    t = math.tan(lat) ** 2\n'
    '    c = ep2 * math.cos(lat) ** 2\n'
    '    a_term = math.cos(lat) * (lon - lon0)\n'
    '    m = GT_meridional_arc(lat, ellipsoid)\n'
    '    easting = k0 * n * (\n'
    '        a_term\n'
    '        + (1 - t + c) * a_term ** 3 / 6.0\n'
    '        + (5 - 18 * t + t * t + 72 * c - 58 * ep2) * a_term ** 5 / 120.0\n'
    '    ) + 500000.0\n'
    '    northing = k0 * (\n'
    '        m\n'
    '        + n * math.tan(lat) * (\n'
    '            a_term ** 2 / 2.0\n'
    '            + (5 - t + 9 * c + 4 * c * c) * a_term ** 4 / 24.0\n'
    '            + (61 - 58 * t + t * t + 600 * c - 330 * ep2) * a_term ** 6 / 720.0\n'
    '        )\n'
    '    )\n'
    '    if lat_deg < 0:\n'
    '        northing += 10000000.0\n'
    '    return easting, northing, zone, hemisphere\n'
    '\n'
    '\n'
    'def GT_utm_to_latlon(easting: float, northing: float, zone: int, hemisphere: str = "N", ellipsoid: Optional[GT_Ellipsoid] = None) -> tuple[float, float]:\n'
    '    ellipsoid = ellipsoid or GT_ELLIPSOIDS["WGS84"]\n'
    '    zone = max(1, min(60, int(zone)))\n'
    '    k0 = 0.9996\n'
    '    e2 = ellipsoid.e2\n'
    '    ep2 = ellipsoid.ep2\n'
    '    a = ellipsoid.a\n'
    '    x = easting - 500000.0\n'
    '    y = northing - (10000000.0 if str(hemisphere).upper().startswith("S") else 0.0)\n'
    '    m = y / k0\n'
    '    mu = m / (a * (1 - e2 / 4.0 - 3.0 * e2 ** 2 / 64.0 - 5.0 * e2 ** 3 / 256.0))\n'
    '    e1 = (1.0 - math.sqrt(1.0 - e2)) / (1.0 + math.sqrt(1.0 - e2))\n'
    '    fp = (\n'
    '        mu\n'
    '        + (3 * e1 / 2 - 27 * e1 ** 3 / 32) * math.sin(2 * mu)\n'
    '        + (21 * e1 ** 2 / 16 - 55 * e1 ** 4 / 32) * math.sin(4 * mu)\n'
    '        + (151 * e1 ** 3 / 96) * math.sin(6 * mu)\n'
    '        + (1097 * e1 ** 4 / 512) * math.sin(8 * mu)\n'
    '    )\n'
    '    sin_fp = math.sin(fp)\n'
    '    cos_fp = math.cos(fp)\n'
    '    t1 = math.tan(fp) ** 2\n'
    '    c1 = ep2 * cos_fp ** 2\n'
    '    r1 = a * (1 - e2) / (1 - e2 * sin_fp ** 2) ** 1.5\n'
    '    n1 = a / math.sqrt(1 - e2 * sin_fp ** 2)\n'
    '    d = x / (n1 * k0)\n'
    '    lat = fp - (n1 * math.tan(fp) / r1) * (\n'
    '        d ** 2 / 2\n'
    '        - (5 + 3 * t1 + 10 * c1 - 4 * c1 ** 2 - 9 * ep2) * d ** 4 / 24\n'
    '        + (61 + 90 * t1 + 298 * c1 + 45 * t1 ** 2 - 252 * ep2 - 3 * c1 ** 2) * d ** 6 / 720\n'
    '    )\n'
    '    lon0 = GT_utm_central_meridian(zone) * GT_DEG\n'
    '    lon = lon0 + (\n'
    '        d\n'
    '        - (1 + 2 * t1 + c1) * d ** 3 / 6\n'
    '        + (5 - 2 * c1 + 28 * t1 - 3 * c1 ** 2 + 8 * ep2 + 24 * t1 ** 2) * d ** 5 / 120\n'
    '    ) / cos_fp\n'
    '    return lat / GT_DEG, lon / GT_DEG\n'
    '\n'
    '\n'
    'def GT_apply_helmert7(x: float, y: float, z: float, datum: GT_Datum, inverse: bool = False) -> tuple[float, float, float]:\n'
    '    dx, dy, dz = datum.dx, datum.dy, datum.dz\n'
    '    rx = datum.rx_arcsec * GT_ARCSEC\n'
    '    ry = datum.ry_arcsec * GT_ARCSEC\n'
    '    rz = datum.rz_arcsec * GT_ARCSEC\n'
    '    s = datum.scale_ppm * 1e-6\n'
    '    if inverse:\n'
    '        dx, dy, dz, rx, ry, rz, s = -dx, -dy, -dz, -rx, -ry, -rz, -s\n'
    '    return (\n'
    '        dx + (1.0 + s) * x - rz * y + ry * z,\n'
    '        dy + rz * x + (1.0 + s) * y - rx * z,\n'
    '        dz - ry * x + rx * y + (1.0 + s) * z,\n'
    '    )\n'
    '\n'
    '\n'
    'def GT_datum_transform(lat_deg: float, lon_deg: float, h: float, source: GT_Datum, target: GT_Datum) -> tuple[float, float, float]:\n'
    '    x, y, z = GT_geodetic_to_ecef(lat_deg, lon_deg, h, source.ellipsoid)\n'
    '    xw, yw, zw = GT_apply_helmert7(x, y, z, source, inverse=False)\n'
    '    xt, yt, zt = GT_apply_helmert7(xw, yw, zw, target, inverse=True)\n'
    '    return GT_ecef_to_geodetic(xt, yt, zt, target.ellipsoid)\n'
    '\n'
    '\n'
    'def show_geodetic_tools_dialog(parent: Any = None) -> None:\n'
    '    """Open a compact Tkinter geodetic conversion toolbox."""\n'
    '    import tkinter as tk\n'
    '    from tkinter import messagebox, ttk\n'
    '\n'
    '    win = tk.Toplevel(parent) if parent is not None else tk.Tk()\n'
    '    win.title("GEOCALC")\n'
    '    win.geometry("920x620")\n'
    '\n'
    '    local_settings = load_app_settings()\n'
    '    current_project_folder = project_root_from_raw_folder(local_settings.raw_folder or str(default_raw_folder()))\n'
    '    project_options = discover_project_options()\n'
    '    if str(current_project_folder) not in project_options:\n'
    '        project_options.insert(0, str(current_project_folder))\n'
    '    grid_options = discover_grid_options(current_project_folder)\n'
    '\n'
    '    notebook = ttk.Notebook(win)\n'
    '    notebook.pack(fill="both", expand=True, padx=10, pady=10)\n'
    '\n'
    '    def show_error(exc: Exception) -> None:\n'
    '        messagebox.showerror("GEOCALC", str(exc), parent=win)\n'
    '\n'
    '    def set_text(widget: tk.Text, text: str) -> None:\n'
    '        widget.configure(state="normal")\n'
    '        widget.delete("1.0", "end")\n'
    '        widget.insert("1.0", text)\n'
    '        widget.configure(state="disabled")\n'
    '\n'
    '    # LLH / XYZ tab\n'
    '    llh_tab = ttk.Frame(notebook, padding=10)\n'
    '    notebook.add(llh_tab, text="LLH / XYZ")\n'
    '    lat_var = tk.StringVar(value="24.8607")\n'
    '    lon_var = tk.StringVar(value="67.0011")\n'
    '    h_var = tk.StringVar(value="0.0")\n'
    '    x_var = tk.StringVar()\n'
    '    y_var = tk.StringVar()\n'
    '    z_var = tk.StringVar()\n'
    '    result1 = tk.Text(llh_tab, height=12, width=42, state="disabled")\n'
    '    for r, (label, var) in enumerate([("Latitude", lat_var), ("Longitude", lon_var), ("Height", h_var), ("X", x_var), ("Y", y_var), ("Z", z_var)]):\n'
    '        ttk.Label(llh_tab, text=label).grid(row=r, column=0, sticky="e", padx=(0, 6), pady=3)\n'
    '        ttk.Entry(llh_tab, textvariable=var, width=28).grid(row=r, column=1, sticky="ew", pady=3)\n'
    '    result1.grid(row=0, column=2, rowspan=7, sticky="nsew", padx=(12, 0))\n'
    '    llh_tab.columnconfigure(1, weight=1)\n'
    '    llh_tab.columnconfigure(2, weight=1)\n'
    '\n'
    '    def llh_to_xyz() -> None:\n'
    '        try:\n'
    '            x, y, z = GT_geodetic_to_ecef(GT_parse_angle(lat_var.get()), GT_parse_angle(lon_var.get()), float(h_var.get() or 0.0))\n'
    '            x_var.set(f"{x:.4f}")\n'
    '            y_var.set(f"{y:.4f}")\n'
    '            z_var.set(f"{z:.4f}")\n'
    '            set_text(result1, f"X: {x:.4f}\\nY: {y:.4f}\\nZ: {z:.4f}")\n'
    '        except Exception as exc:\n'
    '            show_error(exc)\n'
    '\n'
    '    def xyz_to_llh() -> None:\n'
    '        try:\n'
    '            lat, lon, h = GT_ecef_to_geodetic(float(x_var.get()), float(y_var.get()), float(z_var.get()))\n'
    '            lat_var.set(f"{lat:.10f}")\n'
    '            lon_var.set(f"{lon:.10f}")\n'
    '            h_var.set(f"{h:.4f}")\n'
    '            set_text(result1, f"Latitude: {lat:.10f}\\nLongitude: {lon:.10f}\\nHeight: {h:.4f}\\n{GT_format_dms(lat, True)}\\n{GT_format_dms(lon, False)}")\n'
    '        except Exception as exc:\n'
    '            show_error(exc)\n'
    '\n'
    '    ttk.Button(llh_tab, text="LLH to XYZ", command=llh_to_xyz).grid(row=6, column=0, sticky="ew", pady=(8, 0))\n'
    '    ttk.Button(llh_tab, text="XYZ to LLH", command=xyz_to_llh).grid(row=6, column=1, sticky="ew", pady=(8, 0))\n'
    '\n'
    '    # UTM tab\n'
    '    utm_tab = ttk.Frame(notebook, padding=10)\n'
    '    notebook.add(utm_tab, text="UTM")\n'
    '    ulat_var = tk.StringVar(value="24.8607")\n'
    '    ulon_var = tk.StringVar(value="67.0011")\n'
    '    zone_var = tk.StringVar(value="Auto")\n'
    '    hemi_var = tk.StringVar(value="N")\n'
    '    east_var = tk.StringVar()\n'
    '    north_var = tk.StringVar()\n'
    '    result2 = tk.Text(utm_tab, height=12, width=42, state="disabled")\n'
    '    for r, (label, widget) in enumerate([\n'
    '        ("Latitude", ttk.Entry(utm_tab, textvariable=ulat_var, width=28)),\n'
    '        ("Longitude", ttk.Entry(utm_tab, textvariable=ulon_var, width=28)),\n'
    '        ("Zone", ttk.Entry(utm_tab, textvariable=zone_var, width=28)),\n'
    '        ("Hemisphere", ttk.Combobox(utm_tab, textvariable=hemi_var, values=["N", "S"], width=25, state="readonly")),\n'
    '        ("Easting", ttk.Entry(utm_tab, textvariable=east_var, width=28)),\n'
    '        ("Northing", ttk.Entry(utm_tab, textvariable=north_var, width=28)),\n'
    '    ]):\n'
    '        ttk.Label(utm_tab, text=label).grid(row=r, column=0, sticky="e", padx=(0, 6), pady=3)\n'
    '        widget.grid(row=r, column=1, sticky="ew", pady=3)\n'
    '    result2.grid(row=0, column=2, rowspan=7, sticky="nsew", padx=(12, 0))\n'
    '    utm_tab.columnconfigure(1, weight=1)\n'
    '    utm_tab.columnconfigure(2, weight=1)\n'
    '\n'
    '    def ll_to_utm() -> None:\n'
    '        try:\n'
    '            zone_text = zone_var.get().strip()\n'
    '            zone = None if not zone_text or zone_text.lower() == "auto" else int(zone_text)\n'
    '            e, n, zone_out, hemi = GT_latlon_to_utm(GT_parse_angle(ulat_var.get()), GT_parse_angle(ulon_var.get()), zone=zone)\n'
    '            east_var.set(f"{e:.4f}")\n'
    '            north_var.set(f"{n:.4f}")\n'
    '            zone_var.set(str(zone_out))\n'
    '            hemi_var.set(hemi)\n'
    '            set_text(result2, f"Easting: {e:.4f}\\nNorthing: {n:.4f}\\nZone: {zone_out}{hemi}")\n'
    '        except Exception as exc:\n'
    '            show_error(exc)\n'
    '\n'
    '    def utm_to_ll() -> None:\n'
    '        try:\n'
    '            lat, lon = GT_utm_to_latlon(float(east_var.get()), float(north_var.get()), int(zone_var.get()), hemi_var.get())\n'
    '            ulat_var.set(f"{lat:.10f}")\n'
    '            ulon_var.set(f"{lon:.10f}")\n'
    '            set_text(result2, f"Latitude: {lat:.10f}\\nLongitude: {lon:.10f}\\n{GT_format_dms(lat, True)}\\n{GT_format_dms(lon, False)}")\n'
    '        except Exception as exc:\n'
    '            show_error(exc)\n'
    '\n'
    '    ttk.Button(utm_tab, text="LL to UTM", command=ll_to_utm).grid(row=6, column=0, sticky="ew", pady=(8, 0))\n'
    '    ttk.Button(utm_tab, text="UTM to LL", command=utm_to_ll).grid(row=6, column=1, sticky="ew", pady=(8, 0))\n'
    '\n'
    '    # Datum / CRS tab\n'
    '    datum_tab = ttk.Frame(notebook, padding=10)\n'
    '    notebook.add(datum_tab, text="Datum")\n'
    '    src_var = tk.StringVar(value="WGS84")\n'
    '    dst_var = tk.StringVar(value="WGS84")\n'
    '    crs_options = (\n'
    '        ["WGS84 Geographic Lat/Lon"]\n'
    '        + [f"WGS84 / UTM Zone {zone}{hemi}" for hemi in ("N", "S") for zone in range(1, 61)]\n'
    '        + ["Lambert Conical Zone IA", "Lambert Conical Zone IIA", "Local Grid Shift"]\n'
    '    )\n'
    '    src_crs_var = tk.StringVar(value="WGS84 Geographic Lat/Lon")\n'
    '    dst_crs_var = tk.StringVar(value="WGS84 / UTM Zone 42N")\n'
    '    dlat_var = tk.StringVar(value="24.8607")\n'
    '    dlon_var = tk.StringVar(value="67.0011")\n'
    '    dh_var = tk.StringVar(value="0.0")\n'
    '    shift_e_var = tk.StringVar(value=str(getattr(local_settings.geodetic, "delta_x", 0.0)))\n'
    '    shift_n_var = tk.StringVar(value=str(getattr(local_settings.geodetic, "delta_y", 0.0)))\n'
    '    shift_h_var = tk.StringVar(value=str(getattr(local_settings.geodetic, "delta_z", 0.0)))\n'
    '    shift_scale_var = tk.StringVar(value=str(getattr(local_settings.geodetic, "delta_scale", 0.0)))\n'
    '    result3 = tk.Text(datum_tab, height=16, width=66, state="disabled")\n'
    '    rows = [\n'
    '        ("Source datum / CRS", ttk.Combobox(datum_tab, textvariable=src_crs_var, values=crs_options, state="readonly", width=34)),\n'
    '        ("Target datum / CRS", ttk.Combobox(datum_tab, textvariable=dst_crs_var, values=crs_options, state="readonly", width=34)),\n'
    '        ("Input 1: Latitude / Northing", ttk.Entry(datum_tab, textvariable=dlat_var)),\n'
    '        ("Input 2: Longitude / Easting", ttk.Entry(datum_tab, textvariable=dlon_var)),\n'
    '        ("Height", ttk.Entry(datum_tab, textvariable=dh_var)),\n'
    '        ("Local shift Easting/X", ttk.Entry(datum_tab, textvariable=shift_e_var)),\n'
    '        ("Local shift Northing/Y", ttk.Entry(datum_tab, textvariable=shift_n_var)),\n'
    '        ("Local shift Height/Z", ttk.Entry(datum_tab, textvariable=shift_h_var)),\n'
    '        ("Local scale ppm", ttk.Entry(datum_tab, textvariable=shift_scale_var)),\n'
    '    ]\n'
    '    for r, (label, widget) in enumerate(rows):\n'
    '        ttk.Label(datum_tab, text=label).grid(row=r, column=0, sticky="e", padx=(0, 6), pady=3)\n'
    '        widget.grid(row=r, column=1, sticky="ew", pady=3)\n'
    '    result3.grid(row=0, column=2, rowspan=10, sticky="nsew", padx=(12, 0))\n'
    '    datum_tab.columnconfigure(1, weight=1)\n'
    '    datum_tab.columnconfigure(2, weight=1)\n'
    '\n'
    '    def lambert_params(option: str) -> tuple[float, float, float, float, float, float]:\n'
    '        text = str(option).upper()\n'
    '        if "IIA" in text:\n'
    '            return 70.0, 28.0, 28.0, 28.0, 500000.0, 0.0\n'
    '        return 68.0, 24.0, 24.0, 24.0, 500000.0, 0.0\n'
    '\n'
    '    def crs_to_llh(option: str, input1: float, input2: float, height: float) -> tuple[float, float, float]:\n'
    '        text = str(option)\n'
    '        if text == "WGS84 Geographic Lat/Lon":\n'
    '            return input1, input2, height\n'
    '        match = re.search(r"UTM Zone\\s+(\\d+)([NS])", text, re.IGNORECASE)\n'
    '        if match:\n'
    '            lat, lon = GT_utm_to_latlon(float(input2), float(input1), int(match.group(1)), match.group(2).upper())\n'
    '            return lat, lon, height\n'
    '        if "Lambert Conical" in text:\n'
    '            cm, lat0, sp1, sp2, fe, fn = lambert_params(text)\n'
    '            lat, lon = lambert_conformal_conic_to_latlon(float(input2), float(input1), cm, lat0, sp1, sp2, fe, fn)\n'
    '            return lat, lon, height\n'
    '        raise ValueError("Local Grid Shift is a grid-to-grid operation. Use it as either source or target with projected X/Y values.")\n'
    '\n'
    '    def llh_to_crs(option: str, lat: float, lon: float, height: float) -> tuple[float, float, float, str]:\n'
    '        text = str(option)\n'
    '        if text == "WGS84 Geographic Lat/Lon":\n'
    '            return lat, lon, height, "Latitude, Longitude, Height"\n'
    '        match = re.search(r"UTM Zone\\s+(\\d+)([NS])", text, re.IGNORECASE)\n'
    '        if match:\n'
    '            easting, northing, zone_out, hemi = GT_latlon_to_utm(float(lat), float(lon), zone=int(match.group(1)))\n'
    '            return northing, easting, height, f"Northing, Easting, Height | Zone {zone_out}{hemi}"\n'
    '        if "Lambert Conical" in text:\n'
    '            cm, lat0, sp1, sp2, fe, fn = lambert_params(text)\n'
    '            easting, northing = lambert_conformal_conic_to_xy(float(lat), float(lon), cm, lat0, sp1, sp2, fe, fn)\n'
    '            return northing, easting, height, "Northing, Easting, Height"\n'
    '        raise ValueError(f"Unsupported target CRS: {option}")\n'
    '\n'
    '    def apply_local_shift(input1: float, input2: float, height: float, inverse: bool = False) -> tuple[float, float, float]:\n'
    '        shift_e = parse_float(shift_e_var.get()) or 0.0\n'
    '        shift_n = parse_float(shift_n_var.get()) or 0.0\n'
    '        shift_h = parse_float(shift_h_var.get()) or 0.0\n'
    '        scale = 1.0 + ((parse_float(shift_scale_var.get()) or 0.0) * 1e-6)\n'
    '        if inverse:\n'
    '            return (input1 - shift_n) / scale, (input2 - shift_e) / scale, (height - shift_h) / scale\n'
    '        return input1 * scale + shift_n, input2 * scale + shift_e, height * scale + shift_h\n'
    '\n'
    '    def transform_datum() -> None:\n'
    '        try:\n'
    '            input1 = GT_parse_angle(dlat_var.get()) if src_crs_var.get() == "WGS84 Geographic Lat/Lon" else float(dlat_var.get())\n'
    '            input2 = GT_parse_angle(dlon_var.get()) if src_crs_var.get() == "WGS84 Geographic Lat/Lon" else float(dlon_var.get())\n'
    '            height = float(dh_var.get() or 0.0)\n'
    '            if src_crs_var.get() == "Local Grid Shift":\n'
    '                shifted_1, shifted_2, shifted_h = apply_local_shift(input1, input2, height, inverse=True)\n'
    '                set_text(\n'
    '                    result3,\n'
    '                    "Local grid inverse shift\\n"\n'
    '                    f"Input Northing/Y: {input1:.4f}\\nInput Easting/X: {input2:.4f}\\n"\n'
    '                    f"Output Northing/Y: {shifted_1:.4f}\\nOutput Easting/X: {shifted_2:.4f}\\nHeight/Z: {shifted_h:.4f}",\n'
    '                )\n'
    '                return\n'
    '            lat_src, lon_src, h_src = crs_to_llh(src_crs_var.get(), input1, input2, height)\n'
    '            lat_dst, lon_dst, h_dst = GT_datum_transform(lat_src, lon_src, h_src, GT_DATUMS[src_var.get()], GT_DATUMS[dst_var.get()])\n'
    '            if dst_crs_var.get() == "Local Grid Shift":\n'
    '                northing, easting, shifted_h = apply_local_shift(lat_dst, lon_dst, h_dst, inverse=False)\n'
    '                set_text(\n'
    '                    result3,\n'
    '                    "Datum transform with local shift target\\n"\n'
    '                    f"Intermediate latitude: {lat_dst:.10f}\\nIntermediate longitude: {lon_dst:.10f}\\n"\n'
    '                    f"Shifted value 1: {northing:.4f}\\nShifted value 2: {easting:.4f}\\nHeight/Z: {shifted_h:.4f}\\n"\n'
    '                    f"{src_crs_var.get()} -> Local Grid Shift",\n'
    '                )\n'
    '                return\n'
    '            out1, out2, out_h, out_label = llh_to_crs(dst_crs_var.get(), lat_dst, lon_dst, h_dst)\n'
    '            set_text(\n'
    '                result3,\n'
    '                f"Output ({out_label})\\n"\n'
    '                f"Value 1: {out1:.4f}\\nValue 2: {out2:.4f}\\nHeight: {out_h:.4f}\\n\\n"\n'
    '                f"Latitude: {lat_dst:.10f}\\nLongitude: {lon_dst:.10f}\\n"\n'
    '                f"{GT_format_dms(lat_dst, True)}\\n{GT_format_dms(lon_dst, False)}\\n"\n'
    '                f"{src_crs_var.get()} -> {dst_crs_var.get()}",\n'
    '            )\n'
    '        except Exception as exc:\n'
    '            show_error(exc)\n'
    '\n'
    '    ttk.Button(datum_tab, text="Transform Datum / CRS", command=transform_datum).grid(row=9, column=0, columnspan=2, sticky="ew", pady=(8, 0))\n'
    '\n'
    '    # Projects / Grids tab\n'
    '    project_grid_tab = ttk.Frame(notebook, padding=10)\n'
    '    notebook.add(project_grid_tab, text="Projects / Grids")\n'
    '    project_choice_var = tk.StringVar(value=str(current_project_folder))\n'
    '    grid_choice_var = tk.StringVar(value=getattr(local_settings.geodetic, "selected_grid_path", "") or (grid_options[0] if grid_options else ""))\n'
    '    project_status_var = tk.StringVar(value=f"{len(project_options)} project option(s), {len(grid_options)} grid/background file option(s)")\n'
    '\n'
    '    ttk.Label(project_grid_tab, text="Available project").grid(row=0, column=0, sticky="w", padx=6, pady=5)\n'
    '    project_combo = ttk.Combobox(project_grid_tab, textvariable=project_choice_var, values=project_options, width=72)\n'
    '    project_combo.grid(row=0, column=7, columnspan=2, sticky="ew", padx=6, pady=5)\n'
