    '    grid_combo = ttk.Combobox(project_grid_tab, textvariable=grid_choice_var, values=grid_options, width=72)\n'
    '    grid_combo.grid(row=1, column=1, columnspan=2, sticky="ew", padx=6, pady=5)\n'
    '    ttk.Label(project_grid_tab, textvariable=project_status_var, foreground="#244d9a").grid(row=2, column=0, columnspan=3, sticky="ew", padx=6, pady=(0, 8))\n'
    '\n'
