    '\n'
    '    def browse_geocalc_project() -> None:\n'
    '        from tkinter import filedialog\n'
    '        folder = filedialog.askdirectory(title="Select project folder", initialdir=project_choice_var.get() or str(APP_DIR), parent=win)\n'
    '        if folder:\n'
