    '\n'
    '    def browse_geocalc_grid() -> None:\n'
    '        from tkinter import filedialog\n'
    '        name = filedialog.askopenfilename(\n'
    '            title="Select grid/background file",\n'
    '            initialdir=project_choice_var.get() or str(APP_DIR),\n'
    '            filetypes=[("Grid/background files", "*.grd *.grid *.gtx *.gsb *.ktd *.KTD *.csv *.xyz *.brd *.lnw *.dxf *.dwg *.DWG *.000 *.enc *.s57 *.kmz *.kml"), ("All files", "*.*")],\n'
    '            parent=win,\n'
