    '\n'
    '    def apply_geocalc_project_grid() -> None:\n'
    '        try:\n'
    '            project_folder = project_choice_var.get().strip()\n'
    '            if project_folder:\n'
    '                _project_folder, raw_path, _edit_path, _sort_path = ensure_project_subfolders_from_raw(project_folder)\n'
    '                local_settings.raw_folder = str(raw_path)\n'
    '            local_settings.geodetic.selected_grid_path = grid_choice_var.get().strip()\n'
    '            local_settings.save(DEFAULT_SETTINGS_PATH)\n'
    '            project_status_var.set("Project/grid selection saved to Settings.")\n'
    '        except Exception as exc:\n'
    '            show_error(exc)\n'
    '\n'
