    '    ttk.Button(project_grid_tab, text="Browse Project", command=browse_geocalc_project).grid(row=3, column=0, sticky="ew", padx=6, pady=5)\n'
    '    ttk.Button(project_grid_tab, text="Browse Grid", command=browse_geocalc_grid).grid(row=3, column=1, sticky="ew", padx=6, pady=5)\n'
    '    ttk.Button(project_grid_tab, text="Apply to Settings", command=apply_geocalc_project_grid).grid(row=3, column=2, sticky="ew", padx=6, pady=5)\n'
    '    project_grid_tab.columnconfigure(1, weight=1)\n'
    '\n'
    '    ttk.Button(win, text="Close", command=win.destroy).pack(pady=(0, 10))\n'
    '\n'
    '# ======================================================================\n'
    '# END GEODETIC_TOOLS_MERGE.py\n'
    '# ======================================================================\n'
    '\n'
    'def run_gui() -> int:\n'
    '    try:\n'
    '        import tkinter as tk\n'
    '        from tkinter import filedialog, messagebox, simpledialog, ttk\n'
    '    except Exception as exc:\n'
    '        print(f"Tkinter is not available: {exc}", file=sys.stderr)\n'
    '        return 2\n'
    '\n'
    '    model = SurveyModel()\n'
    '    runlines = RunLineSet()\n'
    '    settings = load_app_settings()\n'
    '    _project_folder, _raw_folder, _edit_folder, _sort_folder = ensure_project_subfolders_from_raw(settings.raw_folder)\n'
    '    settings.raw_folder = str(_raw_folder)\n'
    '    try:\n'
    '        settings.save(DEFAULT_SETTINGS_PATH)\n'
    '    except Exception:\n'
    '        pass\n'
    '    project = HydroProject()\n'
    '    border_points: list[tuple[float, float]] = []\n'
    '    dxf_background_shapes: list[MapShape] = []\n'
    '    enc_background_shapes: list[MapShape] = []\n'
    '    kmz_background_shapes: list[MapShape] = []\n'
    '    ktd_extent_shapes: list[MapShape] = []\n'
    '    project_background_points: list[SurveyPoint] = []\n'
    '    project_background_files: list[str] = []\n'
    '    background_file_state: dict[str, str] = {}\n'
    '    background_bbox_cache: dict[int, tuple[float, float, float, float]] = {}\n'
    '\n'
    '    def simplify_background_shape(shape: MapShape, max_points: int = 700) -> MapShape:\n'
    '        if shape.kind != "line" or len(shape.points) <= max_points:\n'
    '            return shape\n'
    '        step = max(1, len(shape.points) // max_points)\n'
    '        pts = shape.points[::step]\n'
    '        if pts and pts[-1] != shape.points[-1]:\n'
    '            pts.append(shape.points[-1])\n'
    '        return MapShape(shape.kind, pts, text=shape.text, color=shape.color, width=shape.width, attrs=dict(shape.attrs))\n'
    '\n'
    '    def rebuild_background_cache(*shape_groups: list[MapShape]) -> None:\n'
    '        background_bbox_cache.clear()\n'
    '        for shapes in shape_groups:\n'
    '            for shape in shapes:\n'
    '                bbox = shape_bbox(shape)\n'
    '                if bbox is not None:\n'
    '                    background_bbox_cache[id(shape)] = bbox\n'
    '\n'
    '    def cached_shape_bbox(shape: MapShape) -> Optional[tuple[float, float, float, float]]:\n'
    '        bbox = background_bbox_cache.get(id(shape))\n'
    '        if bbox is None:\n'
    '            bbox = shape_bbox(shape)\n'
    '            if bbox is not None:\n'
    '                background_bbox_cache[id(shape)] = bbox\n'
    '        return bbox\n'
    '\n'
    '    root = tk.Tk()\n'
    '    logging_active = tk.BooleanVar(value=False)\n'
    '    logging_started_at = tk.StringVar(value="")\n'
    '    root.title(APP_TITLE)\n'
    '    root.geometry("1100x720")\n'
    '    root.minsize(880, 560)\n'
    '    try:\n'
    '        root.state("zoomed")\n'
    '    except Exception:\n'
    '        try:\n'
    '            root.attributes("-zoomed", True)\n'
    '        except Exception:\n'
    '            pass\n'
    '\n'
    '    style = ttk.Style(root)\n'
    '    if "clam" in style.theme_names():\n'
    '        style.theme_use("clam")\n'
    '\n'
    '    THEME_SCHEMES: dict[str, dict[str, str]] = {\n'
    '        "Nautical Light": {\n'
    '            "window": "#f5f7f8",\n'
    '            "panel": "#ffffff",\n'
    '            "button": "#e8eef2",\n'
    '            "button_active": "#d8e5ec",\n'
    '            "text": "#111827",\n'
    '            "accent": "#0f6b8d",\n'
    '            "canvas": CHART_BACKGROUND_COLOR,\n'
    '            "grid": CHART_GRID_COLOR,\n'
    '        },\n'
    '        "High Contrast": {\n'
    '            "window": "#101418",\n'
    '            "panel": "#18212a",\n'
    '            "button": "#263442",\n'
    '            "button_active": "#34506a",\n'
    '            "text": "#f8fafc",\n'
    '            "accent": "#facc15",\n'
    '            "canvas": "#05070a",\n'
    '            "grid": "#52616d",\n'
    '        },\n'
    '        "Soft Dark": {\n'
    '            "window": "#1e242b",\n'
    '            "panel": "#27313b",\n'
    '            "button": "#334252",\n'
    '            "button_active": "#3e556b",\n'
    '            "text": "#eef4f8",\n'
    '            "accent": "#7dd3fc",\n'
    '            "canvas": "#101418",\n'
    '            "grid": "#374754",\n'
    '        },\n'
    '        "Classic Gray": {\n'
    '            "window": "#e5e7eb",\n'
    '            "panel": "#f3f4f6",\n'
    '            "button": "#d1d5db",\n'
    '            "button_active": "#c3cad4",\n'
    '            "text": "#111111",\n'
    '            "accent": "#244d9a",\n'
    '            "canvas": "#f8fafc",\n'
    '            "grid": "#9ca3af",\n'
    '        },\n'
    '    }\n'
    '    theme_colors = dict(THEME_SCHEMES.get(getattr(settings, "ui_color_scheme", "Nautical Light"), THEME_SCHEMES["Nautical Light"]))\n'
    '\n'
    '    def bounded_font(value: object, fallback: int = 10) -> int:\n'
    '        try:\n'
    '            return max(8, min(30, int(float(str(value)))))\n'
    '        except Exception:\n'
    '            return fallback\n'
    '\n'
    '    def apply_theme() -> None:\n'
    '        nonlocal theme_colors\n'
    '        scheme_name = getattr(settings, "ui_color_scheme", "Nautical Light")\n'
    '        theme_colors = dict(THEME_SCHEMES.get(scheme_name, THEME_SCHEMES["Nautical Light"]))\n'
    '        contrast = str(getattr(settings, "ui_contrast", "Standard") or "Standard")\n'
    '        if contrast == "High":\n'
    '            theme_colors["button"] = theme_colors.get("button_active", theme_colors["button"])\n'
    '        elif contrast == "Low":\n'
    '            theme_colors["grid"] = "#d1d5db" if scheme_name != "Soft Dark" else "#334155"\n'
    '        base_font = bounded_font(getattr(settings, "ui_font_size", 10), 10)\n'
    '        button_font = bounded_font(getattr(settings, "ui_button_font_size", base_font), base_font)\n'
    '        menu_font = bounded_font(getattr(settings, "ui_menu_font_size", base_font), base_font)\n'
    '        root.option_add("*Font", ("Segoe UI", base_font))\n'
    '        root.option_add("*Menu.Font", ("Segoe UI", menu_font))\n'
    '        root.option_add("*Menu.background", theme_colors["panel"])\n'
    '        root.option_add("*Menu.foreground", theme_colors["text"])\n'
    '        root.option_add("*Menu.activeBackground", theme_colors["button_active"])\n'
    '        root.option_add("*Menu.activeForeground", theme_colors["text"])\n'
    '        try:\n'
    '            root.configure(bg=theme_colors["window"])\n'
    '        except Exception:\n'
    '            pass\n'
    '        style.configure(".", font=("Segoe UI", base_font), background=theme_colors["window"], foreground=theme_colors["text"])\n'
    '        style.configure("TFrame", background=theme_colors["window"])\n'
    '        style.configure("TLabelframe", background=theme_colors["window"], foreground=theme_colors["text"])\n'
    '        style.configure("TLabelframe.Label", background=theme_colors["window"], foreground=theme_colors["text"], font=("Segoe UI", base_font, "bold"))\n'
    '        style.configure("TNotebook", background=theme_colors["window"])\n'
    '        style.configure("TNotebook.Tab", font=("Segoe UI", base_font), padding=(10, 5))\n'
    '        style.configure("TLabel", background=theme_colors["window"], foreground=theme_colors["text"], font=("Segoe UI", base_font))\n'
    '        style.configure("TCheckbutton", background=theme_colors["window"], foreground=theme_colors["text"], font=("Segoe UI", base_font))\n'
    '        style.configure("TRadiobutton", background=theme_colors["window"], foreground=theme_colors["text"], font=("Segoe UI", base_font))\n'
    '        style.configure("TButton", font=("Segoe UI", button_font), padding=(8, 5), background=theme_colors["button"], foreground=theme_colors["text"])\n'
    '        style.map("TButton", background=[("active", theme_colors["button_active"])])\n'
    '        style.configure("SurveyPlan.TButton", font=("Segoe UI", button_font, "bold"), padding=(8, 5), background=theme_colors["button"], foreground=theme_colors["text"])\n'
    '        style.map("SurveyPlan.TButton", background=[("active", theme_colors["button_active"])])\n'
    '        style.configure("SurveyPlan.TLabel", font=("Segoe UI", base_font), background=theme_colors["window"], foreground=theme_colors["text"])\n'
    '        style.configure("TEntry", font=("Segoe UI", base_font))\n'
    '        style.configure("TCombobox", font=("Segoe UI", base_font))\n'
    '\n'
    '    apply_theme()\n'
    '\n'
    '    tide_var = tk.StringVar(value=f"{model.tide:.3f}")\n'
    '    draft_var = tk.StringVar(value=f"{model.draft:.3f}")\n'
    '    sv_var = tk.StringVar(value=str(model.sound_speed or DEFAULT_SOUND_SPEED))\n'
    '    status_var = tk.StringVar(value="Ready")\n'
    '    view_mode = tk.StringVar(value="plan")\n'
    '    cad_tool = tk.StringVar(value="line")\n'
    '    follow_vessel = tk.BooleanVar(value=False)\n'
    '    nav_scale_var = tk.StringVar(value=getattr(settings, "nav_view_scale", "1:200") or "1:200")\n'
    '    selected_line_index = tk.IntVar(value=-1)\n'
    '    selected_line_name_var = tk.StringVar(value="No Line")\n'
    '    use_selected_line = tk.BooleanVar(value=False)\n'
    '    auto_select_nearest_line = tk.BooleanVar(value=False)\n'
    '    line_selector_widgets: dict[str, Any] = {}\n'
    '    NAV_SCALE_OPTIONS = ["Fit", "1:10", "1:20", "1:50", "1:100", "1:200", "1:500", "1:1000", "1:2000", "1:5000", "1:10000", "1:25000", "1:50000", "1:100000", "1:200000"]\n'
    '\n'
    '    def nav_scale_to_span_m(scale_text: str) -> Optional[float]:\n'
    '        text = str(scale_text or "").strip()\n'
    '        if not text or text.lower() == "fit":\n'
    '            return None\n'
    '        match = re.search(r"(\\d+(?:\\.\\d+)?)", text)\n'
    '        if not match:\n'
    '            return None\n'
    '        value = float(match.group(1))\n'
    '        return value if value > 0 else None\n'
    '\n'
    '    def save_nav_scale_setting(*_args: Any) -> None:\n'
    '        chosen = nav_scale_var.get() or "1:200"\n'
    '        settings.nav_view_scale = chosen\n'
    '        try:\n'
    '            save_default_settings()\n'
    '        except Exception:\n'
    '            pass\n'
    '        view_state["zoom"] = 1.0\n'
    '        try:\n'
    '            request_draw_view()\n'
    '        except Exception:\n'
    '            pass\n'
    '\n'
    '    def enabled_line_indices() -> list[int]:\n'
    '        return [index for index, line in enumerate(runlines.lines) if line.enabled]\n'
    '\n'
    '    def refresh_line_selector_options() -> None:\n'
    '        names = [line.name for line in runlines.lines if line.enabled]\n'
    '        combo = line_selector_widgets.get("combo")\n'
    '        try:\n'
    '            if combo is not None:\n'
    '                combo.configure(values=names or ["No Line"])\n'
    '        except Exception:\n'
    '            pass\n'
    '        selected = selected_navigation_line()\n'
    '        if selected is not None:\n'
    '            selected_line_name_var.set(selected.name)\n'
    '        elif names:\n'
    '            selected_line_name_var.set(names[0])\n'
    '        else:\n'
    '            selected_line_name_var.set("No Line")\n'
    '\n'
    '    def selected_navigation_line() -> Optional[RunLine]:\n'
    '        index = selected_line_index.get()\n'
    '        if 0 <= index < len(runlines.lines) and runlines.lines[index].enabled:\n'
    '            return runlines.lines[index]\n'
    '        return None\n'
    '\n'
    '    def select_line_index(index: int, announce: bool = True, keep_auto: bool = False) -> bool:\n'
    '        enabled = enabled_line_indices()\n'
    '        if not enabled:\n'
    '            selected_line_index.set(-1)\n'
    '            if announce:\n'
    '                status_var.set("No enabled runlines are available.")\n'
    '            return False\n'
    '        if index not in enabled:\n'
    '            index = enabled[0]\n'
    '        selected_line_index.set(index)\n'
    '        selected_line_name_var.set(runlines.lines[index].name)\n'
    '        use_selected_line.set(True)\n'
    '        if not keep_auto:\n'
    '            auto_select_nearest_line.set(False)\n'
    '        if announce:\n'
    '            status_var.set(f"Selected navigation line: {runlines.lines[index].name}")\n'
    '        try:\n'
    '            draw_view()\n'
    '            refresh_data_display()\n'
    '        except Exception:\n'
    '            pass\n'
    '        return True\n'
    '\n'
    '    def select_next_line() -> None:\n'
    '        enabled = enabled_line_indices()\n'
    '        if not enabled:\n'
    '            selected_line_index.set(-1)\n'
    '            status_var.set("No enabled runlines are available for NEXT LINE.")\n'
    '            return\n'
    '        current = selected_line_index.get()\n'
    '        if current in enabled:\n'
    '            next_index = enabled[(enabled.index(current) + 1) % len(enabled)]\n'
    '        else:\n'
    '            next_index = enabled[0]\n'
    '        select_line_index(next_index, announce=True)\n'
    '\n'
    '    def select_previous_line() -> None:\n'
    '        enabled = enabled_line_indices()\n'
    '        if not enabled:\n'
    '            selected_line_index.set(-1)\n'
    '            status_var.set("No enabled runlines are available for PREVIOUS LINE.")\n'
    '            return\n'
    '        current = selected_line_index.get()\n'
    '        if current in enabled:\n'
    '            previous_index = enabled[(enabled.index(current) - 1) % len(enabled)]\n'
    '        else:\n'
    '            previous_index = enabled[-1]\n'
    '        select_line_index(previous_index, announce=True)\n'
    '\n'
    '    def swap_selected_line_direction() -> None:\n'
    '        index = selected_line_index.get()\n'
    '        if not (0 <= index < len(runlines.lines)):\n'
    '            status_var.set("No selected line is available to swap direction.")\n'
    '            return\n'
    '        line = runlines.lines[index]\n'
    '        line.start_x, line.end_x = line.end_x, line.start_x\n'
    '        line.start_y, line.end_y = line.end_y, line.start_y\n'
    '        selected_line_name_var.set(line.name)\n'
    '        use_selected_line.set(True)\n'
    '        auto_select_nearest_line.set(False)\n'
    '        status_var.set(f"Swapped line direction: {line.name}")\n'
    '        try:\n'
    '            draw_view()\n'
    '            refresh_data_display()\n'
    '        except Exception:\n'
    '            pass\n'
    '\n'
    '    def select_nearest_line_to_position(x: float, y: float, announce: bool = False) -> Optional[NavigationSolution]:\n'
    '        candidates = [\n'
    '            (index, line.navigation(x, y))\n'
    '            for index, line in enumerate(runlines.lines)\n'
    '            if line.enabled\n'
    '        ]\n'
    '        if not candidates:\n'
    '            selected_line_index.set(-1)\n'
    '            return None\n'
    '        index, solution = min(candidates, key=lambda item: item[1].absolute_cross_track)\n'
    '        if selected_line_index.get() != index:\n'
    '            selected_line_index.set(index)\n'
    '            selected_line_name_var.set(solution.line.name)\n'
    '            use_selected_line.set(True)\n'
    '            if announce:\n'
    '                status_var.set(f"Auto selected nearest line: {solution.line.name}")\n'
    '        return solution\n'
    '\n'
    '    def select_line_by_name(_event: Any = None) -> None:\n'
    '        chosen = selected_line_name_var.get()\n'
    '        for index, line in enumerate(runlines.lines):\n'
    '            if line.enabled and line.name == chosen:\n'
    '                select_line_index(index, announce=True)\n'
    '                return\n'
    '        refresh_line_selector_options()\n'
    '\n'
    '    view_state: dict[str, Any] = {\n'
    '        "zoom": 1.0,\n'
    '        "pan_x": 0.0,\n'
    '        "pan_y": 0.0,\n'
    '        "drag": None,\n'
    '        "zoom_window": False,\n'
    '        "zoom_rect": None,\n'
    '        "zoom_start": None,\n'
    '        "last_span_x": 1.0,\n'
    '        "last_span_y": 1.0,\n'
    '        "last_min_x": 0.0,\n'
    '        "last_max_x": 1.0,\n'
    '        "last_min_y": 0.0,\n'
    '        "last_max_y": 1.0,\n'
    '        "full_center_x": 0.0,\n'
    '        "full_center_y": 0.0,\n'
    '        "full_span_x": 1.0,\n'
    '        "full_span_y": 1.0,\n'
    '        "last_plot_left": 32.0,\n'
    '        "last_plot_top": 32.0,\n'
    '        "last_plot_right": 100.0,\n'
    '        "last_plot_bottom": 100.0,\n'
    '        "last_plot_width": 1.0,\n'
    '        "last_plot_height": 1.0,\n'
    '        "draw_pending": False,\n'
    '        "is_panning": False,\n'
    '    }\n'
    '    cad_state: dict[str, Any] = {"start": None, "preview": None}\n'
    '    io_monitor_stop_event = threading.Event()\n'
    '    io_monitor_threads: list[threading.Thread] = []\n'
    '    io_monitor_thread_keys: set[str] = set()\n'
    '    io_monitor_displays: list[dict[str, Any]] = []\n'
    '    io_monitor_last_record_times: dict[str, float] = {}\n'
    '    live_raw_records: list[tuple[str, str, str]] = []\n'
    '    live_raw_lock = threading.Lock()\n'
    '    latest_sensor_data: dict[str, Any] = {}\n'
    '    live_echogram_points: list[SurveyPoint] = []\n'
    '    echogram_replay_state: dict[str, Any] = {"active": False, "index": 0, "points": []}\n'
    '    echogram_display_state: dict[str, Any] = {"win": None, "canvas": None, "auto": False, "after": None}\n'
    '    echogram_save_state: dict[str, Any] = {"signature": None, "path": None}\n'
    '    data_display_state: dict[str, Any] = {"win": None, "font_size": 18, "selected": {}, "display_order": [], "config_visible": False}\n'
    '    toolbar_state: dict[str, Any] = {\n'
    '        "dock": "top",\n'
    '        "order": [\n'
    '            "SBES",\n'
    '            "Multi-Beam Sys",\n'
    '            "Start Logging",\n'
    '            "Stop Log&Save",\n'
    '            "Zoom +",\n'
    '            "Zoom -",\n'
    '            "Zoom Window",\n'
    '            "Extents",\n'
    '        ],\n'
    '    }\n'
    '    DATA_DISPLAY_FIELDS = [\n'
    '        ("logging", "Logging Status"),\n'
    '        ("time", "Time"),\n'
    '        ("easting", "Easting"),\n'
    '        ("northing", "Northing"),\n'
    '        ("latitude", "Latitude"),\n'
    '        ("longitude", "Longitude"),\n'
    '        ("heading", "HDG"),\n'
    '        ("course", "COG"),\n'
    '        ("speed", "Speed"),\n'
    '        ("line", "Selected Line"),\n'
    '        ("course_to_steer", "Course to Steer"),\n'
    '        ("xte", "Cross Track"),\n'
    '        ("depth", "Depth"),\n'
    '        ("corrected_depth", "Corrected Depth"),\n'
    '        ("altitude", "Ellipsoidal Height"),\n'
    '        ("ktd_file", "KTD File"),\n'
    '        ("ktd_cell_k", "KTD K at Position"),\n'
    '        ("rtk_reduced_height", "RTK H-K Height"),\n'
    '        ("rtk_reduced_depth", "RTK Corrected Depth"),\n'
    '        ("rtk_tide", "RTK Tide"),\n'
    '        ("chart_datum", "Chart Datum"),\n'
    '        ("rtk_method", "RTK Tide Method"),\n'
    '        ("gnss_sentence_type", "GNSS Sentence"),\n'
    '        ("gnss_latest_ascii", "Latest GNSS ASCII"),\n'
    '        ("quality", "Quality"),\n'
    '        ("source", "Source"),\n'
    '    ]\n'
    '    data_display_state["display_order"] = [field_key for field_key, _field_label in DATA_DISPLAY_FIELDS]\n'
    '    for field_key, _field_label in DATA_DISPLAY_FIELDS:\n'
    '        data_display_state["selected"][field_key] = field_key in {\n'
    '            "logging", "easting", "northing", "heading", "course_to_steer", "line", "xte", "depth",\n'
    '            "ktd_cell_k", "rtk_reduced_height", "rtk_tide"\n'
    '        }\n'
    '\n'
    '    def save_default_settings() -> None:\n'
    '        _project_folder, raw_path, _edit_path, _sort_path = ensure_project_subfolders_from_raw(settings.raw_folder)\n'
    '        settings.raw_folder = str(raw_path)\n'
    '        settings.save(DEFAULT_SETTINGS_PATH)\n'
    '\n'
    '    def configured_devices() -> list[SerialSettings]:\n'
    '        devices: list[SerialSettings] = [settings.gps, settings.sensor]\n'
    '        devices.extend(settings.extra_devices)\n'
    '        return [device for device in devices if getattr(device, "enabled", True)]\n'
    '\n'
    '    def is_sbes_device(device: SerialSettings) -> bool:\n'
    '        try:\n'
    '            return device is settings.sensor or str(device.title).strip().upper() == str(settings.sensor.title).strip().upper() or str(device.port).strip().upper() == str(settings.sensor.port).strip().upper()\n'
    '        except Exception:\n'
    '            return False\n'
    '\n'
    '    def add_live_echogram_depth(depth: float, stamp: str, source: str) -> None:\n'
    '        try:\n'
    '            value = float(depth)\n'
    '        except Exception:\n'
    '            return\n'
    '        point = SurveyPoint(time=stamp, raw_depth=value, source=source)\n'
    '        point.tide = model.tide\n'
    '        point.draft = model.draft\n'
    '        point.sound_speed = model.sound_speed\n'
    '        live_echogram_points.append(point)\n'
    '        if len(live_echogram_points) > 2400:\n'
    '            del live_echogram_points[:-2400]\n'
    '        if view_mode.get() == "echogram":\n'
    '            root.after(0, request_draw_view)\n'
    '\n'
    '    def show_live_echogram_display(auto: bool = False) -> None:\n'
    '        existing = echogram_display_state.get("win")\n'
    '        try:\n'
    '            if existing is not None and existing.winfo_exists():\n'
    '                echogram_display_state["auto"] = bool(auto)\n'
    '                existing.lift()\n'
    '                draw_echogram(echogram_display_state.get("canvas"))\n'
    '                return\n'
    '        except Exception:\n'
    '            pass\n'
    '        win = tk.Toplevel(root)\n'
    '        win.title("LIVE SBES ECHOGRAM")\n'
    '        win.geometry("900x520")\n'
    '        win.minsize(520, 300)\n'
    '        win.resizable(True, True)\n'
    '        echogram_canvas = tk.Canvas(win, bg="#05070a", highlightthickness=0)\n'
    '        echogram_canvas.pack(fill="both", expand=True)\n'
    '        echogram_display_state.update({"win": win, "canvas": echogram_canvas, "auto": bool(auto)})\n'
    '\n'
    '        def refresh_loop() -> None:\n'
    '            try:\n'
    '                if not win.winfo_exists():\n'
    '                    return\n'
    '                draw_echogram(echogram_canvas)\n'
    '                echogram_display_state["after"] = win.after(350, refresh_loop)\n'
    '            except Exception:\n'
    '                return\n'
    '\n'
    '        def on_close() -> None:\n'
    '            after_id = echogram_display_state.get("after")\n'
    '            if after_id is not None:\n'
    '                try:\n'
    '                    win.after_cancel(after_id)\n'
    '                except Exception:\n'
    '                    pass\n'
    '            echogram_display_state.update({"win": None, "canvas": None, "auto": False, "after": None})\n'
    '            win.destroy()\n'
    '\n'
    '        win.protocol("WM_DELETE_WINDOW", on_close)\n'
    '        echogram_canvas.bind("<Configure>", lambda _event: draw_echogram(echogram_canvas))\n'
    '        refresh_loop()\n'
    '\n'
    '    def close_auto_echogram_display() -> None:\n'
    '        win = echogram_display_state.get("win")\n'
    '        if not bool(echogram_display_state.get("auto")):\n'
    '            return\n'
    '        try:\n'
    '            if win is not None and win.winfo_exists():\n'
    '                win.destroy()\n'
    '        except Exception:\n'
    '            pass\n'
    '        echogram_display_state.update({"win": None, "canvas": None, "auto": False, "after": None})\n'
    '\n'
    '    def autosave_echogram(reason: str = "stop") -> Optional[Path]:\n'
    '        source_points = [point for point in live_echogram_points if point.raw_depth is not None or point.corrected_depth is not None]\n'
    '        if not source_points:\n'
    '            source_points = [point for point in model.points if point.raw_depth is not None or point.corrected_depth is not None]\n'
    '        if not source_points:\n'
    '            return None\n'
    '        last_point = source_points[-1]\n'
    '        signature = (\n'
    '            len(source_points),\n'
    '            str(last_point.time or ""),\n'
    '            round(float(last_point.raw_depth if last_point.raw_depth is not None else last_point.corrected_depth or 0.0), 4),\n'
    '        )\n'
    '        if echogram_save_state.get("signature") == signature and echogram_save_state.get("path"):\n'
    '            return Path(str(echogram_save_state["path"]))\n'
    '        project_folder, _raw_path, _edit_path, _sort_path = ensure_project_subfolders_from_raw(settings.raw_folder)\n'
    '        echogram_folder = project_folder / "ECHOGRAM"\n'
    '        echogram_folder.mkdir(parents=True, exist_ok=True)\n'
    '        safe_reason = safe_name(reason or "autosave").lower()\n'
    '        output = echogram_folder / f"echogram_{safe_reason}_{datetime.now():%Y%m%d_%H%M%S}.ppm"\n'
    '        echogram = EchogramModel(depth_bins=180)\n'
    '        echogram.build_from_points(source_points)\n'
    '        try:\n'
    '            echogram.export_ppm(output)\n'
    '        except Exception as exc:\n'
    '            status_var.set(f"Echogram autosave failed: {exc}")\n'
    '            return None\n'
    '        echogram_save_state["signature"] = signature\n'
    '        echogram_save_state["path"] = str(output)\n'
    '        status_var.set(f"Echogram autosaved: {output}")\n'
    '        return output\n'
    '\n'
    '    def start_echogram_replay(points: list[SurveyPoint], delay_ms: int = 80) -> None:\n'
    '        replay_points = [point for point in points if point.raw_depth is not None or point.corrected_depth is not None]\n'
    '        if not replay_points:\n'
    '            messagebox.showinfo(APP_TITLE, "No depth samples are available for echogram replay.")\n'
    '            return\n'
    '        echogram_replay_state["active"] = True\n'
    '        echogram_replay_state["index"] = 0\n'
    '        echogram_replay_state["points"] = replay_points\n'
    '        live_echogram_points.clear()\n'
    '        view_mode.set("echogram")\n'
    '\n'
    '        def replay_step() -> None:\n'
    '            if not echogram_replay_state.get("active"):\n'
    '                return\n'
    '            idx = int(echogram_replay_state.get("index", 0))\n'
    '            samples = echogram_replay_state.get("points", [])\n'
    '            if idx >= len(samples):\n'
    '                echogram_replay_state["active"] = False\n'
    '                status_var.set(f"Echogram replay completed: {len(samples)} samples")\n'
    '                draw_view()\n'
    '                return\n'
    '            sample = samples[idx]\n'
    '            depth = sample.raw_depth if sample.raw_depth is not None else sample.corrected_depth\n'
    '            if depth is not None:\n'
    '                add_live_echogram_depth(float(depth), str(sample.time or ""), str(sample.source or "Replay"))\n'
    '            echogram_replay_state["index"] = idx + 1\n'
    '            draw_view()\n'
    '            root.after(delay_ms, replay_step)\n'
    '\n'
    '        status_var.set(f"Echogram replay started: {len(replay_points)} samples")\n'
    '        replay_step()\n'
    '\n'
    '    def stop_echogram_replay() -> None:\n'
    '        echogram_replay_state["active"] = False\n'
    '        status_var.set("Echogram replay stopped")\n'
    '        draw_view()\n'
    '\n'
    '    def next_raw_path() -> Path:\n'
    '        _project_folder, raw_path, _edit_path, _sort_path = ensure_project_subfolders_from_raw(settings.raw_folder)\n'
    '        settings.raw_folder = str(raw_path)\n'
    '        stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S_%f")\n'
    '        return raw_path / f"SurveyPlan_{stamp}.raw"\n'
    '\n'
    '    def save_existing_data_to_raw(show_message: bool = True) -> Optional[Path]:\n'
    '        read_settings()\n'
    '        path = next_raw_path()\n'
    '        with live_raw_lock:\n'
    '            raw_records = list(live_raw_records)\n'
    '        try:\n'
    '            if raw_records:\n'
    '                count = export_live_hypack_raw(path, raw_records)\n'
    '            else:\n'
    '                count = model.export_hypack_raw(path)\n'
    '        except Exception as exc:\n'
    '            messagebox.showerror(APP_TITLE, f"Could not save HYPACK RAW:\\n{exc}")\n'
    '            return None\n'
    '        if show_message:\n'
    '            status_var.set(f"Saved {count} records to {path}")\n'
    '        return path\n'
    '\n'
    '    def export_live_hypack_raw(path, raw_records):\n'
    '        return _acquisition.export_records(path, raw_records)\n'
    '\n'
    '    def start_logging(_event=None):\n'
    '        try:\n'
    '            return _acquisition.start()\n'
    '        except Exception as exc:\n'
    '            messagebox.showerror(APP_TITLE, str(exc))\n'
    '            return "break"\n'
    '\n'
    '    def stop_logging_and_save(_event=None):\n'
    '        try:\n'
    '            return _acquisition.stop()\n'
    '        except Exception as exc:\n'
    '            messagebox.showerror(APP_TITLE, str(exc))\n'
    '            return "break"\n'
    '\n'
    '    def read_settings() -> None:\n'
    '        model.tide = parse_float(tide_var.get()) or 0.0\n'
    '        model.draft = parse_float(draft_var.get()) or 0.0\n'
    '        model.sound_speed = parse_float(sv_var.get()) or DEFAULT_SOUND_SPEED\n'
    '        model.apply_offsets()\n'
    '\n'
    '    def apply_realtime_rtk_tide(altitude: Optional[float], stamp: str = "", source: str = "") -> None:\n'
    '        if altitude is None:\n'
    '            return\n'
    '        read_settings()\n'
    '        latest_sensor_data["altitude_m"] = altitude\n'
    '        ell_h = parse_float(str(altitude))\n'
    '        if ell_h is None:\n'
    '            return\n'
    '        easting = latest_sensor_data.get("easting")\n'
    '        northing = latest_sensor_data.get("northing")\n'
    '        k_value = None\n'
    '        method = str(getattr(settings.geodetic, "rtk_tide_method", "") or "")\n'
    '        if "KTD" in method.upper() or getattr(settings.geodetic, "ktd_file_path", ""):\n'
    '            k_value = ktd_cell_value_at(\n'
    '                getattr(settings.geodetic, "ktd_file_path", ""),\n'
    '                parse_float(str(easting)) if easting is not None else None,\n'
    '                parse_float(str(northing)) if northing is not None else None,\n'
    '            )\n'
    '        if k_value is not None:\n'
    '            tide_value = ell_h - float(k_value)\n'
    '            latest_sensor_data["ktd_cell_k"] = float(k_value)\n'
    '            latest_sensor_data["rtk_reduced_height"] = tide_value\n'
    '            raw_depth = parse_float(str(latest_sensor_data.get("raw_depth", "")))\n'
    '            if raw_depth is not None:\n'
    '                latest_sensor_data["rtk_reduced_depth"] = raw_depth * (model.sound_speed / DEFAULT_SOUND_SPEED if model.sound_speed else 1.0) + model.draft - tide_value\n'
    '            status_message = f"Realtime RTK/KTD tide H-K {tide_value:.3f} m | H {ell_h:.3f} K {float(k_value):.3f}"\n'
    '        else:\n'
    '            latest_sensor_data["ktd_cell_k"] = None\n'
    '            latest_sensor_data["rtk_reduced_height"] = None\n'
    '            latest_sensor_data["rtk_reduced_depth"] = None\n'
    '            tide_value = compute_rtk_tide_from_ellipsoidal_height(\n'
    '                ell_h,\n'
    '                settings.geodetic,\n'
    '                parse_float(str(easting)) if easting is not None else None,\n'
    '                parse_float(str(northing)) if northing is not None else None,\n'
    '            )\n'
    '            if tide_value is None:\n'
    '                refresh_data_display()\n'
    '                return\n'
    '            status_message = f"RTK tide {tide_value:.3f} m from ellipsoidal height {ell_h:.3f} m"\n'
    '        latest_sensor_data["rtk_tide"] = tide_value\n'
    '        latest_sensor_data["chart_datum_level"] = getattr(settings.geodetic, "chart_datum_level", 0.0)\n'
    '        latest_sensor_data["rtk_tide_method"] = getattr(settings.geodetic, "rtk_tide_method", "")\n'
    '        tide_var.set(f"{tide_value:.3f}")\n'
    '        model.tide = tide_value\n'
    '        for point in live_echogram_points[-500:]:\n'
    '            point.tide = tide_value\n'
    '        refresh_data_display()\n'
    '        status_var.set(status_message)\n'
    '\n'
    '    def latest_position_point() -> Optional[SurveyPoint]:\n'
    '        if latest_sensor_data.get("easting") is not None or latest_sensor_data.get("longitude") is not None:\n'
    '            return ensure_projected_xy(\n'
    '                SurveyPoint(\n'
    '                    time=str(latest_sensor_data.get("time", "")),\n'
    '                    latitude=latest_sensor_data.get("latitude"),\n'
    '                    longitude=latest_sensor_data.get("longitude"),\n'
    '                    easting=latest_sensor_data.get("easting"),\n'
    '                    northing=latest_sensor_data.get("northing"),\n'
    '                    raw_depth=latest_sensor_data.get("raw_depth"),\n'
    '                    tide=float(latest_sensor_data.get("rtk_tide", model.tide) or model.tide),\n'
    '                    quality=str(latest_sensor_data.get("quality", "")),\n'
    '                    source=str(latest_sensor_data.get("source", "")),\n'
    '                    speed_knots=latest_sensor_data.get("speed_knots"),\n'
    '                    course_degrees=latest_sensor_data.get("course_degrees"),\n'
    '                    heading_degrees=latest_sensor_data.get("heading_degrees"),\n'
    '                    altitude_m=latest_sensor_data.get("altitude_m"),\n'
    '                    ktd_cell_k=latest_sensor_data.get("ktd_cell_k"),\n'
    '                    rtk_reduced_height=latest_sensor_data.get("rtk_reduced_height"),\n'
    '                    rtk_reduced_depth=latest_sensor_data.get("rtk_reduced_depth"),\n'
    '                ),\n'
    '                settings.geodetic,\n'
    '            )\n'
    '        for point in reversed(model.points):\n'
    '            ensure_projected_xy(point, settings.geodetic)\n'
    '            if point.easting is not None and point.northing is not None:\n'
    '                return point\n'
    '        return None\n'
    '\n'
    '    def latest_depth_point() -> Optional[SurveyPoint]:\n'
    '        for point in reversed(model.points):\n'
    '            if point.raw_depth is not None or point.corrected_depth is not None:\n'
    '                return point\n'
    '        return None\n'
    '\n'
    '    def latest_navigation_solution() -> Optional[NavigationSolution]:\n'
    '        point = latest_position_point()\n'
    '        if point is None or point.x is None or point.y is None:\n'
    '            return None\n'
    '        x = float(point.x)\n'
    '        y = float(point.y)\n'
    '        if auto_select_nearest_line.get():\n'
    '            return select_nearest_line_to_position(x, y)\n'
    '        if use_selected_line.get():\n'
    '            line = selected_navigation_line()\n'
    '            if line is not None:\n'
    '                return line.navigation(x, y)\n'
    '        return runlines.nearest(x, y)\n'
    '\n'
    '    def course_to_steer(solution: Optional[NavigationSolution]) -> Optional[float]:\n'
    '        if solution is None:\n'
    '            return None\n'
    '        correction = max(-30.0, min(30.0, solution.cross_track * 0.08))\n'
    '        return (solution.line.bearing_degrees - correction) % 360.0\n'
    '\n'
    '    def data_display_values() -> dict[str, str]:\n'
    '        position = latest_position_point()\n'
    '        depth = latest_depth_point()\n'
    '        solution = latest_navigation_solution()\n'
    '        ktd_path_text = str(getattr(settings.geodetic, "ktd_file_path", "") or "")\n'
    '        display_k_value = latest_sensor_data.get("ktd_cell_k")\n'
    '        if display_k_value is None and position is not None and (position.x is not None or position.y is not None):\n'
    '            display_k_value = ktd_cell_value_at(ktd_path_text, position.x, position.y)\n'
    '        display_reduced_height = latest_sensor_data.get("rtk_reduced_height")\n'
    '        altitude_value = latest_sensor_data.get("altitude_m", position.altitude_m if position else None)\n'
    '        if display_reduced_height is None and altitude_value is not None and display_k_value is not None:\n'
    '            display_reduced_height = float(altitude_value) - float(display_k_value)\n'
    '        display_reduced_depth = latest_sensor_data.get("rtk_reduced_depth")\n'
    '        raw_depth_value = latest_sensor_data.get("raw_depth", depth.raw_depth if depth else None)\n'
    '        if display_reduced_depth is None and raw_depth_value is not None and display_reduced_height is not None:\n'
    '            display_reduced_depth = float(raw_depth_value) * (model.sound_speed / DEFAULT_SOUND_SPEED if model.sound_speed else 1.0) + model.draft - float(display_reduced_height)\n'
    '        values = {\n'
    '            "logging": "LOGGING" if logging_active.get() else "NOT LOGGING",\n'
    '            "time": latest_sensor_data.get("time", position.time if position else ""),\n'
    '            "easting": format_number(position.easting if position else None),\n'
    '            "northing": format_number(position.northing if position else None),\n'
    '            "latitude": format_number(position.latitude if position else None),\n'
    '            "longitude": format_number(position.longitude if position else None),\n'
    '            "heading": format_number(latest_sensor_data.get("heading_degrees")),\n'
    '            "course": format_number(latest_sensor_data.get("course_degrees")),\n'
    '            "speed": format_number(latest_sensor_data.get("speed_knots")),\n'
    '            "line": solution.line.name if solution else "",\n'
    '            "course_to_steer": format_number(course_to_steer(solution)),\n'
    '            "xte": "" if solution is None else f"{solution.cross_track:.3f} {solution.side}",\n'
    '            "depth": format_number(raw_depth_value),\n'
    '            "corrected_depth": format_number(depth.corrected_depth if depth else None),\n'
    '            "altitude": format_number(altitude_value),\n'
    '            "ktd_file": Path(ktd_path_text).name if ktd_path_text else "",\n'
    '            "ktd_cell_k": format_number(display_k_value),\n'
    '            "rtk_reduced_height": format_number(display_reduced_height),\n'
    '            "rtk_reduced_depth": format_number(display_reduced_depth),\n'
    '            "rtk_tide": format_number(latest_sensor_data.get("rtk_tide")),\n'
    '            "chart_datum": format_number(getattr(settings.geodetic, "chart_datum_level", 0.0)),\n'
    '            "rtk_method": str(getattr(settings.geodetic, "rtk_tide_method", "")),\n'
    '            "gnss_sentence_type": latest_sensor_data.get("gnss_sentence_type", ""),\n'
    '            "gnss_latest_ascii": latest_sensor_data.get("gnss_latest_ascii", ""),\n'
    '            "quality": latest_sensor_data.get("quality", position.quality if position else ""),\n'
    '            "source": latest_sensor_data.get("source", depth.source if depth else ""),\n'
    '        }\n'
    '        return values\n'
    '\n'
    '    def refresh_data_display() -> None:\n'
    '        win = data_display_state.get("win")\n'
    '        value_vars = data_display_state.get("value_vars", {})\n'
    '        row_frames = data_display_state.get("row_frames", {})\n'
    '        if win is None or not hasattr(win, "winfo_exists"):\n'
    '            return\n'
    '        try:\n'
    '            if not win.winfo_exists():\n'
    '                return\n'
    '            font_size = int(data_display_state.get("font_size", 18))\n'
    '            values = data_display_values()\n'
    '            for field_key, value in values.items():\n'
    '                if field_key in value_vars:\n'
    '                    value_vars[field_key].set(value)\n'
    '            for row in row_frames.values():\n'
    '                if row.winfo_ismapped():\n'
    '                    row.pack_forget()\n'
    '            known_fields = {field_key for field_key, _field_label in DATA_DISPLAY_FIELDS}\n'
    '            order = [field_key for field_key in data_display_state.get("display_order", []) if field_key in known_fields]\n'
    '            for field_key, _field_label in DATA_DISPLAY_FIELDS:\n'
    '                if field_key not in order:\n'
    '                    order.append(field_key)\n'
    '            data_display_state["display_order"] = order\n'
    '            for field_key in order:\n'
    '                if field_key in row_frames and bool(data_display_state["selected"].get(field_key, True)):\n'
    '                    row_frames[field_key].pack(fill="x", padx=10, pady=3)\n'
    '                    for child in row_frames[field_key].winfo_children():\n'
    '                        try:\n'
    '                            child.configure(font=("Segoe UI", font_size, "bold" if child.winfo_class() == "TLabel" else "normal"))\n'
    '                        except Exception:\n'
    '                            pass\n'
    '        except Exception:\n'
    '            pass\n'
    '\n'
    '    def refresh_table() -> None:\n'
    '        draw_view()\n'
    '        refresh_data_display()\n'
    '\n'
    '    def load_project_background_points(path: Path) -> list[SurveyPoint]:\n'
    '        temp_model = SurveyModel()\n'
    '        temp_model.tide = model.tide\n'
    '        temp_model.draft = model.draft\n'
    '        temp_model.sound_speed = model.sound_speed\n'
    '        suffix = path.suffix.lower()\n'
    '        points_loaded: list[SurveyPoint] = []\n'
    '        if suffix == ".ktd":\n'
    '            nodes = load_ktd_nodes(path)\n'
    '            points_loaded = [\n'
    '                SurveyPoint(\n'
    '                    easting=float(x),\n'
    '                    northing=float(y),\n'
    '                    raw_depth=float(value),\n'
    '                    quality="KTD",\n'
    '                    source=f"KTD BACKGROUND {path.name}",\n'
    '                )\n'
    '                for x, y, value in nodes\n'
    '            ]\n'
    '        elif suffix in {".nmea", ".log"} and not is_hypack_raw_file(path) and not is_hypack_edited_file(path):\n'
    '            points_loaded = load_nmea(path)\n'
    '            for point in points_loaded:\n'
    '                point.source = f"BACKGROUND {path.name}"\n'
    '        else:\n'
    '            temp_model.load_file(path)\n'
    '            points_loaded = list(temp_model.points)\n'
    '        for point in points_loaded:\n'
    '            if point.x is None or point.y is None:\n'
    '                ensure_projected_xy(point, settings.geodetic)\n'
    '        return [point for point in points_loaded if point.x is not None and point.y is not None]\n'
    '\n'
    '    def load_ktd_background_path(path_obj: Path, replace_existing: bool = True) -> int:\n'
    '        nonlocal ktd_extent_shapes\n'
    '        if path_obj.suffix.lower() != ".ktd" or not path_obj.exists():\n'
    '            return 0\n'
    '        try:\n'
    '            points_loaded = load_project_background_points(path_obj)\n'
    '        except Exception as exc:\n'
    '            status_var.set(f"KTD background load failed: {path_obj.name}: {exc}")\n'
    '            return 0\n'
    '        if replace_existing:\n'
    '            source_tag = f"KTD BACKGROUND {path_obj.name}"\n'
    '            project_background_points[:] = [\n'
    '                point for point in project_background_points\n'
    '                if not str(point.source).upper().startswith("KTD BACKGROUND")\n'
    '                and str(point.source) != source_tag\n'
    '            ]\n'
    '            project_background_files[:] = [\n'
    '                name for name in project_background_files\n'
    '                if Path(str(name)).suffix.lower() != ".ktd"\n'
    '            ]\n'
    '            ktd_extent_shapes = []\n'
    '        else:\n'
    '            source_name = path_obj.name.upper()\n'
    '            project_background_points[:] = [\n'
    '                point for point in project_background_points\n'
    '                if source_name not in str(point.source).upper()\n'
    '            ]\n'
    '            project_background_files[:] = [\n'
    '                name for name in project_background_files\n'
    '                if normalized_file_key(Path(str(name))) != normalized_file_key(path_obj)\n'
    '            ]\n'
    '            ktd_extent_shapes[:] = [\n'
    '                shape for shape in ktd_extent_shapes\n'
    '                if normalized_file_key(Path(str(shape.attrs.get("SOURCE", "")))) != normalized_file_key(path_obj)\n'
    '            ]\n'
    '        project_background_points.extend(points_loaded)\n'
    '        if str(path_obj) not in project_background_files:\n'
    '            project_background_files.append(str(path_obj))\n'
    '        meta = load_ktd_grid_meta(path_obj)\n'
    '        if meta:\n'
    '            try:\n'
    '                min_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '                min_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '                max_x = float(meta.get("max_x", min_x) or min_x)\n'
    '                max_y = float(meta.get("max_y", min_y) or min_y)\n'
    '                ktd_extent_shapes.append(\n'
    '                    MapShape(\n'
    '                        "line",\n'
    '                        [(min_x, min_y), (max_x, min_y), (max_x, max_y), (min_x, max_y), (min_x, min_y)],\n'
    '                        text=f"KTD LIMIT {path_obj.name}",\n'
    '                        color="#111827",\n'
    '                        width=2,\n'
    '                        attrs={\n'
    '                            "SOURCE": str(path_obj),\n'
    '                            "KTD_LIMIT": True,\n'
    '                            "VALID_NODES": len(points_loaded),\n'
    '                            "TOTAL_NODES": int(meta.get("x_count", 0) or 0) * int(meta.get("y_count", 0) or 0),\n'
    '                        },\n'
    '                    )\n'
    '                )\n'
    '                rebuild_background_cache(dxf_background_shapes, enc_background_shapes, kmz_background_shapes, ktd_extent_shapes)\n'
    '            except Exception:\n'
    '                pass\n'
    '        draw_view()\n'
    '        if meta:\n'
    '            total_nodes = int(meta.get("x_count", 0) or 0) * int(meta.get("y_count", 0) or 0)\n'
    '            percent = (len(points_loaded) / total_nodes * 100.0) if total_nodes else 0.0\n'
    '            if points_loaded:\n'
    '                status_var.set(f"Loaded KTD background: {path_obj.name} ({len(points_loaded)} valid K node(s), {percent:.1f}% of grid).")\n'
    '            else:\n'
    '                status_var.set(f"KTD extent loaded but no real K cells found: {path_obj.name}. All cells may be 999.99 nodata.")\n'
    '        else:\n'
    '            status_var.set(f"Loaded KTD background: {path_obj.name} ({len(points_loaded)} valid K value node(s))")\n'
    '        return len(points_loaded)\n'
    '\n'
    '    def add_project_background_files(file_kind: str, initial_folder: Path, patterns: list[tuple[str, str]]) -> None:\n'
    '        read_settings()\n'
    '        names = filedialog.askopenfilenames(\n'
    '            title=f"Load {file_kind} data in background",\n'
    '            initialdir=str(initial_folder),\n'
    '            filetypes=patterns + [("All files", "*.*")],\n'
    '        )\n'
    '        if not names:\n'
    '            return\n'
    '        loaded = 0\n'
    '        failed: list[str] = []\n'
    '        for name in names:\n'
    '            path_obj = Path(name)\n'
    '            try:\n'
    '                if path_obj.suffix.lower() == ".ktd":\n'
    '                    loaded += load_ktd_background_path(path_obj, replace_existing=(loaded == 0))\n'
    '                else:\n'
    '                    points_loaded = load_project_background_points(path_obj)\n'
    '                    project_background_points.extend(points_loaded)\n'
    '                    project_background_files.append(str(path_obj))\n'
    '                    loaded += len(points_loaded)\n'
    '            except Exception as exc:\n'
    '                failed.append(f"{path_obj.name}: {exc}")\n'
    '        draw_view()\n'
    '        if failed:\n'
    '            messagebox.showwarning(APP_TITLE, "Some background files could not be loaded:\\n" + "\\n".join(failed[:6]))\n'
    '        status_var.set(f"Loaded {loaded} background sounding point(s) from {file_kind} file(s)")\n'
    '\n'
    '    def clear_project_background_data() -> None:\n'
    '        project_background_points.clear()\n'
    '        project_background_files.clear()\n'
    '        ktd_extent_shapes.clear()\n'
    '        rebuild_background_cache(dxf_background_shapes, enc_background_shapes, kmz_background_shapes, ktd_extent_shapes)\n'
    '        draw_view()\n'
    '        status_var.set("Cleared project RAW/EDIT/SORT/KTD background data")\n'
    '\n'
    '    def unload_all_background_layers():\n'
    '        return _acquisition.new_window.clear_layers()\n'
    '\n'
    '    def normalized_file_key(path_obj: Path) -> str:\n'
    '        try:\n'
    '            return str(path_obj.resolve()).lower()\n'
    '        except Exception:\n'
    '            return str(path_obj).lower()\n'
    '\n'
    '    def background_file_kind(path_obj: Path) -> str:\n'
    '        suffix = path_obj.suffix.lower()\n'
    '        name_lower = path_obj.name.lower()\n'
    '        if suffix in {".dxf", ".dwg"}:\n'
    '            return "CAD / DXF"\n'
    '        if suffix in {".kmz", ".kml"}:\n'
    '            return "KMZ / KML"\n'
    '        if suffix == ".ktd":\n'
    '            return "KTD grid"\n'
    '        if suffix == ".brd":\n'
    '            return "Border"\n'
    '        if suffix == ".lnw":\n'
    '            return "Line file"\n'
    '        if suffix == ".s57" or re.fullmatch(r"\\.\\d{3}", suffix or ""):\n'
    '            return "ENC / S-57"\n'
    '        if suffix in {".raw", ".1", ".2", ".3", ".nmea", ".log", ".txt", ".xyz", ".csv", ".edt", ".edit", ".sort", ".tgt"}:\n'
    '            if "line" in name_lower and suffix == ".csv":\n'
    '                return "Line CSV"\n'
    '            return "Sounding / target"\n'
    '        if suffix in {".tif", ".tiff", ".geotiff"}:\n'
    '            return "GeoTIFF"\n'
    '        if suffix in {".all", ".kmall", ".s7k", ".xtf", ".gsf"}:\n'
    '            return "MBES raw"\n'
    '        return ""\n'
    '\n'
    '    def is_background_file_loaded(path_obj: Path, kind: str) -> bool:\n'
    '        key = normalized_file_key(path_obj)\n'
    '        if key in background_file_state:\n'
    '            return True\n'
    '        path_text = str(path_obj)\n'
    '        if kind == "CAD / DXF":\n'
    '            return bool(getattr(settings, "dxf_background_path", "")) and normalized_file_key(Path(settings.dxf_background_path)) == key\n'
    '        if kind == "KMZ / KML":\n'
    '            return bool(getattr(settings, "kmz_background_path", "")) and normalized_file_key(Path(settings.kmz_background_path)) == key\n'
    '        if kind == "ENC / S-57":\n'
    '            return bool(getattr(settings, "enc_background_path", "")) and normalized_file_key(Path(settings.enc_background_path)) == key\n'
    '        if kind in {"KTD grid", "Sounding / target"}:\n'
    '            return any(normalized_file_key(Path(name)) == key for name in project_background_files)\n'
    '        return False\n'
    '\n'
    '    def remove_background_points_for_file(path_obj: Path) -> None:\n'
    '        source_name = path_obj.name.upper()\n'
    '        project_background_points[:] = [\n'
    '            point for point in project_background_points\n'
    '            if source_name not in str(point.source).upper()\n'
    '        ]\n'
    '        project_background_files[:] = [\n'
    '            name for name in project_background_files\n'
    '            if normalized_file_key(Path(str(name))) != normalized_file_key(path_obj)\n'
    '        ]\n'
    '\n'
    '    def show_background_file_explorer():\n'
    '        return _acquisition.new_window.show_background_manager()\n'
    '\n'
    '    def load_files() -> None:\n'
    '        read_settings()\n'
    '        names = filedialog.askopenfilenames(\n'
