    '                    pass\n'
    '\n'
    '        def is_gnss_device(device: SerialSettings) -> bool:\n'
    '            return device is settings.gps or str(device.title).strip().upper() in {"GNSS", "GPS"}\n'
    '\n'
    '        def device_accepts_line(device: SerialSettings, line: str, sentence_type: str, normalized_type: str) -> bool:\n'
    '            accepted = set(getattr(device, "selected_sentences", []) or getattr(device, "sentence_options", []) or [])\n'
    '            accepted = {str(item).strip().upper() for item in accepted if str(item).strip()}\n'
    '            if not accepted:\n'
    '                return True\n'
    '            is_nmea_ascii = line.startswith("$")\n'
    '            generic_allowed = ("NMEA" in accepted and is_nmea_ascii) or ("NON_NMEA" in accepted and not is_nmea_ascii)\n'
    '            return sentence_type in accepted or normalized_type in accepted or generic_allowed\n'
    '\n'
    '        def monitor_device_group(group):\n'
    '            if group:\n'
    '                _acquisition.monitor_group(group, group_key(group), broadcast_device_raw)\n'
    '\n'
    '        io_monitor_stop_event.clear()\n'
    '        for group in grouped_devices:\n'
    '            key = group_key(group)\n'
    '            if key in io_monitor_thread_keys:\n'
    '                continue\n'
    '            thread = threading.Thread(target=monitor_device_group, args=(group,), daemon=True)\n'
