    '\n'
    '        def checksum(sentence: str) -> str:\n'
    '            body = str(sentence or "").strip()\n'
    '            if body.startswith("$"):\n'
    '                body = body[1:]\n'
    '            if "*" in body:\n'
    '                body = body.split("*", 1)[0]\n'
    '            value = 0\n'
    '            for char in body:\n'
    '                value ^= ord(char)\n'
    '            return f"{value:02X}"\n'
    '\n'
    '        def format_ss510_command(command: str, add_checksum: bool = False) -> Optional[str]:\n'
    '            line = str(command or "").strip()\n'
    '            if not line:\n'
    '                return None\n'
    '            if not line.startswith("$"):\n'
    '                line = "$" + line\n'
    '            if add_checksum and "*" not in line:\n'
    '                line = f"{line}*{checksum(line)}"\n'
    '            return line + "\\r\\n"\n'
    '\n'
