    '        edit = ttk.Frame(manual)\n'
    '        edit.grid(row=0, column=2, sticky="nsew")\n'
    '        line_name_var = tk.StringVar(value="L1")\n'
    '        line_sx_var = tk.StringVar()\n'
    '        line_sy_var = tk.StringVar()\n'
    '        line_ex_var = tk.StringVar()\n'
    '        line_ey_var = tk.StringVar()\n'
    '        edit_fields = [\n'
    '            ("Line name", line_name_var),\n'
    '            ("Start E", line_sx_var),\n'
    '            ("Start N", line_sy_var),\n'
    '            ("End E", line_ex_var),\n'
    '            ("End N", line_ey_var),\n'
    '        ]\n'
    '        for row, (label, var) in enumerate(edit_fields):\n'
    '            ttk.Label(edit, text=label).grid(row=row, column=0, sticky="w", pady=3)\n'
    '            ttk.Entry(edit, textvariable=var, width=18).grid(row=row, column=1, sticky="ew", pady=3)\n'
    '        edit.columnconfigure(1, weight=1)\n'
    '\n'
    '        manual_rows: list[RunLine] = []\n'
    '\n'
    '        def refresh_manual_tree(select_index: Optional[int] = None) -> None:\n'
    '            line_tree.delete(*line_tree.get_children())\n'
    '            for index, line in enumerate(manual_rows):\n'
    '                line_tree.insert(\n'
    '                    "",\n'
    '                    "end",\n'
    '                    iid=str(index),\n'
    '                    values=(\n'
    '                        line.name,\n'
    '                        f"{line.start_x:.3f}",\n'
    '                        f"{line.start_y:.3f}",\n'
    '                        f"{line.end_x:.3f}",\n'
    '                        f"{line.end_y:.3f}",\n'
    '                    ),\n'
    '                )\n'
    '            if select_index is not None and manual_rows:\n'
    '                select_index = max(0, min(select_index, len(manual_rows) - 1))\n'
    '                line_tree.selection_set(str(select_index))\n'
    '                line_tree.focus(str(select_index))\n'
    '                load_selected_line_to_fields()\n'
    '\n'
    '        def selected_manual_index() -> Optional[int]:\n'
    '            selection = line_tree.selection()\n'
    '            if not selection:\n'
    '                return None\n'
    '            try:\n'
    '                return int(selection[0])\n'
    '            except ValueError:\n'
    '                return None\n'
    '\n'
    '        def load_selected_line_to_fields(_event: Any = None) -> None:\n'
    '            index = selected_manual_index()\n'
    '            if index is None or index >= len(manual_rows):\n'
    '                return\n'
    '            line = manual_rows[index]\n'
    '            line_name_var.set(line.name)\n'
    '            line_sx_var.set(f"{line.start_x:.3f}")\n'
    '            line_sy_var.set(f"{line.start_y:.3f}")\n'
    '            line_ex_var.set(f"{line.end_x:.3f}")\n'
    '            line_ey_var.set(f"{line.end_y:.3f}")\n'
    '            if use_selected_line.get() and index < len(runlines.lines):\n'
    '                select_line_index(index, announce=False)\n'
    '\n'
    '        def line_from_edit() -> Optional[RunLine]:\n'
    '            try:\n'
    '                return RunLine(\n'
    '                    line_name_var.get().strip() or f"L{len(manual_rows) + 1}",\n'
    '                    float(line_sx_var.get()),\n'
    '                    float(line_sy_var.get()),\n'
    '                    float(line_ex_var.get()),\n'
    '                    float(line_ey_var.get()),\n'
    '                )\n'
    '            except ValueError:\n'
    '                messagebox.showerror(APP_TITLE, "Enter valid numeric Start/End coordinates for the individual line.", parent=win)\n'
    '                return None\n'
    '\n'
    '        def add_manual_line() -> None:\n'
    '            line = line_from_edit()\n'
    '            if line is None:\n'
    '                return\n'
    '            manual_rows.append(line)\n'
    '            line_name_var.set(f"L{len(manual_rows) + 1}")\n'
    '            refresh_manual_tree(len(manual_rows) - 1)\n'
    '            status_var.set(f"Added individual line {line.name}")\n'
    '\n'
    '        def update_manual_line() -> None:\n'
    '            index = selected_manual_index()\n'
    '            if index is None:\n'
    '                messagebox.showinfo(APP_TITLE, "Select a line row to update.", parent=win)\n'
    '                return\n'
    '            line = line_from_edit()\n'
    '            if line is None:\n'
    '                return\n'
    '            manual_rows[index] = line\n'
    '            refresh_manual_tree(index)\n'
    '            status_var.set(f"Updated line {line.name}")\n'
    '\n'
    '        def remove_manual_line() -> None:\n'
    '            index = selected_manual_index()\n'
    '            if index is None:\n'
    '                return\n'
    '            removed = manual_rows.pop(index)\n'
    '            refresh_manual_tree(max(0, index - 1) if manual_rows else None)\n'
    '            status_var.set(f"Removed line {removed.name}")\n'
    '\n'
    '        def set_pick_target(target: str, mode: str = "baseline") -> None:\n'
    '            def receive_pick(world_x: float, world_y: float) -> None:\n'
    '                if mode == "manual":\n'
    '                    if target == "start":\n'
    '                        line_sx_var.set(f"{world_x:.3f}")\n'
    '                        line_sy_var.set(f"{world_y:.3f}")\n'
    '                        pick_state_var.set(f"Selected line start: E {world_x:.3f}, N {world_y:.3f}")\n'
    '                    else:\n'
    '                        line_ex_var.set(f"{world_x:.3f}")\n'
    '                        line_ey_var.set(f"{world_y:.3f}")\n'
    '                        pick_state_var.set(f"Selected line end: E {world_x:.3f}, N {world_y:.3f}")\n'
    '                    index = selected_manual_index()\n'
    '                    if index is not None and all(v.get().strip() for v in [line_sx_var, line_sy_var, line_ex_var, line_ey_var]):\n'
    '                        line = line_from_edit()\n'
    '                        if line is not None:\n'
    '                            manual_rows[index] = line\n'
    '                            refresh_manual_tree(index)\n'
    '                elif target == "start":\n'
    '                    start_x_var.set(f"{world_x:.3f}")\n'
    '                    start_y_var.set(f"{world_y:.3f}")\n'
    '                    pick_state_var.set(f"Baseline start selected: E {world_x:.3f}, N {world_y:.3f}")\n'
    '                else:\n'
    '                    end_x_var.set(f"{world_x:.3f}")\n'
    '                    end_y_var.set(f"{world_y:.3f}")\n'
    '                    pick_state_var.set(f"Baseline end selected: E {world_x:.3f}, N {world_y:.3f}")\n'
    '                view_state["line_pick_callback"] = None\n'
    '                view_state["line_pick_target"] = None\n'
    '                status_var.set(pick_state_var.get())\n'
    '                win.lift()\n'
    '\n'
    '            view_state["line_pick_callback"] = receive_pick\n'
    '            view_state["line_pick_target"] = f"{mode}:{target}"\n'
    '            view_state["zoom_window"] = False\n'
    '            status_var.set(f"Click on the navigation screen to pick {mode} line {target}.")\n'
    '            pick_state_var.set(f"Waiting for map click to pick {mode} {target}.")\n'
    '            win.q.hide()\n'
    '\n'
    '        def generate_parallel_from_values() -> None:\n'
    '            try:\n'
    '                start_x = float(start_x_var.get())\n'
    '                start_y = float(start_y_var.get())\n'
    '                end_x = float(end_x_var.get())\n'
    '                end_y = float(end_y_var.get())\n'
    '                spacing = float(spacing_var.get())\n'
    '                count = int(float(count_var.get()))\n'
    '                prefix = prefix_var.get().strip() or "RL"\n'
    '            except ValueError:\n'
    '                messagebox.showerror(APP_TITLE, "Enter valid numeric baseline coordinates, spacing, and line count.", parent=win)\n'
    '                return\n'
    '            if spacing <= 0.0 or count < 0:\n'
    '                messagebox.showerror(APP_TITLE, "Spacing must be positive and line count cannot be negative.", parent=win)\n'
    '                return\n'
    '            try:\n'
    '                runlines.clear()\n'
    '                runlines.generate_parallel(start_x, start_y, end_x, end_y, spacing, count, prefix)\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror(APP_TITLE, f"Could not generate runlines:\\n{exc}", parent=win)\n'
    '                return\n'
    '            refresh_line_selector_options()\n'
    '            draw_view()\n'
    '            status_var.set(f"Generated {len(runlines.lines)} parallel runlines")\n'
    '\n'
    '        def apply_manual_lines() -> None:\n'
    '            if not manual_rows:\n'
    '                messagebox.showinfo(APP_TITLE, "Add at least one individual line first.", parent=win)\n'
    '                return\n'
    '            runlines.clear()\n'
    '            for line in manual_rows:\n'
    '                runlines.add(line)\n'
    '            if selected_line_index.get() >= len(runlines.lines):\n'
    '                selected_line_index.set(0 if runlines.lines else -1)\n'
    '            refresh_line_selector_options()\n'
    '            draw_view()\n'
    '            status_var.set(f"Applied {len(manual_rows)} individual runlines")\n'
    '\n'
    '        def import_current_lines() -> None:\n'
    '            manual_rows.clear()\n'
    '            manual_rows.extend(RunLine(line.name, line.start_x, line.start_y, line.end_x, line.end_y, line.enabled) for line in runlines.lines)\n'
    '            select_index = selected_line_index.get() if 0 <= selected_line_index.get() < len(manual_rows) else (0 if manual_rows else None)\n'
    '            refresh_manual_tree(select_index)\n'
    '            status_var.set(f"Loaded {len(manual_rows)} current lines into manual editor")\n'
    '\n'
    '        def on_close() -> None:\n'
    '            view_state["line_pick_callback"] = None\n'
    '            view_state["line_pick_target"] = None\n'
    '            win.destroy()\n'
    '\n'
    '        ttk.Button(baseline, text="Pick Baseline Start", command=lambda: set_pick_target("start", "baseline")).grid(row=0, column=10, sticky="ew", padx=4, pady=2)\n'
    '        ttk.Button(baseline, text="Pick Baseline End", command=lambda: set_pick_target("end", "baseline")).grid(row=1, column=4, sticky="ew", padx=4, pady=2)\n'
