    '\n'
    '        ttk.Button(edit, text="Pick Line Start", command=lambda: set_pick_target("start", "manual")).grid(row=5, column=0, columnspan=2, sticky="ew", pady=(8, 3))\n'
    '        ttk.Button(edit, text="Pick Line End", command=lambda: set_pick_target("end", "manual")).grid(row=6, column=0, columnspan=2, sticky="ew", pady=3)\n'
    '        ttk.Button(edit, text="Add Line", command=add_manual_line).grid(row=7, column=0, columnspan=2, sticky="ew", pady=(8, 3))\n'
    '        ttk.Button(edit, text="Update Selected", command=update_manual_line).grid(row=8, column=0, columnspan=2, sticky="ew", pady=3)\n'
    '        ttk.Button(edit, text="Remove Selected", command=remove_manual_line).grid(row=9, column=0, columnspan=2, sticky="ew", pady=3)\n'
    '        ttk.Button(edit, text="Import Current Lines", command=import_current_lines).grid(row=10, column=0, columnspan=2, sticky="ew", pady=(8, 3))\n'
    '        ttk.Button(edit, text="Apply Manual Lines", command=apply_manual_lines).grid(row=11, column=0, columnspan=2, sticky="ew", pady=3)\n'
    '\n'
    '        nav_select = ttk.LabelFrame(edit, text="Navigation line selection", padding=6)\n'
    '        nav_select.grid(row=12, column=0, columnspan=2, sticky="ew", pady=(10, 3))\n'
    '        nav_select.columnconfigure(0, weight=1)\n'
    '        ttk.Checkbutton(nav_select, text="Use Selected Line", variable=use_selected_line, command=draw_view).grid(row=0, column=0, sticky="w")\n'
    '        ttk.Checkbutton(nav_select, text="Auto Select Nearest Line", variable=auto_select_nearest_line, command=lambda: (use_selected_line.set(True), draw_view())).grid(row=1, column=0, sticky="w")\n'
    '        ttk.Button(nav_select, text="NEXT LINE", command=select_next_line).grid(row=2, column=0, sticky="ew", pady=(5, 0))\n'
    '\n'
    '        line_tree.bind("<<TreeviewSelect>>", load_selected_line_to_fields)\n'
    '        ttk.Label(frame, textvariable=pick_state_var, wraplength=760, foreground="#244d9a").grid(row=2, column=0, sticky="ew", pady=(10, 6))\n'
    '        bottom = ttk.Frame(frame)\n'
    '        bottom.grid(row=3, column=0, sticky="ew")\n'
    '        ttk.Button(bottom, text="Close", command=on_close).pack(side="right")\n'
    '        win.protocol("WM_DELETE_WINDOW", on_close)\n'
    '        import_current_lines()\n'
    '\n'
    '    def active_border_points() -> list[tuple[float, float]]:\n'
    '        return list(border_points)\n'
    '\n'
    '    def clip_lines_by_border_dialog() -> None:\n'
    '        nonlocal border_points, dxf_background_shapes, enc_background_shapes\n'
    '        polygon = active_border_points()\n'
    '        if len(polygon) < 3:\n'
    '            name = filedialog.askopenfilename(\n'
    '                title="Select HYPACK border file for clipping",\n'
    '                filetypes=[("HYPACK border", "*.brd"), ("All files", "*.*")],\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            try:\n'
    '                polygon = load_hypack_brd_points(Path(name))\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror(APP_TITLE, f"Could not load border file:\\n{exc}")\n'
    '                return\n'
    '            border_points = polygon\n'
    '        if len(polygon) < 3:\n'
    '            messagebox.showerror(APP_TITLE, "Border must contain at least three points.")\n'
    '            return\n'
    '        keep_inside = messagebox.askyesno(\n'
    '            APP_TITLE,\n'
    '            "Clip all available lines, DXF/ENC background, and XYZ/soundings INSIDE the border?\\n\\nYes = keep inside border\\nNo = keep outside border",\n'
    '        )\n'
    '        before_lines = len(runlines.lines)\n'
    '        before_dxf = len(dxf_background_shapes)\n'
    '        before_enc = len(enc_background_shapes)\n'
    '        before_points = len(model.points)\n'
    '\n'
    '        clipped_lines = clip_runlines_to_polygon(runlines.lines, polygon, keep_inside=keep_inside)\n'
    '        clipped_dxf = clip_map_shapes_to_polygon(dxf_background_shapes, polygon, keep_inside=keep_inside)\n'
    '        clipped_enc = clip_map_shapes_to_polygon(enc_background_shapes, polygon, keep_inside=keep_inside)\n'
    '        clipped_points = clip_survey_points_to_polygon(model.points, polygon, keep_inside=keep_inside)\n'
    '\n'
    '        if before_lines and not clipped_lines:\n'
    '            if not messagebox.askyesno(APP_TITLE, "No run line segments remain after clipping. Continue and clear run lines?"):\n'
    '                return\n'
    '        if before_points and not clipped_points:\n'
    '            if not messagebox.askyesno(APP_TITLE, "No XYZ/sounding points remain after clipping. Continue and clear points?"):\n'
    '                return\n'
    '\n'
    '        if before_lines:\n'
    '            runlines.clear()\n'
    '            for line in clipped_lines:\n'
    '                runlines.add(line)\n'
    '        if before_dxf:\n'
    '            dxf_background_shapes = clipped_dxf\n'
    '        if before_enc:\n'
    '            enc_background_shapes = clipped_enc\n'
    '        if before_points:\n'
    '            model.points = clipped_points\n'
    '            refresh_table()\n'
    '            refresh_data_display()\n'
    '\n'
    '        draw_view()\n'
    '        status_var.set(\n'
    '            f"Clipped {\'inside\' if keep_inside else \'outside\'} border: "\n'
    '            f"lines {before_lines}->{len(runlines.lines)}, "\n'
    '            f"DXF {before_dxf}->{len(dxf_background_shapes)}, "\n'
    '            f"ENC {before_enc}->{len(enc_background_shapes)}, "\n'
    '            f"XYZ {before_points}->{len(model.points)}"\n'
    '        )\n'
    '\n'
    '    def show_border_dialog() -> None:\n'
    '        nonlocal border_points\n'
    '        win = tk.Toplevel(root)\n'
    '        win.title("BORDER")\n'
    '        win.geometry("540x360")\n'
    '        win.resizable(True, True)\n'
    '        frame = ttk.Frame(win, padding=14)\n'
    '        frame.pack(fill="both", expand=True)\n'
    '        info_var = tk.StringVar()\n'
    '\n'
    '        def refresh_info() -> None:\n'
    '            info_var.set(f"Border points: {len(border_points)}")\n'
    '            draw_view()\n'
    '\n'
    '        def start_border_creation() -> None:\n'
    '            def receive_border_point(world_x: float, world_y: float) -> None:\n'
    '                border_points.append((world_x, world_y))\n'
    '                status_var.set(f"Added border point {len(border_points)}: E {world_x:.3f}, N {world_y:.3f}")\n'
    '                refresh_info()\n'
    '\n'
    '            view_mode.set("plan")\n'
    '            view_state["border_pick_callback"] = receive_border_point\n'
    '            view_state["zoom_window"] = False\n'
    '            status_var.set("Border creation active: click the navigation screen to add border points.")\n'
    '            refresh_info()\n'
    '\n'
    '        def stop_border_creation() -> None:\n'
    '            view_state["border_pick_callback"] = None\n'
    '            status_var.set("Border creation stopped")\n'
    '\n'
    '        def load_border() -> None:\n'
    '            nonlocal border_points\n'
    '            name = filedialog.askopenfilename(\n'
    '                title="Load HYPACK border",\n'
    '                filetypes=[("HYPACK border", "*.brd"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            try:\n'
    '                border_points = load_hypack_brd_points(Path(name))\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror(APP_TITLE, f"Could not load border:\\n{exc}", parent=win)\n'
    '                return\n'
    '            status_var.set(f"Loaded border: {Path(name).name}")\n'
    '            refresh_info()\n'
    '\n'
    '        def save_border() -> None:\n'
    '            if len(border_points) < 3:\n'
    '                messagebox.showerror(APP_TITLE, "Create or load at least three border points before saving.", parent=win)\n'
    '                return\n'
    '            name = filedialog.asksaveasfilename(\n'
    '                title="Save HYPACK border",\n'
    '                defaultextension=".brd",\n'
    '                filetypes=[("HYPACK border", "*.brd"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            points_to_save = list(border_points)\n'
    '            if points_to_save[0] != points_to_save[-1]:\n'
    '                points_to_save.append(points_to_save[0])\n'
    '            try:\n'
    '                count = save_hypack_brd_points(Path(name), points_to_save)\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror(APP_TITLE, f"Could not save border:\\n{exc}", parent=win)\n'
    '                return\n'
    '            status_var.set(f"Saved {count} border points to {Path(name).name}")\n'
    '\n'
    '        def create_from_banks() -> None:\n'
    '            def receive(points):\n'
    '                nonlocal border_points\n'
    '                border_points = list(points)\n'
    "                view_state['border_pick_callback'] = None\n"
    "                status_var.set('Created river-bank border. Use Save Border to write a HYPACK .brd file.')\n"
    '                refresh_info()\n'
    '            show_river_bank_border(receive)\n'
    '\n'
    '        def clear_border() -> None:\n'
    '            nonlocal border_points\n'
    '            border_points = []\n'
    '            view_state["border_pick_callback"] = None\n'
    '            status_var.set("Border cleared")\n'
    '            refresh_info()\n'
    '\n'
    '        def on_close() -> None:\n'
    '            view_state["border_pick_callback"] = None\n'
    '            win.destroy()\n'
    '\n'
    '        ttk.Label(frame, textvariable=info_var, font=("Segoe UI", 12, "bold")).grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 12))\n'
    '        ttk.Button(frame, text="Start Border Creation", command=start_border_creation).grid(row=1, column=0, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="Stop Creation", command=stop_border_creation).grid(row=1, column=1, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="Load Border", command=load_border).grid(row=2, column=0, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="Save Border", command=save_border).grid(row=2, column=1, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="New Border from East / West Bank DXF", command=create_from_banks).grid(row=5, column=0, columnspan=2, sticky="ew", padx=4, pady=8)\n'
    '        ttk.Button(frame, text="Clear Border", command=clear_border).grid(row=3, column=0, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="Close", command=on_close).grid(row=3, column=1, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Label(frame, text="Click Start Border Creation, then click points on the navigation screen. Save writes a HYPACK .brd border.", wraplength=390).grid(\n'
    '            row=4, column=0, columnspan=2, sticky="ew", pady=(12, 0)\n'
    '        )\n'
    '        frame.columnconfigure(0, weight=1)\n'
    '        frame.columnconfigure(1, weight=1)\n'
    '        win.protocol("WM_DELETE_WINDOW", on_close)\n'
    '        refresh_info()\n'
    '\n'
    '\n'
    '    def refresh_dxf_background_from_path(path_obj: Path, show_errors: bool = True) -> int:\n'
    '        """Load a CAD DXF/DWG file as a plan-view background layer, not as editor content."""\n'
    '        nonlocal dxf_background_shapes\n'
    '        try:\n'
    '            shapes = load_cad_background_shapes(path_obj)\n'
    '        except Exception as exc:\n'
    '            if show_errors:\n'
    '                messagebox.showerror(APP_TITLE, f"Could not load CAD background:\\n{exc}")\n'
    '            return 0\n'
    '        dxf_background_shapes = [simplify_background_shape(shape, max_points=5000) for shape in shapes]\n'
    '        rebuild_background_cache(dxf_background_shapes, enc_background_shapes, kmz_background_shapes)\n'
    '        settings.dxf_background_path = str(path_obj)\n'
