    '    def project_background_shapes(shapes: list[MapShape]) -> list[MapShape]:\n'
    '        projected_shapes: list[MapShape] = []\n'
    '        for shape in shapes:\n'
    '            converted_points: list[tuple[float, float]] = []\n'
    '            for x_raw, y_raw in shape.points:\n'
    '                x_val = float(x_raw)\n'
    '                y_val = float(y_raw)\n'
    '                if -180.0 <= x_val <= 180.0 and -90.0 <= y_val <= 90.0:\n'
    '                    easting, northing = project_lat_lon_to_selected_xy(y_val, x_val, settings.geodetic)\n'
    '                    if easting is not None and northing is not None:\n'
    '                        converted_points.append((float(easting), float(northing)))\n'
    '                    else:\n'
    '                        converted_points.append((x_val, y_val))\n'
    '                else:\n'
    '                    converted_points.append((x_val, y_val))\n'
    '            projected_shapes.append(MapShape(shape.kind, converted_points, text=shape.text, color=shape.color, width=shape.width, attrs=dict(shape.attrs)))\n'
    '        return projected_shapes\n'
