    '\n'
    '\n'
    '    def load_enc_background_file(path_obj: Path) -> None:\n'
    '        """Load ENC/S-57 as a plan-view background layer."""\n'
    '        nonlocal enc_background_shapes\n'
    '        try:\n'
    '            shapes = load_enc_s57_shapes(path_obj)\n'
    '        except Exception as exc:\n'
    '            messagebox.showerror(APP_TITLE, f"Could not load ENC/S-57 background:\\n{exc}")\n'
    '            return\n'
    '        enc_background_shapes = project_background_shapes(shapes)\n'
    '        rebuild_background_cache(dxf_background_shapes, enc_background_shapes, kmz_background_shapes)\n'
    '        settings.enc_background_path = str(path_obj)\n'
    '        save_default_settings()\n'
    '        follow_vessel.set(False)\n'
    '        view_mode.set("plan")\n'
    '        fit_view()\n'
    '        status_var.set(f"Loaded ENC/S-57 background: {path_obj.name} ({len(shapes)} item(s))")\n'
    '\n'
    '    def show_enc_dialog() -> None:\n'
    '        return _acquisition.new_window.show_enc_editor()\n'
    '        """ENC/S-57 background manager."""\n'
    '        nonlocal enc_background_shapes\n'
    '        win = tk.Toplevel(root)\n'
    '        win.title("ENC / S-57 BACKGROUND")\n'
    '        win.geometry("500x240")\n'
    '        win.resizable(True, True)\n'
    '        frame = ttk.Frame(win, padding=14)\n'
    '        frame.pack(fill="both", expand=True)\n'
    '        info_var = tk.StringVar()\n'
    '\n'
    '        def refresh_info() -> None:\n'
    '            saved_name = Path(settings.enc_background_path).name if getattr(settings, "enc_background_path", "") else "None"\n'
    '            info_var.set(f"ENC/S-57 background items: {len(enc_background_shapes)} | Saved file: {saved_name}")\n'
    '            draw_view()\n'
    '\n'
    '        def load_enc() -> None:\n'
    '            name = filedialog.askopenfilename(\n'
    '                title="Load ENC / S-57 background",\n'
    '                filetypes=[("ENC / S-57", "*.000 *.001 *.002 *.003 *.004 *.005 *.006 *.007 *.s57"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            load_enc_background_file(Path(name))\n'
    '            refresh_info()\n'
    '\n'
    '        def clear_enc() -> None:\n'
    '            nonlocal enc_background_shapes\n'
    '            enc_background_shapes = []\n'
    '            rebuild_background_cache(dxf_background_shapes, enc_background_shapes, kmz_background_shapes)\n'
    '            settings.enc_background_path = ""\n'
    '            save_default_settings()\n'
    '            status_var.set("ENC/S-57 background cleared")\n'
    '            refresh_info()\n'
    '\n'
    '        ttk.Label(frame, textvariable=info_var, font=("Segoe UI", 12, "bold")).grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 12))\n'
    '        ttk.Button(frame, text="Load ENC / S-57", command=load_enc).grid(row=1, column=0, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="Clear ENC", command=clear_enc).grid(row=1, column=1, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="Feature Summary", command=show_enc_summary).grid(row=2, column=0, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Button(frame, text="Close", command=win.destroy).grid(row=2, column=1, sticky="ew", padx=4, pady=4)\n'
    '        ttk.Label(\n'
    '            frame,\n'
    '            text="Loads ENC/S-57 feature-object layers as a plan-view background layer. Requires GDAL/OGR Python bindings for S-57 decoding.",\n'
    '            wraplength=450,\n'
    '        ).grid(row=3, column=0, columnspan=2, sticky="ew", pady=(12, 0))\n'
    '        frame.columnconfigure(0, weight=1)\n'
    '        frame.columnconfigure(1, weight=1)\n'
    '        refresh_info()\n'
    '\n'
    '    def show_geotiff_background_dialog() -> None:\n'
    '        messagebox.showinfo("GeoTIFF — unavailable", "Georeferenced raster rendering is not implemented in HYDROGEOMATICS. Selecting a TIFF would not draw it. Use DXF, KML/KMZ, ENC with GDAL, or processed XYZ/CSV backgrounds.", parent=root)\n'
    '\n'
