    '            wraplength=470,\n'
    '        ).pack(anchor="w", fill="x", pady=(0, 10))\n'
    '        ttk.Button(frame, text="Explorer Load / Unload", command=show_background_file_explorer, style="SurveyPlan.TButton").pack(fill="x", pady=3)\n'
    '        ttk.Button(frame, text="Unload Background", command=show_background_unload_dialog, style="SurveyPlan.TButton").pack(fill="x", pady=3)\n'
    '        ttk.Button(frame, text="Fit / Extents", command=fit_view, style="SurveyPlan.TButton").pack(fill="x", pady=3)\n'
    '        ttk.Button(frame, text="Close", command=win.destroy).pack(fill="x", pady=(12, 0))\n'
    '\n'
    '    def xy_to_kml_lonlat(x_value: float, y_value: float) -> tuple[float, float]:\n'
    '        """Convert displayed grid coordinates to lon/lat for Google Earth export."""\n'
    '        geo = settings.geodetic\n'
    '        if not getattr(geo, "use_projection", True):\n'
    '            return float(x_value), float(y_value)\n'
    '        zone = selected_utm_zone(geo, None) or 42\n'
    '        hemi = "S" if float(y_value) >= 10000000.0 else "N"\n'
    '        try:\n'
    '            lat, lon = GT_utm_to_latlon(float(x_value), float(y_value), zone, hemi)\n'
    '            return lon, lat\n'
    '        except Exception:\n'
    '            # Last-resort fallback keeps the export process from crashing.\n'
    '            return float(x_value), float(y_value)\n'
    '\n'
    '    def kml_linestring(name: str, points_xy: list[tuple[float, float]], color: str = "ff00ffff") -> Optional[str]:\n'
    '        if len(points_xy) < 2:\n'
    '            return None\n'
    '        coords = []\n'
    '        for x_value, y_value in points_xy:\n'
    '            lon, lat = xy_to_kml_lonlat(float(x_value), float(y_value))\n'
    '            coords.append(f"{lon:.10f},{lat:.10f},0")\n'
    '        return f"""\n'
    '<Placemark><name>{_kml_escape(name)}</name>\n'
    '<Style><LineStyle><color>{color}</color><width>2</width></LineStyle></Style>\n'
    "<LineString><tessellate>1</tessellate><coordinates>{' '.join(coords)}</coordinates></LineString>\n"
    '</Placemark>"""\n'
    '\n'
    '    def kml_point(name: str, x_value: float, y_value: float, description: str = "") -> str:\n'
    '        lon, lat = xy_to_kml_lonlat(float(x_value), float(y_value))\n'
    '        return f"""\n'
    '<Placemark><name>{_kml_escape(name)}</name><description>{_kml_escape(description)}</description>\n'
    '<Point><coordinates>{lon:.10f},{lat:.10f},0</coordinates></Point></Placemark>"""\n'
    '\n'
    '    def export_current_kmz() -> None:\n'
    '        """Export current survey/map data plus optional selected files to KMZ."""\n'
    '        name = filedialog.asksaveasfilename(\n'
    '            title="Export KMZ for Google Earth",\n'
    '            defaultextension=".kmz",\n'
    '            filetypes=[("Google Earth KMZ", "*.kmz"), ("All files", "*.*")],\n'
    '        )\n'
    '        if not name:\n'
    '            return\n'
    '        placemarks: list[str] = []\n'
    '        exported_points = 0\n'
    '        extra_files = filedialog.askopenfilenames(\n'
    '            title="Optional: select RAW / EDIT / SORT / XYZ / BRD / LNW / DXF / DWG / KML / KMZ files to include",\n'
    '            filetypes=[\n'
    '                ("KMZ export sources", "*.raw *.RAW *.log *.1 *.2 *.3 *.4 *.5 *.xyz *.XYZ *.csv *.txt *.brd *.lnw *.dxf *.kml *.kmz"),\n'
    '                ("Recorded RAW", "*.raw *.RAW"),\n'
    '                ("Edited files", "*.log *.1 *.2 *.3 *.4 *.5"),\n'
    '                ("Sorted XYZ", "*.xyz *.XYZ *.csv *.txt"),\n'
    '                ("Border / lines", "*.brd *.lnw"),\n'
    '                ("CAD / Earth", "*.dxf *.kml *.kmz"),\n'
    '                ("All files", "*.*"),\n'
    '            ],\n'
    '        )\n'
    '\n'
    '        for file_name in extra_files:\n'
    '            source_path = Path(file_name)\n'
    '            suffix = source_path.suffix.lower()\n'
    '            try:\n'
    '                if suffix == ".brd":\n'
    '                    pts = load_hypack_brd_points(source_path)\n'
    '                    if len(pts) >= 2:\n'
    '                        if len(pts) >= 3 and pts[0] != pts[-1]:\n'
    '                            pts = pts + [pts[0]]\n'
    '                        item = kml_linestring(f"Border {source_path.stem}", pts, "ff00ffff")\n'
    '                        if item:\n'
    '                            placemarks.append(item)\n'
    '                elif suffix == ".lnw":\n'
    '                    for line in load_hypack_lnw(source_path):\n'
    '                        item = kml_linestring(\n'
    '                            f"{source_path.stem} {line.name}",\n'
    '                            [(line.start_x, line.start_y), (line.end_x, line.end_y)],\n'
    '                            "ff00ff00",\n'
    '                        )\n'
    '                        if item:\n'
    '                            placemarks.append(item)\n'
    '                elif suffix == ".dxf":\n'
    '                    for index, shape in enumerate(load_dxf_shapes(source_path), 1):\n'
    '                        pts = [(float(x), float(y)) for x, y in shape.points]\n'
    '                        item = kml_linestring(f"DXF {source_path.stem} {index}", pts, "ffffaa00")\n'
    '                        if item:\n'
    '                            placemarks.append(item)\n'
    '                elif suffix in {".kml", ".kmz"}:\n'
    '                    for index, shape in enumerate(project_background_shapes(load_kmz_shapes(source_path)), 1):\n'
    '                        pts = [(float(x), float(y)) for x, y in shape.points]\n'
    '                        if shape.kind == "point" and pts:\n'
    '                            placemarks.append(kml_point(f"{source_path.stem} {index} {shape.text}", pts[0][0], pts[0][1]))\n'
    '                        else:\n'
    '                            item = kml_linestring(f"{source_path.stem} {index} {shape.text}", pts, "ffff6600")\n'
    '                            if item:\n'
    '                                placemarks.append(item)\n'
    '                else:\n'
    '                    for index, point in enumerate(load_points_from_any(source_path), 1):\n'
    '                        ensure_projected_xy(point, settings.geodetic)\n'
    '                        if point.x is not None and point.y is not None:\n'
    '                            desc = f"Depth: {format_number(point.corrected_depth)} | Raw: {format_number(point.raw_depth)} | Source: {source_path.name}"\n'
    '                            placemarks.append(kml_point(f"{source_path.stem} {index}", float(point.x), float(point.y), desc))\n'
    '                            exported_points += 1\n'
    '            except Exception as exc:\n'
    '                messagebox.showwarning(APP_TITLE, f"Skipped {source_path.name}:\\n{exc}")\n'
    '\n'
    '        for index, point in enumerate(model.points, 1):\n'
    '            ensure_projected_xy(point, settings.geodetic)\n'
    '            if point.x is None or point.y is None:\n'
    '                continue\n'
    '            desc = f"Depth: {format_number(point.corrected_depth)} | Raw: {format_number(point.raw_depth)} | Source: {point.source}"\n'
    '            placemarks.append(kml_point(f"Current sounding {index}", float(point.x), float(point.y), desc))\n'
    '            exported_points += 1\n'
    '\n'
    '        for index, point in enumerate(project_background_points, 1):\n'
    '            if point.x is None or point.y is None:\n'
    '                continue\n'
    '            desc = f"Background depth: {format_number(point.corrected_depth)} | Raw: {format_number(point.raw_depth)} | Source: {point.source}"\n'
    '            placemarks.append(kml_point(f"Background sounding {index}", float(point.x), float(point.y), desc))\n'
    '\n'
    '        if len(border_points) >= 2:\n'
    '            pts = list(border_points)\n'
    '            if len(pts) >= 3 and pts[0] != pts[-1]:\n'
    '                pts.append(pts[0])\n'
    '            item = kml_linestring("Current Border", pts, "ff00ffff")\n'
    '            if item:\n'
    '                placemarks.append(item)\n'
    '\n'
    '        for line in runlines.lines:\n'
    '            item = kml_linestring(f"Runline {line.name}", [(line.start_x, line.start_y), (line.end_x, line.end_y)], "ff00ff00")\n'
    '            if item:\n'
    '                placemarks.append(item)\n'
    '\n'
    '        for prefix, shapes, color in [\n'
    '            ("CAD", dxf_background_shapes, "ffffaa00"),\n'
    '            ("ENC", enc_background_shapes, "ffff0000"),\n'
    '            ("KMZ", kmz_background_shapes, "ffff6600"),\n'
    '        ]:\n'
    '            for index, shape in enumerate(shapes, 1):\n'
    '                pts = [(float(x), float(y)) for x, y in shape.points]\n'
    '                if shape.kind == "point" and pts:\n'
    '                    placemarks.append(kml_point(f"{prefix} {index} {shape.text}", pts[0][0], pts[0][1]))\n'
    '                else:\n'
    '                    item = kml_linestring(f"{prefix} {index} {shape.text}", pts, color)\n'
    '                    if item:\n'
    '                        placemarks.append(item)\n'
    '\n'
    '        if not placemarks:\n'
    '            messagebox.showinfo(APP_TITLE, "No current data or selected files are available to export.")\n'
    '            return\n'
    '        try:\n'
    '            write_kmz(Path(name), placemarks)\n'
    '        except Exception as exc:\n'
    '            messagebox.showerror(APP_TITLE, f"Could not export KMZ:\\n{exc}")\n'
    '            return\n'
    '        status_var.set(f"Exported KMZ: {Path(name).name} | selected files {len(extra_files)} | points {exported_points} | placemarks {len(placemarks)}")\n'
    '\n'
    '    def show_line_editor():\n'
    '        return _acquisition.new_window.show_line_editor_panel()\n'
    '\n'
    '    def set_view(mode: str) -> None:\n'
    '        view_mode.set(mode)\n'
    '        draw_view()\n'
    '\n'
    '    def set_follow_vessel(enabled: bool) -> None:\n'
    '        follow_vessel.set(enabled)\n'
    '        view_mode.set("plan")\n'
    '        if enabled:\n'
    '            settings.nav_view_scale = nav_scale_var.get() or "1:200"\n'
    '            try:\n'
    '                save_default_settings()\n'
    '            except Exception:\n'
    '                pass\n'
    '        draw_view()\n'
    '        status_var.set("Follow Vessel enabled" if enabled else "Follow Vessel disabled")\n'
    '\n'
    '    def enable_realtime_navigation_follow() -> None:\n'
    '        if not follow_vessel.get():\n'
    '            follow_vessel.set(True)\n'
    '        view_mode.set("plan")\n'
    '        settings.nav_view_scale = nav_scale_var.get() or "1:200"\n'
    '        draw_view()\n'
    '\n'
    '    def zoom_view(factor: float, center_screen: Optional[tuple[float, float]] = None) -> None:\n'
    '        view_mode.set("plan")\n'
    '        view_state["zoom_window"] = False\n'
    '        view_state["is_panning"] = False\n'
    '        follow_vessel.set(False)\n'
    '        if nav_scale_var.get().lower() != "fit":\n'
    '            nav_scale_var.set("Fit")\n'
    '        plot_left = float(view_state.get("last_plot_left", 32.0))\n'
    '        plot_right = float(view_state.get("last_plot_right", max(canvas.winfo_width() - 32, 33)))\n'
    '        plot_top = float(view_state.get("last_plot_top", 32.0))\n'
    '        plot_bottom = float(view_state.get("last_plot_bottom", max(canvas.winfo_height() - 32, 33)))\n'
    '        if center_screen is None:\n'
    '            center_screen = ((plot_left + plot_right) / 2.0, (plot_top + plot_bottom) / 2.0)\n'
    '        ratio_x = max(0.0, min(1.0, (float(center_screen[0]) - plot_left) / max(plot_right - plot_left, 1.0)))\n'
    '        ratio_y = max(0.0, min(1.0, (float(center_screen[1]) - plot_top) / max(plot_bottom - plot_top, 1.0)))\n'
    '        focus_x, focus_y = screen_to_world(center_screen[0], center_screen[1])\n'
    '        old_zoom = max(float(view_state["zoom"]), 0.05)\n'
    '        new_zoom = max(0.05, min(500.0, old_zoom * factor))\n'
    '        effective = max(new_zoom / old_zoom, 1e-9)\n'
    '        new_span_x = max(float(view_state.get("last_span_x", 1.0)) / effective, 1e-9)\n'
    '        new_span_y = max(float(view_state.get("last_span_y", 1.0)) / effective, 1e-9)\n'
    '        new_center_x = float(focus_x) - (ratio_x - 0.5) * new_span_x\n'
    '        new_center_y = float(focus_y) + (ratio_y - 0.5) * new_span_y\n'
    '        view_state["zoom"] = new_zoom\n'
    '        view_state["pan_x"] = new_center_x - float(view_state.get("full_center_x", new_center_x))\n'
    '        view_state["pan_y"] = new_center_y - float(view_state.get("full_center_y", new_center_y))\n'
    '        draw_view()\n'
    '        status_var.set(f"Plan zoom: {float(view_state[\'zoom\']):.2f}x")\n'
    '\n'
    '    def pan_view(dx_fraction: float, dy_fraction: float) -> None:\n'
    '        view_mode.set("plan")\n'
    '        follow_vessel.set(False)\n'
    '        view_state["is_panning"] = False\n'
    '        view_state["pan_x"] = float(view_state["pan_x"]) + float(view_state.get("last_span_x", 1.0)) * dx_fraction\n'
    '        view_state["pan_y"] = float(view_state["pan_y"]) + float(view_state.get("last_span_y", 1.0)) * dy_fraction\n'
    '        draw_view()\n'
    '        status_var.set("Pan view")\n'
    '\n'
    '    def fit_view() -> None:\n'
    '        view_mode.set("plan")\n'
    '        view_state["zoom_window"] = False\n'
    '        view_state["zoom"] = 1.0\n'
    '        view_state["pan_x"] = 0.0\n'
    '        view_state["pan_y"] = 0.0\n'
    '        draw_view()\n'
    '        status_var.set("Plan view reset to extents")\n'
    '\n'
    '    def enable_zoom_window() -> None:\n'
    '        view_mode.set("plan")\n'
    '        view_state["zoom_window"] = True\n'
    '        view_state["zoom_start"] = None\n'
    '        if view_state.get("zoom_rect") is not None:\n'
    '            try:\n'
    '                canvas.delete(view_state["zoom_rect"])\n'
    '            except Exception:\n'
    '                pass\n'
    '            view_state["zoom_rect"] = None\n'
    '        status_var.set("Zoom Window: drag a rectangle on the navigation screen.")\n'
    '\n'
    '    def screen_to_world(screen_x: float, screen_y: float) -> tuple[float, float]:\n'
    '        plot_left = float(view_state.get("last_plot_left", 32.0))\n'
    '        plot_right = float(view_state.get("last_plot_right", max(canvas.winfo_width() - 32, 33)))\n'
    '        plot_top = float(view_state.get("last_plot_top", 32.0))\n'
    '        plot_bottom = float(view_state.get("last_plot_bottom", max(canvas.winfo_height() - 32, 33)))\n'
    '        width_span = max(plot_right - plot_left, 1.0)\n'
    '        height_span = max(plot_bottom - plot_top, 1.0)\n'
    '        ratio_x = max(0.0, min(1.0, (float(screen_x) - plot_left) / width_span))\n'
    '        ratio_y = max(0.0, min(1.0, (float(screen_y) - plot_top) / height_span))\n'
    '        world_x = float(view_state.get("last_min_x", 0.0)) + ratio_x * float(view_state.get("last_span_x", 1.0))\n'
    '        world_y = float(view_state.get("last_max_y", 1.0)) - ratio_y * float(view_state.get("last_span_y", 1.0))\n'
    '        return world_x, world_y\n'
    '\n'
    '    def on_canvas_mouse_move(event: Any) -> None:\n'
    '        if view_mode.get() != "plan":\n'
    '            return\n'
    '        world_x, world_y = screen_to_world(event.x, event.y)\n'
    '        view_state["last_cursor_world"] = (world_x, world_y)\n'
    '        try:\n'
    '            lon_value, lat_value = xy_to_kml_lonlat(float(world_x), float(world_y))\n'
    '            status_var.set(f"E {world_x:.3f}  N {world_y:.3f}  Lat {lat_value:.7f}  Lon {lon_value:.7f}")\n'
    '        except Exception:\n'
    '            status_var.set(f"E {world_x:.3f}  N {world_y:.3f}")\n'
    '\n'
    '    def point_segment_distance(px: float, py: float, ax: float, ay: float, bx: float, by: float) -> float:\n'
    '        dx = bx - ax\n'
    '        dy = by - ay\n'
    '        if abs(dx) < 1e-12 and abs(dy) < 1e-12:\n'
    '            return math.hypot(px - ax, py - ay)\n'
    '        t = max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)))\n'
    '        return math.hypot(px - (ax + t * dx), py - (ay + t * dy))\n'
    '\n'
    '    def nearest_enc_shape(world_x: float, world_y: float) -> Optional[MapShape]:\n'
    '        if not enc_background_shapes:\n'
    '            return None\n'
    '        tolerance = max(float(view_state.get("last_span_x", 1.0)), float(view_state.get("last_span_y", 1.0))) * 0.025\n'
    '        best_shape: Optional[MapShape] = None\n'
    '        best_distance = float("inf")\n'
    '        search_bbox = (world_x - tolerance, world_y - tolerance, world_x + tolerance, world_y + tolerance)\n'
    '        for shape in enc_background_shapes:\n'
    '            bbox = cached_shape_bbox(shape)\n'
    '            if bbox is not None and not bbox_intersects(bbox, search_bbox):\n'
    '                continue\n'
    '            pts = [(float(x), float(y)) for x, y in shape.points]\n'
    '            if not pts:\n'
    '                continue\n'
    '            if shape.kind == "point" or len(pts) == 1:\n'
    '                dist = min(math.hypot(world_x - x, world_y - y) for x, y in pts)\n'
    '            else:\n'
    '                step = max(1, len(pts) // 250)\n'
    '                reduced = pts[::step]\n'
    '                if reduced[-1] != pts[-1]:\n'
    '                    reduced.append(pts[-1])\n'
    '                dist = min(\n'
    '                    point_segment_distance(world_x, world_y, ax, ay, bx, by)\n'
    '                    for (ax, ay), (bx, by) in zip(reduced, reduced[1:])\n'
    '                )\n'
    '            if dist < best_distance:\n'
    '                best_distance = dist\n'
    '                best_shape = shape\n'
    '        return best_shape if best_distance <= tolerance else None\n'
    '\n'
    '    def show_enc_feature_details() -> None:\n'
    '        cursor = view_state.get("last_cursor_world")\n'
    '        if cursor is None:\n'
    '            messagebox.showinfo(APP_TITLE, "Right-click near an ENC feature first.", parent=root)\n'
    '            return\n'
    '        shape = nearest_enc_shape(float(cursor[0]), float(cursor[1]))\n'
    '        if shape is None:\n'
    '            messagebox.showinfo(APP_TITLE, "No ENC feature found near the cursor.", parent=root)\n'
    '            return\n'
    '        win = tk.Toplevel(root)\n'
    '        win.title("ENC FEATURE DETAILS")\n'
    '        win.geometry("620x520")\n'
    '        win.minsize(420, 320)\n'
    '        frame = ttk.Frame(win, padding=10)\n'
    '        frame.pack(fill="both", expand=True)\n'
    '        text_box = tk.Text(frame, wrap="word")\n'
    '        text_box.pack(side="left", fill="both", expand=True)\n'
    '        scroll = ttk.Scrollbar(frame, orient="vertical", command=text_box.yview)\n'
    '        scroll.pack(side="right", fill="y")\n'
    '        text_box.configure(yscrollcommand=scroll.set)\n'
    '        text_box.insert("end", full_feature_details(shape))\n'
    '        text_box.configure(state="disabled")\n'
    '\n'
    '    def apply_zoom_window(x0: float, y0: float, x1: float, y1: float) -> None:\n'
    '        wx0, wy0 = screen_to_world(x0, y0)\n'
    '        wx1, wy1 = screen_to_world(x1, y1)\n'
    '        target_span_x = abs(wx1 - wx0)\n'
    '        target_span_y = abs(wy1 - wy0)\n'
    '        if target_span_x <= 1e-9 or target_span_y <= 1e-9:\n'
    '            return\n'
    '        full_span_x = max(float(view_state.get("full_span_x", target_span_x)), 1e-9)\n'
    '        full_span_y = max(float(view_state.get("full_span_y", target_span_y)), 1e-9)\n'
    '        view_state["zoom"] = max(0.2, min(50.0, min(full_span_x / target_span_x, full_span_y / target_span_y)))\n'
    '        view_state["pan_x"] = ((wx0 + wx1) / 2.0) - float(view_state.get("full_center_x", 0.0))\n'
    '        view_state["pan_y"] = ((wy0 + wy1) / 2.0) - float(view_state.get("full_center_y", 0.0))\n'
    '        follow_vessel.set(False)\n'
    '        draw_view()\n'
    '        status_var.set(f"Zoom Window applied: {float(view_state[\'zoom\']):.2f}x")\n'
    '\n'
    '    def on_canvas_mouse_down(event: Any) -> None:\n'
    '        if view_mode.get() == "plan":\n'
    '            border_callback = view_state.get("border_pick_callback")\n'
    '            if border_callback is not None:\n'
    '                world_x, world_y = screen_to_world(event.x, event.y)\n'
    '                border_callback(world_x, world_y)\n'
    '                return\n'
    '            pick_callback = view_state.get("line_pick_callback")\n'
    '            if pick_callback is not None:\n'
    '                world_x, world_y = screen_to_world(event.x, event.y)\n'
    '                pick_callback(world_x, world_y)\n'
    '                return\n'
    '            if view_state.get("zoom_window"):\n'
    '                view_state["zoom_start"] = (event.x, event.y)\n'
    '                view_state["drag"] = None\n'
    '                if view_state.get("zoom_rect") is not None:\n'
    '                    try:\n'
    '                        canvas.delete(view_state["zoom_rect"])\n'
    '                    except Exception:\n'
    '                        pass\n'
    '                view_state["zoom_rect"] = canvas.create_rectangle(\n'
    '                    event.x, event.y, event.x, event.y, outline="#ffcc66", width=2, dash=(5, 3)\n'
    '                )\n'
    '            else:\n'
    '                view_state["drag"] = (event.x, event.y)\n'
    '\n'
    '    def on_canvas_mouse_drag(event: Any) -> None:\n'
    '        if view_mode.get() != "plan":\n'
    '            return\n'
    '        if view_state.get("zoom_window") and view_state.get("zoom_start") is not None:\n'
    '            start_x, start_y = view_state["zoom_start"]\n'
    '            rect_id = view_state.get("zoom_rect")\n'
    '            if rect_id is not None:\n'
    '                canvas.coords(rect_id, start_x, start_y, event.x, event.y)\n'
    '            return\n'
    '        if view_state["drag"] is None:\n'
    '            return\n'
    '        follow_vessel.set(False)\n'
    '        view_state["is_panning"] = True\n'
    '        previous_x, previous_y = view_state["drag"]\n'
    '        dx = event.x - previous_x\n'
    '        dy = event.y - previous_y\n'
    '        view_state["drag"] = (event.x, event.y)\n'
    '        plot_width = max(float(view_state["last_plot_width"]), 1.0)\n'
    '        plot_height = max(float(view_state["last_plot_height"]), 1.0)\n'
    '        view_state["pan_x"] = float(view_state["pan_x"]) - dx * float(view_state["last_span_x"]) / plot_width\n'
    '        view_state["pan_y"] = float(view_state["pan_y"]) + dy * float(view_state["last_span_y"]) / plot_height\n'
    '        request_draw_view()\n'
    '\n'
    '    def on_canvas_mouse_up(_event: Any) -> None:\n'
    '        if view_mode.get() == "plan" and view_state.get("zoom_window") and view_state.get("zoom_start") is not None:\n'
    '            start_x, start_y = view_state["zoom_start"]\n'
    '            rect_id = view_state.get("zoom_rect")\n'
    '            if rect_id is not None:\n'
    '                try:\n'
    '                    canvas.delete(rect_id)\n'
    '                except Exception:\n'
    '                    pass\n'
    '            view_state["zoom_rect"] = None\n'
    '            view_state["zoom_start"] = None\n'
    '            view_state["zoom_window"] = False\n'
    '            if abs(_event.x - start_x) >= 8 and abs(_event.y - start_y) >= 8:\n'
    '                apply_zoom_window(start_x, start_y, _event.x, _event.y)\n'
    '            else:\n'
    '                status_var.set("Zoom Window cancelled: selection was too small.")\n'
    '            return\n'
    '        view_state["drag"] = None\n'
    '        if view_state.get("is_panning"):\n'
    '            view_state["is_panning"] = False\n'
    '            draw_view()\n'
    '\n'
    '    def on_canvas_mouse_wheel(event: Any) -> None:\n'
    '        if view_mode.get() != "plan":\n'
    '            return\n'
    '        view_state["zoom_window"] = False\n'
    '        if getattr(event, "num", None) == 4 or getattr(event, "delta", 0) > 0:\n'
    '            zoom_view(1.25, (event.x, event.y))\n'
    '        elif getattr(event, "num", None) == 5 or getattr(event, "delta", 0) < 0:\n'
    '            zoom_view(0.8, (event.x, event.y))\n'
