    '\n'
    '        def point_depth(point: SurveyPoint) -> Optional[float]:\n'
    '            edited = getattr(point, "sb_edited_depth", None)\n'
    '            if edited is not None:\n'
    '                return float(edited)\n'
    '            if point.corrected_depth is not None:\n'
    '                return float(point.corrected_depth)\n'
    '            if point.raw_depth is not None:\n'
    '                return float(point.raw_depth)\n'
    '            return None\n'
    '\n'
    '        def sb_points() -> list[SurveyPoint]:\n'
    '            return [point for point in model.points if point.raw_depth is not None or point.corrected_depth is not None or point.x is not None or point.y is not None]\n'
    '\n'
    '        def ensure_edit_state() -> list[SurveyPoint]:\n'
    '            points = sb_points()\n'
    '            last_xy: Optional[tuple[float, float]] = None\n'
    '            along = 0.0\n'
    '            for index, point in enumerate(points, 1):\n'
    '                xy = (point.x, point.y)\n'
    '                if xy[0] is not None and xy[1] is not None:\n'
    '                    xy_float = (float(xy[0]), float(xy[1]))\n'
    '                    if last_xy is not None:\n'
    '                        along += math.hypot(xy_float[0] - last_xy[0], xy_float[1] - last_xy[1])\n'
    '                    last_xy = xy_float\n'
    '                else:\n'
    '                    along = float(index)\n'
    '                setattr(point, "sb_edit_index", index)\n'
    '                setattr(point, "sb_along_track", along if along > 0 else float(index))\n'
    '                if not hasattr(point, "sb_accepted"):\n'
    '                    setattr(point, "sb_accepted", True)\n'
    '                if not hasattr(point, "sb_flag"):\n'
    '                    setattr(point, "sb_flag", "RAW")\n'
    '                if not hasattr(point, "sb_note"):\n'
    '                    setattr(point, "sb_note", "")\n'
    '                if not hasattr(point, "sb_edited_depth"):\n'
    '                    setattr(point, "sb_edited_depth", point.corrected_depth if point.corrected_depth is not None else point.raw_depth)\n'
    '            return points\n'
    '\n'
    '        def sounding_points() -> list[SurveyPoint]:\n'
    '            return [point for point in ensure_edit_state() if point_depth(point) is not None]\n'
    '\n'
    '        def selected_sounding() -> Optional[SurveyPoint]:\n'
    '            return selected_point.get("point")\n'
    '\n'
    '        def set_selected(point: Optional[SurveyPoint]) -> None:\n'
    '            selected_point["point"] = point\n'
    '\n'
    '        def table_values(point: SurveyPoint) -> tuple[str, ...]:\n'
    '            return (\n'
    '                point.time,\n'
    '                format_number(point.x),\n'
    '                format_number(point.y),\n'
    '                format_number(point.altitude_m),\n'
    '                format_number(point.ktd_cell_k),\n'
    '                format_number(point.rtk_reduced_height),\n'
    '                format_number(point.corrected_depth),\n'
    '                format_number(point_depth(point)),\n'
    '                "ACCEPT" if bool(getattr(point, "sb_accepted", True)) else "REJECT",\n'
    '                format_number(point.raw_depth),\n'
    '                format_number(point.draft),\n'
    '                format_number(point.sound_speed),\n'
    '            )\n'
    '\n'
    '        def normalized_table_page(total: int) -> tuple[int, int]:\n'
    '            size = int(parse_float(table_page_size.get()) or 2500)\n'
    '            size = max(100, min(10000, size))\n'
    '            start = max(0, int(table_page_start.get() or 0))\n'
    '            if total:\n'
    '                start = min(start, max(0, total - 1))\n'
    '            else:\n'
    '                start = 0\n'
    '            table_page_size.set(str(size))\n'
    '            table_page_start.set(start)\n'
    '            return start, min(total, start + size)\n'
    '\n'
    '        def set_table_page(start_index: int) -> None:\n'
    '            table_page_start.set(max(0, int(start_index)))\n'
    '            populate_sb_edit_table(ensure_edit_state())\n'
    '\n'
    '        def page_table(direction: int) -> None:\n'
    '            size = int(parse_float(table_page_size.get()) or 2500)\n'
    '            set_table_page(int(table_page_start.get() or 0) + direction * max(100, size))\n'
    '\n'
    '        def populate_sb_edit_table(points: list[SurveyPoint]) -> None:\n'
    '            after_id = table_load_job.get("after_id")\n'
    '            if after_id is not None:\n'
    '                try:\n'
    '                    win.after_cancel(after_id)\n'
    '                except Exception:\n'
    '                    pass\n'
    '                table_load_job["after_id"] = None\n'
    '            tree.delete(*tree.get_children())\n'
    '            tree.tag_configure("accepted", foreground="#111827")\n'
    '            tree.tag_configure("rejected", foreground="#b91c1c")\n'
    '            total = len(points)\n'
    '            start, end = normalized_table_page(total)\n'
    '            page_points = points[start:end]\n'
    '            batch_size = 500\n'
    '            table_page_status.set(f"Rows {start + 1 if total else 0}-{end} of {total}")\n'
    '            status.set(f"Loading table rows {start + 1 if total else 0}-{end} of {total}...")\n'
    '\n'
    '            def insert_batch(start_index: int = 0) -> None:\n'
    '                end_index = min(start_index + batch_size, len(page_points))\n'
    '                for point in page_points[start_index:end_index]:\n'
    '                    tag = "rejected" if not bool(getattr(point, "sb_accepted", True)) else "accepted"\n'
    '                    tree.insert(\n'
    '                        "",\n'
    '                        "end",\n'
    '                        iid=str(id(point)),\n'
    '                        values=table_values(point),\n'
    '                        tags=(tag,),\n'
    '                    )\n'
    '                if end_index < len(page_points):\n'
    '                    status.set(f"Loading table page {end_index}/{len(page_points)}...")\n'
    '                    table_load_job["after_id"] = win.after(10, lambda: insert_batch(end_index))\n'
    '                else:\n'
    '                    table_load_job["after_id"] = None\n'
    '                    status.set(f"Loaded table rows {start + 1 if total else 0}-{end} of {total}.")\n'
    '\n'
    '            insert_batch()\n'
    '\n'
    '        def refresh_sb_edit() -> None:\n'
    '            points = ensure_edit_state()\n'
    '            soundings = [point for point in points if point_depth(point) is not None]\n'
    '            track = [point for point in points if point.x is not None and point.y is not None]\n'
    '            accepted = [point for point in soundings if bool(getattr(point, "sb_accepted", True))]\n'
    '            rejected = len(soundings) - len(accepted)\n'
    '            depths = [point_depth(point) for point in accepted if point_depth(point) is not None] or [point_depth(point) for point in soundings if point_depth(point) is not None]\n'
    '            if depths:\n'
    '                summary.set(\n'
    '                    f"Soundings: {len(soundings)} | Accepted: {len(accepted)} | Rejected: {rejected} | "\n'
    '                    f"Bins: {len(edit_bins)} | Min/Max/Mean: {min(depths):.2f}/{max(depths):.2f}/{statistics.mean(depths):.2f} m | Track: {len(track)}"\n'
    '                )\n'
    '            else:\n'
    '                summary.set(f"Soundings: {len(soundings)} | Track: {len(track)} | Total rows: {len(points)}")\n'
    '            populate_sb_edit_table(points)\n'
    '            redraw_sb_plot()\n'
    '\n'
    '        def clamp_graph_view() -> None:\n'
    '            start = max(0.0, min(99.0, float(graph_view_start.get())))\n'
    '            end = max(start + 1.0, min(100.0, float(graph_view_end.get())))\n'
    '            if end - start < 1.0:\n'
    '                start = max(0.0, end - 1.0)\n'
    '            graph_view_start.set(start)\n'
    '            graph_view_end.set(end)\n'
    '\n'
    '        def set_graph_view(start: float, end: float) -> None:\n'
    '            start = max(0.0, min(99.0, start))\n'
    '            end = max(start + 1.0, min(100.0, end))\n'
    '            graph_scroll_guard["updating"] = True\n'
    '            graph_view_start.set(start)\n'
    '            graph_view_end.set(end)\n'
    '            graph_scroll_guard["updating"] = False\n'
    '            redraw_sb_plot()\n'
    '\n'
    '        def graph_scroll_changed() -> None:\n'
    '            if graph_scroll_guard["updating"]:\n'
    '                return\n'
    '            width_pct = max(1.0, float(graph_view_end.get()) - float(graph_view_start.get()))\n'
    '            start = float(graph_view_start.get())\n'
    '            set_graph_view(start, min(100.0, start + width_pct))\n'
    '\n'
    '        def set_graph_tool(name: str) -> None:\n'
    '            graph_tool.set(name)\n'
    '            cursor_status.set(f"Graphical Linear Editor mode: {name}.")\n'
    '\n'
    '        def pan_graph(fraction: float) -> None:\n'
    '            width_pct = max(1.0, float(graph_view_end.get()) - float(graph_view_start.get()))\n'
    '            delta = width_pct * fraction\n'
    '            start = float(graph_view_start.get()) + delta\n'
    '            end = float(graph_view_end.get()) + delta\n'
    '            if start < 0.0:\n'
    '                end -= start\n'
    '                start = 0.0\n'
    '            if end > 100.0:\n'
    '                start -= end - 100.0\n'
    '                end = 100.0\n'
    '            set_graph_view(start, end)\n'
    '\n'
    '        def zoom_graph(factor: float, center_pct: Optional[float] = None) -> None:\n'
    '            start = float(graph_view_start.get())\n'
    '            end = float(graph_view_end.get())\n'
    '            center = center_pct if center_pct is not None else (start + end) / 2.0\n'
    '            width_pct = max(1.0, min(100.0, (end - start) * factor))\n'
    '            set_graph_view(center - width_pct / 2.0, center + width_pct / 2.0)\n'
    '\n'
    '        def full_graph_extent() -> None:\n'
    '            set_graph_view(0.0, 100.0)\n'
    '\n'
    '        def chain_from_canvas_x(x_value: float) -> float:\n'
    '            left = graph_world["left"]\n'
    '            plot_w = max(1.0, graph_world["plot_w"])\n'
    '            ratio = max(0.0, min(1.0, (float(x_value) - left) / plot_w))\n'
    '            return graph_world["min_chain"] + ratio * (graph_world["max_chain"] - graph_world["min_chain"])\n'
    '\n'
    '        def percent_from_chain(chain: float, all_min: float, all_max: float) -> float:\n'
    '            span = max(1.0, all_max - all_min)\n'
    '            return max(0.0, min(100.0, (chain - all_min) / span * 100.0))\n'
    '\n'
    '        def redraw_sb_plot() -> None:\n'
    '            plot_canvas.delete("all")\n'
    '            width = max(plot_canvas.winfo_width(), 10)\n'
    '            height = max(plot_canvas.winfo_height(), 10)\n'
    '            plot_canvas.create_rectangle(0, 0, width, height, fill="#ffffff", outline="")\n'
    '            all_points = sounding_points()\n'
    '            if not all_points:\n'
    '                plot_canvas.create_text(\n'
    '                    width // 2,\n'
    '                    height // 2,\n'
    '                    text="Load RAW / NMEA or use the logger to populate SB EDIT.",\n'
    '                    fill="#64748b",\n'
    '                    font=("Segoe UI", 13),\n'
    '                )\n'
    '                return\n'
    '            clamp_graph_view()\n'
    '            margin_left, margin_top, margin_right, margin_bottom = 62, 24, 24, 52\n'
    '            plot_w = max(1, width - margin_left - margin_right)\n'
    '            plot_h = max(1, height - margin_top - margin_bottom)\n'
    '            all_chains = [float(getattr(point, "sb_along_track", index + 1)) for index, point in enumerate(all_points)]\n'
    '            all_min_chain, all_max_chain = min(all_chains), max(all_chains)\n'
    '            all_span = max(1.0, all_max_chain - all_min_chain)\n'
    '            view_min = all_min_chain + (float(graph_view_start.get()) / 100.0) * all_span\n'
    '            view_max = all_min_chain + (float(graph_view_end.get()) / 100.0) * all_span\n'
    '            points = [\n'
    '                point\n'
    '                for point in all_points\n'
    '                if view_min <= float(getattr(point, "sb_along_track", 0.0)) <= view_max\n'
    '            ]\n'
    '            if not points:\n'
    '                points = all_points\n'
    '                view_min = all_min_chain\n'
    '                view_max = all_max_chain\n'
    '            if len(points) > 3500:\n'
    '                step = max(1, len(points) // 3500)\n'
    '                display_points = points[::step]\n'
    '                if points[-1] is not display_points[-1]:\n'
    '                    display_points.append(points[-1])\n'
    '                cursor_status.set(f"Graph view decimated for speed: showing {len(display_points)} of {len(points)} visible soundings. Zoom in for more detail.")\n'
    '            else:\n'
    '                display_points = points\n'
    '            chains = [float(getattr(point, "sb_along_track", index + 1)) for index, point in enumerate(points)]\n'
    '            depths = [point_depth(point) for point in points if point_depth(point) is not None]\n'
    '            min_chain, max_chain = min(chains), max(chains)\n'
    '            min_depth, max_depth = min(depths), max(depths)\n'
    '            depth_pad = max(0.5, (max_depth - min_depth) * 0.12)\n'
    '            min_depth -= depth_pad\n'
    '            max_depth += depth_pad\n'
    '            span_chain = max(max_chain - min_chain, 1.0)\n'
    '            span_depth = max(max_depth - min_depth, 0.1)\n'
    '            graph_world.update(\n'
    '                {\n'
    '                    "min_chain": min_chain,\n'
    '                    "max_chain": max_chain,\n'
    '                    "all_min_chain": all_min_chain,\n'
    '                    "all_max_chain": all_max_chain,\n'
    '                    "left": float(margin_left),\n'
    '                    "top": float(margin_top),\n'
    '                    "plot_w": float(plot_w),\n'
    '                    "plot_h": float(plot_h),\n'
    '                }\n'
    '            )\n'
    '            point_cache.clear()\n'
    '\n'
    '            def project_point(point: SurveyPoint, depth: float) -> tuple[float, float]:\n'
    '                chain = float(getattr(point, "sb_along_track", 0.0))\n'
    '                x = margin_left + (chain - min_chain) / span_chain * plot_w\n'
    '                y = margin_top + (depth - min_depth) / span_depth * plot_h\n'
    '                return x, y\n'
    '\n'
    '            for tick in range(6):\n'
    '                ratio = tick / 5\n'
    '                y = margin_top + ratio * plot_h\n'
    '                x = margin_left + ratio * plot_w\n'
    '                plot_canvas.create_line(margin_left, y, margin_left + plot_w, y, fill="#e2e8f0")\n'
    '                plot_canvas.create_line(x, margin_top, x, margin_top + plot_h, fill="#eef2f7")\n'
    '                plot_canvas.create_text(margin_left - 8, y, text=f"{min_depth + ratio * span_depth:.1f}", fill="#64748b", anchor="e", font=("Consolas", 9))\n'
    '                plot_canvas.create_text(x, margin_top + plot_h + 16, text=f"{min_chain + ratio * span_chain:.0f}", fill="#64748b", anchor="n", font=("Consolas", 9))\n'
    '            plot_canvas.create_rectangle(margin_left, margin_top, margin_left + plot_w, margin_top + plot_h, outline="#94a3b8")\n'
    '            plot_canvas.create_text(margin_left, height - 22, text="Along-track chainage (m)", fill="#475569", anchor="w")\n'
    '            plot_canvas.create_text(10, margin_top, text="Depth (m)", fill="#475569", anchor="nw")\n'
    '\n'
    '            last_raw: Optional[tuple[float, float]] = None\n'
    '            last_edit: Optional[tuple[float, float]] = None\n'
    '            for point in display_points:\n'
    '                raw_depth = point.corrected_depth if point.corrected_depth is not None else point.raw_depth\n'
    '                edit_depth = point_depth(point)\n'
    '                if raw_depth is not None:\n'
    '                    rx, ry = project_point(point, float(raw_depth))\n'
    '                    if last_raw is not None:\n'
    '                        plot_canvas.create_line(last_raw[0], last_raw[1], rx, ry, fill="#94a3b8", width=1)\n'
    '                    last_raw = (rx, ry)\n'
    '                if edit_depth is None:\n'
    '                    continue\n'
    '                ex, ey = project_point(point, float(edit_depth))\n'
    '                accepted_state = bool(getattr(point, "sb_accepted", True))\n'
    '                if last_edit is not None:\n'
    '                    plot_canvas.create_line(last_edit[0], last_edit[1], ex, ey, fill="#16a34a" if accepted_state else "#dc2626", width=2)\n'
    '                last_edit = (ex, ey)\n'
    '                is_selected = selected_sounding() is point\n'
    '                radius = 6 if is_selected else 3\n'
    '                color = "#f59e0b" if is_selected else "#16a34a" if accepted_state else "#dc2626"\n'
    '                plot_canvas.create_oval(ex - radius, ey - radius, ex + radius, ey + radius, fill=color, outline="")\n'
    '                if not accepted_state:\n'
    '                    plot_canvas.create_line(ex - 5, ey - 5, ex + 5, ey + 5, fill="#ffffff")\n'
    '                    plot_canvas.create_line(ex + 5, ey - 5, ex - 5, ey + 5, fill="#ffffff")\n'
    '                point_cache.append((ex, ey, point))\n'
    '\n'
    '            previous_bin: Optional[tuple[float, float]] = None\n'
    '            for item in edit_bins:\n'
    '                chain = float(item["center_m"])\n'
    '                if chain < min_chain or chain > max_chain:\n'
    '                    continue\n'
    '                depth = float(item["depth"])\n'
    '                x = margin_left + (chain - min_chain) / span_chain * plot_w\n'
    '                y = margin_top + (depth - min_depth) / span_depth * plot_h\n'
    '                plot_canvas.create_rectangle(x - 4, y - 4, x + 4, y + 4, fill="#0891b2", outline="")\n'
    '                if previous_bin is not None:\n'
    '                    plot_canvas.create_line(previous_bin[0], previous_bin[1], x, y, fill="#0891b2", dash=(4, 4), width=2)\n'
    '                previous_bin = (x, y)\n'
    '            plot_canvas.create_text(\n'
    '                margin_left + 8,\n'
    '                margin_top + 8,\n'
    '                text="Gray raw/corrected | Green accepted | Red rejected | Yellow selected | Cyan bin average",\n'
    '                fill="#475569",\n'
    '                anchor="nw",\n'
    '            )\n'
    '\n'
    '        def nearest_plotted_point(x: float, y: float) -> Optional[SurveyPoint]:\n'
    '            best_point = None\n'
    '            best_distance = 12.0\n'
    '            for px, py, point in point_cache:\n'
    '                distance = math.hypot(px - x, py - y)\n'
    '                if distance < best_distance:\n'
    '                    best_distance = distance\n'
    '                    best_point = point\n'
    '            return best_point\n'
    '\n'
    '        def update_selected_detail(point: Optional[SurveyPoint]) -> None:\n'
    '            if point is None:\n'
    '                return\n'
    '            cursor_status.set(\n'
    '                f"Selected #{getattr(point, \'sb_edit_index\', \'-\')} | "\n'
    '                f"Chain {format_number(getattr(point, \'sb_along_track\', None))} m | "\n'
    '                f"Edited depth {format_number(point_depth(point))} m | "\n'
    '                f"{\'ACCEPTED\' if bool(getattr(point, \'sb_accepted\', True)) else \'REJECTED\'} | "\n'
    '                f"{getattr(point, \'sb_flag\', \'RAW\')}"\n'
    '            )\n'
    '            log(\n'
    '                f"Selected #{getattr(point, \'sb_edit_index\', \'-\')} chain {format_number(getattr(point, \'sb_along_track\', None))} m, "\n'
    '                f"raw {format_number(point.raw_depth)}, corrected {format_number(point.corrected_depth)}, "\n'
    '                f"edited {format_number(point_depth(point))}, {getattr(point, \'sb_flag\', \'RAW\')}"\n'
    '            )\n'
    '\n'
    '        def accept_point(point: Optional[SurveyPoint] = None) -> None:\n'
    '            point = point or selected_sounding()\n'
    '            if point is None:\n'
    '                return\n'
    '            setattr(point, "sb_accepted", True)\n'
    '            setattr(point, "sb_flag", "ACCEPTED")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def reject_point(point: Optional[SurveyPoint] = None) -> None:\n'
    '            point = point or selected_sounding()\n'
    '            if point is None:\n'
    '                return\n'
    '            setattr(point, "sb_accepted", False)\n'
    '            setattr(point, "sb_flag", "REJECTED")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def accept_all() -> None:\n'
    '            for point in sounding_points():\n'
    '                setattr(point, "sb_accepted", True)\n'
    '                if str(getattr(point, "sb_flag", "")).startswith("SPIKE") or getattr(point, "sb_flag", "") == "REJECTED":\n'
    '                    setattr(point, "sb_flag", "ACCEPTED")\n'
    '            log("Accepted all SB EDIT soundings.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def reset_editing() -> None:\n'
    '            edit_bins.clear()\n'
    '            for point in sounding_points():\n'
    '                setattr(point, "sb_accepted", True)\n'
    '                setattr(point, "sb_flag", "RAW")\n'
    '                setattr(point, "sb_edited_depth", point.corrected_depth if point.corrected_depth is not None else point.raw_depth)\n'
    '            log("Reset edited depths, flags, and bins.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def detect_spikes() -> None:\n'
    '            points = sounding_points()\n'
    '            if len(points) < 5:\n'
    '                log("Need at least five soundings for spike detection.")\n'
    '                return\n'
    '            threshold = max(0.05, parse_float(spike_threshold.get()) or 0.75)\n'
    '            rejected = 0\n'
    '            for pos, point in enumerate(points):\n'
    '                depth = point_depth(point)\n'
    '                if depth is None:\n'
    '                    continue\n'
    '                lo = max(0, pos - 2)\n'
    '                hi = min(len(points), pos + 3)\n'
    '                window = sorted(point_depth(item) for item in points[lo:hi] if point_depth(item) is not None)\n'
    '                if not window:\n'
    '                    continue\n'
    '                median = window[len(window) // 2]\n'
    '                delta = abs(depth - median)\n'
    '                if delta > threshold:\n'
    '                    setattr(point, "sb_accepted", False)\n'
    '                    setattr(point, "sb_flag", f"SPIKE {delta:.2f}m")\n'
    '                    rejected += 1\n'
    '            log(f"Spike detection rejected {rejected} sounding(s) using {threshold:.2f} m threshold.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def smooth_depths(local_only: bool = False) -> None:\n'
    '            points = sounding_points()\n'
    '            if not points:\n'
    '                return\n'
    '            window = max(3, int(parse_float(smooth_window.get()) or 5))\n'
    '            if window % 2 == 0:\n'
    '                window += 1\n'
    '            targets = [selected_sounding()] if local_only else points\n'
    '            half = window // 2\n'
    '            updates: list[tuple[SurveyPoint, float]] = []\n'
    '            for point in targets:\n'
    '                if point is None or not bool(getattr(point, "sb_accepted", True)):\n'
    '                    continue\n'
    '                pos = points.index(point)\n'
    '                lo = max(0, pos - half)\n'
    '                hi = min(len(points), pos + half + 1)\n'
    '                values = [point_depth(item) for item in points[lo:hi] if bool(getattr(item, "sb_accepted", True)) and point_depth(item) is not None]\n'
    '                if values:\n'
    '                    updates.append((point, statistics.mean(values)))\n'
    '            for point, depth in updates:\n'
    '                setattr(point, "sb_edited_depth", depth)\n'
    '                setattr(point, "sb_accepted", True)\n'
    '                setattr(point, "sb_flag", f"{\'LOCAL \' if local_only else \'\'}SMOOTH {window}")\n'
    '            log(f"Smoothed {len(updates)} sounding(s) with {window}-sample moving average.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def apply_tide_draft_edit() -> None:\n'
    '            tide = parse_float(tide_adjustment.get())\n'
    '            draft = parse_float(draft_adjustment.get())\n'
    '            if tide is None or draft is None:\n'
    '                messagebox.showwarning("SB EDIT", "Enter numeric tide and draft values.", parent=win)\n'
    '                return\n'
    '            for point in sounding_points():\n'
    '                if not bool(getattr(point, "sb_accepted", True)) or point.raw_depth is None:\n'
    '                    continue\n'
    '                point.tide = float(tide)\n'
    '                point.draft = float(draft)\n'
    '                setattr(point, "sb_edited_depth", point.corrected_depth)\n'
    '                setattr(point, "sb_flag", "TIDE+DRAFT")\n'
    '            log(f"Applied SB EDIT tide {tide:.3f} m and draft {draft:.3f} m to accepted soundings.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def bin_average() -> None:\n'
    '            points = [point for point in sounding_points() if bool(getattr(point, "sb_accepted", True)) and point_depth(point) is not None]\n'
    '            if not points:\n'
    '                log("No accepted soundings available for bin averaging.")\n'
    '                return\n'
    '            spacing = max(1.0, parse_float(bin_size.get()) or 25.0)\n'
    '            groups: dict[int, list[SurveyPoint]] = {}\n'
    '            for point in points:\n'
    '                key = int(float(getattr(point, "sb_along_track", 0.0)) // spacing)\n'
    '                groups.setdefault(key, []).append(point)\n'
    '            edit_bins.clear()\n'
    '            for key in sorted(groups):\n'
    '                rows = groups[key]\n'
    '                edit_bins.append(\n'
    '                    {\n'
    '                        "bin": key,\n'
    '                        "center_m": key * spacing + spacing / 2.0,\n'
    '                        "count": len(rows),\n'
    '                        "depth": statistics.mean(float(point_depth(row) or 0.0) for row in rows),\n'
    '                        "easting": statistics.mean(float(row.x or 0.0) for row in rows),\n'
    '                        "northing": statistics.mean(float(row.y or 0.0) for row in rows),\n'
    '                    }\n'
    '                )\n'
    '            log(f"Created {len(edit_bins)} bin-average sounding(s) at {spacing:.1f} m spacing.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def plot_click(event: tk.Event) -> None:\n'
    '            point = nearest_plotted_point(event.x, event.y)\n'
    '            if point is None:\n'
    '                return\n'
    '            set_selected(point)\n'
    '            mode = edit_mode.get()\n'
    '            if mode == "Reject":\n'
    '                reject_point(point)\n'
    '            elif mode == "Accept":\n'
    '                accept_point(point)\n'
    '            elif mode == "Smooth Local":\n'
    '                smooth_depths(local_only=True)\n'
    '            else:\n'
    '                update_selected_detail(point)\n'
    '                refresh_sb_edit()\n'
    '\n'
    '        def plot_press(event: tk.Event) -> None:\n'
    '            tool = graph_tool.get()\n'
    '            if tool == "Zoom Window":\n'
    '                graph_drag["start"] = (event.x, event.y)\n'
    '                if graph_drag.get("rect") is not None:\n'
    '                    plot_canvas.delete(graph_drag["rect"])\n'
    '                graph_drag["rect"] = plot_canvas.create_rectangle(event.x, event.y, event.x, event.y, outline="#2563eb", dash=(4, 3), width=2)\n'
    '                return\n'
    '            if tool == "Pan":\n'
    '                graph_drag["start"] = (event.x, float(graph_view_start.get()), float(graph_view_end.get()))\n'
    '                cursor_status.set("Pan mode: drag left/right to move through the line.")\n'
    '                return\n'
    '            plot_click(event)\n'
    '\n'
    '        def plot_drag(event: tk.Event) -> None:\n'
    '            tool = graph_tool.get()\n'
    '            start = graph_drag.get("start")\n'
    '            if tool == "Zoom Window" and start is not None:\n'
    '                x0, y0 = start  # type: ignore[misc]\n'
    '                rect = graph_drag.get("rect")\n'
    '                if rect is not None:\n'
    '                    plot_canvas.coords(rect, x0, y0, event.x, event.y)\n'
    '                return\n'
    '            if tool == "Pan" and start is not None:\n'
    '                x0, start_pct, end_pct = start  # type: ignore[misc]\n'
    '                plot_w = max(1.0, graph_world["plot_w"])\n'
    '                width_pct = max(1.0, end_pct - start_pct)\n'
    '                delta_pct = -((float(event.x) - float(x0)) / plot_w) * width_pct\n'
    '                set_graph_view(float(start_pct) + delta_pct, float(end_pct) + delta_pct)\n'
    '\n'
    '        def plot_release(event: tk.Event) -> None:\n'
    '            tool = graph_tool.get()\n'
    '            start = graph_drag.get("start")\n'
    '            if tool == "Zoom Window" and start is not None:\n'
    '                x0, _y0 = start  # type: ignore[misc]\n'
    '                rect = graph_drag.get("rect")\n'
    '                if rect is not None:\n'
    '                    plot_canvas.delete(rect)\n'
    '                graph_drag["start"] = None\n'
    '                graph_drag["rect"] = None\n'
    '                if abs(float(event.x) - float(x0)) < 8:\n'
    '                    return\n'
    '                chain0 = chain_from_canvas_x(float(x0))\n'
    '                chain1 = chain_from_canvas_x(float(event.x))\n'
    '                all_min = graph_world.get("all_min_chain", graph_world["min_chain"])\n'
    '                all_max = graph_world.get("all_max_chain", graph_world["max_chain"])\n'
    '                set_graph_view(\n'
    '                    percent_from_chain(min(chain0, chain1), all_min, all_max),\n'
    '                    percent_from_chain(max(chain0, chain1), all_min, all_max),\n'
    '                )\n'
    '                return\n'
    '            if tool == "Pan":\n'
    '                graph_drag["start"] = None\n'
    '\n'
    '        def plot_mousewheel(event: tk.Event) -> None:\n'
    '            all_min = graph_world.get("all_min_chain", graph_world["min_chain"])\n'
    '            all_max = graph_world.get("all_max_chain", graph_world["max_chain"])\n'
    '            center_chain = chain_from_canvas_x(getattr(event, "x", graph_world["left"] + graph_world["plot_w"] / 2.0))\n'
    '            center_pct = percent_from_chain(center_chain, all_min, all_max)\n'
    '            if getattr(event, "num", None) == 4 or getattr(event, "delta", 0) > 0:\n'
    '                zoom_graph(0.70, center_pct)\n'
    '            else:\n'
    '                zoom_graph(1.45, center_pct)\n'
    '\n'
    '        def plot_motion(event: tk.Event) -> None:\n'
    '            point = nearest_plotted_point(event.x, event.y)\n'
    '            if point is None:\n'
    '                cursor_status.set("Graphical Linear Editor: move over a sounding point, left-click to select, right-click for edit commands.")\n'
    '                return\n'
    '            cursor_status.set(\n'
    '                f"Hover #{getattr(point, \'sb_edit_index\', \'-\')} | "\n'
    '                f"Chain {format_number(getattr(point, \'sb_along_track\', None))} m | "\n'
    '                f"Raw {format_number(point.raw_depth)} | Corrected {format_number(point.corrected_depth)} | "\n'
    '                f"Edited {format_number(point_depth(point))} | {getattr(point, \'sb_flag\', \'RAW\')}"\n'
    '            )\n'
    '\n'
    '        def plot_right_click(event: tk.Event) -> None:\n'
    '            point = nearest_plotted_point(event.x, event.y)\n'
    '            if point is not None:\n'
    '                set_selected(point)\n'
    '                update_selected_detail(point)\n'
    '                redraw_sb_plot()\n'
    '            edit_menu = tk.Menu(win, tearoff=False)\n'
    '            edit_menu.add_command(label="Accept selected sounding", command=accept_point)\n'
    '            edit_menu.add_command(label="Reject selected sounding", command=reject_point)\n'
    '            edit_menu.add_command(label="Smooth selected sounding", command=lambda: smooth_depths(True))\n'
    '            edit_menu.add_separator()\n'
    '            edit_menu.add_command(label="Detect visible spikes", command=detect_spikes)\n'
    '            edit_menu.add_command(label="Bin average accepted soundings", command=bin_average)\n'
    '            try:\n'
    '                edit_menu.tk_popup(event.x_root, event.y_root)\n'
    '            finally:\n'
    '                edit_menu.grab_release()\n'
    '\n'
    '        def table_selected(_event: tk.Event) -> None:\n'
    '            selection = tree.selection()\n'
    '            if not selection:\n'
    '                return\n'
    '            target_id = selection[0]\n'
    '            for point in ensure_edit_state():\n'
    '                if str(id(point)) == target_id:\n'
    '                    set_selected(point)\n'
    '                    update_selected_detail(point)\n'
    '                    redraw_sb_plot()\n'
    '                    return\n'
    '\n'
    '        def save_sb_edit_json() -> None:\n'
    '            name = filedialog.asksaveasfilename(\n'
    '                title="Save SB EDIT JSON",\n'
    '                defaultextension=".json",\n'
    '                filetypes=[("JSON", "*.json"), ("All files", "*.*")],\n'
    '                initialfile="sb_edit_project.json",\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            rows = []\n'
    '            for point in ensure_edit_state():\n'
    '                rows.append(\n'
    '                    {\n'
    '                        "index": getattr(point, "sb_edit_index", None),\n'
    '                        "time": point.time,\n'
    '                        "along_track": getattr(point, "sb_along_track", None),\n'
    '                        "easting": point.x,\n'
    '                        "northing": point.y,\n'
    '                        "raw_depth": point.raw_depth,\n'
    '                        "corrected_depth": point.corrected_depth,\n'
    '                        "edited_depth": point_depth(point),\n'
    '                        "tide": point.tide,\n'
    '                        "draft": point.draft,\n'
    '                        "sound_speed": point.sound_speed,\n'
    '                        "accepted": bool(getattr(point, "sb_accepted", True)),\n'
    '                        "flag": getattr(point, "sb_flag", "RAW"),\n'
    '                        "source": point.source,\n'
    '                    }\n'
    '                )\n'
    '            payload = {"name": "SB EDIT", "saved": datetime.now().isoformat(timespec="seconds"), "soundings": rows, "bins": edit_bins}\n'
    '            Path(name).write_text(json.dumps(payload, indent=2), encoding="utf-8")\n'
    '            log(f"Saved SB EDIT JSON: {Path(name).name}")\n'
    '\n'
    '        def export_edited_csv() -> None:\n'
    '            name = filedialog.asksaveasfilename(\n'
    '                title="Export SB EDIT CSV",\n'
    '                defaultextension=".csv",\n'
    '                filetypes=[("CSV", "*.csv"), ("All files", "*.*")],\n'
    '                initialfile="sb_edit_soundings.csv",\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            fields = [\n'
    '                "index",\n'
    '                "time",\n'
    '                "along_track",\n'
    '                "easting",\n'
    '                "northing",\n'
    '                "raw_depth",\n'
    '                "corrected_depth",\n'
    '                "edited_depth",\n'
    '                "tide",\n'
    '                "draft",\n'
    '                "sound_speed",\n'
    '                "accepted",\n'
    '                "flag",\n'
    '                "source",\n'
    '            ]\n'
    '            with Path(name).open("w", encoding="utf-8", newline="") as handle:\n'
    '                writer = csv.DictWriter(handle, fieldnames=fields)\n'
    '                writer.writeheader()\n'
    '                for point in ensure_edit_state():\n'
    '                    writer.writerow(\n'
    '                        {\n'
    '                            "index": getattr(point, "sb_edit_index", None),\n'
    '                            "time": point.time,\n'
    '                            "along_track": getattr(point, "sb_along_track", None),\n'
    '                            "easting": point.x,\n'
    '                            "northing": point.y,\n'
    '                            "raw_depth": point.raw_depth,\n'
    '                            "corrected_depth": point.corrected_depth,\n'
    '                            "edited_depth": point_depth(point),\n'
    '                            "tide": point.tide,\n'
    '                            "draft": point.draft,\n'
    '                            "sound_speed": point.sound_speed,\n'
    '                            "accepted": int(bool(getattr(point, "sb_accepted", True))),\n'
    '                            "flag": getattr(point, "sb_flag", "RAW"),\n'
    '                            "source": point.source,\n'
    '                        }\n'
    '                    )\n'
    '            log(f"Exported SB EDIT CSV: {Path(name).name}")\n'
    '\n'
    '        def export_binned_csv() -> None:\n'
    '            if not edit_bins:\n'
    '                bin_average()\n'
    '                if not edit_bins:\n'
    '                    return\n'
    '            name = filedialog.asksaveasfilename(\n'
    '                title="Export SB EDIT Binned CSV",\n'
    '                defaultextension=".csv",\n'
    '                filetypes=[("CSV", "*.csv"), ("All files", "*.*")],\n'
    '                initialfile="sb_edit_binned.csv",\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            with Path(name).open("w", encoding="utf-8", newline="") as handle:\n'
    '                writer = csv.DictWriter(handle, fieldnames=["bin", "center_m", "count", "depth", "easting", "northing"])\n'
    '                writer.writeheader()\n'
    '                writer.writerows(edit_bins)\n'
    '            log(f"Exported SB EDIT binned CSV: {Path(name).name}")\n'
    '\n'
    '        def sentence_kind(text: str) -> str:\n'
    '            value = str(text or "").strip()\n'
    '            if not value.startswith("$"):\n'
    '                return ""\n'
    '            return value.split("*", 1)[0].split(",", 1)[0][-3:].upper()\n'
    '\n'
    '        def read_parameters() -> bool:\n'
    '            dialog = tk.Toplevel(win)\n'
    '            dialog.title("SB EDIT - Read Parameters")\n'
    '            dialog.geometry("720x700")\n'
    '            dialog.minsize(640, 620)\n'
    '            dialog.transient(win)\n'
    '            dialog.grab_set()\n'
    '            result = {"ok": False}\n'
    '\n'
    '            frame = ttk.Frame(dialog, padding=10)\n'
    '            frame.pack(fill="both", expand=True)\n'
    '            ttk.Label(\n'
    '                frame,\n'
    '                text="Select input sentences before loading RAW/NMEA data",\n'
    '                font=("Segoe UI", 12, "bold"),\n'
    '            ).pack(anchor="w", pady=(0, 8))\n'
    '            ttk.Label(\n'
    '                frame,\n'
    '                text="GNSS sentences are used for time/position only. Echosounder sentences are used for depths only.",\n'
    '                wraplength=560,\n'
    '            ).pack(anchor="w", pady=(0, 8))\n'
    '            top_action = ttk.Frame(frame)\n'
    '            top_action.pack(fill="x", pady=(0, 10))\n'
    '            ttk.Button(\n'
    '                top_action,\n'
    '                text="Apply Parameters and Load Selected File(s)",\n'
    '                command=lambda: apply_params(),\n'
    '            ).pack(side="left", fill="x", expand=True)\n'
    '            ttk.Button(top_action, text="Cancel", command=dialog.destroy).pack(side="right", padx=(8, 0))\n'
    '\n'
    '            body_params = ttk.PanedWindow(frame, orient="horizontal")\n'
    '            body_params.pack(fill="both", expand=True)\n'
    '            gnss_frame = ttk.LabelFrame(body_params, text="GNSS / Position Sentences", padding=8)\n'
    '            echo_frame = ttk.LabelFrame(body_params, text="Echosounder / Depth Sentences", padding=8)\n'
    '            body_params.add(gnss_frame, weight=1)\n'
    '            body_params.add(echo_frame, weight=1)\n'
    '\n'
    '            gnss_vars: dict[str, tk.BooleanVar] = {}\n'
    '            for row, item in enumerate(["GGA", "RMC", "GLL", "VTG", "GSA", "GSV", "ZDA", "GST", "HDT", "THS", "GNS", "GBS", "BESTPOSA", "BESTPOS"]):\n'
    '                var = tk.BooleanVar(value=item in sb_load_params["gnss"])\n'
    '                gnss_vars[item] = var\n'
    '                ttk.Checkbutton(gnss_frame, text=item, variable=var).grid(row=row, column=0, sticky="w", pady=1)\n'
    '\n'
    '            echo_vars: dict[str, tk.BooleanVar] = {}\n'
    '            for row, item in enumerate(["DPT", "DBT", "DBS", "DBK", "ECHOTRAC", "DESO25", "PLAIN_DEPTH"]):\n'
    '                var = tk.BooleanVar(value=item in sb_load_params["echo"] or (item == "PLAIN_DEPTH" and bool(sb_load_params["allow_plain_depth"])))\n'
    '                echo_vars[item] = var\n'
    '                ttk.Checkbutton(echo_frame, text=item, variable=var).grid(row=row, column=0, sticky="w", pady=1)\n'
    '\n'
    '            gnss_non_var = tk.BooleanVar(value=bool(sb_load_params["allow_gnss_non_nmea"]))\n'
    '            echo_non_var = tk.BooleanVar(value=bool(sb_load_params["allow_echo_non_nmea"]))\n'
    '            plain_var = tk.BooleanVar(value=bool(sb_load_params["allow_plain_depth"]))\n'
    '            ttk.Checkbutton(gnss_frame, text="Allow GNSS NON-NMEA text", variable=gnss_non_var).grid(row=11, column=0, sticky="w", pady=(10, 1))\n'
    '            ttk.Checkbutton(echo_frame, text="Allow echosounder NON-NMEA text", variable=echo_non_var).grid(row=11, column=0, sticky="w", pady=(10, 1))\n'
    '            ttk.Checkbutton(echo_frame, text="Allow plain numeric depth rows", variable=plain_var).grid(row=12, column=0, sticky="w", pady=1)\n'
    '\n'
    '            filters = ttk.LabelFrame(frame, text="Pre-Edit Depth Filters", padding=8)\n'
    '            filters.pack(fill="x", pady=(10, 0))\n'
    '            max_depth_var = tk.StringVar(value=str(sb_load_params["max_plain_depth"]))\n'
    '            spike_limit_var = tk.StringVar(value=str(sb_load_params["spike_limit"]))\n'
    '            step_gate_var = tk.StringVar(value=str(sb_load_params["step_gate"]))\n'
    '            for col in range(3):\n'
    '                filters.columnconfigure(col * 2 + 1, weight=1)\n'
    '            ttk.Label(filters, text="Max plain depth m").grid(row=0, column=0, sticky="w", padx=(0, 4), pady=2)\n'
    '            ttk.Entry(filters, textvariable=max_depth_var, width=8).grid(row=0, column=1, sticky="ew", padx=(0, 10), pady=2)\n'
    '            ttk.Label(filters, text="Spike limit m").grid(row=0, column=2, sticky="w", padx=(0, 4), pady=2)\n'
    '            ttk.Entry(filters, textvariable=spike_limit_var, width=8).grid(row=0, column=3, sticky="ew", padx=(0, 10), pady=2)\n'
    '            ttk.Label(filters, text="Step gate m").grid(row=0, column=4, sticky="w", padx=(0, 4), pady=2)\n'
    '            ttk.Entry(filters, textvariable=step_gate_var, width=8).grid(row=0, column=5, sticky="ew", pady=2)\n'
    '            ttk.Label(\n'
    '                filters,\n'
    '                text="Spike limit rejects local outliers. Step gate rejects sudden depth jumps between consecutive soundings.",\n'
    '                wraplength=560,\n'
    '            ).grid(row=1, column=0, columnspan=6, sticky="w", pady=(6, 0))\n'
    '\n'
    '            button_row = ttk.Frame(frame)\n'
    '            button_row.pack(fill="x", pady=(10, 0))\n'
    '\n'
    '            def apply_params() -> None:\n'
    '                gnss = {key for key, var in gnss_vars.items() if var.get()}\n'
    '                echo = {key for key, var in echo_vars.items() if var.get() and key != "PLAIN_DEPTH"}\n'
    '                allow_plain = bool(plain_var.get() or echo_vars["PLAIN_DEPTH"].get())\n'
    '                max_depth = parse_float(max_depth_var.get())\n'
    '                spike_limit = parse_float(spike_limit_var.get())\n'
    '                step_gate = parse_float(step_gate_var.get())\n'
    '                if not gnss:\n'
    '                    messagebox.showwarning("Read Parameters", "Select at least one GNSS sentence.", parent=dialog)\n'
    '                    return\n'
    '                if not echo and not allow_plain and not echo_non_var.get():\n'
    '                    messagebox.showwarning("Read Parameters", "Select at least one echosounder sentence or plain/NON-NMEA depth option.", parent=dialog)\n'
    '                    return\n'
    '                if max_depth is None or max_depth <= 0:\n'
    '                    messagebox.showwarning("Read Parameters", "Max plain depth must be positive.", parent=dialog)\n'
    '                    return\n'
    '                if spike_limit is None or spike_limit <= 0:\n'
    '                    messagebox.showwarning("Read Parameters", "Spike limit must be positive.", parent=dialog)\n'
    '                    return\n'
    '                if step_gate is None or step_gate <= 0:\n'
    '                    messagebox.showwarning("Read Parameters", "Step gate must be positive.", parent=dialog)\n'
    '                    return\n'
    '                sb_load_params.update(\n'
    '                    {\n'
    '                        "gnss": gnss,\n'
    '                        "echo": echo,\n'
    '                        "allow_gnss_non_nmea": bool(gnss_non_var.get()),\n'
    '                        "allow_echo_non_nmea": bool(echo_non_var.get()),\n'
    '                        "allow_plain_depth": allow_plain,\n'
    '                        "max_plain_depth": float(max_depth),\n'
    '                        "spike_limit": float(spike_limit),\n'
    '                        "step_gate": float(step_gate),\n'
    '                    }\n'
    '                )\n'
    '                params_ready.set(True)\n'
    '                spike_threshold.set(f"{float(spike_limit):.3f}")\n'
    '                params_status.set(\n'
    '                    "Read Parameters ready: "\n'
    '                    f"GNSS={\',\'.join(sorted(gnss))}; Echo={\',\'.join(sorted(echo)) or \'NONE\'}; "\n'
    '                    f"PlainDepth={\'ON\' if allow_plain else \'OFF\'}; Spike={float(spike_limit):.2f}m; Step={float(step_gate):.2f}m"\n'
    '                )\n'
    '                result["ok"] = True\n'
    '                dialog.destroy()\n'
    '\n'
    '            ttk.Button(button_row, text="Apply Parameters and Load Selected File(s)", command=apply_params).pack(side="left", fill="x", expand=True)\n'
    '            ttk.Button(button_row, text="Cancel", command=dialog.destroy).pack(side="right")\n'
    '            dialog.bind("<Return>", lambda _event: apply_params())\n'
    '            dialog.protocol("WM_DELETE_WINDOW", dialog.destroy)\n'
    '            dialog.lift()\n'
    '            dialog.focus_force()\n'
    '            win.wait_window(dialog)\n'
    '            return bool(result["ok"])\n'
    '\n'
    '        def clone_with_position(depth_point: SurveyPoint, position: Optional[SurveyPoint], source: str) -> SurveyPoint:\n'
    '            point = SurveyPoint(\n'
    '                time=depth_point.time or (position.time if position is not None else ""),\n'
    '                raw_depth=depth_point.raw_depth,\n'
    '                tide=model.tide,\n'
    '                draft=model.draft,\n'
    '                sound_speed=model.sound_speed,\n'
    '                source=source,\n'
    '            )\n'
    '            if position is not None:\n'
    '                point.easting = position.easting\n'
    '                point.northing = position.northing\n'
    '                point.latitude = position.latitude\n'
    '                point.longitude = position.longitude\n'
    '                point.altitude_m = position.altitude_m\n'
    '                point.quality = position.quality\n'
    '            return point\n'
    '\n'
    '        def parse_plain_depth_line(line: str) -> Optional[float]:\n'
    '            values = [parse_float(item) for item in re.split(r"[,\\t ]+", line.strip()) if item.strip()]\n'
    '            nums = [value for value in values if value is not None]\n'
    '            if len(nums) != 1:\n'
    '                return None\n'
    '            depth = float(nums[0])\n'
    '            if depth <= 0 or depth > float(sb_load_params["max_plain_depth"]):\n'
    '                return None\n'
    '            return depth\n'
    '\n'
    '        def load_filtered_sbes_file(path_obj: Path) -> list[SurveyPoint]:\n'
    '            if is_hypack_raw_file(path_obj):\n'
    '                # Typed HYPACK observations are authoritative; MSG is archival.\n'
    '                # Reading both would duplicate soundings and mistake RAW navigation for depth.\n'
    '                loaded = load_hypack_raw_points(path_obj)\n'
    '                for point in loaded:\n'
    '                    point.sound_speed = model.sound_speed\n'
    '                    if not point.draft: point.draft = model.draft\n'
    '                return loaded\n'
    '            loaded: list[SurveyPoint] = []\n'
    '            current_position: Optional[SurveyPoint] = None\n'
    '            last_tide = model.tide\n'
    '            with path_obj.open("r", encoding="utf-8", errors="replace") as handle:\n'
    '                for line_no, raw_line in enumerate(handle, 1):\n'
    '                    line = raw_line.strip()\n'
    '                    if not line:\n'
    '                        continue\n'
    '                    parts = line.replace(",", " ").split()\n'
    '                    tag = parts[0].upper() if parts else ""\n'
    '                    if tag == "TID" and len(parts) >= 4:\n'
    '                        tide = parse_float(parts[3])\n'
    '                        if tide is not None:\n'
    '                            last_tide = float(tide)\n'
    '                            if current_position is not None:\n'
    '                                current_position.tide = last_tide\n'
    '                        continue\n'
    '                    if tag == "POS" and len(parts) >= 5:\n'
    '                        point = SurveyPoint(\n'
    '                            time=hypack_time_to_display(parts[2] if len(parts) > 2 else parts[1]),\n'
    '                            easting=parse_float(parts[3]),\n'
    '                            northing=parse_float(parts[4]),\n'
    '                            tide=last_tide,\n'
    '                            source=f"{path_obj.name}:{line_no}",\n'
    '                        )\n'
    '                        loaded.append(point)\n'
    '                        current_position = point\n'
    '                        continue\n'
    '                    sentences = NMEA_RE.findall(line)\n'
    '                    used_sentence = False\n'
    '                    for sentence in sentences:\n'
    '                        used_sentence = True\n'
    '                        kind = sentence_kind(sentence)\n'
    '                        if kind in sb_load_params["gnss"]:\n'
    '                            parsed = parse_nmea_sentence(sentence)\n'
    '                            if parsed is not None:\n'
    '                                parsed.source = f"{path_obj.name}:{line_no}"\n'
    '                                if parsed.latitude is not None and parsed.longitude is not None:\n'
    '                                    ensure_projected_xy(parsed, settings.geodetic)\n'
    '                                    current_position = parsed\n'
    '                                    loaded.append(parsed)\n'
    '                                elif current_position is not None:\n'
    '                                    current_position.time = current_position.time or parsed.time\n'
    '                                    current_position.speed_knots = parsed.speed_knots or current_position.speed_knots\n'
    '                                    current_position.course_degrees = parsed.course_degrees or current_position.course_degrees\n'
    '                                    current_position.heading_degrees = parsed.heading_degrees or current_position.heading_degrees\n'
    '                        elif kind in sb_load_params["echo"]:\n'
    '                            parsed_depth = parse_sbes_sentence(sentence)\n'
    '                            depth = parsed_depth.get("depth")\n'
    '                            if depth is None:\n'
    '                                parsed = parse_nmea_sentence(sentence)\n'
    '                                depth = parsed.raw_depth if parsed is not None else None\n'
    '                            if depth is None:\n'
    '                                continue\n'
    '                            depth_point = SurveyPoint(raw_depth=float(depth), source=f"{path_obj.name}:{line_no}")\n'
    '                            loaded.append(clone_with_position(depth_point, current_position, f"{path_obj.name}:{line_no}"))\n'
    '                    if used_sentence:\n'
    '                        continue\n'
    '                    if tag in {"EC1", "EC2", "DEP", "RAW"} and bool(sb_load_params["allow_echo_non_nmea"]):\n'
    '                        if tag == "RAW" and len(parts) >= 3:\n'
    '                            depth = parse_float(parts[2])\n'
    '                            time_text = parts[1]\n'
    '                        elif len(parts) >= 4:\n'
    '                            depth = parse_float(parts[3])\n'
    '                            time_text = parts[2]\n'
    '                        else:\n'
    '                            depth = None\n'
    '                            time_text = ""\n'
    '                        if depth is not None and 0 < float(depth) <= float(sb_load_params["max_plain_depth"]):\n'
    '                            depth_point = SurveyPoint(\n'
    '                                time=hypack_time_to_display(time_text),\n'
    '                                raw_depth=float(depth),\n'
    '                                tide=last_tide,\n'
    '                                source=f"{path_obj.name}:{line_no}",\n'
    '                            )\n'
    '                            loaded.append(clone_with_position(depth_point, current_position, f"{path_obj.name}:{line_no}"))\n'
    '                        continue\n'
    '                    if bool(sb_load_params["allow_plain_depth"]):\n'
    '                        depth = parse_plain_depth_line(line)\n'
    '                        if depth is not None:\n'
    '                            loaded.append(clone_with_position(SurveyPoint(raw_depth=depth), current_position, f"{path_obj.name}:{line_no}"))\n'
    '            return loaded\n'
    '\n'
    '        def apply_pre_edit_filters(points: list[SurveyPoint]) -> tuple[int, int]:\n'
    '            soundings = [point for point in points if point.raw_depth is not None or point.corrected_depth is not None]\n'
    '            if not soundings:\n'
    '                return 0, 0\n'
    '            ensure_edit_state()\n'
    '            spike_limit = float(sb_load_params["spike_limit"])\n'
    '            step_gate = float(sb_load_params["step_gate"])\n'
    '            spike_rejects = 0\n'
    '            step_rejects = 0\n'
    '            for pos, point in enumerate(soundings):\n'
    '                depth = point_depth(point)\n'
    '                if depth is None:\n'
    '                    continue\n'
    '                lo = max(0, pos - 2)\n'
    '                hi = min(len(soundings), pos + 3)\n'
    '                window = sorted(point_depth(item) for item in soundings[lo:hi] if point_depth(item) is not None)\n'
    '                if window:\n'
    '                    median = window[len(window) // 2]\n'
    '                    delta = abs(depth - median)\n'
    '                    if delta > spike_limit:\n'
    '                        setattr(point, "sb_accepted", False)\n'
    '                        setattr(point, "sb_flag", f"PRE SPIKE {delta:.2f}m")\n'
    '                        spike_rejects += 1\n'
    '                        continue\n'
    '                if pos > 0:\n'
    '                    previous = point_depth(soundings[pos - 1])\n'
    '                    if previous is not None and abs(depth - previous) > step_gate:\n'
    '                        setattr(point, "sb_accepted", False)\n'
    '                        setattr(point, "sb_flag", f"STEP GATE {abs(depth - previous):.2f}m")\n'
    '                        step_rejects += 1\n'
    '            return spike_rejects, step_rejects\n'
    '\n'
    '        def load_hypack_raw(path_obj):\n'
    '            return load_hypack_raw_points(path_obj)\n'
    '\n'
    '        def load_recorded() -> None:\n'
    '            names = filedialog.askopenfilenames(\n'
    '                title="Load One or More Recorded RAW / NMEA Files",\n'
    '                initialdir=str(Path(settings.raw_folder or str(default_raw_folder()))),\n'
    '                filetypes=[\n'
    '                    ("Recorded RAW / NMEA", "*.raw *.RAW *.txt *.log *.nmea *.csv *.1 *.2 *.3"),\n'
    '                    ("All files", "*.*"),\n'
    '                ],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not names:\n'
    '                return\n'
    '            path_list = [Path(name) for name in names]\n'
    '            if len(path_list) == 1:\n'
    '                params_status.set(f"Selected {path_list[0].name}. Confirm Read Parameters before loading.")\n'
    '            else:\n'
    '                params_status.set(f"Selected {len(path_list)} files. Confirm Read Parameters before loading.")\n'
    '            if not read_parameters():\n'
    '                log("Load cancelled. Read Parameters must be confirmed after selecting RAW/NMEA file(s).")\n'
    '                return\n'
    '            before = len(model.points)\n'
    '            total_added = 0\n'
    '            loaded_points: list[SurveyPoint] = []\n'
    '            file_summaries: list[str] = []\n'
    '            try:\n'
    '                read_settings()\n'
    '\n'
    '                def add_loaded_point(point: SurveyPoint) -> None:\n'
    '                    if point.latitude is not None and point.longitude is not None:\n'
    '                        easting, northing = project_lat_lon_to_selected_xy(point.latitude, point.longitude, settings.geodetic)\n'
    '                        if easting is not None and northing is not None:\n'
    '                            point.easting = easting\n'
    '                            point.northing = northing\n'
    '                    model.add(point)\n'
    '                    loaded_points.append(point)\n'
    '\n'
    '                for path_obj in path_list:\n'
    '                    added = 0\n'
    '                    if is_hypack_raw_file(path_obj):\n'
    '                        for point in load_filtered_sbes_file(path_obj):\n'
    '                            add_loaded_point(point)\n'
    '                            added += 1\n'
    '                        if added == 0:\n'
    '                            log(f"{path_obj.name}: no HYPACK RAW rows matched. Enable echosounder NON-NMEA for EC1/DEP/RAW depth tags.")\n'
    '                    elif is_hypack_edited_file(path_obj):\n'
    '                        for point in load_hypack_edited_points(path_obj):\n'
    '                            add_loaded_point(point)\n'
    '                            added += 1\n'
    '                    elif path_obj.suffix.lower() in {".nmea", ".log", ".txt", ".raw"}:\n'
    '                        for point in load_filtered_sbes_file(path_obj):\n'
    '                            add_loaded_point(point)\n'
    '                            added += 1\n'
    '                        if added == 0:\n'
    '                            log(f"{path_obj.name}: no rows matched the selected Read Parameters.")\n'
    '                    else:\n'
    '                        temp_model = SurveyModel()\n'
    '                        temp_model.tide = model.tide\n'
    '                        temp_model.draft = model.draft\n'
    '                        temp_model.sound_speed = model.sound_speed\n'
    '                        added = temp_model.load_file(path_obj)\n'
    '                        for point in temp_model.points:\n'
    '                            add_loaded_point(point)\n'
    '                    total_added += added\n'
    '                    file_summaries.append(f"{path_obj.name}: {added}")\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror("SB EDIT", f"Could not load recorded file:\\n{exc}", parent=win)\n'
    '                return\n'
    '            spike_rejects, step_rejects = apply_pre_edit_filters(loaded_points)\n'
    '            log(\n'
    '                f"Loaded {len(path_list)} file(s). Added {len(model.points) - before if total_added else 0} row(s). "\n'
    '                f"Pre-edit filters: spike rejected {spike_rejects}, step-gate rejected {step_rejects}."\n'
    '            )\n'
    '            if file_summaries:\n'
    '                log("File load counts: " + "; ".join(file_summaries))\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def create_tid_tdx_editor() -> None:\n'
    '            editor = tk.Toplevel(win)\n'
    '            editor.title("Create TID / TDX Tide File")\n'
    '            editor.geometry("760x560")\n'
    '            editor.minsize(620, 420)\n'
    '            try:\n'
    '                editor.state("zoomed")\n'
    '            except Exception:\n'
    '                pass\n'
    '            frame = ttk.Frame(editor, padding=10)\n'
    '            frame.pack(fill="both", expand=True)\n'
    '            ttk.Label(frame, text="Manual Tide Spreadsheet: Date, Time, Tide Height", font=("Segoe UI", 11, "bold")).pack(anchor="w")\n'
    '            tide_text = tk.Text(frame, wrap="none", height=18)\n'
    '            tide_text.pack(fill="both", expand=True, pady=8)\n'
    '            tide_text.insert("end", "Date,Time,TideHeight\\n2026-06-12,08:00:00,0.00\\n2026-06-12,09:00:00,0.05\\n")\n'
    '            status_local = tk.StringVar(value="Enter or paste rows as Date, Time, TideHeight. CSV, tab, or space separated rows are accepted.")\n'
    '            ttk.Label(frame, textvariable=status_local).pack(anchor="w", pady=(0, 6))\n'
    '\n'
    '            def tide_rows() -> list[tuple[str, str, float]]:\n'
    '                rows: list[tuple[str, str, float]] = []\n'
    '                for raw_line in tide_text.get("1.0", "end").splitlines():\n'
    '                    line = raw_line.strip()\n'
    '                    if not line or line.startswith("#") or line.lower().startswith("date"):\n'
    '                        continue\n'
    '                    parts = [part.strip() for part in re.split(r"[,\\\\t ]+", line) if part.strip()]\n'
    '                    if len(parts) < 2:\n'
    '                        continue\n'
    '                    height = parse_float(parts[-1])\n'
    '                    if height is None:\n'
    '                        continue\n'
    '                    if len(parts) >= 3:\n'
    '                        date_text = parts[0]\n'
    '                        time_text = parts[1]\n'
    '                    else:\n'
    '                        date_text = ""\n'
    '                        time_text = parts[0]\n'
    '                    rows.append((date_text, time_text, float(height)))\n'
    '                return rows\n'
    '\n'
    '            def save_tide_file(kind: str) -> None:\n'
    '                rows = tide_rows()\n'
    '                if not rows:\n'
    '                    messagebox.showwarning("Create TID / TDX", "No valid tide rows found.", parent=editor)\n'
    '                    return\n'
    '                ext = ".tdx" if kind.upper() == "TDX" else ".tid"\n'
    '                name = filedialog.asksaveasfilename(\n'
    '                    title=f"Save {kind.upper()} Tide File",\n'
    '                    initialdir=str(project_root_from_raw_folder(settings.raw_folder)),\n'
    '                    defaultextension=ext,\n'
    '                    filetypes=[(f"{kind.upper()} tide", f"*{ext}"), ("All files", "*.*")],\n'
    '                    parent=editor,\n'
    '                )\n'
    '                if not name:\n'
    '                    return\n'
    '                target = Path(name)\n'
    '                with target.open("w", encoding="utf-8", newline="\\\\n") as handle:\n'
    '                    if kind.upper() == "TDX":\n'
    '                        handle.write("Date,Time,TideHeight\\\\n")\n'
    '                        for date_text, time_text, height in rows:\n'
    '                            handle.write(f"{date_text},{time_text},{height:.3f}\\\\n")\n'
    '                    else:\n'
    '                        handle.write("# HYDROGEOMATICS TID tide file\\\\n")\n'
    '                        handle.write("# Date Time TideHeight_m\\\\n")\n'
    '                        for date_text, time_text, height in rows:\n'
    '                            handle.write(f"{date_text} {time_text} {height:.3f}\\\\n")\n'
    '                status_local.set(f"Saved {len(rows)} tide row(s) to {target.name}")\n'
    '                log(f"Created {target.name} with {len(rows)} tide row(s).")\n'
    '\n'
    '            buttons = ttk.Frame(frame)\n'
    '            buttons.pack(fill="x")\n'
    '            ttk.Button(buttons, text="Save TID", command=lambda: save_tide_file("TID")).pack(side="left", padx=3)\n'
    '            ttk.Button(buttons, text="Save TDX", command=lambda: save_tide_file("TDX")).pack(side="left", padx=3)\n'
    '            ttk.Button(buttons, text="Close", command=editor.destroy).pack(side="right", padx=3)\n'
    '\n'
    '        def tide_editor() -> None:\n'
    '            value = simpledialog.askfloat("SB EDIT", "Tide correction (m):", initialvalue=model.tide, parent=win)\n'
    '            if value is None:\n'
    '                return\n'
    '            tide_var.set(f"{value:.3f}")\n'
    '            read_settings()\n'
    '            model.apply_offsets()\n'
    '            log(f"Tide correction set to {value:.3f} m")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def sv_editor() -> None:\n'
    '            value = simpledialog.askfloat("SB EDIT", "Sound velocity (m/s):", initialvalue=model.sound_speed, minvalue=1.0, parent=win)\n'
    '            if value is None:\n'
    '                return\n'
    '            sv_var.set(f"{value:.3f}")\n'
    '            read_settings()\n'
    '            model.apply_offsets()\n'
    '            log(f"Sound velocity set to {value:.3f} m/s")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def apply_tide_sv() -> None:\n'
    '            read_settings()\n'
    '            model.apply_offsets()\n'
    '            for point in live_echogram_points:\n'
    '                point.tide = model.tide\n'
    '                point.draft = model.draft\n'
    '                point.sound_speed = model.sound_speed\n'
    '            log("Applied tide, draft, and sound velocity corrections.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def interpolate_tide_by_index(tides: list[tuple[int, float]], index: int) -> Optional[float]:\n'
    '            if not tides:\n'
    '                return None\n'
    '            tides_sorted = sorted(tides, key=lambda item: item[0])\n'
    '            if index <= tides_sorted[0][0]:\n'
    '                return tides_sorted[0][1]\n'
    '            if index >= tides_sorted[-1][0]:\n'
    '                return tides_sorted[-1][1]\n'
    '            for (i0, v0), (i1, v1) in zip(tides_sorted, tides_sorted[1:]):\n'
    '                if i0 <= index <= i1:\n'
    '                    if i1 == i0:\n'
    '                        return v0\n'
    '                    ratio = (index - i0) / (i1 - i0)\n'
    '                    return v0 + (v1 - v0) * ratio\n'
    '            return tides_sorted[-1][1]\n'
    '\n'
    '        def apply_observed_tide_file_to_loaded() -> None:\n'
    '            if not messagebox.askyesno(\n'
    '                "SB EDIT post-processing",\n'
    '                "Use an observed Tide file for post-processing this loaded data?\\n\\n"\n'
    '                "This applies observed tide values and does not recalculate RTK/KTD corrections.",\n'
    '                parent=win,\n'
    '            ):\n'
    '                return\n'
    '            name = filedialog.askopenfilename(\n'
    '                title="Select observed Tide file",\n'
    '                initialdir=str(project_root_from_raw_folder(settings.raw_folder)),\n'
    '                filetypes=[("HYPACK Tide", "*.tid *.TID *.tide *.txt"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            try:\n'
    '                tides = load_hypack_tide_file(Path(name))\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror("SB EDIT", f"Could not load tide file:\\n{exc}", parent=win)\n'
    '                return\n'
    '            applied = 0\n'
    '            for index, point in enumerate(model.points):\n'
    '                tide_value = interpolate_tide_by_index(tides, index)\n'
    '                if tide_value is None:\n'
    '                    continue\n'
    '                point.tide = tide_value\n'
    '                point.rtk_reduced_height = None\n'
    '                point.rtk_reduced_depth = None\n'
    '                point.ktd_cell_k = None\n'
    '                applied += 1\n'
    '            model.apply_offsets()\n'
    '            log(f"Applied observed tide file {Path(name).name} to {applied} row(s). RTK/KTD recalculation was not used.")\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def apply_rtk_tide_to_loaded() -> None:\n'
    '            if not messagebox.askyesno(\n'
    '                "SB EDIT post-processing",\n'
    '                "Recalculate RTK tidal corrections using the selected KTD file?\\n\\n"\n'
    '                "This uses each raw point\'s ellipsoidal height H and KTD cell value K: H-K. "\n'
    '                "Choose No if you want observed tide-file corrections for this file.",\n'
    '                parent=win,\n'
    '            ):\n'
    '                return\n'
    '            applied = 0\n'
    '            last_reduced_height = None\n'
    '            missing_alt = 0\n'
    '            missing_k = 0\n'
    '            read_settings()\n'
    '            for point in model.points:\n'
    '                if point.altitude_m is None:\n'
    '                    missing_alt += 1\n'
    '                    continue\n'
    '                if apply_ktd_rtk_postprocess_to_point(point, settings.geodetic):\n'
    '                    last_reduced_height = point.rtk_reduced_height\n'
    '                    applied += 1\n'
    '                else:\n'
    '                    missing_k += 1\n'
    '            if applied and last_reduced_height is not None:\n'
    '                tide_var.set(f"{last_reduced_height:.3f}")\n'
    '                log(\n'
    '                    f"RTK KTD post-processing applied to {applied} row(s): "\n'
    '                    "H-K reduced height and depth = raw depth + draft - (H-K). "\n'
    '                    f"Skipped no ellipsoid height: {missing_alt}; no K cell: {missing_k}."\n'
    '                )\n'
    '            else:\n'
    '                log(\n'
    '                    "No rows processed. Need raw rows with ellipsoidal height and a KTD file selected in Geodetic settings. "\n'
    '                    f"Skipped no ellipsoid height: {missing_alt}; no K cell: {missing_k}."\n'
    '                )\n'
    '            refresh_sb_edit()\n'
    '\n'
    '        def replay_loaded_echogram() -> None:\n'
    '            read_settings()\n'
    '            points = current_points()\n'
    '            start_echogram_replay(points)\n'
    '            log(f"Replaying echogram from {len([p for p in points if p.raw_depth is not None or p.corrected_depth is not None])} depth sample(s).")\n'
    '\n'
    '        def clear_live_echogram() -> None:\n'
    '            live_echogram_points.clear()\n'
    '            stop_echogram_replay()\n'
    '            draw_view()\n'
    '            log("Cleared live/replay echogram buffer.")\n'
    '\n'
    '        def export_csv() -> None:\n'
    '            name = filedialog.asksaveasfilename(\n'
    '                title="Export SB CSV",\n'
    '                defaultextension=".csv",\n'
    '                filetypes=[("CSV", "*.csv"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            try:\n'
    '                count = model.export_csv(Path(name))\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror("SB EDIT", f"Could not export CSV:\\n{exc}", parent=win)\n'
    '                return\n'
    '            log(f"Exported {count} rows to {Path(name).name}")\n'
    '\n'
    '        def export_xyz() -> None:\n'
    '            name = filedialog.asksaveasfilename(\n'
    '                title="Export SB XYZ",\n'
    '                defaultextension=".xyz",\n'
    '                filetypes=[("XYZ", "*.xyz"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            try:\n'
    '                count = model.export_xyz(Path(name))\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror("SB EDIT", f"Could not export XYZ:\\n{exc}", parent=win)\n'
    '                return\n'
    '            log(f"Exported {count} soundings to {Path(name).name}")\n'
    '\n'
    '        actions = [\n'
    '            ("Load RAW / NMEA", load_recorded),\n'
    '            ("Create TID/TDX", create_tid_tdx_editor),\n'
    '            ("Accept", accept_point),\n'
    '            ("Reject", reject_point),\n'
    '            ("Accept All", accept_all),\n'
    '            ("Detect Spikes", detect_spikes),\n'
    '            ("Smooth", lambda: smooth_depths(False)),\n'
    '            ("Smooth Local", lambda: smooth_depths(True)),\n'
    '            ("Bin Average", bin_average),\n'
    '            ("Reset Edit", reset_editing),\n'
    '            ("Apply Tide/Draft", apply_tide_draft_edit),\n'
    '            ("Save JSON", save_sb_edit_json),\n'
    '            ("Export Edited CSV", export_edited_csv),\n'
    '            ("Export Binned CSV", export_binned_csv),\n'
    '            ("Set Tide", tide_editor),\n'
    '            ("Sound Velocity", sv_editor),\n'
    '            ("Apply Tide", apply_tide_sv),\n'
    '            ("Post: Tide File", apply_observed_tide_file_to_loaded),\n'
    '            ("Post: RTK/KTD", apply_rtk_tide_to_loaded),\n'
    '            ("Replay Echogram", replay_loaded_echogram),\n'
    '            ("Stop Replay", stop_echogram_replay),\n'
    '            ("Clear Echogram", clear_live_echogram),\n'
    '            ("Export CSV", export_csv),\n'
    '            ("Export XYZ", export_xyz),\n'
    '            ("Refresh", refresh_sb_edit),\n'
    '        ]\n'
    '        button_bar = ttk.Frame(top)\n'
    '        button_bar.pack(side="left", fill="x", expand=True)\n'
    '        for index, (label, command) in enumerate(actions):\n'
    '            row = index // 8\n'
    '            col = index % 8\n'
    '            ttk.Button(button_bar, text=label, command=command).grid(row=row, column=col, sticky="ew", padx=3, pady=2)\n'
    '            button_bar.columnconfigure(col, weight=1)\n'
    '        ttk.Label(top, textvariable=status).pack(side="right", padx=6)\n'
    '        plot_canvas.bind("<Configure>", lambda _event: redraw_sb_plot())\n'
    '        plot_canvas.bind("<Button-1>", plot_press)\n'
    '        plot_canvas.bind("<B1-Motion>", plot_drag)\n'
    '        plot_canvas.bind("<ButtonRelease-1>", plot_release)\n'
    '        plot_canvas.bind("<Motion>", plot_motion)\n'
    '        plot_canvas.bind("<Button-3>", plot_right_click)\n'
    '        plot_canvas.bind("<MouseWheel>", plot_mousewheel)\n'
    '        plot_canvas.bind("<Button-4>", plot_mousewheel)\n'
    '        plot_canvas.bind("<Button-5>", plot_mousewheel)\n'
    '        tree.bind("<<TreeviewSelect>>", table_selected)\n'
    '        refresh_sb_edit()\n'
    '\n'
    '    def draw_view() -> None:\n'
    '        view_state["draw_pending"] = False\n'
    '        if root.q.property("unified_navigation"):return\n'
    '        if view_mode.get() == "echogram":\n'
    '            draw_echogram()\n'
    '        else:\n'
    '            draw_plot()\n'
    '\n'
    '    def request_draw_view(delay_ms: int = 25) -> None:\n'
    '        if view_state.get("draw_pending"):\n'
    '            return\n'
    '        view_state["draw_pending"] = True\n'
    '        root.after(delay_ms, draw_view)\n'
    '\n'
    '    def draw_echogram(target_canvas: Optional[tk.Canvas] = None) -> None:\n'
    '        target = target_canvas or canvas\n'
    '        target.delete("all")\n'
    '        width = max(target.winfo_width(), 10)\n'
    '        height = max(target.winfo_height(), 10)\n'
    '        target.create_rectangle(0, 0, width, height, fill="#05070a", outline="")\n'
    '        echogram_source = live_echogram_points if live_echogram_points else model.points\n'
    '        echogram = EchogramModel(depth_bins=max(40, min(220, height - 42)))\n'
    '        echogram.build_from_points(echogram_source)\n'
    '        if not echogram.pings:\n'
    '            target.create_text(\n'
    '                width // 2,\n'
    '                height // 2,\n'
    '                text=f"No echogram samples. Enable SBES {settings.sensor.port} or replay loaded data from SB EDIT.",\n'
    '                fill="#b8c2cc",\n'
    '                font=("Segoe UI", 14),\n'
    '            )\n'
    '            return\n'
    '        plot_left = 38\n'
    '        plot_top = 12\n'
    '        plot_bottom = height - 28\n'
    '        plot_width = max(1, width - plot_left - 8)\n'
    '        plot_height = max(1, plot_bottom - plot_top)\n'
    '        pings = echogram.pings[-plot_width:]\n'
    '        x_scale = plot_width / max(1, len(pings))\n'
    '        y_scale = plot_height / max(1, echogram.depth_bins)\n'
    '        for x_index, ping in enumerate(pings):\n'
    '            x1 = plot_left + x_index * x_scale\n'
    '            x2 = plot_left + (x_index + 1) * x_scale + 1\n'
    '            for y_index, value in enumerate(ping):\n'
    '                r, g, b = waterfall_color(value)\n'
    '                y1 = plot_top + y_index * y_scale\n'
    '                y2 = plot_top + (y_index + 1) * y_scale + 1\n'
    '                target.create_rectangle(x1, y1, x2, y2, fill=f"#{r:02x}{g:02x}{b:02x}", outline="")\n'
    '        depths = [\n'
    '            float(depth)\n'
    '            for point in echogram_source\n'
    '            for depth in [point.corrected_depth if point.corrected_depth is not None else point.raw_depth]\n'
    '            if depth is not None\n'
    '        ]\n'
    '        max_depth = max(depths) * 1.15 if depths else 1.0\n'
    '        visible_depths = echogram.bottom_depths[-len(pings):]\n'
    '        last_xy: Optional[tuple[float, float]] = None\n'
    '        for x_index, depth in enumerate(visible_depths):\n'
    '            if depth is None:\n'
    '                continue\n'
    '            x = plot_left + (x_index + 0.5) * x_scale\n'
    '            y = plot_top + min(max(depth / max_depth, 0.0), 1.0) * plot_height\n'
    '            if last_xy is not None:\n'
    '                target.create_line(last_xy[0], last_xy[1], x, y, fill="#ffffff", width=2)\n'
    '            last_xy = (x, y)\n'
    '        for tick in range(5):\n'
    '            ratio = tick / 4\n'
    '            y = plot_top + ratio * plot_height\n'
    '            target.create_line(plot_left - 4, y, plot_left, y, fill="#6b7785")\n'
    '            target.create_text(\n'
    '                plot_left - 8,\n'
    '                y,\n'
    '                anchor="e",\n'
    '                text=f"{max_depth * ratio:.1f}",\n'
    '                fill="#b8c2cc",\n'
    '                font=("Segoe UI", 8),\n'
    '            )\n'
    '        target.create_text(\n'
    '            plot_left,\n'
    '            height - 18,\n'
    '            anchor="w",\n'
    '            text=f"Acoustic Waterfall | {\'LIVE/REPLAY\' if live_echogram_points else \'MODEL\'} | {len(echogram.pings)} pings | SBES {settings.sensor.port} | white trace = bottom/depth pick",\n'
    '            fill="#d8dee9",\n'
    '            font=("Segoe UI", 10),\n'
    '        )\n'
    '\n'
    '    def draw_plot() -> None:\n'
    '        canvas.delete("all")\n'
    '        width = max(canvas.winfo_width(), 10)\n'
    '        height = max(canvas.winfo_height(), 10)\n'
    '        chart_style = bool(enc_background_shapes)\n'
    '        canvas_bg = CHART_BACKGROUND_COLOR if chart_style else theme_colors.get("canvas", "#101418")\n'
    '        canvas.create_rectangle(0, 0, width, height, fill=canvas_bg, outline="")\n'
    '        points = [p for p in model.points if p.x is not None and p.y is not None]\n'
    '        background_points = [p for p in project_background_points if p.x is not None and p.y is not None]\n'
    '        line_points: list[tuple[float, float]] = list(border_points)\n'
    '        for shape in dxf_background_shapes + enc_background_shapes + kmz_background_shapes + ktd_extent_shapes:\n'
    '            bbox = cached_shape_bbox(shape)\n'
    '            if bbox is not None:\n'
    '                line_points.append((bbox[0], bbox[1]))\n'
    '                line_points.append((bbox[2], bbox[3]))\n'
    '        for line in runlines.lines:\n'
    '            line_points.append((line.start_x, line.start_y))\n'
    '            line_points.append((line.end_x, line.end_y))\n'
    '        if not points and not background_points and not line_points:\n'
    '            canvas.create_rectangle(8, 8, width - 8, height - 8, outline="#7c8791", width=2)\n'
    '            canvas.create_text(\n'
    '                width // 2,\n'
    '                height // 2,\n'
    '                text="Load survey data or create runlines",\n'
    '                fill="#b8c2cc",\n'
    '                font=("Segoe UI", 14),\n'
    '            )\n'
    '            return\n'
    '        xs = [float(p.x) for p in points if p.x is not None] + [float(p.x) for p in background_points if p.x is not None] + [p[0] for p in line_points]\n'
    '        ys = [float(p.y) for p in points if p.y is not None] + [float(p.y) for p in background_points if p.y is not None] + [p[1] for p in line_points]\n'
    '        depths = [p.corrected_depth for p in points if p.corrected_depth is not None]\n'
    '        min_x, max_x = min(xs), max(xs)\n'
    '        min_y, max_y = min(ys), max(ys)\n'
    '        full_min_x, full_max_x = min_x, max_x\n'
    '        full_min_y, full_max_y = min_y, max_y\n'
    '        min_d = min(depths) if depths else 0.0\n'
    '        max_d = max(depths) if depths else 1.0\n'
    '        margin = 54\n'
    '        span_x = max(max_x - min_x, 1e-9)\n'
    '        span_y = max(max_y - min_y, 1e-9)\n'
    '        span_d = max(max_d - min_d, 1e-9)\n'
    '        selected_scale_span = nav_scale_to_span_m(nav_scale_var.get())\n'
    '        if follow_vessel.get() and points:\n'
    '            vessel_point = points[-1]\n'
    '            center_x = float(vessel_point.x)\n'
    '            center_y = float(vessel_point.y)\n'
    '        else:\n'
    '            if selected_scale_span is not None and float(view_state.get("last_span_x", 0.0)) > 0.0:\n'
    '                center_x = (float(view_state.get("last_min_x", min_x)) + float(view_state.get("last_max_x", max_x))) / 2.0 + float(view_state["pan_x"])\n'
    '                center_y = (float(view_state.get("last_min_y", min_y)) + float(view_state.get("last_max_y", max_y))) / 2.0 + float(view_state["pan_y"])\n'
    '            else:\n'
    '                center_x = (min_x + max_x) / 2.0 + float(view_state["pan_x"])\n'
    '                center_y = (min_y + max_y) / 2.0 + float(view_state["pan_y"])\n'
    '        if selected_scale_span is not None:\n'
    '            aspect = max((height - margin * 2) / max(width - margin * 2, 1), 0.1)\n'
    '            span_x = max(selected_scale_span, 1e-9)\n'
    '            span_y = max(selected_scale_span * aspect, 1e-9)\n'
    '            zoom = 1.0\n'
    '        else:\n'
    '            zoom = max(float(view_state["zoom"]), 0.05)\n'
    '            span_x = max(span_x / zoom, 1e-9)\n'
    '            span_y = max(span_y / zoom, 1e-9)\n'
    '            plot_aspect = max((height - margin * 2) / max(width - margin * 2, 1), 0.1)\n'
    '            current_aspect = span_y / max(span_x, 1e-9)\n'
    '            if current_aspect < plot_aspect:\n'
    '                span_y = span_x * plot_aspect\n'
    '            elif current_aspect > plot_aspect:\n'
    '                span_x = span_y / plot_aspect\n'
    '        min_x = center_x - span_x / 2.0\n'
    '        max_x = center_x + span_x / 2.0\n'
    '        min_y = center_y - span_y / 2.0\n'
    '        max_y = center_y + span_y / 2.0\n'
    '        view_state["last_span_x"] = span_x\n'
    '        view_state["last_span_y"] = span_y\n'
    '        view_state["last_min_x"] = min_x\n'
    '        view_state["last_max_x"] = max_x\n'
    '        view_state["last_min_y"] = min_y\n'
    '        view_state["last_max_y"] = max_y\n'
    '        view_state["full_center_x"] = (full_min_x + full_max_x) / 2.0\n'
    '        view_state["full_center_y"] = (full_min_y + full_max_y) / 2.0\n'
    '        view_state["full_span_x"] = max(full_max_x - full_min_x, 1e-9)\n'
    '        view_state["full_span_y"] = max(full_max_y - full_min_y, 1e-9)\n'
    '        view_state["last_plot_width"] = max(width - margin * 2, 1)\n'
    '        view_state["last_plot_height"] = max(height - margin * 2, 1)\n'
    '\n'
    '        def project_xy(x_value: float, y_value: float) -> tuple[float, float]:\n'
    '            px = margin + ((x_value - min_x) / span_x) * (width - margin * 2)\n'
    '            py = height - margin - ((y_value - min_y) / span_y) * (height - margin * 2)\n'
    '            return px, py\n'
    '\n'
    '        plot_left = margin\n'
    '        plot_top = margin\n'
    '        plot_right = width - margin\n'
    '        plot_bottom = height - margin\n'
    '        view_state["last_plot_left"] = float(plot_left)\n'
    '        view_state["last_plot_top"] = float(plot_top)\n'
    '        view_state["last_plot_right"] = float(plot_right)\n'
    '        view_state["last_plot_bottom"] = float(plot_bottom)\n'
    '        frame_color = "#4b5563" if chart_style else "#d7dde4"\n'
    '        grid_color = CHART_GRID_COLOR if chart_style else theme_colors.get("grid", "#24313b")\n'
    '        label_color = CHART_TEXT_COLOR if chart_style else theme_colors.get("text", "#d7dde4")\n'
    '        canvas.create_rectangle(plot_left, plot_top, plot_right, plot_bottom, outline=frame_color, width=2)\n'
    '        tick_count = 8\n'
    '        for tick in range(tick_count + 1):\n'
    '            ratio = tick / tick_count\n'
    '            gx = plot_left + ratio * (plot_right - plot_left)\n'
    '            gy = plot_top + ratio * (plot_bottom - plot_top)\n'
    '            easting = min_x + ratio * span_x\n'
    '            northing = max_y - ratio * span_y\n'
    '            canvas.create_line(gx, plot_top, gx, plot_bottom, fill=grid_color)\n'
    '            canvas.create_line(plot_left, gy, plot_right, gy, fill=grid_color)\n'
    '            canvas.create_line(gx, plot_bottom, gx, plot_bottom + 7, fill=label_color)\n'
    '            canvas.create_line(gx, plot_top - 7, gx, plot_top, fill=label_color)\n'
    '            canvas.create_line(plot_left, gy, plot_left + 7, gy, fill=label_color)\n'
    '            canvas.create_line(plot_right - 7, gy, plot_right, gy, fill=label_color)\n'
    '            canvas.create_text(gx, plot_bottom + 13, text=f"{easting:.0f}", fill=label_color, font=("Segoe UI", 8))\n'
    '            canvas.create_text(plot_left + 10, gy, text=f"{northing:.0f}", fill=label_color, font=("Segoe UI", 8), anchor="w")\n'
    '            try:\n'
    '                lon_at_bottom, _lat_at_bottom = xy_to_kml_lonlat(float(easting), float(min_y))\n'
    '                _lon_at_left, lat_at_left = xy_to_kml_lonlat(float(min_x), float(northing))\n'
    '                canvas.create_text(gx, plot_top - 18, text=f"{lon_at_bottom:.5f}", fill=label_color, font=("Segoe UI", 7))\n'
    '                canvas.create_text(plot_right + 6, gy, text=f"{lat_at_left:.5f}", fill=label_color, font=("Segoe UI", 7), anchor="w")\n'
    '            except Exception:\n'
    '                pass\n'
    '        canvas.create_text((plot_left + plot_right) / 2, height - 11, text="Easting / Longitude", fill=label_color, font=("Segoe UI", 10, "bold"))\n'
    '        canvas.create_text(plot_left + 24, (plot_top + plot_bottom) / 2, text="Northing", fill=label_color, font=("Segoe UI", 10, "bold"), angle=90)\n'
    '        canvas.create_text(width - 12, (plot_top + plot_bottom) / 2, text="Latitude", fill=label_color, font=("Segoe UI", 9, "bold"), angle=90)\n'
    '        canvas.create_text((plot_left + plot_right) / 2, plot_top - 36, text=f"Longitude along top | Latitude along right | Map scale {nav_scale_var.get()}", fill=label_color, font=("Segoe UI", 9, "bold"))\n'
    '\n'
    '        def nice_scale_distance(target_m: float) -> float:\n'
    '            if target_m <= 0:\n'
    '                return 1.0\n'
    '            exponent = math.floor(math.log10(target_m))\n'
    '            base = 10 ** exponent\n'
    '            fraction = target_m / base\n'
    '            if fraction >= 5:\n'
    '                nice = 5\n'
    '            elif fraction >= 2:\n'
    '                nice = 2\n'
    '            else:\n'
    '                nice = 1\n'
    '            return float(nice * base)\n'
    '\n'
    '        scale_distance = nice_scale_distance(span_x / 5.0)\n'
    '        scale_pixels = min((scale_distance / max(span_x, 1e-9)) * (plot_right - plot_left), (plot_right - plot_left) * 0.32)\n'
    '        scale_x0 = plot_left + 18\n'
    '        scale_y = plot_bottom - 18\n'
    '        canvas.create_line(scale_x0, scale_y, scale_x0 + scale_pixels, scale_y, fill=label_color, width=3)\n'
    '        canvas.create_line(scale_x0, scale_y - 5, scale_x0, scale_y + 5, fill=label_color, width=2)\n'
    '        canvas.create_line(scale_x0 + scale_pixels, scale_y - 5, scale_x0 + scale_pixels, scale_y + 5, fill=label_color, width=2)\n'
    '        scale_label = f"{scale_distance:.0f} m" if scale_distance < 1000 else f"{scale_distance / 1000.0:g} km"\n'
    '        canvas.create_text(scale_x0 + scale_pixels / 2.0, scale_y - 11, text=scale_label, fill=label_color, font=("Segoe UI", 8, "bold"))\n'
    '\n'
    '        visible_bbox = (min_x, min_y, max_x, max_y)\n'
    '        drag_fast = bool(view_state.get("is_panning"))\n'
    '        bbox_pad = max(span_x, span_y) * 0.03\n'
    '        query_bbox = (min_x - bbox_pad, min_y - bbox_pad, max_x + bbox_pad, max_y + bbox_pad)\n'
    '\n'
    '        def draw_background_shapes(\n'
    '            shapes: list[MapShape],\n'
    '            default_color: str,\n'
    '            label_limit: int = 80,\n'
    '            segment_limit: int = 6000,\n'
    '            shape_limit: int = 3500,\n'
    '        ) -> tuple[int, int]:\n'
    '            drawn = 0\n'
    '            labels = 0\n'
    '            visited = 0\n'
    '            if drag_fast:\n'
    '                label_limit = min(label_limit, 8)\n'
    '                segment_limit = max(600, min(segment_limit, 3500))\n'
    '                shape_limit = max(600, min(shape_limit, 2000))\n'
    '            visible_items: list[tuple[float, tuple[float, float, float, float], MapShape]] = []\n'
    '            for shape in shapes:\n'
    '                bbox = cached_shape_bbox(shape)\n'
    '                if bbox is not None and bbox_intersects(bbox, query_bbox):\n'
    '                    area = max((bbox[2] - bbox[0]) * (bbox[3] - bbox[1]), 0.0)\n'
    '                    visible_items.append((area, bbox, shape))\n'
    '            visible_items.sort(key=lambda item: item[0])\n'
    '            if len(visible_items) > shape_limit:\n'
    '                visible_items = visible_items[:shape_limit]\n'
    '            visible_count = len(visible_items)\n'
    '            for _area, _bbox, shape in visible_items:\n'
    '                visited += 1\n'
    '                if drawn >= segment_limit:\n'
    '                    break\n'
    '                pts = [(float(x), float(y)) for x, y in shape.points]\n'
    '                color_shape = shape.color or default_color\n'
    '                if shape.kind == "point" and pts:\n'
    '                    sx, sy = project_xy(pts[0][0], pts[0][1])\n'
    '                    if plot_left - 8 <= sx <= plot_right + 8 and plot_top - 8 <= sy <= plot_bottom + 8:\n'
    '                        symbol_name = enc_symbol_kind(shape)\n'
    '                        sound_text = enc_sound_display(shape.attrs)\n'
    '                        if symbol_name.startswith("SOUNDG") and sound_text:\n'
