    '                                else:\n'
    '                                    canvas.create_line(x1d, y1d, sx, sy, fill=color_shape, width=max(1, int(shape.width)))\n'
    '                                drawn += 1\n'
    '                                if label_xy is None:\n'
    '                                    label_xy = (sx, sy)\n'
    '                                if drawn >= segment_limit:\n'
    '                                    break\n'
    '                        previous = (sx, sy)\n'
    '                    if shape.text and labels < label_limit and label_xy is not None and float(view_state.get("last_span_x", span_x)) < 5000:\n'
