    '\n'
    '        background_drawn = 0\n'
    '        ktd_drawn = 0\n'
    '        ktd_labels = 0\n'
    '        ktd_label_cells: set[tuple[int, int]] = set()\n'
    '        ktd_values = [\n'
    '            float(point.raw_depth)\n'
