    '\n'
    '        def ktd_color(value: float) -> str:\n'
    '            span_value = max(ktd_max - ktd_min, 0.001)\n'
    '            ratio = max(0.0, min(1.0, (float(value) - ktd_min) / span_value))\n'
    '            red = int(36 + 204 * ratio)\n'
    '            green = int(180 - 70 * ratio)\n'
    '            blue = int(235 - 150 * ratio)\n'
    '            return f"#{red:02x}{green:02x}{blue:02x}"\n'
    '\n'
    '        def ktd_display_color(value: float) -> str:\n'
    '            if is_ktd_nodata(float(value)):\n'
