    '            return "#ff00ff"\n'
    '\n'
    '        def draw_ktd_capsule(cx: float, cy: float, value: float) -> None:\n'
    '            label = f"{float(value):.2f}"\n'
    '            fill_color = ktd_display_color(float(value))\n'
    '            radius = 3 if ktd_span < 65000 else 2\n'
