    '\n'
    '        def draw_ktd_matrix_surface() -> int:\n'
    '            nonlocal ktd_labels\n'
    '            drawn_cells = 0\n'
    '            ktd_paths = [Path(str(name)) for name in project_background_files if Path(str(name)).suffix.lower() == ".ktd"]\n'
    '            if not ktd_paths:\n'
    '                path_text = str(getattr(settings.geodetic, "ktd_file_path", "") or "")\n'
    '                if path_text:\n'
    '                    ktd_paths = [Path(path_text)]\n'
    '            for ktd_path in ktd_paths:\n'
    '                matrix = load_ktd_matrix(ktd_path) if ktd_path.exists() else None\n'
    '                if not matrix:\n'
    '                    continue\n'
    '                meta = matrix.get("meta", {})\n'
    '                rows = matrix.get("rows", [])\n'
    '                if not isinstance(meta, dict) or not isinstance(rows, list):\n'
    '                    continue\n'
    '                x_count = int(meta.get("x_count", 0) or 0)\n'
    '                y_count = int(meta.get("y_count", 0) or 0)\n'
    '                min_grid_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '                min_grid_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '                max_grid_x = float(meta.get("max_x", min_grid_x) or min_grid_x)\n'
    '                max_grid_y = float(meta.get("max_y", min_grid_y) or min_grid_y)\n'
    '                if x_count <= 1 or y_count <= 1:\n'
    '                    continue\n'
    '                if max_grid_x < min_x or min_grid_x > max_x or max_grid_y < min_y or min_grid_y > max_y:\n'
    '                    continue\n'
    '                dx_grid = (max_grid_x - min_grid_x) / max(x_count - 1, 1)\n'
    '                dy_grid = (max_grid_y - min_grid_y) / max(y_count - 1, 1)\n'
    '                col_min = max(0, int(math.floor((min_x - min_grid_x) / max(dx_grid, 1e-12))) - 1)\n'
    '                col_max = min(x_count - 1, int(math.ceil((max_x - min_grid_x) / max(dx_grid, 1e-12))) + 1)\n'
    '                row_min = max(0, int(math.floor((min_y - min_grid_y) / max(dy_grid, 1e-12))) - 1)\n'
    '                row_max = min(y_count - 1, int(math.ceil((max_y - min_grid_y) / max(dy_grid, 1e-12))) + 1)\n'
    '                visible_count = max(1, (col_max - col_min + 1) * (row_max - row_min + 1))\n'
    '                step = max(1, int(math.ceil(math.sqrt(visible_count / 45000.0))))\n'
    '                for row in range(row_min, row_max + 1, step):\n'
    '                    if row >= len(rows) or not isinstance(rows[row], list):\n'
    '                        continue\n'
    '                    row_values = rows[row]\n'
    '                    for col in range(col_min, col_max + 1, step):\n'
    '                        if col >= len(row_values):\n'
    '                            continue\n'
    '                        value = row_values[col]\n'
    '                        if value is None:\n'
    '                            continue\n'
    '                        cx, cy = project_xy(min_grid_x + col * dx_grid, min_grid_y + row * dy_grid)\n'
