    '\n'
    '        project_folder = project_root_from_raw_folder(settings.raw_folder or str(default_raw_folder()))\n'
    '        default_path = Path(getattr(settings.geodetic, "ktd_file_path", "") or str(project_folder / "rtk_separation.ktd"))\n'
