    '\n'
    '        def tree_nodes() -> list[tuple[float, float, float]]:\n'
    '            nodes: list[tuple[float, float, float]] = []\n'
    '            for item in tree.get_children():\n'
    '                values = tree.item(item, "values")\n'
    '                if len(values) < 3:\n'
    '                    continue\n'
    '                x = parse_float(values[0])\n'
    '                y = parse_float(values[1])\n'
    '                value = parse_float(values[2])\n'
    '                if x is not None and y is not None and value is not None:\n'
    '                    nodes.append((float(x), float(y), float(value)))\n'
    '            return nodes\n'
    '\n'
    '        def ktd_matrix_summary(file_path: Path, node_count: int) -> str:\n'
    '            meta = load_ktd_grid_meta(file_path)\n'
    '            if not meta:\n'
    '                return f"{node_count} KTD node(s)"\n'
    '            x_count = int(meta.get("x_count", 0) or 0)\n'
    '            y_count = int(meta.get("y_count", 0) or 0)\n'
    '            min_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '            min_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '            max_x = float(meta.get("max_x", min_x) or min_x)\n'
    '            max_y = float(meta.get("max_y", min_y) or min_y)\n'
    '            dx = (max_x - min_x) / max(x_count - 1, 1)\n'
    '            dy = (max_y - min_y) / max(y_count - 1, 1)\n'
    '            total = max(x_count * y_count, 1)\n'
    '            return (\n'
    '                f"{node_count} valid KTD node(s) | matrix {y_count} rows x {x_count} columns | "\n'
    '                f"dx {dx:.3f} dy {dy:.3f} | valid {node_count / total * 100:.1f}%"\n'
    '            )\n'
    '\n'
    '        def refresh_tree(nodes: list[tuple[float, float, float]], source_path: Optional[Path] = None) -> None:\n'
    '            tree.delete(*tree.get_children())\n'
    '            for x, y, value in nodes:\n'
    '                tree.insert("", "end", values=(f"{x:.3f}", f"{y:.3f}", f"{value:.4f}"))\n'
    '            summary = ktd_matrix_summary(source_path, len(nodes)) if source_path else f"{len(nodes)} KTD node(s)"\n'
    '            status.set(f"{summary}; all valid KTD nodes loaded.")\n'
    '\n'
    '        def selected_or_last_world() -> tuple[float, float]:\n'
    '            cursor = view_state.get("last_cursor_world")\n'
    '            if cursor:\n'
    '                return float(cursor[0]), float(cursor[1])\n'
    '            point = latest_position_point()\n'
    '            if point and point.x is not None and point.y is not None:\n'
    '                return float(point.x), float(point.y)\n'
    '            return 0.0, 0.0\n'
    '\n'
    '        def add_node() -> None:\n'
    '            x, y = selected_or_last_world()\n'
    '            value = parse_float(value_var.get()) or 0.0\n'
    '            tree.insert("", "end", values=(f"{x:.3f}", f"{y:.3f}", f"{value:.4f}"))\n'
    '            status.set("Added node. Edit values by selecting a row and pressing Edit Row.")\n'
    '\n'
    '        def edit_row() -> None:\n'
    '            selection = tree.selection()\n'
    '            if not selection:\n'
    '                return\n'
    '            item = selection[0]\n'
    '            values = list(tree.item(item, "values"))\n'
    '            x = simpledialog.askfloat("KTD Editor", "Easting:", initialvalue=parse_float(values[0]) or 0.0, parent=win)\n'
    '            if x is None:\n'
    '                return\n'
    '            y = simpledialog.askfloat("KTD Editor", "Northing:", initialvalue=parse_float(values[1]) or 0.0, parent=win)\n'
    '            if y is None:\n'
    '                return\n'
    '            value = simpledialog.askfloat("KTD Editor", "K or K-N value:", initialvalue=parse_float(values[2]) or 0.0, parent=win)\n'
    '            if value is None:\n'
    '                return\n'
    '            tree.item(item, values=(f"{x:.3f}", f"{y:.3f}", f"{value:.4f}"))\n'
    '\n'
    '        def remove_node() -> None:\n'
    '            for item in tree.selection():\n'
    '                tree.delete(item)\n'
    '            status.set(f"{len(tree.get_children())} KTD node(s)")\n'
    '\n'
    '        def generate_grid() -> None:\n'
    '            x0 = parse_float(x0_var.get())\n'
    '            y0 = parse_float(y0_var.get())\n'
    '            if x0 is None or y0 is None:\n'
    '                x0, y0 = selected_or_last_world()\n'
    '                x0_var.set(f"{x0:.3f}")\n'
    '                y0_var.set(f"{y0:.3f}")\n'
    '            x_count = max(1, int(xdim_var.get()))\n'
    '            y_count = max(1, int(ydim_var.get()))\n'
    '            x_interval = parse_float(xint_var.get()) or 1.0\n'
    '            y_interval = parse_float(yint_var.get()) or 1.0\n'
    '            value = parse_float(value_var.get()) or 0.0\n'
    '            nodes: list[tuple[float, float, float]] = []\n'
    '            for row in range(y_count):\n'
    '                for col in range(x_count):\n'
    '                    nodes.append((float(x0) + col * x_interval, float(y0) + row * y_interval, value))\n'
    '            refresh_tree(nodes)\n'
    '            status.set(f"Generated {len(nodes)} node grid.")\n'
    '\n'
    '        def browse_path() -> None:\n'
    '            name = filedialog.asksaveasfilename(\n'
    '                title="KTD file",\n'
    '                initialdir=str(project_folder),\n'
    '                initialfile=Path(path_var.get()).name or "rtk_separation.ktd",\n'
