    '                filetypes=[("KTD files", "*.ktd *.KTD"), ("XYZ/text", "*.xyz *.txt *.csv"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if name:\n'
    '                path_var.set(name)\n'
    '\n'
    '        def load_file() -> None:\n'
    '            name = filedialog.askopenfilename(\n'
    '                title="Load KTD / XYZ separation file",\n'
    '                initialdir=str(Path(path_var.get()).parent if path_var.get() else project_folder),\n'
    '                filetypes=[("KTD / XYZ files", "*.ktd *.KTD *.xyz *.txt *.csv"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not name:\n'
    '                return\n'
    '            path_var.set(name)\n'
    '            file_path = Path(name)\n'
    '            nodes = load_ktd_nodes(file_path)\n'
    '            meta = load_ktd_grid_meta(file_path)\n'
    '            if meta:\n'
    '                xdim_var.set(int(meta.get("x_count", xdim_var.get()) or xdim_var.get()))\n'
    '                ydim_var.set(int(meta.get("y_count", ydim_var.get()) or ydim_var.get()))\n'
    '                x0_var.set(f"{float(meta.get(\'min_x\', 0.0) or 0.0):.3f}")\n'
    '                y0_var.set(f"{float(meta.get(\'min_y\', 0.0) or 0.0):.3f}")\n'
    '                x_count = max(int(meta.get("x_count", 1) or 1), 1)\n'
    '                y_count = max(int(meta.get("y_count", 1) or 1), 1)\n'
    '                min_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '                min_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '                max_x = float(meta.get("max_x", min_x) or min_x)\n'
    '                max_y = float(meta.get("max_y", min_y) or min_y)\n'
    '                xint_var.set(f"{(max_x - min_x) / max(x_count - 1, 1):.3f}")\n'
    '                yint_var.set(f"{(max_y - min_y) / max(y_count - 1, 1):.3f}")\n'
    '            refresh_tree(nodes, file_path)\n'
    '            load_ktd_background_path(file_path, replace_existing=True)\n'
    '            status.set(f"Loaded {Path(name).name}: {ktd_matrix_summary(file_path, len(nodes))}; displayed as KTD background.")\n'
    '\n'
    '        def save_file(apply_settings: bool = True) -> None:\n'
    '            nodes = tree_nodes()\n'
    '            if not nodes:\n'
    '                messagebox.showwarning("KTD Editor", "No KTD nodes to save.", parent=win)\n'
