    '                save_default_settings()\n'
    '            status.set(f"Saved {len(nodes)} node(s) to {target.name} and displayed as KTD background.")\n'
    '\n'
    '        def clip_ktd_by_border() -> None:\n'
    '            polygon = list(border_points)\n'
    '            if len(polygon) < 3:\n'
    '                name = filedialog.askopenfilename(\n'
    '                    title="Load border file for KTD clipping",\n'
    '                    initialdir=str(project_folder),\n'
    '                    filetypes=[("HYPACK border", "*.brd *.BRD"), ("All files", "*.*")],\n'
    '                    parent=win,\n'
    '                )\n'
    '                if name:\n'
    '                    polygon = load_hypack_brd_points(Path(name))\n'
    '            if len(polygon) < 3:\n'
    '                messagebox.showwarning("KTD Editor", "Load or create a border with at least 3 points before clipping KTD.", parent=win)\n'
    '                return\n'
    '            source = Path(path_var.get() or str(default_path))\n'
    '            if not source.exists():\n'
    '                messagebox.showwarning("KTD Editor", "Load or save a source KTD file before clipping by border.", parent=win)\n'
    '                return\n'
    '            nodes = load_ktd_nodes(source)\n'
    '            meta = load_ktd_grid_meta(source)\n'
    '            if not nodes:\n'
    '                messagebox.showwarning("KTD Editor", "No valid K values found in the KTD file.", parent=win)\n'
    '                return\n'
    '            inside_nodes = [(x, y, value) for x, y, value in nodes if point_in_polygon(float(x), float(y), polygon)]\n'
    '            total_cells = None\n'
    '            if meta:\n'
    '                try:\n'
    '                    total_cells = int(meta.get("x_count", 0) or 0) * int(meta.get("y_count", 0) or 0)\n'
    '                except Exception:\n'
    '                    total_cells = None\n'
    '            target_name = filedialog.asksaveasfilename(\n'
    '                title="Save clipped KTD file",\n'
    '                initialdir=str(source.parent),\n'
    '                initialfile=f"{source.stem}_border_clipped.ktd",\n'
    '                defaultextension=".ktd",\n'
    '                filetypes=[("KTD files", "*.ktd *.KTD"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not target_name:\n'
    '                return\n'
    '            target = Path(target_name)\n'
    '            try:\n'
    '                save_ktd_nodes(target, inside_nodes, mode_var.get(), grid_meta=meta)\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror("KTD Editor", f"Could not save clipped KTD file:\\\\n{exc}", parent=win)\n'
    '                return\n'
    '            path_var.set(str(target))\n'
    '            refresh_tree(inside_nodes, target)\n'
    '            settings.geodetic.ktd_file_path = str(target)\n'
    '            if inside_nodes:\n'
    '                settings.geodetic.ktd_k_value = sum(value for _x, _y, value in inside_nodes) / len(inside_nodes)\n'
    '            load_ktd_background_path(target, replace_existing=True)\n'
    '            save_default_settings()\n'
    '            outside_note = ""\n'
    '            if total_cells is not None:\n'
    '                outside_note = f" Outside/no-data grid cells: {max(total_cells - len(inside_nodes), 0)}."\n'
    '            status.set(\n'
    '                f"Saved clipped KTD: kept {len(inside_nodes)} ORIGINAL inside-border K value(s). "\n'
    '                f"All outside-border cells are grey 999.99 no-data cells and are ignored for realtime K correction.{outside_note}"\n'
    '            )\n'
    '\n'
    '        def create_ktd_from_boundary() -> None:\n'
    '            polygon = list(border_points)\n'
    '            if len(polygon) < 3:\n'
    '                name = filedialog.askopenfilename(\n'
    '                    title="Load boundary for new KTD",\n'
    '                    initialdir=str(project_folder),\n'
    '                    filetypes=[("HYPACK border", "*.brd *.BRD"), ("All files", "*.*")],\n'
    '                    parent=win,\n'
    '                )\n'
    '                if name:\n'
    '                    polygon = load_hypack_brd_points(Path(name))\n'
    '            if len(polygon) < 3:\n'
    '                messagebox.showwarning("KTD Editor", "Load or select a boundary with at least 3 points before creating a boundary KTD.", parent=win)\n'
    '                return\n'
    '            k_value = parse_float(value_var.get())\n'
    '            if k_value is None:\n'
    '                messagebox.showwarning("KTD Editor", "Enter the required K value in Default Value before creating the KTD.", parent=win)\n'
    '                return\n'
    '            x_interval = parse_float(xint_var.get())\n'
    '            y_interval = parse_float(yint_var.get())\n'
    '            if x_interval is None or y_interval is None or x_interval <= 0 or y_interval <= 0:\n'
    '                messagebox.showwarning("KTD Editor", "Enter positive X Interval and Y Interval values.", parent=win)\n'
    '                return\n'
    '            xs = [float(x) for x, _y in polygon]\n'
    '            ys = [float(y) for _x, y in polygon]\n'
    '            min_poly_x, max_poly_x = min(xs), max(xs)\n'
    '            min_poly_y, max_poly_y = min(ys), max(ys)\n'
    '            x_count = max(2, int(math.ceil((max_poly_x - min_poly_x) / float(x_interval))) + 1)\n'
    '            y_count = max(2, int(math.ceil((max_poly_y - min_poly_y) / float(y_interval))) + 1)\n'
    '            total_cells = x_count * y_count\n'
    '            if total_cells > 1000000 and not messagebox.askyesno(\n'
    '                "KTD Editor",\n'
    '                f"This will create a {y_count} x {x_count} KTD grid ({total_cells:,} cells). Continue?",\n'
    '                parent=win,\n'
    '            ):\n'
    '                return\n'
    '            max_grid_x = min_poly_x + (x_count - 1) * float(x_interval)\n'
    '            max_grid_y = min_poly_y + (y_count - 1) * float(y_interval)\n'
    '            nodes: list[tuple[float, float, float]] = []\n'
    '            for row in range(y_count):\n'
    '                y = min_poly_y + row * float(y_interval)\n'
    '                for col in range(x_count):\n'
    '                    x = min_poly_x + col * float(x_interval)\n'
    '                    if point_in_polygon(float(x), float(y), polygon):\n'
    '                        nodes.append((float(x), float(y), float(k_value)))\n'
    '            if not nodes:\n'
    '                messagebox.showwarning("KTD Editor", "No grid cells fell inside the selected boundary. Reduce the interval or check the boundary file.", parent=win)\n'
    '                return\n'
    '            target_name = filedialog.asksaveasfilename(\n'
    '                title="Save boundary KTD file",\n'
    '                initialdir=str(Path(path_var.get()).parent if path_var.get() else project_folder),\n'
    '                initialfile="boundary_constant_k.ktd",\n'
    '                defaultextension=".ktd",\n'
    '                filetypes=[("KTD files", "*.ktd *.KTD"), ("All files", "*.*")],\n'
    '                parent=win,\n'
    '            )\n'
    '            if not target_name:\n'
    '                return\n'
    '            target = Path(target_name)\n'
    '            grid_meta = {\n'
    '                "x_count": x_count,\n'
    '                "y_count": y_count,\n'
    '                "min_x": min_poly_x,\n'
    '                "min_y": min_poly_y,\n'
    '                "max_x": max_grid_x,\n'
    '                "max_y": max_grid_y,\n'
    '                "header_order": "rows_cols",\n'
    '            }\n'
    '            try:\n'
    '                save_ktd_nodes(target, nodes, mode_var.get(), grid_meta=grid_meta)\n'
    '            except Exception as exc:\n'
    '                messagebox.showerror("KTD Editor", f"Could not save boundary KTD file:\\\\n{exc}", parent=win)\n'
    '                return\n'
    '            path_var.set(str(target))\n'
    '            x0_var.set(f"{min_poly_x:.3f}")\n'
    '            y0_var.set(f"{min_poly_y:.3f}")\n'
    '            xdim_var.set(x_count)\n'
    '            ydim_var.set(y_count)\n'
    '            refresh_tree(nodes, target)\n'
    '            settings.geodetic.ktd_file_path = str(target)\n'
    '            settings.geodetic.ktd_k_value = float(k_value)\n'
    '            load_ktd_background_path(target, replace_existing=True)\n'
    '            save_default_settings()\n'
    '            status.set(\n'
    '                f"Created {target.name}: {len(nodes)} inside-boundary K cell(s), "\n'
    '                f"{max(total_cells - len(nodes), 0)} grey 999.99 outside/no-data cell(s)."\n'
    '            )\n'
    '\n'
    '        def apply_to_settings() -> None:\n'
    '            nodes = tree_nodes()\n'
    '            if nodes:\n'
    '                settings.geodetic.ktd_k_value = sum(value for _x, _y, value in nodes) / len(nodes)\n'
    '            settings.geodetic.ktd_file_path = path_var.get().strip()\n'
    '            ktd_path = Path(settings.geodetic.ktd_file_path)\n'
    '            if ktd_path.exists():\n'
    '                load_ktd_background_path(ktd_path, replace_existing=True)\n'
    '            save_default_settings()\n'
    '            status.set("KTD file applied to Geodetic Settings and displayed as background.")\n'
    '\n'
    '        ttk.Button(top, text="Browse", command=browse_path).grid(row=0, column=6, sticky="ew", padx=4)\n'
    '        ttk.Button(buttons, text="Load KTD/XYZ", command=load_file).pack(side="left", padx=3)\n'
