    '        ttk.Button(buttons, text="Remove Node", command=remove_node).pack(side="left", padx=3)\n'
    '        ttk.Button(buttons, text="Save KTD", command=save_file).pack(side="left", padx=3)\n'
    '        ttk.Button(buttons, text="Clip by Border", command=clip_ktd_by_border).pack(side="left", padx=3)\n'
    '        ttk.Button(buttons, text="Create KTD in Border", command=create_ktd_from_boundary).pack(side="left", padx=3)\n'
    '        ttk.Button(buttons, text="Apply to Settings", command=apply_to_settings).pack(side="left", padx=3)\n'
    '        ttk.Button(buttons, text="Close", command=win.destroy).pack(side="left", padx=3)\n'
    '\n'
    '        existing = Path(path_var.get())\n'
    '        if existing.exists():\n'
    '            refresh_tree(load_ktd_nodes(existing))\n'
    '        else:\n'
    '            x, y = selected_or_last_world()\n'
    '            x0_var.set(f"{x:.3f}")\n'
    '            y0_var.set(f"{y:.3f}")\n'
    '\n'
    '    def show_sbes_workflow():\n'
