    '\n'
    '        def show(self, _event: Any = None) -> None:\n'
    '            if self.tip is not None or not self.text:\n'
    '                return\n'
    '            try:\n'
    '                x = self.widget.winfo_rootx() + 18\n'
    '                y = self.widget.winfo_rooty() + self.widget.winfo_height() + 8\n'
    '                self.tip = tk.Toplevel(self.widget)\n'
    '                self.tip.wm_overrideredirect(True)\n'
    '                self.tip.wm_geometry(f"+{x}+{y}")\n'
    '                label = ttk.Label(self.tip, text=self.text, wraplength=360, justify="left", padding=(8, 5), relief="solid", borderwidth=1)\n'
    '                label.pack()\n'
    '            except Exception:\n'
    '                self.tip = None\n'
    '\n'
    '        def hide(self, _event: Any = None) -> None:\n'
    '            if self.tip is not None:\n'
    '                try:\n'
    '                    self.tip.destroy()\n'
    '                except Exception:\n'
    '                    pass\n'
    '                self.tip = None\n'
