    '                    text.see("end")\n'
    '                except Exception:\n'
    '                    pass\n'
    '            def worker() -> None:\n'
    '                sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n'
    '                sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\n'
    '                sock.settimeout(0.35)\n'
    '                try:\n'
    '                    sock.bind(("0.0.0.0", int(port_number)))\n'
    '                    root.after(0, write_line, f"Listening to {title} UDP {port_number}")\n'
    '                    while not popup_stop.is_set():\n'
    '                        try:\n'
    '                            payload, addr = sock.recvfrom(65535)\n'
    '                        except socket.timeout:\n'
    '                            continue\n'
    '                        preview = payload.decode("ascii", errors="replace").strip()\n'
    '                        if not preview:\n'
    '                            preview = payload[:48].hex(" ")\n'
    '                        root.after(0, write_line, f"{addr[0]}:{addr[1]} | {len(payload)} bytes | {preview[:220]}")\n'
    '                except Exception as exc:\n'
    '                    root.after(0, write_line, f"Stopped: {exc}")\n'
    '                finally:\n'
    '                    sock.close()\n'
    '            def on_close() -> None:\n'
    '                popup_stop.set()\n'
    '                popup.destroy()\n'
    '            popup.protocol("WM_DELETE_WINDOW", on_close)\n'
    '            threading.Thread(target=worker, daemon=True).start()\n'
    '\n'
    '        def open_tcp_server_popup(title: str, port_number: int) -> None:\n'
    '            popup = tk.Toplevel(win)\n'
    '            popup.title(f"MBES Realtime - {title}")\n'
    '            popup.geometry("760x420")\n'
    '            popup_stop = threading.Event()\n'
    '            text = tk.Text(popup, wrap="none", bg="#0b1220", fg="#d8f3ff", insertbackground="#d8f3ff")\n'
    '            text.pack(fill="both", expand=True)\n'
    '            def write_line(line: str) -> None:\n'
    '                try:\n'
    '                    text.insert("end", line + "\\n")\n'
    '                    text.see("end")\n'
    '                except Exception:\n'
    '                    pass\n'
    '            def worker() -> None:\n'
    '                server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n'
    '                server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\n'
    '                server.settimeout(0.35)\n'
    '                try:\n'
    '                    server.bind(("0.0.0.0", int(port_number)))\n'
    '                    server.listen(5)\n'
    '                    root.after(0, write_line, f"Listening to {title} TCP {port_number}")\n'
    '                    clients: list[socket.socket] = []\n'
    '                    while not popup_stop.is_set():\n'
    '                        try:\n'
    '                            client, addr = server.accept()\n'
    '                            client.settimeout(0.05)\n'
    '                            clients.append(client)\n'
    '                            root.after(0, write_line, f"TCP client connected: {addr[0]}:{addr[1]}")\n'
    '                        except socket.timeout:\n'
    '                            pass\n'
    '                        for client in list(clients):\n'
    '                            try:\n'
    '                                payload = client.recv(4096)\n'
    '                                if not payload:\n'
    '                                    clients.remove(client)\n'
    '                                    client.close()\n'
    '                                    continue\n'
    '                                preview = payload.decode("ascii", errors="replace").strip()\n'
    '                                root.after(0, write_line, f"{len(payload)} bytes | {preview[:220]}")\n'
    '                            except socket.timeout:\n'
    '                                continue\n'
    '                            except Exception:\n'
    '                                try:\n'
    '                                    clients.remove(client)\n'
    '                                    client.close()\n'
    '                                except Exception:\n'
    '                                    pass\n'
    '                    for client in clients:\n'
    '                        try:\n'
    '                            client.close()\n'
    '                        except Exception:\n'
    '                            pass\n'
    '                except Exception as exc:\n'
    '                    root.after(0, write_line, f"Stopped: {exc}")\n'
    '                finally:\n'
    '                    server.close()\n'
    '            def on_close() -> None:\n'
    '                popup_stop.set()\n'
    '                popup.destroy()\n'
    '            popup.protocol("WM_DELETE_WINDOW", on_close)\n'
    '            threading.Thread(target=worker, daemon=True).start()\n'
