    '\n'
    '        def visual_float(row: dict[str, str], names: list[str]) -> Optional[float]:\n'
    '            lowered = {str(key).strip().lower(): value for key, value in row.items()}\n'
    '            for name in names:\n'
    '                value = lowered.get(name.lower())\n'
    '                if value in (None, ""):\n'
    '                    continue\n'
    '                try:\n'
    '                    return float(str(value).strip())\n'
    '                except Exception:\n'
    '                    continue\n'
    '            return None\n'
    '\n'
    '        def read_visual_points(path: str) -> list[tuple[float, float, float]]:\n'
    '            source = Path(path)\n'
    '            points: list[tuple[float, float, float]] = []\n'
    '            if not source.exists():\n'
    '                raise FileNotFoundError(source)\n'
    '            with source.open("r", encoding="utf-8-sig", newline="") as handle:\n'
    '                sample = handle.read(4096)\n'
    '                handle.seek(0)\n'
    '                try:\n'
    '                    dialect = csv.Sniffer().sniff(sample, delimiters=",;\\t ")\n'
    '                except Exception:\n'
    '                    dialect = csv.excel\n'
    '                reader = csv.DictReader(handle, dialect=dialect)\n'
    '                for row in reader:\n'
    '                    accepted = str(row.get("accepted", "1")).strip().lower()\n'
    '                    if accepted in {"0", "false", "no", "rejected"}:\n'
    '                        continue\n'
    '                    x = visual_float(row, ["x", "easting", "east", "lon", "longitude"])\n'
    '                    y = visual_float(row, ["y", "northing", "north", "lat", "latitude"])\n'
    '                    z = visual_float(row, ["corrected_depth_m", "mean_depth_m", "depth_m", "raw_depth_m", "depth", "z", "sounding"])\n'
    '                    if x is None or y is None or z is None:\n'
    '                        continue\n'
    '                    points.append((float(x), float(y), float(z)))\n'
    '            return points\n'
    '\n'
    '        def depth_color(depth: float, min_depth: float, max_depth: float) -> str:\n'
    '            span = max(max_depth - min_depth, 0.001)\n'
    '            ratio = max(0.0, min(1.0, (depth - min_depth) / span))\n'
    '            red = int(52 + 190 * ratio)\n'
    '            green = int(190 - 80 * ratio)\n'
    '            blue = int(235 - 170 * ratio)\n'
    '            return f"#{red:02x}{green:02x}{blue:02x}"\n'
    '\n'
    '        def draw_visualization() -> None:\n'
    '            visual_canvas.delete("all")\n'
    '            points: list[tuple[float, float, float]] = list(visual_state.get("points", []))\n'
    '            width = max(visual_canvas.winfo_width(), 300)\n'
    '            height = max(visual_canvas.winfo_height(), 260)\n'
    '            visual_canvas.create_rectangle(0, 0, width, height, fill="#101418", outline="")\n'
    '            if not points:\n'
    '                visual_canvas.create_text(width / 2, height / 2, text="No MBES points loaded", fill="#d8dee9", font=("Segoe UI", 14, "bold"))\n'
    '                return\n'
    '            xs = [point[0] for point in points]\n'
    '            ys = [point[1] for point in points]\n'
    '            ds = [point[2] for point in points]\n'
    '            min_x, max_x = min(xs), max(xs)\n'
    '            min_y, max_y = min(ys), max(ys)\n'
    '            min_d, max_d = min(ds), max(ds)\n'
    '            span_x = max(max_x - min_x, 1.0)\n'
    '            span_y = max(max_y - min_y, 1.0)\n'
    '            margin = 44\n'
    '            scale = min((width - margin * 2) / span_x, (height - margin * 2) / span_y) * float(visual_state.get("zoom", 1.0))\n'
    '            center_x = (min_x + max_x) / 2.0 + float(visual_state.get("pan_x", 0.0))\n'
    '            center_y = (min_y + max_y) / 2.0 + float(visual_state.get("pan_y", 0.0))\n'
    '\n'
    '            def project_xy(x: float, y: float) -> tuple[float, float]:\n'
    '                sx = width / 2.0 + (x - center_x) * scale\n'
    '                sy = height / 2.0 - (y - center_y) * scale\n'
    '                return sx, sy\n'
    '\n'
    '            for gx in range(0, width, 80):\n'
    '                visual_canvas.create_line(gx, 0, gx, height, fill="#1f2937")\n'
    '            for gy in range(0, height, 80):\n'
    '                visual_canvas.create_line(0, gy, width, gy, fill="#1f2937")\n'
    '            max_draw = 50000\n'
    '            step = max(1, len(points) // max_draw)\n'
    '            for x, y, depth in points[::step]:\n'
    '                sx, sy = project_xy(x, y)\n'
    '                if sx < -4 or sx > width + 4 or sy < -4 or sy > height + 4:\n'
    '                    continue\n'
    '                color = depth_color(depth, min_d, max_d)\n'
    '                visual_canvas.create_oval(sx - 2, sy - 2, sx + 2, sy + 2, fill=color, outline="")\n'
    '            legend_x = width - 170\n'
    '            legend_y = 32\n'
    '            visual_canvas.create_text(12, 12, anchor="nw", text=f"{len(points)} MBES points | depth {min_d:.3f} to {max_d:.3f} m | zoom {float(visual_state.get(\'zoom\', 1.0)):.2f}x", fill="#e5eef7", font=("Segoe UI", 10, "bold"))\n'
    '            for index in range(80):\n'
    '                ratio = index / 79.0\n'
    '                d = min_d + (max_d - min_d) * ratio\n'
    '                visual_canvas.create_rectangle(legend_x, legend_y + index * 2, legend_x + 18, legend_y + index * 2 + 2, fill=depth_color(d, min_d, max_d), outline="")\n'
    '            visual_canvas.create_text(legend_x + 26, legend_y, anchor="w", text=f"{min_d:.2f} m", fill="#e5eef7", font=("Segoe UI", 9))\n'
    '            visual_canvas.create_text(legend_x + 26, legend_y + 158, anchor="w", text=f"{max_d:.2f} m", fill="#e5eef7", font=("Segoe UI", 9))\n'
    '\n'
    '        def load_visual_source() -> None:\n'
    '            try:\n'
    '                points = read_visual_points(visual_source_var.get())\n'
    '            except Exception as exc:\n'
