    '    line_selector_widgets["combo"] = line_selector_combo\n'
    '    line_selector_combo.grid(row=0, column=9, sticky="ew")\n'
    '    line_selector_combo.bind("<<ComboboxSelected>>", select_line_by_name)\n'
