    '    ttk.Checkbutton(correction_bar, text="Selected", variable=use_selected_line, command=draw_view).grid(row=0, column=11, sticky="w", padx=(6, 0))\n'
    '    ttk.Checkbutton(correction_bar, text="Auto nearest", variable=auto_select_nearest_line, command=lambda: (use_selected_line.set(True), draw_view())).grid(row=0, column=12, sticky="w", padx=(6, 0))\n'
