    '\n'
    '    def ktd_paths_for_screen_edit() -> list[Path]:\n'
    '        paths = [Path(str(name)) for name in project_background_files if Path(str(name)).suffix.lower() == ".ktd"]\n'
    '        path_text = str(getattr(settings.geodetic, "ktd_file_path", "") or "").strip()\n'
    '        if path_text:\n'
    '            ktd_path = Path(path_text)\n'
    '            if ktd_path not in paths:\n'
    '                paths.append(ktd_path)\n'
    '        return paths\n'
    '\n'
    '    def ktd_cell_under_world(easting: float, northing: float) -> Optional[dict[str, object]]:\n'
    '        for ktd_path in ktd_paths_for_screen_edit():\n'
    '            if not ktd_path.exists():\n'
    '                continue\n'
    '            matrix = load_ktd_matrix(ktd_path)\n'
    '            if not matrix:\n'
    '                continue\n'
    '            meta = matrix.get("meta", {})\n'
    '            rows = matrix.get("rows", [])\n'
    '            if not isinstance(meta, dict) or not isinstance(rows, list):\n'
    '                continue\n'
    '            x_count = int(meta.get("x_count", 0) or 0)\n'
    '            y_count = int(meta.get("y_count", 0) or 0)\n'
    '            min_grid_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '            min_grid_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '            max_grid_x = float(meta.get("max_x", min_grid_x) or min_grid_x)\n'
    '            max_grid_y = float(meta.get("max_y", min_grid_y) or min_grid_y)\n'
    '            if x_count <= 1 or y_count <= 1:\n'
    '                continue\n'
    '            dx_grid = (max_grid_x - min_grid_x) / max(x_count - 1, 1)\n'
    '            dy_grid = (max_grid_y - min_grid_y) / max(y_count - 1, 1)\n'
    '            col = int(round((float(easting) - min_grid_x) / max(dx_grid, 1e-12)))\n'
    '            row = int(round((float(northing) - min_grid_y) / max(dy_grid, 1e-12)))\n'
    '            if col < 0 or col >= x_count or row < 0 or row >= y_count:\n'
    '                continue\n'
    '            center_x = min_grid_x + col * dx_grid\n'
    '            center_y = min_grid_y + row * dy_grid\n'
    '            if abs(float(easting) - center_x) > abs(dx_grid) * 0.55 or abs(float(northing) - center_y) > abs(dy_grid) * 0.55:\n'
    '                continue\n'
    '            value = None\n'
    '            try:\n'
    '                value = rows[row][col]\n'
    '            except Exception:\n'
    '                value = KTD_NODATA_VALUE\n'
    '            return {\n'
    '                "path": ktd_path,\n'
    '                "meta": meta,\n'
    '                "rows": rows,\n'
    '                "row": row,\n'
    '                "col": col,\n'
    '                "x": center_x,\n'
    '                "y": center_y,\n'
    '                "value": KTD_NODATA_VALUE if value is None else float(value),\n'
    '            }\n'
    '        return None\n'
    '\n'
    '    def edit_ktd_cell_at_cursor() -> None:\n'
    '        cursor = view_state.get("last_cursor_world")\n'
    '        if not cursor:\n'
    '            messagebox.showinfo("KTD Screen Edit", "Right-click on a visible KTD grid cell first.", parent=root)\n'
    '            return\n'
    '        cell = ktd_cell_under_world(float(cursor[0]), float(cursor[1]))\n'
    '        if not cell:\n'
    '            messagebox.showinfo("KTD Screen Edit", "No loaded KTD cell was found at the selected map position.", parent=root)\n'
    '            return\n'
    '        ktd_path = cell["path"]\n'
    '        old_value = float(cell.get("value", KTD_NODATA_VALUE) or KTD_NODATA_VALUE)\n'
    '        row = int(cell.get("row", 0) or 0)\n'
    '        col = int(cell.get("col", 0) or 0)\n'
    '        x = float(cell.get("x", 0.0) or 0.0)\n'
    '        y = float(cell.get("y", 0.0) or 0.0)\n'
    '        new_value = simpledialog.askfloat(\n'
    '            "Edit KTD Cell",\n'
    '            (\n'
    '                f"File: {Path(str(ktd_path)).name}\\n"\n'
    '                f"Cell row {row + 1}, column {col + 1}\\n"\n'
    '                f"Easting {x:.3f}, Northing {y:.3f}\\n\\n"\n'
    '                "Enter K value. Use 999.99 for no-data:"\n'
    '            ),\n'
    '            initialvalue=old_value,\n'
    '            parent=root,\n'
    '        )\n'
    '        if new_value is None:\n'
    '            return\n'
    '        matrix = load_ktd_matrix(Path(str(ktd_path)))\n'
    '        if not matrix:\n'
    '            messagebox.showerror("KTD Screen Edit", "Could not reload the selected KTD matrix.", parent=root)\n'
    '            return\n'
    '        meta = matrix.get("meta", {})\n'
    '        rows = matrix.get("rows", [])\n'
    '        if not isinstance(meta, dict) or not isinstance(rows, list):\n'
    '            messagebox.showerror("KTD Screen Edit", "The selected KTD matrix is not editable.", parent=root)\n'
    '            return\n'
    '        try:\n'
    '            rows[row][col] = float(new_value)\n'
    '        except Exception as exc:\n'
    '            messagebox.showerror("KTD Screen Edit", f"Could not update the selected KTD cell:\\\\n{exc}", parent=root)\n'
    '            return\n'
    '        x_count = int(meta.get("x_count", 0) or 0)\n'
    '        y_count = int(meta.get("y_count", 0) or 0)\n'
    '        min_grid_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '        min_grid_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '        max_grid_x = float(meta.get("max_x", min_grid_x) or min_grid_x)\n'
    '        max_grid_y = float(meta.get("max_y", min_grid_y) or min_grid_y)\n'
    '        dx_grid = (max_grid_x - min_grid_x) / max(x_count - 1, 1)\n'
    '        dy_grid = (max_grid_y - min_grid_y) / max(y_count - 1, 1)\n'
    '        nodes: list[tuple[float, float, float]] = []\n'
    '        for r_index, row_values in enumerate(rows[:y_count]):\n'
    '            if not isinstance(row_values, list):\n'
    '                continue\n'
    '            node_y = min_grid_y + r_index * dy_grid\n'
    '            for c_index, value in enumerate(row_values[:x_count]):\n'
    '                if value is None or is_ktd_nodata(float(value)):\n'
    '                    continue\n'
    '                node_x = min_grid_x + c_index * dx_grid\n'
    '                nodes.append((float(node_x), float(node_y), float(value)))\n'
    '        try:\n'
    '            save_ktd_nodes(Path(str(ktd_path)), nodes, "K", grid_meta=meta)\n'
    '        except Exception as exc:\n'
    '            messagebox.showerror("KTD Screen Edit", f"Could not save the edited KTD file:\\\\n{exc}", parent=root)\n'
    '            return\n'
    '        try:\n'
    '            load_ktd_background_path(Path(str(ktd_path)), replace_existing=True)\n'
    '        except Exception:\n'
    '            pass\n'
    '        status_var.set(f"Edited KTD {Path(str(ktd_path)).name}: row {row + 1}, col {col + 1}, K={float(new_value):.2f}")\n'
    '        draw_view()\n'
    '\n'
