    '    line_cursor_menu.add_command(label="Clip All by Border", command=clip_lines_by_border_dialog)\n'
    '    line_cursor_menu.add_separator()\n'
    '    line_cursor_menu.add_command(label="Line Editor Window", command=show_line_editor)\n'
    '    cursor_menu.add_cascade(label="Line Editor", menu=line_cursor_menu)\n'
    '    cursor_menu.add_command(label="Data Display", command=show_data_display)\n'
    '    cursor_menu.add_command(label="I/O Monitor", command=show_io_monitor)\n'
    '    cursor_menu.add_command(label="SB EDIT", command=show_sb_edit)\n'
    '    cursor_menu.add_command(label="KTD Editor", command=show_ktd_editor)\n'
    '    cursor_menu.add_command(label="Edit KTD Cell Here", command=edit_ktd_cell_at_cursor)\n'
    '    cursor_menu.add_command(label="Border", command=show_border_dialog)\n'
    '    cursor_menu.add_command(label="Explorer Load / Unload", command=show_background_file_explorer)\n'
    '    cursor_menu.add_command(label="Background Upload", command=show_background_upload_dialog)\n'
    '    cursor_menu.add_command(label="Unload Background", command=show_background_unload_dialog)\n'
    '    cursor_menu.add_command(label="ENC Feature Details", command=show_enc_feature_details)\n'
    '    cursor_menu.add_command(label="S57 Display Options", command=show_s57_display_options)\n'
    '    cursor_menu.add_command(label="ENC Feature Summary", command=show_enc_summary)\n'
    '\n'
    '    def show_cursor_controls(event: Any) -> str:\n'
    '        try:\n'
    '            view_state["last_cursor_world"] = screen_to_world(event.x, event.y)\n'
