    'def get_serial_module():\n'
    '    global _SERIAL_MODULE, _SERIAL_IMPORT_DONE\n'
    '    if not _SERIAL_IMPORT_DONE:\n'
    '        try:\n'
    '            import serial as module  # type: ignore\n'
    '\n'
    '            _SERIAL_MODULE = module\n'
    '        except Exception:\n'
    '            _SERIAL_MODULE = None\n'
    '        _SERIAL_IMPORT_DONE = True\n'
    '    return _SERIAL_MODULE\n'
    '\n'
    '\n'
    'def list_serial_ports() -> list[str]:\n'
    '    try:\n'
    '        from serial.tools import list_ports  # type: ignore\n'
    '\n'
    '        return sorted(port.device for port in list_ports.comports())\n'
    '    except Exception:\n'
    '        return []\n'
    '\n'
    '\n'
    'def list_serial_ports_detailed() -> list[tuple[str, str]]:\n'
    '    """Return (device, description) pairs for all available serial ports."""\n'
    '    try:\n'
    '        from serial.tools import list_ports  # type: ignore\n'
    '\n'
    '        return sorted(\n'
    '            (port.device, f"{port.device} — {port.description}" if port.description and port.description != "n/a" else port.device)\n'
    '            for port in list_ports.comports()\n'
    '        )\n'
    '    except Exception:\n'
    '        return []\n'
    '\n'
    '\n'
    'class PortState:\n'
    '    """Connection state constants for serial ports."""\n'
    '    UNAVAILABLE = "unavailable"\n'
    '    AVAILABLE = "available"\n'
    '    CONNECTING = "connecting"\n'
    '    CONNECTED = "connected"\n'
    '    DISCONNECTED = "disconnected"\n'
    '    ERROR = "error"\n'
    '\n'
    '    _LABELS = {\n'
    '        "unavailable": "Unavailable",\n'
    '        "available": "Available",\n'
    '        "connecting": "Connecting…",\n'
    '        "connected": "Connected",\n'
    '        "disconnected": "Disconnected",\n'
    '        "error": "Error",\n'
    '    }\n'
    '    _COLORS = {\n'
    '        "unavailable": "#6b7280",\n'
    '        "available": "#2563eb",\n'
    '        "connecting": "#d97706",\n'
    '        "connected": "#16a34a",\n'
    '        "disconnected": "#dc2626",\n'
    '        "error": "#dc2626",\n'
    '    }\n'
    '\n'
    '    @classmethod\n'
    '    def label(cls, state: str) -> str:\n'
    '        return cls._LABELS.get(state, state.title())\n'
    '\n'
    '    @classmethod\n'
    '    def color(cls, state: str) -> str:\n'
    '        return cls._COLORS.get(state, "#6b7280")\n'
    '\n'
    '\n'
    'class SerialPortMonitor:\n'
    '    """Periodically scans for serial port changes and tracks connection states."""\n'
    '\n'
    '    def __init__(self) -> None:\n'
    '        self._known_ports: set[str] = set()\n'
    '        self._port_states: dict[str, str] = {}  # port_name -> PortState\n'
    '        self._callbacks: list[object] = []\n'
    '\n'
    '    @property\n'
    '    def known_ports(self) -> set[str]:\n'
    '        return set(self._known_ports)\n'
    '\n'
    '    def port_state(self, port: str) -> str:\n'
    '        return self._port_states.get(port, PortState.UNAVAILABLE)\n'
    '\n'
    '    def set_port_state(self, port: str, state: str) -> None:\n'
    '        old = self._port_states.get(port)\n'
    '        self._port_states[port] = state\n'
    '        if old != state:\n'
    '            for callback in self._callbacks:\n'
    '                try:\n'
    '                    callback(port, state, old or PortState.UNAVAILABLE)  # type: ignore[operator]\n'
    '                except Exception:\n'
    '                    pass\n'
    '\n'
    '    def scan(self) -> tuple[list[str], list[str]]:\n'
    '        """Scan ports. Returns (newly_appeared, newly_disappeared) lists."""\n'
    '        current = set(list_serial_ports())\n'
    '        appeared = sorted(current - self._known_ports)\n'
    '        disappeared = sorted(self._known_ports - current)\n'
    '        self._known_ports = current\n'
    '\n'
    '        for port in appeared:\n'
    '            if port not in self._port_states or self._port_states[port] in (PortState.UNAVAILABLE, PortState.DISCONNECTED):\n'
    '                self.set_port_state(port, PortState.AVAILABLE)\n'
    '\n'
    '        for port in disappeared:\n'
    '            if self._port_states.get(port) in (PortState.CONNECTED, PortState.CONNECTING):\n'
    '                self.set_port_state(port, PortState.DISCONNECTED)\n'
    '            else:\n'
    '                self.set_port_state(port, PortState.UNAVAILABLE)\n'
    '\n'
    '        # Clean up stale states for ports that no longer exist\n'
    '        for port in list(self._port_states.keys()):\n'
    '            if port not in current and self._port_states[port] not in (PortState.UNAVAILABLE, PortState.DISCONNECTED, PortState.ERROR):\n'
    '                self.set_port_state(port, PortState.UNAVAILABLE)\n'
    '\n'
    '        return appeared, disappeared\n'
    '\n'
    '    def on_state_change(self, callback: object) -> None:\n'
    '        self._callbacks.append(callback)\n'
    '\n'
    '    def is_port_available(self, port: str) -> bool:\n'
    '        return port in self._known_ports\n'
    '\n'
    '\n'
    'def get_ezdxf():\n'
    '    global _EZDXF_MODULE, _EZDXF_IMPORT_DONE\n'
    '    if not _EZDXF_IMPORT_DONE:\n'
