    '\n'
    'def ll_to_utm42(lat: float, lon: float) -> Optional[tuple[float, float]]:\n'
    '    global _LL_TO_UTM42_TRANSFORMER\n'
    '    transformer_class = get_transformer_class()\n'
    '    if transformer_class is None:\n'
    '        return None\n'
    '    try:\n'
    '        if _LL_TO_UTM42_TRANSFORMER is None:\n'
    '            _LL_TO_UTM42_TRANSFORMER = transformer_class.from_crs("EPSG:4326", "EPSG:32642", always_xy=True)\n'
    '        x, y = _LL_TO_UTM42_TRANSFORMER.transform(float(lon), float(lat))\n'
    '        return float(x), float(y)\n'
    '    except Exception:\n'
    '        return None\n'
    '\n'
