    'def find_oda_file_converter() -> Optional[Path]:\n'
    '    path_hit = shutil.which("ODAFileConverter.exe") or shutil.which("ODAFileConverter")\n'
    '    if path_hit:\n'
    '        return Path(path_hit)\n'
    '    for base in (os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)")):\n'
