    '\n'
    '\n'
    'def convert_dwg_to_dxf_with_oda(dwg_path: Path, output_folder: Optional[Path] = None, version: str = "ACAD2018") -> Path:\n'
    '    converter = find_oda_file_converter()\n'
    '    if converter is None:\n'
    '        raise RuntimeError("ODA File Converter was not found on this computer.")\n'
    '    source = Path(dwg_path)\n'
    '    target_folder = Path(output_folder) if output_folder else source.parent\n'
    '    target_folder.mkdir(parents=True, exist_ok=True)\n'
    '    target_path = target_folder / f"{source.stem}.dxf"\n'
    '    with tempfile.TemporaryDirectory(prefix="HYDROGEOMATICS_pyqt_oda_") as tmp_name:\n'
    '        tmp_root = Path(tmp_name)\n'
    '        tmp_in = tmp_root / "in"\n'
    '        tmp_out = tmp_root / "out"\n'
    '        tmp_in.mkdir()\n'
    '        tmp_out.mkdir()\n'
    '        shutil.copy2(source, tmp_in / "source.dwg")\n'
    '        result = subprocess.run(\n'
    '            [str(converter), str(tmp_in), str(tmp_out), version, "DXF", "0", "1", "*.dwg"],\n'
    '            capture_output=True,\n'
    '            text=True,\n'
    '            timeout=180,\n'
    '        )\n'
    '        converted = tmp_out / "source.dxf"\n'
    '        if result.returncode != 0 or not converted.exists():\n'
    '            detail = "\\n".join(part.strip() for part in (result.stdout, result.stderr) if part and part.strip())\n'
    '            raise RuntimeError(detail or f"ODA conversion failed: {source.name}")\n'
    '        shutil.copy2(converted, target_path)\n'
    '    return target_path\n'
    '\n'
    '\n'
    'def dxf_color(index: int) -> str:\n'
    '    table = {\n'
    '        1: "#ef4444",\n'
    '        2: "#f59e0b",\n'
    '        3: "#22c55e",\n'
    '        4: "#06b6d4",\n'
    '        5: "#3b82f6",\n'
    '        6: "#d946ef",\n'
    '        7: "#111827",\n'
    '        8: "#6b7280",\n'
    '    }\n'
    '    return table.get(int(index or 8), "#6b7280")\n'
    '\n'
    '\n'
    'def is_ktd_nodata(value: float) -> bool:\n'
    '    return abs(float(value) - KTD_NODATA_VALUE) < 0.005\n'
    '\n'
    '\n'
    'PROTECTED_KTD_MAGIC = "HYDROGEOMATICS-KTD-PROTECTED-V1"\n'
    'PROTECTED_DXF_MAGIC = "HYDROGEOMATICS-DXF-PROTECTED-V1"\n'
    'EMBEDDED_PROTECTED_FILES: dict[str, str] = {}\n'
    '\n'
    '\n'
    'def app_resource_path(name: str) -> Path:\n'
    '    base = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent))\n'
    '    return base / name\n'
    '\n'
    '\n'
    'def protected_ktd_key() -> bytes:\n'
    '    seed = f"{APP_TITLE}|hydrographic-rtk-ktd|{KTD_NODATA_VALUE}".encode("utf-8")\n'
    '    return hashlib.sha256(seed).digest()\n'
    '\n'
    '\n'
    'def xor_bytes(data: bytes, key: bytes) -> bytes:\n'
    '    return bytes(byte ^ key[index % len(key)] for index, byte in enumerate(data))\n'
    '\n'
    '\n'
    'def protect_ktd_bytes(raw: bytes) -> bytes:\n'
    '    packed = zlib.compress(raw, level=9)\n'
    '    protected = xor_bytes(packed, protected_ktd_key())\n'
    '    return (PROTECTED_KTD_MAGIC + "\\n").encode("ascii") + base64.b85encode(protected)\n'
    '\n'
    '\n'
    'def unprotect_ktd_bytes(payload: bytes) -> bytes:\n'
    '    header, _, body = payload.partition(b"\\n")\n'
    '    if header.decode("ascii", errors="replace") != PROTECTED_KTD_MAGIC:\n'
    '        raise RuntimeError("Protected KTD header is not valid.")\n'
    '    protected = base64.b85decode(body.strip())\n'
    '    return zlib.decompress(xor_bytes(protected, protected_ktd_key()))\n'
    '\n'
    '\n'
    'def protect_ktd_file(source: Path, target: Path) -> None:\n'
    '    target.parent.mkdir(parents=True, exist_ok=True)\n'
    '    target.write_bytes(protect_ktd_bytes(source.read_bytes()))\n'
    '\n'
    '\n'
    'def protect_dxf_bytes(raw: bytes) -> bytes:\n'
    '    packed = zlib.compress(raw, level=9)\n'
    '    protected = xor_bytes(packed, protected_ktd_key())\n'
    '    return (PROTECTED_DXF_MAGIC + "\\n").encode("ascii") + base64.b85encode(protected)\n'
    '\n'
    '\n'
    'def unprotect_dxf_bytes(payload: bytes) -> bytes:\n'
    '    header, _, body = payload.partition(b"\\n")\n'
    '    if header.decode("ascii", errors="replace") != PROTECTED_DXF_MAGIC:\n'
    '        raise RuntimeError("Protected DXF header is not valid.")\n'
    '    protected = base64.b85decode(body.strip())\n'
    '    return zlib.decompress(xor_bytes(protected, protected_ktd_key()))\n'
    '\n'
    '\n'
    'def protect_dxf_file(source: Path, target: Path) -> None:\n'
    '    target.parent.mkdir(parents=True, exist_ok=True)\n'
    '    target.write_bytes(protect_dxf_bytes(source.read_bytes()))\n'
    '\n'
    '\n'
    'def embedded_protected_path(name: str) -> Path:\n'
    '    target = Path(tempfile.gettempdir()) / "HYDROGEOMATICS_embedded_resources" / name\n'
    '    target.parent.mkdir(parents=True, exist_ok=True)\n'
    '    return target\n'
    '\n'
    '\n'
    'def ensure_embedded_protected_file(name: str) -> Optional[Path]:\n'
    '    payload = EMBEDDED_PROTECTED_FILES.get(name)\n'
    '    if not payload:\n'
    '        return None\n'
    '    target = embedded_protected_path(name)\n'
    '    if not target.exists():\n'
    '        target.write_bytes(payload.encode("ascii"))\n'
    '    return target\n'
    '\n'
    '\n'
    'def arc_points(cx: float, cy: float, radius: float, start_deg: float, end_deg: float, steps: int = 48) -> list[tuple[float, float]]:\n'
    '    if end_deg < start_deg:\n'
    '        end_deg += 360.0\n'
    '    points: list[tuple[float, float]] = []\n'
    '    for i in range(max(2, steps) + 1):\n'
    '        angle = math.radians(start_deg + (end_deg - start_deg) * i / max(1, steps))\n'
    '        points.append((cx + radius * math.cos(angle), cy + radius * math.sin(angle)))\n'
    '    return points\n'
    '\n'
    '\n'
    'def load_dxf_shapes(path: Path) -> list[Shape]:\n'
    '    ezdxf = get_ezdxf()\n'
    '    if ezdxf is None:\n'
    '        raise RuntimeError("ezdxf is required to load DXF files in this prototype.")\n'
    '    with path.open("rb") as source:\n'
    '        raw_prefix = source.read(len(PROTECTED_DXF_MAGIC))\n'
    '    if path.suffix.lower() == ".hpdxf" or raw_prefix == PROTECTED_DXF_MAGIC.encode("ascii"):\n'
    '        raw = unprotect_dxf_bytes(path.read_bytes())\n'
    '        stream = io.TextIOWrapper(io.BytesIO(raw), encoding="utf-8", errors="ignore")\n'
    '        doc = ezdxf.read(stream)\n'
    '    else:\n'
    '        doc = ezdxf.readfile(str(path))\n'
    '    shapes: list[Shape] = []\n'
    '    from ezdxf.colors import aci2rgb\n'
    '    from ezdxf.path import from_hatch\n'
    '    for entity in doc.modelspace():\n'
    '        first_shape = len(shapes)\n'
    '        kind = entity.dxftype().upper()\n'
    '        layer = str(getattr(entity.dxf, "layer", path.stem))\n'
    '        layer_record = doc.layers.get(layer)\n'
    "        aci = int(entity.dxf.get('color', 256))\n"
    "        rgb = entity.dxf.get('true_color')\n"
    '        if aci == 256 and rgb is None:\n'
    "            rgb = layer_record.dxf.get('true_color')\n"
    "            aci = abs(layer_record.dxf.get('color', 7))\n"
    '        auto_color = rgb is None and aci == 7\n'
    '        if rgb is not None:\n'
    "            color = f'#{int(rgb):06x}'\n"
    '        else:\n'
    '            rgb = aci2rgb(aci if 1 <= aci <= 255 else 7)\n'
    "            color = '#111827' if auto_color else '#%02x%02x%02x' % tuple(rgb)\n"
    "        if kind == 'HATCH' and entity.dxf.solid_fill:\n"
    '            rings = []\n'
    '            for boundary in from_hatch(entity):\n'
    '                ring = [(float(v.x), float(v.y)) for v in boundary.flattening(0.5)]\n'
    '                if len(ring) >= 3: rings.append(ring)\n'
    '            if rings:\n'
    "                shape = Shape('cad_fill', rings[0], layer, color)\n"
    '                shape.rings = rings\n'
    '                shapes.append(shape)\n'
    '        if kind == "LINE":\n'
    '            s = entity.dxf.start\n'
    '            e = entity.dxf.end\n'
    '            shapes.append(Shape("line", [(float(s.x), float(s.y)), (float(e.x), float(e.y))], layer, color))\n'
    '        elif kind == "LWPOLYLINE":\n'
    '            pts = [(float(p[0]), float(p[1])) for p in entity.get_points()]\n'
    '            if len(pts) >= 2:\n'
    '                if bool(getattr(entity, "closed", False)) and pts[0] != pts[-1]:\n'
    '                    pts.append(pts[0])\n'
    '                shapes.append(Shape("line", pts, layer, color))\n'
    '        elif kind == "POLYLINE":\n'
    '            pts = [(float(v.dxf.location.x), float(v.dxf.location.y)) for v in entity.vertices]\n'
    '            if len(pts) >= 2:\n'
    '                shapes.append(Shape("line", pts, layer, color))\n'
    '        elif kind == "CIRCLE":\n'
    '            c = entity.dxf.center\n'
    '            shapes.append(Shape("line", arc_points(float(c.x), float(c.y), float(entity.dxf.radius), 0, 360, 72), layer, color))\n'
    '        elif kind == "ARC":\n'
    '            c = entity.dxf.center\n'
    '            shapes.append(\n'
    '                Shape(\n'
    '                    "line",\n'
    '                    arc_points(float(c.x), float(c.y), float(entity.dxf.radius), float(entity.dxf.start_angle), float(entity.dxf.end_angle)),\n'
    '                    layer,\n'
    '                    color,\n'
    '                )\n'
    '            )\n'
    '        elif kind == "POINT":\n'
    '            p = entity.dxf.location\n'
    '            shapes.append(Shape("point", [(float(p.x), float(p.y))], layer, color))\n'
    '        elif kind in {"TEXT", "MTEXT"}:\n'
    '            p = entity.dxf.insert\n'
    '            label = str(entity.plain_text() if hasattr(entity, "plain_text") else entity.dxf.text)\n'
    '            shapes.append(Shape("text", [(float(p.x), float(p.y))], label, color))\n'
    '        for shape in shapes[first_shape:]:\n'
    '            shape.cad_layer = layer\n'
    '            shape.cad_auto_color = auto_color\n'
    "            shape.cad_visible = not (layer_record.is_off() or layer_record.is_frozen() or entity.dxf.get('invisible', 0))\n"
    '    return shapes\n'
    '\n'
    '\n'
    'def parse_float(value: object) -> Optional[float]:\n'
    '    try:\n'
    '        return float(str(value).strip())\n'
    '    except Exception:\n'
    '        return None\n'
    '\n'
    '\n'
    'def load_ktd_grid_meta(path: Path) -> Optional[dict[str, float | int | str]]:\n'
    '    if not path.exists():\n'
    '        return None\n'
    '    try:\n'
    '        lines = [line.strip() for line in path.read_text(encoding="utf-8", errors="replace").splitlines() if line.strip()]\n'
    '        if not lines:\n'
    '            return None\n'
    '        first = [part for part in re.split(r"[,\\t ]+", lines[0]) if part]\n'
    '        values = [parse_float(part) for part in first]\n'
    '        if len(values) >= 6 and all(value is not None for value in values[:6]):\n'
    '            y_count = int(values[0] or 0)\n'
    '            x_count = int(values[1] or 0)\n'
    '            if x_count > 1 and y_count > 1:\n'
    '                return {\n'
    '                    "x_count": x_count,\n'
    '                    "y_count": y_count,\n'
    '                    "min_x": float(values[2] or 0.0),\n'
    '                    "min_y": float(values[3] or 0.0),\n'
    '                    "max_x": float(values[4] or 0.0),\n'
    '                    "max_y": float(values[5] or 0.0),\n'
    '                    "row_order": "bottom_up",\n'
    '                }\n'
    '    except Exception:\n'
    '        return None\n'
    '    return None\n'
    '\n'
    '\n'
    'def load_ktd_shapes(path: Path, include_nodata: bool = True) -> list[Shape]:\n'
    '    if path.suffix.lower() in {".ktdp", ".hpktd"} or path.read_bytes()[: len(PROTECTED_KTD_MAGIC)] == PROTECTED_KTD_MAGIC.encode("ascii"):\n'
    '        matrix = read_ktd_matrix(path)\n'
    '        shapes: list[Shape] = []\n'
    '        for index, value in enumerate(matrix.values):\n'
    '            nodata = is_ktd_nodata(value)\n'
    '            if nodata and not include_nodata:\n'
    '                continue\n'
    '            row = index // matrix.x_count\n'
    '            col = index % matrix.x_count\n'
    '            x = matrix.min_x + col * matrix.dx\n'
    '            y = matrix.min_y + row * matrix.dy\n'
    '            shapes.append(Shape("ktd", [(x, y)], "999.99" if nodata else f"{float(value):.2f}", "#9ca3af" if nodata else "#d000ff", float(value)))\n'
    '        return shapes\n'
    '    shapes: list[Shape] = []\n'
    '    raw_text = path.read_text(encoding="utf-8", errors="replace")\n'
    '    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]\n'
    '    meta = load_ktd_grid_meta(path)\n'
    '    if meta:\n'
    '        x_count = int(meta.get("x_count", 0) or 0)\n'
    '        y_count = int(meta.get("y_count", 0) or 0)\n'
    '        min_x = float(meta.get("min_x", 0.0) or 0.0)\n'
    '        min_y = float(meta.get("min_y", 0.0) or 0.0)\n'
    '        max_x = float(meta.get("max_x", min_x) or min_x)\n'
    '        max_y = float(meta.get("max_y", min_y) or min_y)\n'
    '        dx = (max_x - min_x) / max(x_count - 1, 1)\n'
    '        dy = (max_y - min_y) / max(y_count - 1, 1)\n'
    '        tokens = [token for token in re.split(r"[,\\t\\s]+", "\\n".join(lines[1:]).strip()) if token]\n'
    '        limit = min(len(tokens), x_count * y_count)\n'
    '        for index in range(limit):\n'
    '            value = parse_float(tokens[index])\n'
    '            if value is None:\n'
    '                continue\n'
    '            row = index // x_count\n'
    '            col = index % x_count\n'
    '            x = min_x + col * dx\n'
    '            y = min_y + row * dy\n'
    '            nodata = is_ktd_nodata(value)\n'
    '            if nodata and not include_nodata:\n'
    '                continue\n'
    '            label = "999.99" if nodata else f"{float(value):.2f}"\n'
    '            color = "#9ca3af" if nodata else "#d000ff"\n'
    '            shapes.append(Shape("ktd", [(x, y)], label, color, float(value)))\n'
    '        return shapes\n'
    '\n'
    '    for line in lines:\n'
    '        if line.startswith("#") or line.startswith(";"):\n'
    '            continue\n'
    '        parts = [part for part in re.split(r"[,\\t ]+", line) if part]\n'
    '        if parts and parts[0].upper() in {"KTD", "NODE", "XYZ"}:\n'
    '            parts = parts[1:]\n'
    '        if len(parts) < 3:\n'
    '            continue\n'
    '        x = parse_float(parts[0])\n'
    '        y = parse_float(parts[1])\n'
    '        value = parse_float(parts[2])\n'
    '        if x is None or y is None or value is None:\n'
    '            continue\n'
    '        nodata = is_ktd_nodata(value)\n'
    '        if nodata and not include_nodata:\n'
    '            continue\n'
    '        shapes.append(Shape("ktd", [(float(x), float(y))], "999.99" if nodata else f"{float(value):.2f}", "#9ca3af" if nodata else "#d000ff", float(value)))\n'
    '    return shapes\n'
    '\n'
    '\n'
    'def load_xyz_csv_shapes(path: Path) -> list[Shape]:\n'
    '    shapes: list[Shape] = []\n'
    '    with path.open("r", encoding="utf-8", errors="replace", newline="") as handle:\n'
    '        sample = handle.read(4096)\n'
    '        handle.seek(0)\n'
    '        dialect = csv.Sniffer().sniff(sample, delimiters=",\\t ;") if sample.strip() else csv.excel\n'
    '        rows = csv.reader(handle, dialect)\n'
    '        for row in rows:\n'
    '            values = [parse_float(cell) for cell in row]\n'
    '            nums = [value for value in values if value is not None]\n'
    '            if len(nums) >= 2:\n'
    '                label = f"{nums[2]:.2f}" if len(nums) >= 3 else ""\n'
    '                shapes.append(Shape("point", [(float(nums[0]), float(nums[1]))], label, "#2563eb"))\n'
    '    return shapes\n'
    '\n'
    '\n'
    'def load_xy_line_shapes(path: Path, color: str = "#dc2626", label: str = "") -> list[Shape]:\n'
    '    points: list[tuple[float, float]] = []\n'
    '    for raw_line in path.read_text(encoding="utf-8", errors="replace").splitlines():\n'
    '        line = raw_line.strip()\n'
    '        if not line or line.startswith(("#", ";")):\n'
    '            continue\n'
    '        values = [parse_float(part) for part in re.split(r"[,\\t ]+", line) if part]\n'
    '        nums = [value for value in values if value is not None]\n'
    '        if len(nums) >= 2:\n'
    '            points.append((float(nums[0]), float(nums[1])))\n'
    '    if len(points) >= 2:\n'
    '        return [Shape("line", points, label or path.stem, color)]\n'
    '    if len(points) == 1:\n'
    '        return [Shape("point", points, label or path.stem, color)]\n'
    '    return []\n'
    '\n'
    '\n'
    'def load_shapes(path: Path) -> list[Shape]:\n'
    '    suffix = path.suffix.lower()\n'
    '    if suffix in {".dxf", ".hpdxf"}:\n'
    '        return load_dxf_shapes(path)\n'
    '    if suffix == ".dwg":\n'
    '        dxf_path = convert_dwg_to_dxf_with_oda(path)\n'
    '        return load_dxf_shapes(dxf_path)\n'
    '    if suffix in {".ktd", ".ktdp", ".hpktd"}:\n'
    '        return load_ktd_shapes(path, include_nodata=False)\n'
    '    if suffix in {".csv", ".xyz", ".txt"}:\n'
    '        return load_xyz_csv_shapes(path)\n'
    '    raise RuntimeError(f"Unsupported prototype map file: {path.suffix}")\n'
    '\n'
    '\n'
    '@dataclass\n'
    'class KtdMatrix:\n'
    '    path: Path\n'
    '    x_count: int\n'
    '    y_count: int\n'
    '    min_x: float\n'
    '    min_y: float\n'
    '    max_x: float\n'
    '    max_y: float\n'
    '    values: list[float]\n'
    '\n'
    '    @property\n'
    '    def dx(self) -> float:\n'
    '        return (self.max_x - self.min_x) / max(self.x_count - 1, 1)\n'
    '\n'
    '    @property\n'
    '    def dy(self) -> float:\n'
    '        return (self.max_y - self.min_y) / max(self.y_count - 1, 1)\n'
    '\n'
    '\n'
    'def read_ktd_matrix(path: Path) -> KtdMatrix:\n'
    '    raw = path.read_bytes()\n'
    '    if raw.startswith(PROTECTED_KTD_MAGIC.encode("ascii")):\n'
    '        raw = unprotect_ktd_bytes(raw)\n'
    '    lines = [line.strip() for line in raw.decode("utf-8", errors="replace").splitlines() if line.strip()]\n'
    '    if not lines:\n'
    '        raise RuntimeError("KTD file is empty.")\n'
    '    header = [part for part in re.split(r"[,\\t ]+", lines[0]) if part]\n'
    '    nums = [parse_float(part) for part in header]\n'
    '    if len(nums) < 6 or any(value is None for value in nums[:6]):\n'
    '        raise RuntimeError("Only matrix-style KTD files can be clipped while preserving original format.")\n'
    '    y_count = int(nums[0] or 0)\n'
    '    x_count = int(nums[1] or 0)\n'
    '    min_x = float(nums[2] or 0.0)\n'
    '    min_y = float(nums[3] or 0.0)\n'
    '    max_x = float(nums[4] or min_x)\n'
    '    max_y = float(nums[5] or min_y)\n'
    '    tokens = [token for token in re.split(r"[,\\t\\s]+", "\\n".join(lines[1:]).strip()) if token]\n'
    '    expected = x_count * y_count\n'
    '    values = [KTD_NODATA_VALUE] * expected\n'
    '    for index, token in enumerate(tokens[:expected]):\n'
    '        value = parse_float(token)\n'
    '        values[index] = KTD_NODATA_VALUE if value is None else float(value)\n'
    '    return KtdMatrix(path, x_count, y_count, min_x, min_y, max_x, max_y, values)\n'
    '\n'
    '\n'
    'def write_ktd_matrix(path: Path, matrix: KtdMatrix, values: list[float]) -> None:\n'
    '    path.parent.mkdir(parents=True, exist_ok=True)\n'
    '    with path.open("w", encoding="utf-8", newline="\\n") as handle:\n'
    '        handle.write(f"{matrix.y_count} {matrix.x_count} {matrix.min_x:.2f} {matrix.min_y:.2f} {matrix.max_x:.2f} {matrix.max_y:.2f}\\n")\n'
    '        for row in range(matrix.y_count):\n'
    '            start = row * matrix.x_count\n'
    '            row_values = values[start : start + matrix.x_count]\n'
    '            handle.write(" ".join("999.99" if is_ktd_nodata(value) else f"{float(value):.2f}" for value in row_values))\n'
    '            handle.write("\\n")\n'
    '\n'
    '\n'
    'def ktd_value_at_xy(matrix: KtdMatrix, x: float, y: float) -> Optional[float]:\n'
    '    if x < matrix.min_x or x > matrix.max_x or y < matrix.min_y or y > matrix.max_y:\n'
    '        return None\n'
    '    col_f = (float(x) - matrix.min_x) / matrix.dx if abs(matrix.dx) > 1e-12 else 0.0\n'
    '    row_f = (float(y) - matrix.min_y) / matrix.dy if abs(matrix.dy) > 1e-12 else 0.0\n'
    '    col0 = int(math.floor(col_f))\n'
    '    row0 = int(math.floor(row_f))\n'
    '    col1 = min(col0 + 1, matrix.x_count - 1)\n'
    '    row1 = min(row0 + 1, matrix.y_count - 1)\n'
    '    if row0 < 0 or col0 < 0 or row0 >= matrix.y_count or col0 >= matrix.x_count:\n'
    '        return None\n'
    '    tx = max(0.0, min(1.0, col_f - col0))\n'
    '    ty = max(0.0, min(1.0, row_f - row0))\n'
    '    samples: list[tuple[float, float]] = []\n'
    '    for row, wy in ((row0, 1.0 - ty), (row1, ty)):\n'
    '        for col, wx in ((col0, 1.0 - tx), (col1, tx)):\n'
    '            weight = wx * wy\n'
    '            if weight <= 0:\n'
    '                continue\n'
    '            value = matrix.values[row * matrix.x_count + col]\n'
    '            if not is_ktd_nodata(value):\n'
    '                samples.append((float(value), float(weight)))\n'
    '    if samples:\n'
    '        weight_sum = sum(weight for _value, weight in samples)\n'
    '        if weight_sum > 1e-12:\n'
    '            return sum(value * weight for value, weight in samples) / weight_sum\n'
    '    search_radius = 3\n'
    '    nearest: Optional[tuple[float, float]] = None\n'
    '    for rr in range(max(0, row0 - search_radius), min(matrix.y_count, row0 + search_radius + 1)):\n'
    '        for cc in range(max(0, col0 - search_radius), min(matrix.x_count, col0 + search_radius + 1)):\n'
    '            value = matrix.values[rr * matrix.x_count + cc]\n'
    '            if is_ktd_nodata(value):\n'
    '                continue\n'
    '            cx = matrix.min_x + cc * matrix.dx\n'
    '            cy = matrix.min_y + rr * matrix.dy\n'
    '            distance = math.hypot(cx - x, cy - y)\n'
    '            if nearest is None or distance < nearest[0]:\n'
    '                nearest = (distance, float(value))\n'
    '    return nearest[1] if nearest is not None else None\n'
    '\n'
    '\n'
    'def polyline_length(points: list[tuple[float, float]]) -> float:\n'
    '    return sum(math.hypot(points[index][0] - points[index - 1][0], points[index][1] - points[index - 1][1]) for index in range(1, len(points)))\n'
    '\n'
    '\n'
    'def perpendicular_distance(point: tuple[float, float], start: tuple[float, float], end: tuple[float, float]) -> float:\n'
    '    px, py = point\n'
    '    sx, sy = start\n'
    '    ex, ey = end\n'
    '    dx = ex - sx\n'
    '    dy = ey - sy\n'
    '    if abs(dx) < 1e-12 and abs(dy) < 1e-12:\n'
    '        return math.hypot(px - sx, py - sy)\n'
    '    t = max(0.0, min(1.0, ((px - sx) * dx + (py - sy) * dy) / (dx * dx + dy * dy)))\n'
    '    qx = sx + t * dx\n'
    '    qy = sy + t * dy\n'
    '    return math.hypot(px - qx, py - qy)\n'
    '\n'
    '\n'
    'def simplify_polyline(points: list[tuple[float, float]], tolerance: float = 60.0) -> list[tuple[float, float]]:\n'
    '    if len(points) <= 3:\n'
    '        return list(points)\n'
    '    keep = {0, len(points) - 1}\n'
    '    stack = [(0, len(points) - 1)]\n'
    '    while stack:\n'
    '        start, end = stack.pop()\n'
    '        if end <= start + 1:\n'
    '            continue\n'
    '        max_distance = -1.0\n'
    '        split = start\n'
    '        for index in range(start + 1, end):\n'
    '            distance = perpendicular_distance(points[index], points[start], points[end])\n'
    '            if distance > max_distance:\n'
    '                max_distance = distance\n'
    '                split = index\n'
    '        if max_distance > tolerance:\n'
    '            keep.add(split)\n'
    '            stack.append((start, split))\n'
    '            stack.append((split, end))\n'
    '    return [points[index] for index in sorted(keep)]\n'
    '\n'
    '\n'
    'def extract_dxf_polylines(path: Path) -> list[list[tuple[float, float]]]:\n'
    '    ezdxf = get_ezdxf()\n'
    '    if ezdxf is None:\n'
    '        raise RuntimeError("ezdxf is required for DXF bank clipping.")\n'
    '    doc = ezdxf.readfile(str(path))\n'
    '    polylines: list[list[tuple[float, float]]] = []\n'
    '    for entity in doc.modelspace():\n'
    '        kind = entity.dxftype().upper()\n'
    '        points: list[tuple[float, float]] = []\n'
    '        if kind == "LWPOLYLINE":\n'
    '            points = [(float(p[0]), float(p[1])) for p in entity.get_points()]\n'
    '        elif kind == "POLYLINE":\n'
    '            points = [(float(v.dxf.location.x), float(v.dxf.location.y)) for v in entity.vertices]\n'
    '        if len(points) >= 3:\n'
    '            polylines.append(points)\n'
    '    return polylines\n'
    '\n'
    '\n'
    'def nearest_endpoint_chain(start: tuple[float, float], end: tuple[float, float], candidates: list[list[tuple[float, float]]]) -> list[tuple[float, float]]:\n'
    '    unused = [list(points) for points in candidates if len(points) >= 2]\n'
    '    chain: list[tuple[float, float]] = []\n'
    '    current = start\n'
    '    for _ in range(len(unused)):\n'
    '        best_index = -1\n'
    '        best_reverse = False\n'
    '        best_distance = float("inf")\n'
    '        for index, points in enumerate(unused):\n'
    '            d_start = math.hypot(points[0][0] - current[0], points[0][1] - current[1])\n'
    '            d_end = math.hypot(points[-1][0] - current[0], points[-1][1] - current[1])\n'
    '            if d_start < best_distance:\n'
    '                best_index, best_reverse, best_distance = index, False, d_start\n'
    '            if d_end < best_distance:\n'
    '                best_index, best_reverse, best_distance = index, True, d_end\n'
    '        if best_index < 0:\n'
    '            break\n'
    '        points = unused.pop(best_index)\n'
    '        if best_reverse:\n'
    '            points = list(reversed(points))\n'
    '        if chain and points and math.hypot(points[0][0] - chain[-1][0], points[0][1] - chain[-1][1]) < 1e-6:\n'
    '            chain.extend(points[1:])\n'
    '        else:\n'
    '            chain.extend(points)\n'
    '        current = chain[-1]\n'
    '        if math.hypot(current[0] - end[0], current[1] - end[1]) < max(200.0, best_distance * 1.5):\n'
    '            break\n'
    '    return chain\n'
    '\n'
    '\n'
    'def build_river_bank_polygon(path: Path) -> list[tuple[float, float]]:\n'
    '    polylines = extract_dxf_polylines(path)\n'
    '    closed = [points for points in polylines if math.hypot(points[0][0] - points[-1][0], points[0][1] - points[-1][1]) < 1.0]\n'
    '    if closed:\n'
    '        polygon = max(closed, key=polyline_length)\n'
    '        if polygon[0] != polygon[-1]:\n'
    '            polygon = polygon + [polygon[0]]\n'
    '        simplified = simplify_polyline(polygon, 60.0)\n'
    '        if simplified[0] != simplified[-1]:\n'
    '            simplified.append(simplified[0])\n'
    '        return simplified\n'
    '    if len(polylines) < 2:\n'
    '        raise RuntimeError("River bank DXF needs at least two polylines or one closed polygon.")\n'
    '    bank_a = max(polylines, key=lambda points: max(y for _x, y in points) - min(y for _x, y in points))\n'
    '    remaining = [points for points in polylines if points is not bank_a]\n'
    '    bank_b = nearest_endpoint_chain(bank_a[-1], bank_a[0], remaining)\n'
    '    if len(bank_b) < 2:\n'
    '        bank_b = max(remaining, key=polyline_length)\n'
    '    polygon = list(bank_a) + list(bank_b)\n'
    '    if polygon[0] != polygon[-1]:\n'
    '        polygon.append(polygon[0])\n'
    '    simplified = simplify_polyline(polygon, 60.0)\n'
    '    if simplified[0] != simplified[-1]:\n'
    '        simplified.append(simplified[0])\n'
    '    return simplified\n'
    '\n'
    '\n'
    'def point_in_polygon(x: float, y: float, polygon: list[tuple[float, float]]) -> bool:\n'
    '    inside = False\n'
    '    j = len(polygon) - 1\n'
    '    for i in range(len(polygon)):\n'
    '        xi, yi = polygon[i]\n'
    '        xj, yj = polygon[j]\n'
    '        if ((yi > y) != (yj > y)) and (x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-12) + xi):\n'
    '            inside = not inside\n'
    '        j = i\n'
    '    return inside\n'
    '\n'
    '\n'
    'def median_value(values: list[float]) -> Optional[float]:\n'
    '    if not values:\n'
    '        return None\n'
    '    ordered = sorted(values)\n'
    '    mid = len(ordered) // 2\n'
    '    if len(ordered) % 2:\n'
    '        return float(ordered[mid])\n'
    '    return float((ordered[mid - 1] + ordered[mid]) / 2.0)\n'
    '\n'
    '\n'
    'def interpolate_row_values(row_values: list[Optional[float]]) -> list[Optional[float]]:\n'
    '    known = [(index, value) for index, value in enumerate(row_values) if value is not None]\n'
    '    if not known:\n'
    '        return list(row_values)\n'
    '    result = list(row_values)\n'
    '    for row, value in known:\n'
    '        result[row] = value\n'
    '    first_row, first_value = known[0]\n'
    '    for row in range(0, first_row):\n'
    '        result[row] = first_value\n'
    '    last_row, last_value = known[-1]\n'
    '    for row in range(last_row + 1, len(result)):\n'
    '        result[row] = last_value\n'
    '    for (row_a, value_a), (row_b, value_b) in zip(known, known[1:]):\n'
    '        if row_b <= row_a + 1:\n'
    '            continue\n'
    '        for row in range(row_a + 1, row_b):\n'
    '            ratio = (row - row_a) / (row_b - row_a)\n'
    '            result[row] = float(value_a) + (float(value_b) - float(value_a)) * ratio\n'
    '    return result\n'
    '\n'
    '\n'
    'def clip_ktd_matrix_to_polygon(\n'
    '    matrix: KtdMatrix,\n'
    '    polygon: list[tuple[float, float]],\n'
    '    buffer_m: float = 0.0,\n'
    '    interpolate_gaps: bool = False,\n'
    ') -> tuple[list[float], int, int, int, int]:\n'
    '    xs = [p[0] for p in polygon]\n'
    '    ys = [p[1] for p in polygon]\n'
    '    min_px, max_px = min(xs) - buffer_m, max(xs) + buffer_m\n'
    '    min_py, max_py = min(ys) - buffer_m, max(ys) + buffer_m\n'
    '    clipped = [KTD_NODATA_VALUE] * len(matrix.values)\n'
    '    inside_mask = [False] * len(matrix.values)\n'
    '    kept = 0\n'
    '    real_total = 0\n'
    '    land_nodata = 0\n'
    '    row_samples: list[list[float]] = [[] for _ in range(matrix.y_count)]\n'
    '    for index, value in enumerate(matrix.values):\n'
    '        if is_ktd_nodata(value):\n'
    '            pass\n'
    '        else:\n'
    '            real_total += 1\n'
    '        row = index // matrix.x_count\n'
    '        col = index % matrix.x_count\n'
    '        x = matrix.min_x + col * matrix.dx\n'
    '        y = matrix.min_y + row * matrix.dy\n'
    '        if x < min_px or x > max_px or y < min_py or y > max_py:\n'
    '            continue\n'
    '        if point_in_polygon(x, y, polygon):\n'
    '            inside_mask[index] = True\n'
    '            if is_ktd_nodata(value):\n'
    '                land_nodata += 1\n'
    '            else:\n'
    '                clipped[index] = value\n'
    '                row_samples[row].append(float(value))\n'
    '                kept += 1\n'
    '\n'
    '    filled = 0\n'
    '    if interpolate_gaps:\n'
    '        row_medians = [median_value(samples) for samples in row_samples]\n'
    '        row_model = interpolate_row_values(row_medians)\n'
    '        for index, is_inside in enumerate(inside_mask):\n'
    '            if not is_inside or not is_ktd_nodata(clipped[index]):\n'
    '                continue\n'
    '            row = index // matrix.x_count\n'
    '            value = row_model[row]\n'
    '            if value is not None:\n'
    '                clipped[index] = round(float(value), 2)\n'
    '                filled += 1\n'
    '    return clipped, kept, real_total, filled, land_nodata\n'
    '\n'
    '\n'
    'class SurveyMapView(QGraphicsView):\n'
    '    def __init__(self, parent: Optional[QWidget] = None) -> None:\n'
    '        super().__init__(parent)\n'
    '        self.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.TextAntialiasing)\n'
    '        self.setDragMode(QGraphicsView.DragMode.NoDrag)\n'
    '        self.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)\n'
    '        self.setResizeAnchor(QGraphicsView.ViewportAnchor.AnchorViewCenter)\n'
    '        self.setBackgroundBrush(QColor("#f8fafc"))\n'
    '        self.rubber_band = QRubberBand(QRubberBand.Shape.Rectangle, self)\n'
    '        self.origin = QPoint()\n'
    '        self.mode = "Pan"\n'
    '        self._panning = False\n'
    '        self._last_pan = QPoint()\n'
    '\n'
    '    def wheelEvent(self, event) -> None:  # type: ignore[override]\n'
    '        factor = 1.20 if event.angleDelta().y() > 0 else 1 / 1.20\n'
    '        before = self.mapToScene(event.position().toPoint())\n'
    '        self.scale(factor, factor)\n'
    '        after = self.mapToScene(event.position().toPoint())\n'
    '        delta = after - before\n'
    '        self.translate(delta.x(), delta.y())\n'
    '        self.window().update_status_from_view()  # type: ignore[attr-defined]\n'
    '        event.accept()\n'
    '\n'
    '    def mousePressEvent(self, event) -> None:  # type: ignore[override]\n'
    '        if self.mode == "Zoom Window" and event.button() == Qt.MouseButton.LeftButton:\n'
    '            self.origin = event.position().toPoint()\n'
    '            self.rubber_band.setGeometry(self.origin.x(), self.origin.y(), 1, 1)\n'
    '            self.rubber_band.show()\n'
    '            return\n'
    '        if event.button() in {Qt.MouseButton.LeftButton, Qt.MouseButton.MiddleButton}:\n'
    '            self._panning = True\n'
    '            self._last_pan = event.position().toPoint()\n'
    '            self.setCursor(Qt.CursorShape.ClosedHandCursor)\n'
    '            event.accept()\n'
    '            return\n'
    '        super().mousePressEvent(event)\n'
    '\n'
    '    def mouseMoveEvent(self, event) -> None:  # type: ignore[override]\n'
    '        pos = event.position().toPoint()\n'
    '        scene_pos = self.mapToScene(pos)\n'
    '        self.window().set_coordinate_status(scene_pos.x(), -scene_pos.y())  # type: ignore[attr-defined]\n'
    '        if self.rubber_band.isVisible():\n'
    '            rect = QRectF(QPointF(self.origin), QPointF(pos)).normalized().toRect()\n'
    '            self.rubber_band.setGeometry(rect)\n'
    '            return\n'
    '        if self._panning:\n'
    '            before = self.mapToScene(self._last_pan)\n'
    '            after = self.mapToScene(pos)\n'
    '            delta = after - before\n'
    '            self._last_pan = pos\n'
    '            self.translate(delta.x(), delta.y())\n'
    '            event.accept()\n'
    '            return\n'
    '        super().mouseMoveEvent(event)\n'
    '\n'
    '    def mouseReleaseEvent(self, event) -> None:  # type: ignore[override]\n'
    '        if self.rubber_band.isVisible():\n'
    '            rect = self.rubber_band.geometry()\n'
    '            self.rubber_band.hide()\n'
    '            if rect.width() > 8 and rect.height() > 8:\n'
    '                scene_rect = self.mapToScene(rect).boundingRect()\n'
    '                self.fitInView(scene_rect, Qt.AspectRatioMode.KeepAspectRatio)\n'
    '            self.mode = "Pan"\n'
    '            self.window().set_mode("Pan")  # type: ignore[attr-defined]\n'
    '            return\n'
    '        if self._panning:\n'
    '            self._panning = False\n'
    '            self.setCursor(Qt.CursorShape.ArrowCursor)\n'
    '            self.window().update_status_from_view()  # type: ignore[attr-defined]\n'
    '            event.accept()\n'
    '            return\n'
    '        super().mouseReleaseEvent(event)\n'
    '\n'
    '\n'
    'class KtdLayerItem(QGraphicsItem):\n'
    '    def __init__(self, shapes: list[Shape]) -> None:\n'
    '        super().__init__()\n'
    '        self.cells = [\n'
    '            (float(shape.points[0][0]), -float(shape.points[0][1]), str(shape.label), str(shape.color), float(shape.value or KTD_NODATA_VALUE))\n'
    '            for shape in shapes\n'
    '            if shape.points\n'
    '        ]\n'
    '        if self.cells:\n'
    '            xs = [cell[0] for cell in self.cells]\n'
    '            ys = [cell[1] for cell in self.cells]\n'
    '            self.min_x = min(xs)\n'
    '            self.min_y = min(ys)\n'
    '            self.max_x = max(xs)\n'
    '            self.max_y = max(ys)\n'
    '            self._rect = QRectF(self.min_x - 5.0, self.min_y - 5.0, self.max_x - self.min_x + 10.0, self.max_y - self.min_y + 10.0)\n'
    '            span = max(self.max_x - self.min_x, self.max_y - self.min_y, 1.0)\n'
    '            self.tile_size = max(50.0, span / 140.0)\n'
    '        else:\n'
    '            self.min_x = self.min_y = self.max_x = self.max_y = 0.0\n'
    '            self.tile_size = 100.0\n'
    '            self._rect = QRectF()\n'
    '        self.tiles: dict[tuple[int, int], list[tuple[float, float, str, str, float]]] = {}\n'
    '        for cell in self.cells:\n'
    '            tile_key = self.tile_for_point(cell[0], cell[1])\n'
    '            self.tiles.setdefault(tile_key, []).append(cell)\n'
    '\n'
    '    def tile_for_point(self, x: float, y: float) -> tuple[int, int]:\n'
    '        return (math.floor((x - self.min_x) / self.tile_size), math.floor((y - self.min_y) / self.tile_size))\n'
    '\n'
    '    def boundingRect(self) -> QRectF:  # type: ignore[override]\n'
    '        return self._rect\n'
    '\n'
    '    def paint(self, painter: QPainter, option, widget=None) -> None:  # type: ignore[override]\n'
    '        exposed = option.exposedRect.adjusted(-10, -10, 10, 10)\n'
    '        lod = option.levelOfDetailFromTransform(painter.worldTransform())\n'
    '        radius = 2.6 / max(lod, 0.25)\n'
    '        radius = max(1.1, min(radius, 4.5))\n'
    '        valid_pen = QPen(QColor("#d000ff"), 0)\n'
    '        valid_brush = QColor("#d000ff")\n'
    '        nodata_pen = QPen(QColor("#9ca3af"), 0)\n'
    '        nodata_brush = QColor("#9ca3af")\n'
    '        label_limit = 9000 if lod > 0.04 else 4500 if lod > 0.015 else 1200\n'
    '        visible_cells: list[tuple[float, float, str, str, float]] = []\n'
    '        min_tx = math.floor((exposed.left() - self.min_x) / self.tile_size)\n'
    '        max_tx = math.floor((exposed.right() - self.min_x) / self.tile_size)\n'
    '        min_ty = math.floor((exposed.top() - self.min_y) / self.tile_size)\n'
    '        max_ty = math.floor((exposed.bottom() - self.min_y) / self.tile_size)\n'
    '        for tx in range(min_tx, max_tx + 1):\n'
    '            for ty in range(min_ty, max_ty + 1):\n'
    '                visible_cells.extend(self.tiles.get((tx, ty), []))\n'
    '        label_stride = max(1, len(visible_cells) // max(label_limit, 1)) if label_limit else len(visible_cells) + 1\n'
    '        point_limit = 90000 if lod < 0.02 else 180000 if lod < 0.05 else 500000\n'
    '        point_stride = max(1, len(visible_cells) // point_limit)\n'
    '        for index, (x, y, label, _color, value) in enumerate(visible_cells):\n'
    '            if index % point_stride:\n'
    '                continue\n'
    '            if not exposed.contains(QPointF(x, y)):\n'
    '                continue\n'
    '            nodata = is_ktd_nodata(value)\n'
    '            painter.setPen(nodata_pen if nodata else valid_pen)\n'
    '            painter.setBrush(nodata_brush if nodata else valid_brush)\n'
    '            painter.drawEllipse(QPointF(x, y), radius, radius)\n'
    '\n'
    '        labels_drawn = 0\n'
    '        font = QFont("Arial", 9)\n'
    '        font.setPointSizeF(max(8.0, min(42.0, 8.0 / max(lod, 0.08))))\n'
    '        font.setBold(True)\n'
    '        painter.setFont(font)\n'
    '        label_offset = max(4.0, min(55.0, 7.5 / max(lod, 0.08)))\n'
    '        for index, (x, y, label, _color, value) in enumerate(visible_cells):\n'
    '            if labels_drawn >= label_limit or index % label_stride:\n'
    '                continue\n'
    '            if not exposed.contains(QPointF(x, y)):\n'
    '                continue\n'
    '            nodata = is_ktd_nodata(value)\n'
    '            painter.setPen(QPen(QColor("#4b5563" if nodata else "#d000ff"), 0))\n'
    '            painter.drawText(QPointF(x + label_offset, y - label_offset), label)\n'
    '            labels_drawn += 1\n'
    '\n'
    '\n'
    'class LiveSurveyItem(QGraphicsItem):\n'
    '    def __init__(self) -> None:\n'
    '        super().__init__()\n'
    '        self.track_points: list[tuple[float, float]] = []\n'
    '        self.soundings: list[tuple[float, float, float]] = []\n'
    '        self._rect = QRectF(-100.0, -100.0, 200.0, 200.0)\n'
    '\n'
    '    def update_data(self, track_points: list[tuple[float, float]], soundings: list[tuple[float, float, float]]) -> None:\n'
    '        self.prepareGeometryChange()\n'
    '        self.track_points = list(track_points[-20000:])\n'
    '        self.soundings = list(soundings[-20000:])\n'
    '        xs = [p[0] for p in self.track_points] + [p[0] for p in self.soundings]\n'
    '        ys = [-p[1] for p in self.track_points] + [-p[1] for p in self.soundings]\n'
    '        if xs and ys:\n'
    '            self._rect = QRectF(min(xs) - 25.0, min(ys) - 25.0, max(xs) - min(xs) + 50.0, max(ys) - min(ys) + 50.0)\n'
    '        else:\n'
    '            self._rect = QRectF(-100.0, -100.0, 200.0, 200.0)\n'
    '        self.update()\n'
    '\n'
    '    def boundingRect(self) -> QRectF:  # type: ignore[override]\n'
    '        return self._rect\n'
    '\n'
    '    def paint(self, painter: QPainter, option, widget=None) -> None:  # type: ignore[override]\n'
    '        lod = option.levelOfDetailFromTransform(painter.worldTransform())\n'
    '        exposed = option.exposedRect.adjusted(-20, -20, 20, 20)\n'
    '        dot_radius = max(0.8, min(2.2, 1.7 / max(lod, 0.25)))\n'
    '        painter.setPen(QPen(QColor("#0f766e"), 0))\n'
    '        painter.setBrush(QColor("#0f766e"))\n'
    '        stride = max(1, len(self.track_points) // 8000)\n'
    '        for index, (x, y) in enumerate(self.track_points):\n'
    '            if index % stride:\n'
    '                continue\n'
    '            scene_y = -y\n'
    '            if exposed.contains(QPointF(x, scene_y)):\n'
    '                painter.drawEllipse(QPointF(x, scene_y), dot_radius, dot_radius)\n'
    '\n'
    '        label_limit = 3500 if lod > 0.03 else 0\n'
    '        label_stride = max(1, len(self.soundings) // max(label_limit, 1)) if label_limit else len(self.soundings) + 1\n'
    '        painter.setFont(QFont("Times New Roman", 8))\n'
    '        painter.setPen(QPen(QColor("#111827"), 0))\n'
    '        for index, (x, y, depth) in enumerate(self.soundings):\n'
    '            if not label_limit or index % label_stride:\n'
    '                continue\n'
    '            scene_y = -y\n'
    '            if not exposed.contains(QPointF(x, scene_y)):\n'
    '                continue\n'
    '            label = f"{depth:.1f}"\n'
    '            painter.drawText(QPointF(x + 1.5 / max(lod, 0.25), scene_y - 1.5 / max(lod, 0.25)), label)\n'
    '\n'
    '\n'
    'class UTMCoordinateAxis(pg.AxisItem):\n'
    '    """Absolute project-grid metres, matching the cursor coordinate display."""\n'
    '    def tickStrings(self, values, scale, spacing):\n'
    '        return [f"{float(value):,.3f}" if math.isfinite(float(value)) else "" for value in values]\n'
    '\n'
    '\n'
    'class PyQtGraphSurveyMap(pg.PlotWidget):\n'
    '    def __init__(self, owner: Any = None) -> None:\n'
    '        super().__init__(axisItems={"left": UTMCoordinateAxis(orientation="left"), "bottom": UTMCoordinateAxis(orientation="bottom")})\n'
    '        for name in ("left", "bottom"):\n'
    '            self.getAxis(name).enableAutoSIPrefix(False)\n'
    '        self.getAxis("left").setWidth(140)\n'
    '        self.owner = owner\n'
    '        self.mode = "Pan"\n'
    '        self._editing_vertex = False\n'
    '        self._measuring = False\n'
    '        self.measure_start: Optional[tuple[float, float]] = None\n'
    '        self.measure_line = pg.PlotDataItem([], [], pen=pg.mkPen("#ef4444", width=2))\n'
    '        self.measure_label = pg.TextItem("", color=(239, 68, 68), anchor=(0, 1))\n'
    '        self.setBackground("w")\n'
    '        self.showGrid(x=True, y=True, alpha=0.22)\n'
    '        self.setAspectLocked(True)\n'
    '        self.setLabel("bottom", "Easting")\n'
    '        self.setLabel("left", "Northing")\n'
    '        self.plotItem.vb.setMouseMode(pg.ViewBox.PanMode)\n'
    '        self.live_track_item = pg.ScatterPlotItem(pxMode=True, pen=None, brush=pg.mkBrush(15, 118, 110, 190), size=5)\n'
    '        self.live_sounding_items: list[pg.TextItem] = []\n'
    '        self.addItem(self.live_track_item)\n'
    '        self.addItem(self.measure_line)\n'
    '        self.addItem(self.measure_label)\n'
    '        self.measure_line.setVisible(False)\n'
    '        self.measure_label.setVisible(False)\n'
    '        self.scene().sigMouseMoved.connect(self._on_mouse_moved)\n'
    '\n'
    '    def _on_mouse_moved(self, pos: QPointF) -> None:\n'
    '        if self.owner is None:\n'
    '            return\n'
    '        if self.sceneBoundingRect().contains(pos):\n'
    '            point = self.plotItem.vb.mapSceneToView(pos)\n'
    '            try:\n'
    '                self.owner.set_coordinate_status(float(point.x()), float(point.y()))\n'
    '            except Exception:\n'
    '                pass\n'
    '\n'
    '    def set_mode(self, mode: str) -> None:\n'
    '        self.mode = mode\n'
    '        self.plotItem.vb.setMouseMode(pg.ViewBox.RectMode if mode == "Zoom Window" else pg.ViewBox.PanMode)\n'
    '        if mode != "Measure":\n'
    '            self._measuring = False\n'
    '\n'
    '    def event_to_map_xy(self, event) -> tuple[float, float]:\n'
    '        scene_pos = self.mapToScene(event.position().toPoint())\n'
    '        point = self.plotItem.vb.mapSceneToView(scene_pos)\n'
    '        return float(point.x()), float(point.y())\n'
    '\n'
    '    def mousePressEvent(self, event) -> None:  # type: ignore[override]\n'
    '        owner = self.owner\n'
    '        if owner is not None and getattr(owner, "_consume_planning_click", None):\n'
    '            if owner._consume_planning_click(event, self):\n'
    '                event.accept()\n'
    '                return\n'
    '        picker = getattr(self, "corner_picker", None)\n'
    '        if picker is not None:\n'
    '            if event.button() == Qt.MouseButton.RightButton:\n'
    '                picker.cancel_pick()\n'
    '            elif event.button() == Qt.MouseButton.LeftButton:\n'
    '                scene_pos = self.mapToScene(event.position().toPoint())\n'
    '                if self.plotItem.vb.sceneBoundingRect().contains(scene_pos):\n'
    '                    picker.map_click(*self.event_to_map_xy(event))\n'
    '            event.accept()\n'
    '            return\n'
    '        if self.mode == "Measure" and event.button() == Qt.MouseButton.LeftButton:\n'
    '            self.measure_start = self.event_to_map_xy(event)\n'
    '            self._measuring = True\n'
    '            self.update_measure_overlay(*self.measure_start)\n'
    '            event.accept()\n'
    '            return\n'
    '        if self.mode == "Edit DXF" and event.button() == Qt.MouseButton.LeftButton and self.owner is not None:\n'
    '            x, y = self.event_to_map_xy(event)\n'
    '            try:\n'
    '                self._editing_vertex = bool(self.owner.select_edit_vertex(x, y))\n'
    '            except Exception:\n'
    '                self._editing_vertex = False\n'
    '            if self._editing_vertex:\n'
    '                event.accept()\n'
    '                return\n'
    '        super().mousePressEvent(event)\n'
    '\n'
    '    def keyPressEvent(self, event):\n'
    '        if event.key() == Qt.Key.Key_Escape and self.owner is not None:\n'
    "            cancel = getattr(self.owner, 'context', {}).get('view_state', {}).get('line_pick_cancel')\n"
    '            if cancel:\n'
    '                cancel();event.accept();return\n'
    '        picker = getattr(self, "corner_picker", None)\n'
    '        if picker is not None and event.key() == Qt.Key.Key_Escape:\n'
    '            picker.cancel_pick()\n'
    '            event.accept()\n'
    '            return\n'
    '        super().keyPressEvent(event)\n'
    '\n'
    '    def mouseMoveEvent(self, event) -> None:  # type: ignore[override]\n'
    '        if self.mode == "Measure" and self._measuring and self.measure_start is not None:\n'
    '            x, y = self.event_to_map_xy(event)\n'
    '            self.update_measure_overlay(x, y)\n'
    '            event.accept()\n'
    '            return\n'
    '        if self.mode == "Edit DXF" and self._editing_vertex and self.owner is not None:\n'
    '            x, y = self.event_to_map_xy(event)\n'
    '            try:\n'
    '                self.owner.move_selected_vertex(x, y)\n'
    '            except Exception:\n'
    '                pass\n'
    '            event.accept()\n'
    '            return\n'
    '        super().mouseMoveEvent(event)\n'
    '\n'
    '    def mouseReleaseEvent(self, event) -> None:  # type: ignore[override]\n'
    '        if self.mode == "Measure" and self._measuring:\n'
    '            x, y = self.event_to_map_xy(event)\n'
    '            self.update_measure_overlay(x, y)\n'
    '            self._measuring = False\n'
    '            event.accept()\n'
    '            return\n'
    '        if self.mode == "Edit DXF" and self._editing_vertex and self.owner is not None:\n'
    '            try:\n'
    '                self.owner.finish_edit_vertex()\n'
    '            except Exception:\n'
    '                pass\n'
    '            self._editing_vertex = False\n'
    '            event.accept()\n'
    '            return\n'
    '        super().mouseReleaseEvent(event)\n'
    '\n'
    '    def update_measure_overlay(self, x: float, y: float) -> None:\n'
    '        if self.measure_start is None:\n'
    '            return\n'
    '        x0, y0 = self.measure_start\n'
    '        dx = float(x) - x0\n'
    '        dy = float(y) - y0\n'
    '        distance = math.hypot(dx, dy)\n'
    '        bearing = (math.degrees(math.atan2(dx, dy)) + 360.0) % 360.0\n'
    '        self.measure_line.setData([x0, float(x)], [y0, float(y)])\n'
    '        self.measure_line.setVisible(True)\n'
    '        self.measure_label.setText(f"{distance:,.2f} m  Brg {bearing:06.2f}")\n'
    '        self.measure_label.setPos(float(x), float(y))\n'
    '        self.measure_label.setVisible(True)\n'
    '        if self.owner is not None:\n'
    '            try:\n'
    '                self.owner.status.showMessage(f"Measure: {distance:,.2f} m | Bearing {bearing:06.2f}", 4000)\n'
    '            except Exception:\n'
    '                pass\n'
    '\n'
    '    def set_map_background(self, color: str) -> None:\n'
    '        self.setBackground(color)\n'
    '        self._apply_cad_contrast(self.scene().items())\n'
    '\n'
    '    def zoom_by(self, factor: float) -> None:\n'
    '        scale = 1.0 / max(float(factor), 0.0001)\n'
    '        self.plotItem.vb.scaleBy((scale, scale))\n'
    '\n'
    '    def pan_fraction(self, dx_fraction: float, dy_fraction: float) -> None:\n'
    '        x_range, y_range = self.plotItem.vb.viewRange()\n'
    '        dx = (x_range[1] - x_range[0]) * float(dx_fraction)\n'
    '        dy = (y_range[1] - y_range[0]) * float(dy_fraction)\n'
    '        self.plotItem.vb.setXRange(x_range[0] + dx, x_range[1] + dx, padding=0)\n'
    '        self.plotItem.vb.setYRange(y_range[0] + dy, y_range[1] + dy, padding=0)\n'
    '\n'
    '    def add_shapes_layer(self, shapes: list[Shape]) -> list[Any]:\n'
    "        cad = [s for s in shapes if hasattr(s, 'cad_layer')]\n"
    "        items = self._add_non_cad_shapes([s for s in shapes if not hasattr(s, 'cad_layer')])\n"
    '        lines = {}\n'
    '        for s in cad:\n'
    '            if not s.points: continue\n'
    '            item = None\n'
    "            if s.kind == 'cad_fill':\n"
    '                path = QPainterPath()\n'
    '                path.setFillRule(Qt.FillRule.OddEvenFill)\n'
    '                for ring in s.rings:\n'
    '                    path.moveTo(*ring[0])\n'
    '                    for p in ring[1:]: path.lineTo(*p)\n'
    '                    path.closeSubpath()\n'
    '                item = QGraphicsPathItem(path)\n'
    '                item.setPen(QPen(Qt.PenStyle.NoPen))\n'
    '                item.setBrush(QColor(s.color))\n'
    '                item._cad_kind = 0\n'
    "            elif s.kind == 'line':\n"
    '                points = lines.setdefault((s.cad_layer, s.color, s.cad_visible, s.cad_auto_color), [])\n'
    "                points.extend(s.points); points.append((float('nan'), float('nan')))\n"
    "            elif s.kind == 'text':\n"
    '                item = pg.TextItem(s.label, color=s.color, anchor=(0, 1))\n'
    "                item.setFont(QFont('Arial', 12))\n"
    '                item.setPos(*s.points[0]); item._cad_kind = 2\n'
    "            elif s.kind == 'point':\n"
    '                item = pg.ScatterPlotItem([s.points[0][0]], [s.points[0][1]], brush=s.color, pen=None, size=5)\n'
    '                item._cad_kind = 1\n'
    '            if item is not None:\n'
    '                item._cad_layer = s.cad_layer\n'
    '                item._cad_auto_color = s.cad_auto_color\n'
    '                item._entity_visible = s.cad_visible\n'
    '                self.addItem(item); items.append(item)\n'
    '        for (name, color, visible, auto_color), points in lines.items():\n'
    '            arr = np.asarray(points)\n'
    "            item = pg.PlotDataItem(arr[:,0], arr[:,1], connect='finite', pen=pg.mkPen(color, width=1))\n"
    '            item._cad_layer = name; item._cad_kind = 1; item._entity_visible = visible\n'
    '            item._cad_auto_color = auto_color\n'
    '            self.addItem(item); items.append(item)\n'
    '        self._apply_cad_contrast(items)\n'
    '        return items\n'
    '\n'
    '    def _apply_cad_contrast(self, items):\n'
    "        color = '#111827' if self.backgroundBrush().color().lightness() > 128 else '#ffffff'\n"
    '        for item in items:\n'
    "            if not getattr(item, '_cad_auto_color', False): continue\n"
    '            if isinstance(item, pg.TextItem): item.setColor(color)\n'
    '            elif isinstance(item, pg.PlotDataItem): item.setPen(pg.mkPen(color, width=1))\n'
    '            elif isinstance(item, pg.ScatterPlotItem): item.setBrush(pg.mkBrush(color))\n'
    '            elif isinstance(item, QGraphicsPathItem): item.setBrush(QColor(color))\n'
    '\n'
    '    def _add_non_cad_shapes(self, shapes: list[Shape]) -> list[Any]:\n'
    '        items: list[Any] = []\n'
    '        ktd_x: list[float] = []\n'
    '        ktd_y: list[float] = []\n'
    '        ktd_v: list[float] = []\n'
    '        point_x: list[float] = []\n'
    '        point_y: list[float] = []\n'
    '        point_labels: list[str] = []\n'
    '        line_groups = {}\n'
    '\n'
    '        for shape in shapes:\n'
    '            if not shape.points:\n'
    '                continue\n'
    '            if shape.kind == "ktd":\n'
    '                value = float(shape.value if shape.value is not None else KTD_NODATA_VALUE)\n'
    '                if is_ktd_nodata(value):\n'
    '                    continue\n'
    '                ktd_x.append(float(shape.points[0][0]))\n'
    '                ktd_y.append(float(shape.points[0][1]))\n'
    '                ktd_v.append(value)\n'
    '            elif shape.kind == "point":\n'
    '                point_x.append(float(shape.points[0][0]))\n'
    '                point_y.append(float(shape.points[0][1]))\n'
    '                point_labels.append(str(shape.label or ""))\n'
    '            elif shape.kind == "line" and len(shape.points) >= 2:\n'
    '                points = line_groups.setdefault(shape.color or "#64748b", [])\n'
    '                points.extend(shape.points)\n'
    '                points.append((float("nan"), float("nan")))\n'
    '            elif shape.kind == "text":\n'
    '                label = pg.TextItem(str(shape.label)[:80], color=shape.color or "#111827", anchor=(0, 1))\n'
    '                label.setPos(float(shape.points[0][0]), float(shape.points[0][1]))\n'
    '                self.addItem(label)\n'
    '                items.append(label)\n'
    '\n'
    '        for color, points in line_groups.items():\n'
    '            arr = np.asarray(points, dtype=float)\n'
    '            item = pg.PlotDataItem(arr[:, 0], arr[:, 1], connect="finite", pen=pg.mkPen(color, width=1))\n'
    '            self.addItem(item)\n'
    '            items.append(item)\n'
    '\n'
    '        if ktd_x:\n'
    '            x_arr = np.asarray(ktd_x, dtype=float)\n'
    '            y_arr = np.asarray(ktd_y, dtype=float)\n'
    '            v_arr = np.asarray(ktd_v, dtype=float)\n'
    '            min_x, max_x = float(np.min(x_arr)), float(np.max(x_arr))\n'
    '            min_y, max_y = float(np.min(y_arr)), float(np.max(y_arr))\n'
    '            grid_x: list[float] = []\n'
    '            grid_y: list[float] = []\n'
    '            start_x = math.floor(min_x / 100.0) * 100.0\n'
    '            end_x = math.ceil(max_x / 100.0) * 100.0\n'
    '            start_y = math.floor(min_y / 100.0) * 100.0\n'
    '            end_y = math.ceil(max_y / 100.0) * 100.0\n'
    '            value = start_x\n'
    '            while value <= end_x:\n'
    '                grid_x.extend([value, value, float("nan")])\n'
    '                grid_y.extend([start_y, end_y, float("nan")])\n'
    '                value += 100.0\n'
    '            value = start_y\n'
    '            while value <= end_y:\n'
    '                grid_x.extend([start_x, end_x, float("nan")])\n'
    '                grid_y.extend([value, value, float("nan")])\n'
    '                value += 100.0\n'
    '            if grid_x:\n'
    '                grid_item = pg.PlotDataItem(np.asarray(grid_x), np.asarray(grid_y), pen=pg.mkPen((210, 0, 255, 45), width=0.6))\n'
    '                self.addItem(grid_item)\n'
    '                items.append(grid_item)\n'
    '            scatter = pg.ScatterPlotItem(x=x_arr, y=y_arr, pxMode=True, pen=None, brush=pg.mkBrush(210, 0, 255, 190), size=5)\n'
    '            self.addItem(scatter)\n'
    '            items.append(scatter)\n'
    '            label_stride = 1 if len(x_arr) <= 10000 else max(1, len(x_arr) // 10000)\n'
    '            for xi, yi, vi in zip(x_arr[::label_stride], y_arr[::label_stride], v_arr[::label_stride]):\n'
    '                label = pg.TextItem(f"{vi:.2f}", color=(210, 0, 255), anchor=(0, 1))\n'
    '                label.setPos(float(xi), float(yi))\n'
    '                self.addItem(label)\n'
    '                items.append(label)\n'
    '\n'
    '        if point_x:\n'
    '            scatter = pg.ScatterPlotItem(x=np.asarray(point_x), y=np.asarray(point_y), pxMode=True, pen=None, brush=pg.mkBrush(37, 99, 235, 190), size=6)\n'
    '            self.addItem(scatter)\n'
    '            items.append(scatter)\n'
    '            label_stride = max(1, len(point_x) // 500)\n'
    '            for xi, yi, label_text in zip(point_x[::label_stride], point_y[::label_stride], point_labels[::label_stride]):\n'
    '                if label_text:\n'
    '                    label = pg.TextItem(label_text[:32], color=(17, 24, 39), anchor=(0, 1))\n'
    '                    label.setPos(float(xi), float(yi))\n'
    '                    self.addItem(label)\n'
    '                    items.append(label)\n'
    '        return items\n'
    '\n'
    '    def remove_layer_items(self, items: Optional[list[Any]]) -> None:\n'
    '        for item in list(items or []):\n'
    '            try:\n'
    '                self.removeItem(item)\n'
    '            except Exception:\n'
    '                pass\n'
    '\n'
    '    def clear_background_items(self, layer_items: list[list[Any]]) -> None:\n'
    '        for items in layer_items:\n'
    '            self.remove_layer_items(items)\n'
    '\n'
    '    def update_live(self, track_points: list[tuple[float, float]], soundings: list[tuple[float, float, float]]) -> None:\n'
    '        if track_points:\n'
    '            arr = np.asarray(track_points[-30000:], dtype=float)\n'
    '            self.live_track_item.setData(x=arr[:, 0], y=arr[:, 1])\n'
    '        else:\n'
    '            self.live_track_item.setData([], [])\n'
    '        for item in self.live_sounding_items:\n'
    '            self.removeItem(item)\n'
    '        self.live_sounding_items.clear()\n'
    '        if soundings:\n'
    '            stride = max(1, len(soundings) // 3500)\n'
    '            for x, y, depth in soundings[-30000::stride]:\n'
    '                label = pg.TextItem(f"{depth:.1f}", color=(17, 24, 39), anchor=(0, 1))\n'
    '                label.setPos(float(x), float(y))\n'
    '                self.addItem(label)\n'
    '                self.live_sounding_items.append(label)\n'
    '\n'
    '    def visible_bounds(self) -> QRectF:\n'
    '        x_range, y_range = self.plotItem.vb.viewRange()\n'
    '        return QRectF(float(x_range[0]), float(y_range[0]), float(x_range[1] - x_range[0]), float(y_range[1] - y_range[0]))\n'
    '\n'
    '    def fit_bounds(self, bounds: Optional[tuple[float, float, float, float]]) -> None:\n'
    '        if not bounds:\n'
    '            self.autoRange()\n'
    '            return\n'
    '        min_x, min_y, max_x, max_y = bounds\n'
    '        if max_x <= min_x or max_y <= min_y:\n'
    '            return\n'
    '        self.setXRange(min_x, max_x, padding=0.05)\n'
    '        self.setYRange(min_y, max_y, padding=0.05)\n'
    '\n'
    '\n'
    'def validate_four_corners(points):\n'
    '    p = np.asarray(points, dtype=float)\n'
    '    if p.shape != (4, 2) or not np.isfinite(p).all():\n'
    '        raise ValueError("Enter finite Easting and Northing coordinates for all four corners.")\n'
    '    edges = np.roll(p, -1, axis=0) - p\n'
    '    cross = edges[:, 0] * np.roll(edges, -1, axis=0)[:, 1] - edges[:, 1] * np.roll(edges, -1, axis=0)[:, 0]\n'
    '    tolerance = max(float(np.max(np.abs(edges))) ** 2 * 1e-12, 1e-16)\n'
    '    if not (np.all(cross > tolerance) or np.all(cross < -tolerance)):\n'
    '        raise ValueError("Corners must form a convex area in clockwise or counterclockwise order, without duplicates or crossing edges.")\n'
    '    return p\n'
    '\n'
    '\n'
    'def interpolate_four_corners(points, values, queries):\n'
    '    """Piecewise linear interpolation on triangles 1-2-3 and 1-3-4."""\n'
    '    p = validate_four_corners(points)\n'
    '    k = np.asarray(values, dtype=float)\n'
    '    if k.shape != (4,) or not np.isfinite(k).all() or any(is_ktd_nodata(v) for v in k):\n'
    '        raise ValueError("Enter four finite K values; 999.99 is reserved for NoData.")\n'
    '    q = np.asarray(queries, dtype=float).reshape(-1, 2)\n'
    '    result = np.full(len(q), KTD_NODATA_VALUE)\n'
    '    inside = np.zeros(len(q), dtype=bool)\n'
    '    for indices in ((0, 1, 2), (0, 2, 3)):\n'
    '        a, b, c = p[list(indices)]\n'
    '        uv = np.linalg.solve(np.column_stack((b - a, c - a)), (q - a).T).T\n'
    '        weights = np.column_stack((1 - uv.sum(axis=1), uv))\n'
    '        mask = np.all(weights >= -1e-10, axis=1)\n'
    '        result[mask] = weights[mask] @ k[list(indices)]\n'
    '        inside |= mask\n'
    '    if any(is_ktd_nodata(v) for v in result[inside]):\n'
    '        raise ValueError("Interpolation produces reserved NoData value 999.99; adjust the K values.")\n'
    '    return result, inside\n'
    '\n'
    '\n'
    'class FourCornerDialog(QDialog):\n'
    '    def __init__(self, owner, with_values=False):\n'
    '        super().__init__(owner)\n'
    '        self.owner = owner\n'
    '        self.with_values = with_values\n'
    '        self.setWindowTitle("Four corners — map coordinates")\n'
    '        layout = QVBoxLayout(self)\n'
    '        layout.addWidget(QLabel("Enter corners around the perimeter (clockwise or counterclockwise).\\nCoordinates use the map\'s Easting/Northing system. K values are in metres."))\n'
    '        self.table = QTableWidget(4, 3 if with_values else 2)\n'
    '        self.table.setHorizontalHeaderLabels(["Easting", "Northing", "K"] if with_values else ["Easting", "Northing"])\n'
    '        for row in range(4):\n'
    '            for col in range(self.table.columnCount()):\n'
    '                self.table.setItem(row, col, QTableWidgetItem(""))\n'
    '        layout.addWidget(self.table)\n'
    '        self.message = QLabel("Pick all four corners on the main map, or type coordinates above.")\n'
    '        layout.addWidget(self.message)\n'
    '        for text, callback in (("Pick four corners on map", self.pick), ("Use these corners", self.confirm), ("Cancel", self.reject)):\n'
    '            button = QPushButton(text)\n'
    '            button.clicked.connect(callback)\n'
    '            layout.addWidget(button)\n'
    '        self.finished.connect(self.cleanup)\n'
    '        self.resize(590, 370)\n'
    '\n'
    '    def pick(self):\n'
    '        view = self.owner.view\n'
    '        self.cleanup()\n'
    '        previous = getattr(view, "corner_picker", None)\n'
    '        if previous is not None and previous != self:\n'
    '            previous.cancel_pick()\n'
    '        self.picked = []\n'
    '        view.corner_picker = self\n'
    '        self.overlay = pg.PlotDataItem([], [], pen=pg.mkPen("#dc2626", width=2), symbol="o", symbolSize=9)\n'
    '        view.addItem(self.overlay)\n'
    '        self.hide()\n'
    '        self.owner.raise_()\n'
    '        view.setFocus()\n'
    '        self.owner.status.showMessage("Select corner 1 of 4. Right-click or Escape cancels selection.")\n'
    '\n'
    '    def map_click(self, x, y):\n'
    '        row = len(self.picked)\n'
    '        self.picked.append((x, y))\n'
    '        for col, value in enumerate((x, y)):\n'
    '            self.table.item(row, col).setText(f"{value:.8f}")\n'
    '        self.overlay.setData([p[0] for p in self.picked], [p[1] for p in self.picked])\n'
    '        if len(self.picked) == 4:\n'
    '            self.cancel_pick()\n'
    '            self.message.setText("Four corners selected. Review coordinates and enter K values before continuing.")\n'
    '        else:\n'
    '            self.owner.status.showMessage(f"Select corner {len(self.picked) + 1} of 4. Right-click or Escape cancels.")\n'
    '\n'
    '    def cleanup(self, *_):\n'
    '        if getattr(self.owner.view, "corner_picker", None) is self:\n'
    '            self.owner.view.corner_picker = None\n'
    '        if getattr(self, "overlay", None) is not None:\n'
    '            self.owner.view.removeItem(self.overlay)\n'
    '            self.overlay = None\n'
    '        self.owner.status.clearMessage()\n'
    '\n'
    '    def cancel_pick(self):\n'
    '        self.cleanup()\n'
    '        self.show()\n'
    '        self.raise_()\n'
    '        self.activateWindow()\n'
    '\n'
    '    def confirm(self):\n'
    '        try:\n'
    '            rows = [[float(self.table.item(r, c).text()) for c in range(self.table.columnCount())] for r in range(4)]\n'
    '            self.points = validate_four_corners([r[:2] for r in rows]).tolist()\n'
    '            self.values = [r[2] for r in rows] if self.with_values else []\n'
    '            if self.with_values:\n'
    '                interpolate_four_corners(self.points, self.values, self.points)\n'
    '            self.accept()\n'
    '        except ValueError as exc:\n'
    '            QMessageBox.warning(self, "Four corners", str(exc))\n'
    '\n'
    '\n'
    'class MatrixKtdEditor(QMainWindow):\n'
    '    def __init__(self, owner):\n'
    '        super().__init__(owner)\n'
    '        self.owner = owner\n'
    '        self.matrix = None\n'
    '        self.setWindowTitle("KTD Matrix Editor — four corners")\n'
    '        root = QWidget()\n'
    '        layout = QVBoxLayout(root)\n'
    '        layout.addWidget(QLabel("Create a regular KTD grid or edit an existing matrix. Interpolation uses\\ntriangles 1–2–3 and 1–3–4; values outside the selected area remain unchanged."))\n'
    '        options = QHBoxLayout()\n'
    '        self.nx, self.ny = QSpinBox(), QSpinBox()\n'
    '        for label, spin in (("Columns", self.nx), ("Rows", self.ny)):\n'
    '            spin.setRange(2, 500)\n'
    '            spin.setValue(21)\n'
    '            options.addWidget(QLabel(label))\n'
    '            options.addWidget(spin)\n'
    '        layout.addLayout(options)\n'
    '        buttons = QHBoxLayout()\n'
    '        for label, callback in (("New from four corners", self.new_grid), ("Open matrix KTD", self.open_grid), ("Interpolate from four points", self.interpolate), ("Save KTD as…", self.save_grid)):\n'
    '            button = QPushButton(label)\n'
    '            button.clicked.connect(callback)\n'
    '            buttons.addWidget(button)\n'
    '        layout.addLayout(buttons)\n'
    '        self.table = QTableWidget(0, 3)\n'
    '        self.table.setHorizontalHeaderLabels(["Easting", "Northing", "K (editable)"])\n'
    '        layout.addWidget(self.table)\n'
    '        self.status = QLabel("Create or open a matrix KTD. Maximum 50,000 cells in this editor.")\n'
    '        layout.addWidget(self.status)\n'
    '        self.setCentralWidget(root)\n'
    '        self.resize(950, 650)\n'
    '\n'
    '    def corners(self, callback):\n'
    '        self.corner_dialog = FourCornerDialog(self.owner, True)\n'
    '        self.corner_dialog.accepted.connect(lambda: callback(self.corner_dialog.points, self.corner_dialog.values))\n'
    '        self.corner_dialog.show()\n'
    '\n'
    '    def queries(self):\n'
    '        m = self.matrix\n'
    '        xx, yy = np.meshgrid(np.linspace(m.min_x, m.max_x, m.x_count), np.linspace(m.min_y, m.max_y, m.y_count))\n'
    '        return np.column_stack((xx.ravel(), yy.ravel()))\n'
    '\n'
    '    def refresh(self):\n'
    '        self.table.setRowCount(len(self.matrix.values))\n'
    '        for row, ((x, y), k) in enumerate(zip(self.queries(), self.matrix.values)):\n'
    '            for col, value in enumerate((x, y, k)):\n'
    '                item = QTableWidgetItem(f"{value:.8f}")\n'
    '                if col < 2:\n'
    '                    item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsEditable)\n'
    '                self.table.setItem(row, col, item)\n'
    '        self.status.setText(f"{self.matrix.x_count} columns × {self.matrix.y_count} rows. 999.99 = NoData. Save to write changes.")\n'
    '\n'
    '    def collect(self):\n'
    '        if self.matrix is None:\n'
    '            raise ValueError("Create or open a matrix first.")\n'
    '        values = []\n'
    '        for row in range(self.table.rowCount()):\n'
    '            try:\n'
    '                value = float(self.table.item(row, 2).text())\n'
    '                if not math.isfinite(value):\n'
    '                    raise ValueError()\n'
    '            except ValueError:\n'
    '                raise ValueError(f"Enter a finite K value at row {row + 1}.")\n'
    '            values.append(value)\n'
    '        self.matrix.values = values\n'
    '\n'
    '    def new_grid(self):\n'
    '        if self.nx.value() * self.ny.value() > 50000:\n'
    '            QMessageBox.warning(self, "Grid size", "Use at most 50,000 cells.")\n'
    '            return\n'
    '        self.corners(self.create_grid)\n'
    '\n'
    '    def create_grid(self, points, values):\n'
    '        if self.nx.value() * self.ny.value() > 50000:\n'
    '            QMessageBox.warning(self, "Grid size", "Use at most 50,000 cells.")\n'
    '            return\n'
    '        p = validate_four_corners(points)\n'
    '        m = KtdMatrix(Path("new.ktd"), self.nx.value(), self.ny.value(), *p.min(axis=0), *p.max(axis=0), [])\n'
    '        previous = self.matrix\n'
    '        try:\n'
    '            self.matrix = m\n'
    '            result, mask = interpolate_four_corners(points, values, self.queries())\n'
    '            if not mask.any():\n'
    '                raise ValueError("No grid nodes fall inside the area. Increase grid resolution.")\n'
    '            m.values = result.tolist()\n'
    '            self.refresh()\n'
    '        except ValueError as exc:\n'
    '            self.matrix = previous\n'
    '            QMessageBox.warning(self, "Create KTD", str(exc))\n'
    '\n'
    '    def open_grid(self):\n'
    '        name, _ = QFileDialog.getOpenFileName(self, "Open matrix KTD", str(self.owner.project_folder), "KTD (*.ktd *.KTD *.hpktd *.ktdp)")\n'
    '        if not name:\n'
    '            return\n'
    '        try:\n'
    '            matrix = read_ktd_matrix(Path(name))\n'
    '            if matrix.x_count < 2 or matrix.y_count < 2 or len(matrix.values) > 50000 or matrix.dx <= 0 or matrix.dy <= 0:\n'
    '                raise ValueError("Use a regular matrix with 2 or more rows/columns and at most 50,000 cells.")\n'
    '            self.matrix = matrix\n'
    '            self.refresh()\n'
    '        except Exception as exc:\n'
    '            QMessageBox.warning(self, "Open KTD", str(exc))\n'
    '\n'
    '    def interpolate(self):\n'
    '        try:\n'
    '            self.collect()\n'
    '        except ValueError as exc:\n'
    '            QMessageBox.warning(self, "Interpolate", str(exc))\n'
    '            return\n'
    '        self.corners(self.apply_interpolation)\n'
    '\n'
    '    def apply_interpolation(self, points, values):\n'
    '        try:\n'
    '            self.collect()\n'
    '            result, mask = interpolate_four_corners(points, values, self.queries())\n'
    '            if not mask.any():\n'
    '                raise ValueError("No existing grid nodes are inside the selected area.")\n'
    '            data = np.asarray(self.matrix.values)\n'
    '            data[mask] = result[mask]\n'
    '            self.matrix.values = data.tolist()\n'
    '            self.refresh()\n'
    '            self.status.setText(f"Interpolated {int(mask.sum())} cells. Save to write changes.")\n'
    '        except ValueError as exc:\n'
    '            QMessageBox.warning(self, "Interpolate", str(exc))\n'
    '\n'
    '    def save_grid(self):\n'
    '        try:\n'
    '            self.collect()\n'
    '            name, _ = QFileDialog.getSaveFileName(self, "Save matrix KTD", str(self.owner.project_folder / "KTD" / "four_corner.ktd"), "KTD (*.ktd)")\n'
    '            if not name:\n'
    '                return\n'
    '            target = Path(name).with_suffix(".ktd")\n'
    '            # Preserve coordinate and K precision in newly edited matrices.\n'
    '            target.parent.mkdir(parents=True, exist_ok=True)\n'
    '            m = self.matrix\n'
    '            with target.open("w", encoding="utf-8") as handle:\n'
    '                handle.write(f"{m.y_count} {m.x_count} {m.min_x:.8f} {m.min_y:.8f} {m.max_x:.8f} {m.max_y:.8f}\\n")\n'
    '                for row in range(m.y_count):\n'
    '                    handle.write(" ".join(f"{v:.8f}" for v in m.values[row*m.x_count:(row+1)*m.x_count]) + "\\n")\n'
    '            m.path = target\n'
    '            self.owner.add_layer(Layer(target.name, target, load_ktd_shapes(target, False)))\n'
    '            self.owner.fit_extents()\n'
    '            self.status.setText(f"Saved and displayed {target}. Load in the original KTD Editor to apply as RTK tide KTD.")\n'
    '        except Exception as exc:\n'
    '            QMessageBox.warning(self, "Save KTD", str(exc))\n'
    '\n'
    '\n'
    'def show_four_corner_border(owner):\n'
    '    dialog = FourCornerDialog(owner)\n'
    '    owner.four_corner_border_dialog = dialog\n'
    '    def save():\n'
    '        name, _ = QFileDialog.getSaveFileName(owner, "Save four-corner border", str(owner.project_folder / "EXPORT" / "four_corner.brd"), "Border (*.brd)")\n'
    '        if not name:\n'
    '            return\n'
    '        try:\n'
    '            target = Path(name).with_suffix(".brd")\n'
    '            target.parent.mkdir(parents=True, exist_ok=True)\n'
    '            points = [tuple(p) for p in dialog.points]\n'
    '            points.append(points[0])\n'
    '            target.write_text("".join(f"{x:.8f} {y:.8f}\\n" for x, y in points), encoding="utf-8")\n'
    '            owner.add_layer(Layer(f"BORDER {target.name}", target, [Shape("line", points, target.stem, "#dc2626")]))\n'
    '            owner.fit_extents()\n'
    '            owner.status.showMessage(f"Saved four-corner border: {target}", 10000)\n'
    '        except Exception as exc:\n'
    '            QMessageBox.warning(owner, "Save border", str(exc))\n'
    '    dialog.accepted.connect(save)\n'
    '    dialog.show()\n'
