    '        win.resize(900, 600)\n'
    '        win.show()\n'
    '\n'
    '    def refresh_project_label(self) -> None:\n'
    '        self.project_label.setText(f"Project: {self.project_folder}")\n'
    '\n'
    '    def active_ktd_reference_path(self) -> Path:\n'
