    '\n'
    '    def startup_geodetic_settings_path(self) -> Path:\n'
    '        return self.project_folder / "Settings" / "startup_geodetic.json"\n'
    '\n'
    '    def load_startup_geodetic_settings(self) -> dict[str, object]:\n'
    '        path = self.startup_geodetic_settings_path()\n'
    '        defaults: dict[str, object] = {\n'
    '            "crs": "EPSG:32642 UTM 42N",\n'
    '            "source_datum": "WGS84 / GNSS",\n'
    '            "target_datum": "WGS84 / UTM Zone 42N",\n'
    '            "projection": "UTM Zone 42N",\n'
    '            "vertical_reference": "RTK tide using active KTD",\n'
    '            "ktd_path": self.ktd_file_path,\n'
    '            "use_rtk_tide": self.use_rtk_tide_method,\n'
    '        }\n'
    '        if not path.exists():\n'
    '            return defaults\n'
    '        try:\n'
    '            saved = json.loads(path.read_text(encoding="utf-8", errors="replace"))\n'
    '            if isinstance(saved, dict):\n'
    '                defaults.update(saved)\n'
    '        except Exception:\n'
    '            pass\n'
    '        return defaults\n'
    '\n'
    '    def save_startup_geodetic_settings(self, settings: dict[str, object]) -> None:\n'
    '        path = self.startup_geodetic_settings_path()\n'
    '        path.parent.mkdir(parents=True, exist_ok=True)\n'
    '        payload = dict(settings)\n'
    '        payload["saved"] = datetime.now().isoformat(timespec="seconds")\n'
    '        payload["project"] = str(self.project_folder)\n'
    '        path.write_text(json.dumps(payload, indent=2), encoding="utf-8")\n'
    '\n'
    '    def apply_startup_geodetic_settings(self, settings: dict[str, object], save: bool) -> None:\n'
    '        crs = str(settings.get("crs", self.crs_box.currentText()))\n'
    '        index = self.crs_box.findText(crs)\n'
    '        if index >= 0:\n'
    '            self.crs_box.setCurrentIndex(index)\n'
    '        self.ktd_file_path = str(settings.get("ktd_path", "")).strip()\n'
    '        self.use_rtk_tide_method = bool(settings.get("use_rtk_tide", True))\n'
    '        self.startup_geodetic_settings = dict(settings)\n'
    '        if save:\n'
    '            self.save_active_ktd_reference()\n'
    '            self.save_startup_geodetic_settings(settings)\n'
    '        self.refresh_project_label()\n'
    '        self.log_event(\n'
    '            "Startup geodetic setup confirmed: "\n'
    '            f"{crs}; KTD={Path(self.ktd_file_path).name if self.ktd_file_path else \'not selected\'}; "\n'
    '            f"RTK tide={\'on\' if self.use_rtk_tide_method else \'off\'}."\n'
    '        )\n'
    '\n'
    '    def confirm_startup_geodetic_setup(self) -> None:\n'
    '        settings = self.load_startup_geodetic_settings()\n'
    '        dialog = QDialog(self)\n'
