    '        if crs_index >= 0:\n'
    '            crs_box.setCurrentIndex(crs_index)\n'
    '        else:\n'
    '            crs_box.setCurrentText(str(settings.get("crs", self.crs_box.currentText())))\n'
    '        source_box = QComboBox()\n'
    '        source_box.addItems(STARTUP_SOURCE_DATUM_OPTIONS)\n'
    '        source_box.setEditable(True)\n'
    '        source_box.setCurrentText(str(settings.get("source_datum", "WGS84 / GNSS")))\n'
    '        target_box = QComboBox()\n'
