    '        projection_box.addItems(STARTUP_PROJECTION_OPTIONS)\n'
    '        projection_box.setEditable(True)\n'
    '        projection_box.setCurrentText(str(settings.get("projection", "UTM Zone 42N")))\n'
    '        vertical_box = QComboBox()\n'
    '        vertical_box.addItems(STARTUP_VERTICAL_REFERENCE_OPTIONS)\n'
    '        vertical_box.setEditable(True)\n'
    '        vertical_box.setCurrentText(str(settings.get("vertical_reference", "RTK tide using active KTD")))\n'
    '        use_rtk_check = QCheckBox("Use selected KTD for realtime and post-processing RTK tide")\n'
    '        use_rtk_check.setChecked(bool(settings.get("use_rtk_tide", False)))\n'
    "        # Restore the user's project default; Browse can select any supported KTD.\n"
    '        ktd_edit = QLineEdit(str(settings.get("ktd_path", "")))\n'
    '        browse_btn = QPushButton("Browse KTD")\n'
    '        clear_btn = QPushButton("Clear")\n'
    '        ktd_row = QHBoxLayout()\n'
    '        ktd_row.addWidget(ktd_edit, 1)\n'
    '        ktd_row.addWidget(browse_btn)\n'
    '        ktd_row.addWidget(clear_btn)\n'
    '        form.addRow("Project CRS", crs_box)\n'
    '        form.addRow("Source datum", source_box)\n'
    '        form.addRow("Target datum", target_box)\n'
    '        form.addRow("Projection", projection_box)\n'
    '        form.addRow("Vertical reference", vertical_box)\n'
    '        form.addRow("Default KTD file", ktd_row)\n'
    '        form.addRow("", use_rtk_check)\n'
    '        layout.addLayout(form)\n'
    '\n'
    '        status = QLabel()\n'
