    '        buttons.addStretch(1)\n'
    '        buttons.addWidget(save_btn)\n'
    '        buttons.addWidget(continue_btn)\n'
    '        buttons.addWidget(cancel_btn)\n'
    '        layout.addLayout(buttons)\n'
    '\n'
    '        def update_status() -> None:\n'
    '            path_text = ktd_edit.text().strip()\n'
    '            if use_rtk_check.isChecked() and not path_text:\n'
    '                status.setText("Warning: RTK tide is enabled but no KTD file is selected. Browse for a KTD file or disable RTK tide to continue.")\n'
    '            elif path_text and not Path(path_text).exists():\n'
    '                status.setText("Warning: selected KTD path does not exist. Please browse again or clear it.")\n'
    '            else:\n'
    '                status.setText("Ready. Press Save and Continue to store these defaults, or Continue This Time to use them for this run only.")\n'
    '\n'
    '        def collect_settings() -> dict[str, object]:\n'
    '            return {\n'
    '                "crs": crs_box.currentText(),\n'
    '                "source_datum": source_box.currentText().strip(),\n'
    '                "target_datum": target_box.currentText().strip(),\n'
    '                "projection": projection_box.currentText().strip(),\n'
    '                "vertical_reference": vertical_box.currentText().strip(),\n'
    '                "ktd_path": ktd_edit.text().strip(),\n'
    '                "use_rtk_tide": use_rtk_check.isChecked(),\n'
    '            }\n'
    '\n'
    '        def browse_ktd() -> None:\n'
    '            name, _ = QFileDialog.getOpenFileName(dialog, "Select default startup KTD file", str(Path.home() / "Desktop"), "KTD files (*.ktd *.KTD *.hpktd *.ktdp);;All files (*.*)")\n'
    '            if name:\n'
    '                ktd_edit.setText(name)\n'
    '                use_rtk_check.setChecked(True)\n'
    '                update_status()\n'
    '\n'
    '        def validate_selection() -> bool:\n'
    '            path_text = ktd_edit.text().strip()\n'
    '            if not path_text:\n'
    '                if use_rtk_check.isChecked():\n'
    '                    QMessageBox.warning(dialog, "Select KTD", "Select a KTD file or disable RTK tide.")\n'
    '                    return False\n'
    '                return True\n'
    '            try:\n'
    '                path = Path(path_text).expanduser().resolve()\n'
    '                if not path.is_file():\n'
    '                    raise ValueError("The selected file does not exist.")\n'
    '                if path.suffix.lower() not in {".ktd", ".hpktd", ".ktdp"}:\n'
    '                    raise ValueError("Select a .ktd, .hpktd, or .ktdp file.")\n'
    '                if not load_ktd_shapes(path, include_nodata=False):\n'
    '                    raise ValueError("The selected KTD contains no usable data.")\n'
    '                ktd_edit.setText(str(path))\n'
    '                return True\n'
    '            except Exception as exc:\n'
    '                QMessageBox.warning(dialog, "Invalid KTD", str(exc))\n'
    '                return False\n'
    '\n'
    '        def accept_saved() -> None:\n'
    '            if not validate_selection():\n'
    '                return\n'
    '            self.apply_startup_geodetic_settings(collect_settings(), save=True)\n'
    '            dialog.accept()\n'
    '\n'
    '        def accept_once() -> None:\n'
    '            if not validate_selection():\n'
    '                return\n'
    '            self.apply_startup_geodetic_settings(collect_settings(), save=False)\n'
    '            dialog.accept()\n'
    '\n'
    '        browse_btn.clicked.connect(browse_ktd)\n'
    '        clear_btn.clicked.connect(lambda: (ktd_edit.clear(), use_rtk_check.setChecked(False), update_status()))\n'
    '        use_rtk_check.stateChanged.connect(update_status)\n'
    '        ktd_edit.textChanged.connect(update_status)\n'
    '        save_btn.clicked.connect(accept_saved)\n'
    '        continue_btn.clicked.connect(accept_once)\n'
    '        cancel_btn.clicked.connect(dialog.reject)\n'
    '        update_status()\n'
    '\n'
    '        if dialog.exec() == QDialog.DialogCode.Accepted:\n'
    '            self.autoload_project_layers()\n'
    '        else:\n'
    '            self.log_event("Startup geodetic confirmation cancelled by user.")\n'
    '            self.close()\n'
    '\n'
    '    def load_active_ktd_reference(self) -> None:\n'
    '        ref = self.active_ktd_reference_path()\n'
    '        if not ref.exists():\n'
    '            return\n'
    '        try:\n'
    '            lines = [line.strip() for line in ref.read_text(encoding="utf-8", errors="replace").splitlines() if line.strip()]\n'
    '            if lines:\n'
    '                self.ktd_file_path = lines[0]\n'
    '            if len(lines) > 1:\n'
    '                self.use_rtk_tide_method = lines[1].split("=", 1)[-1].strip().lower() not in {"0", "false", "no", "off"}\n'
    '        except Exception:\n'
    '            return\n'
    '\n'
    '    def save_active_ktd_reference(self) -> None:\n'
    '        ref = self.active_ktd_reference_path()\n'
    '        ref.parent.mkdir(parents=True, exist_ok=True)\n'
    '        ref.write_text(f"{self.ktd_file_path}\\nuse_rtk_tide={int(self.use_rtk_tide_method)}\\n", encoding="utf-8")\n'
    '\n'
    '    def background_state_path(self) -> Path:\n'
