    '\n'
    '    def default_dxf_source_names(self) -> set[str]:\n'
    '        return {\n'
    '            "river banks updated 19 Mar 2018.dxf",\n'
    '            "Channel with chainage.dxf",\n'
    '            "Complete c.l.RPDK to attock 19 Mar 2018.dxf",\n'
    '            "river_banks_default.hpdxf",\n'
    '            "channel_chainage_default.hpdxf",\n'
    '            "centerline_default.hpdxf",\n'
    '        }\n'
    '\n'
    '    def embedded_default_dxf_sources(self) -> list[Path]:\n'
    '        embedded_paths = [\n'
    '            path\n'
    '            for path in (ensure_embedded_protected_file(name) for name in EMBEDDED_PROTECTED_FILES)\n'
    '            if path is not None and path.suffix.lower() == ".hpdxf"\n'
    '        ]\n'
    '        resource_paths = [\n'
    '            app_resource_path("river_banks_default.hpdxf"),\n'
    '            app_resource_path("channel_chainage_default.hpdxf"),\n'
    '            app_resource_path("centerline_default.hpdxf"),\n'
    '        ]\n'
    '        return [path for path in embedded_paths + resource_paths if path.exists()]\n'
    '\n'
    '    def default_background_sources(self) -> list[Path]:\n'
    '        cad = Path.home() / "Desktop" / "CAD"\n'
    '        names = [\n'
    '            "river banks updated 19 Mar 2018.dxf",\n'
    '            "Channel with chainage.dxf",\n'
    '            "Complete c.l.RPDK to attock 19 Mar 2018.dxf",\n'
    '        ]\n'
    '        paths = self.embedded_default_dxf_sources()\n'
    '        if not paths:\n'
    '            paths.extend([cad / name for name in names])\n'
    '        if self.ktd_file_path:\n'
    '            paths.append(Path(self.ktd_file_path))\n'
    '        return [path for path in paths if path.exists()]\n'
    '\n'
    '    def project_copy_for_background(self, source: Path) -> Path:\n'
    '        if source.suffix.lower() == ".hpdxf":\n'
    '            return source\n'
    '        target_folder = self.project_folder / ("KTD" if source.suffix.lower() in {".ktd", ".ktdp", ".hpktd"} else "CAD")\n'
    '        target_folder.mkdir(parents=True, exist_ok=True)\n'
    '        target = target_folder / source.name\n'
    '        try:\n'
    '            if source.resolve() == target.resolve():\n'
    '                return target\n'
    '        except Exception:\n'
    '            pass\n'
    '        try:\n'
    '            if not target.exists() or source.stat().st_mtime > target.stat().st_mtime or source.stat().st_size != target.stat().st_size:\n'
    '                shutil.copy2(source, target)\n'
    '        except Exception:\n'
    '            if source.exists() and not target.exists():\n'
    '                shutil.copy2(source, target)\n'
    '        return target\n'
    '\n'
    '    def save_background_state(self) -> None:\n'
    '        if self.suppress_background_state_save:\n'
    '            return\n'
    '        state_path = self.background_state_path()\n'
    '        state_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '        payload = {\n'
    '            "saved": datetime.now().isoformat(timespec="seconds"),\n'
    '            "project": str(self.project_folder),\n'
    '            "layers": [\n'
    '                {"name": layer.name, "path": str(layer.path or ""), "visible": bool(layer.visible), "cad_order": getattr(layer, "cad_order", []), "cad_visibility": getattr(layer, "cad_visibility", {})}\n'
    '                for layer in self.layers\n'
    '                if layer.path is not None and not layer.hidden and not layer.protected\n'
    '            ],\n'
    '        }\n'
    '        state_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")\n'
    '\n'
    '    def autoload_project_layers(self) -> None:\n'
    '        state_path = self.background_state_path()\n'
    '        layer_specs: list[dict[str, object]] = []\n'
    '        if state_path.exists():\n'
    '            try:\n'
    '                payload = json.loads(state_path.read_text(encoding="utf-8", errors="replace"))\n'
    '                layer_specs = [dict(item) for item in payload.get("layers", []) if isinstance(item, dict)]\n'
    '            except Exception as exc:\n'
    '                self.log_event(f"Could not read background state: {exc}")\n'
    '        embedded_default_sources = self.embedded_default_dxf_sources()\n'
    '        if embedded_default_sources:\n'
    '            default_names = self.default_dxf_source_names()\n'
    '            layer_specs = [\n'
    '                spec\n'
    '                for spec in layer_specs\n'
    '                if Path(str(spec.get("path", ""))).name not in default_names\n'
    '                and str(spec.get("name", "")) not in default_names\n'
    '            ]\n'
    '            existing = {Path(str(spec.get("path", ""))).name for spec in layer_specs}\n'
    '            for source in embedded_default_sources:\n'
    '                if source.name not in existing:\n'
    '                    layer_specs.append({"name": source.name, "path": str(source), "visible": True, "hidden": True, "protected": True})\n'
    '        if not layer_specs:\n'
    '            for source in self.default_background_sources():\n'
    '                project_path = self.project_copy_for_background(source)\n'
    '                is_protected_dxf = project_path.suffix.lower() == ".hpdxf"\n'
    '                layer_specs.append({"name": project_path.name, "path": str(project_path), "visible": True, "hidden": is_protected_dxf, "protected": is_protected_dxf})\n'
    '            if layer_specs:\n'
    '                state_path.parent.mkdir(parents=True, exist_ok=True)\n'
    '                visible_specs = [spec for spec in layer_specs if not bool(spec.get("hidden", False)) and not bool(spec.get("protected", False))]\n'
    '                state_path.write_text(json.dumps({"saved": datetime.now().isoformat(timespec="seconds"), "project": str(self.project_folder), "layers": visible_specs}, indent=2), encoding="utf-8")\n'
    '\n'
    '        self.suppress_background_state_save = True\n'
    '        loaded = 0\n'
    '        try:\n'
    '            for spec in layer_specs:\n'
    '                path = Path(str(spec.get("path", "")))\n'
    '                if path.suffix.lower() in {".ktd", ".ktdp", ".hpktd"}:\n'
    "                    # KTD startup loading follows only the user's selected default.\n"
    '                    continue\n'
    '                if not path.exists() or any(layer.path == path for layer in self.layers):\n'
    '                    continue\n'
    '                try:\n'
    '                    layer = Layer(\n'
    '                        str(spec.get("name") or path.name),\n'
    '                        path,\n'
    '                        load_shapes(path),\n'
    '                        visible=bool(spec.get("visible", True)),\n'
    '                        hidden=bool(spec.get("hidden", False)) or path.suffix.lower() == ".hpdxf",\n'
    '                        protected=bool(spec.get("protected", False)) or path.suffix.lower() == ".hpdxf",\n'
    '                    )\n'
    '                    layer.cad_order = list(spec.get("cad_order", []))\n'
    '                    layer.cad_visibility = dict(spec.get("cad_visibility", {}))\n'
    '                    self.add_layer(layer)\n'
    '                    if not layer.visible and self.layer_list.count() > 0:\n'
    '                        self.layer_list.item(self.layer_list.count() - 1).setCheckState(Qt.CheckState.Unchecked)\n'
    '                    loaded += 1\n'
    '                except Exception as exc:\n'
    '                    self.log_event(f"Could not autoload background {path.name}: {exc}")\n'
    '        finally:\n'
    '            self.suppress_background_state_save = False\n'
    '        self.autoload_active_ktd_layer()\n'
    '        if loaded:\n'
    '            self.fit_extents()\n'
    '            self.log_event(f"Autoloaded {loaded} project background layer(s).")\n'
    '\n'
    '    def autoload_active_ktd_layer(self) -> None:\n'
