    '\n'
    '        def collect_mbes_setup() -> dict[str, str]:\n'
    '            for key, edit in fields.items():\n'
    '                self.mbes_setup[key] = edit.text().strip()\n'
    '            return {key: str(value) for key, value in self.mbes_setup.items()}\n'
    '\n'
    '        def validate_mbes_setup() -> list[str]:\n'
    '            setup = collect_mbes_setup()\n'
    '            messages: list[str] = []\n'
    '            for key, box in required_checks.items():\n'
    '                if box.isChecked() and not setup.get(key, "").strip():\n'
    '                    messages.append(f"FAIL: required {box.text()} field is empty.")\n'
    '            ports: list[int] = []\n'
    '            for key in ("sonar_udp", "gnss_udp", "motion_udp", "heading_udp"):\n'
    '                text = setup.get(key, "").strip()\n'
    '                value = int(parse_float(text) or 0)\n'
    '                if value < 1 or value > 65535:\n'
    '                    messages.append(f"FAIL: {key} must be a UDP port from 1 to 65535.")\n'
    '                    continue\n'
    '                ports.append(value)\n'
    '                sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n'
    '                try:\n'
    '                    sock.bind(("0.0.0.0", value))\n'
    '                    messages.append(f"PASS: UDP {value} can be opened.")\n'
    '                except OSError as exc:\n'
    '                    messages.append(f"WARN: UDP {value} could not be opened now: {exc}")\n'
    '                finally:\n'
    '                    sock.close()\n'
