    '    def start_device_readers(self) -> None:\n'
    '        self.stop_device_readers(join_timeout=0.2)\n'
    '        serial_module = get_serial_module()\n'
    '        if serial_module is None:\n'
    '            self.log_event("pyserial is not installed; RAW container opened without live serial device data.")\n'
    '            return\n'
    '        self.device_stop.clear()\n'
    '        self.device_thread_states.clear()\n'
    '        configs = [("GNSS", self.gnss_port, self.gnss_baud), ("SBES", self.sbes_port, self.sbes_baud)]\n'
    '        if self.shared_gnss_sbes_port and self.gnss_port and self.gnss_port == self.sbes_port:\n'
    '            configs = [("GNSS", self.gnss_port, self.gnss_baud)]\n'
    '        for name, port, baud in configs:\n'
    '            if not port:\n'
    '                continue\n'
    '            self.device_thread_states[name] = PortState.CONNECTING\n'
    '            thread = threading.Thread(target=self.serial_reader_worker, args=(name, port, baud), daemon=True, name=f"HYDROGEOMATICS-{name}-{port}")\n'
    '            thread.start()\n'
    '            self.device_threads.append(thread)\n'
    '            self.log_event(f"Started {name} reader on {port} @ {baud}")\n'
    '        if not self.device_threads:\n'
    '            self.log_event("No GNSS/SBES serial ports selected. Use Settings to choose COM ports.")\n'
    '        self._update_connection_status_display()\n'
    '\n'
    '    def stop_device_readers(self, join_timeout: float = 1.0) -> None:\n'
    '        self.device_stop.set()\n'
    '        for thread in list(self.device_threads):\n'
    '            thread.join(timeout=join_timeout)\n'
    '        self.device_threads.clear()\n'
    '        self.device_thread_states.clear()\n'
    '        self._update_connection_status_display()\n'
    '\n'
    '    def serial_reader_worker(self, name: str, port: str, baud: int) -> None:\n'
    '        serial_module = get_serial_module()\n'
    '        if serial_module is None:\n'
    '            return\n'
    '        reconnect_delay = 0.5\n'
    '        max_reconnect_delay = 8.0\n'
    '        consecutive_errors = 0\n'
    '\n'
    '        while not self.device_stop.is_set():\n'
    '            # Check if port is physically present before trying to open\n'
    '            if not self.port_monitor.is_port_available(port):\n'
    '                self.device_thread_states[name] = PortState.DISCONNECTED\n'
    '                self.device_queue.put((name, datetime.now().strftime("%H:%M:%S.%f")[:-3],\n'
    '                                      f"WAIT {port}: port not detected, waiting for reconnection…"))\n'
    '                # Wait until port reappears or stop is signalled\n'
    '                for _ in range(int(max_reconnect_delay / 0.5)):\n'
    '                    if self.device_stop.is_set():\n'
    '                        return\n'
    '                    if self.port_monitor.is_port_available(port):\n'
    '                        break\n'
    '                    self.device_stop.wait(0.5)\n'
    '                continue\n'
    '\n'
    '            ser = None\n'
    '            try:\n'
    '                self.device_thread_states[name] = PortState.CONNECTING\n'
    '                ser = serial_module.Serial(port=port, baudrate=int(baud), timeout=0.3)\n'
    '                self.device_thread_states[name] = PortState.CONNECTED\n'
    '                self.port_monitor.set_port_state(port, PortState.CONNECTED)\n'
    '                consecutive_errors = 0\n'
    '                reconnect_delay = 0.5\n'
    '                self.device_queue.put((name, datetime.now().strftime("%H:%M:%S.%f")[:-3],\n'
    '                                      f"CONNECTED {port} @ {baud}"))\n'
    '\n'
    '                while not self.device_stop.is_set():\n'
    '                    try:\n'
    '                        raw = ser.readline()\n'
    '                    except Exception as read_exc:\n'
    '                        self.device_queue.put((name, datetime.now().strftime("%H:%M:%S.%f")[:-3],\n'
    '                                              f"READ_ERROR {port}: {read_exc}"))\n'
    '                        break  # exit inner loop to trigger reconnect\n'
    '                    if not raw:\n'
    '                        continue\n'
    '                    text = raw.decode("ascii", errors="replace").strip()\n'
    '                    if text:\n'
    '                        self.device_queue.put((name, datetime.now().strftime("%H:%M:%S.%f")[:-3], text))\n'
    '\n'
    '            except Exception as exc:\n'
    '                consecutive_errors += 1\n'
    '                self.device_thread_states[name] = PortState.ERROR\n'
    '                self.port_monitor.set_port_state(port, PortState.ERROR)\n'
    '                self.device_queue.put((name, datetime.now().strftime("%H:%M:%S.%f")[:-3],\n'
    '                                      f"ERROR {port}: {exc} (attempt {consecutive_errors})"))\n'
    '            finally:\n'
    '                if ser is not None:\n'
    '                    try:\n'
    '                        ser.close()\n'
    '                    except Exception:\n'
    '                        pass\n'
    '\n'
    '            if self.device_stop.is_set():\n'
    '                return\n'
    '\n'
    '            # Backoff before reconnect\n'
    '            self.device_thread_states[name] = PortState.DISCONNECTED\n'
    '            self.port_monitor.set_port_state(port, PortState.DISCONNECTED)\n'
    '            self.device_queue.put((name, datetime.now().strftime("%H:%M:%S.%f")[:-3],\n'
    '                                  f"RECONNECT {port}: retrying in {reconnect_delay:.1f}s…"))\n'
    '            self.device_stop.wait(reconnect_delay)\n'
    '            reconnect_delay = min(reconnect_delay * 1.5, max_reconnect_delay)\n'
    '\n'
    '        self.device_thread_states[name] = PortState.UNAVAILABLE\n'
    '\n'
    '    def _periodic_port_scan(self) -> None:\n'
    '        """Called by port_scan_timer every 2 seconds to detect port changes."""\n'
    '        appeared, disappeared = self.port_monitor.scan()\n'
    '        if appeared:\n'
    '            self.log_event(f"Serial port(s) detected: {\', \'.join(appeared)}")\n'
    '        if disappeared:\n'
    '            self.log_event(f"Serial port(s) removed: {\', \'.join(disappeared)}")\n'
    '        if appeared or disappeared:\n'
    '            self._update_connection_status_display()\n'
    '\n'
    '    def _on_port_state_change(self, port: str, new_state: str, old_state: str) -> None:\n'
    '        """Callback from SerialPortMonitor when a port\'s state changes."""\n'
    '        pass  # state is tracked; UI update happens in _periodic_port_scan and process_device_queue\n'
    '\n'
    '    def _update_connection_status_display(self) -> None:\n'
    '        """Update the GNSS/SBES status labels in the header bar."""\n'
    '        for name, port_attr, label in [\n'
    '            ("GNSS", "gnss_port", self.gnss_status_label),\n'
    '            ("SBES", "sbes_port", self.sbes_status_label),\n'
    '        ]:\n'
    '            port = getattr(self, port_attr, "")\n'
    '            if not port:\n'
    '                label.setText(f"{name}: not configured")\n'
    '                label.setStyleSheet("font-size:11px; padding:3px 10px; border-radius:3px; background:#f3f4f6; color:#6b7280;")\n'
    '                continue\n'
    '\n'
    '            # Determine effective state\n'
    '            thread_state = self.device_thread_states.get(name)\n'
    '            if thread_state:\n'
    '                state = thread_state\n'
    '            elif self.port_monitor.is_port_available(port):\n'
    '                state = PortState.AVAILABLE\n'
    '            else:\n'
    '                state = PortState.UNAVAILABLE\n'
    '\n'
    '            color = PortState.color(state)\n'
    '            state_text = PortState.label(state)\n'
    '            label.setText(f"{name}: {port} · {state_text}")\n'
    '\n'
    '            if state == PortState.CONNECTED:\n'
    '                label.setStyleSheet(f"font-size:11px; font-weight:600; padding:3px 10px; border-radius:3px; background:#dcfce7; color:{color};")\n'
    '            elif state in (PortState.DISCONNECTED, PortState.ERROR):\n'
    '                label.setStyleSheet(f"font-size:11px; font-weight:600; padding:3px 10px; border-radius:3px; background:#fef2f2; color:{color};")\n'
    '            elif state == PortState.CONNECTING:\n'
    '                label.setStyleSheet(f"font-size:11px; padding:3px 10px; border-radius:3px; background:#fefce8; color:{color};")\n'
    '            else:\n'
    '                label.setStyleSheet(f"font-size:11px; padding:3px 10px; border-radius:3px; background:#f3f4f6; color:{color};")\n'
    '\n'
    '    def process_device_queue(self) -> None:\n'
    '        processed = 0\n'
    '        status_changed = False\n'
    '        while processed < 2000:\n'
    '            try:\n'
    '                name, timestamp, text = self.device_queue.get_nowait()\n'
    '            except queue.Empty:\n'
    '                break\n'
    '            processed += 1\n'
    '            # Detect connection lifecycle messages (not raw NMEA data)\n'
    '            upper_text = text.upper()\n'
    '            is_status_msg = upper_text.startswith(("ERROR ", "CONNECTED ", "RECONNECT ", "WAIT ", "READ_ERROR "))\n'
    '            if is_status_msg:\n'
    '                status_changed = True\n'
    '                self.log_event(f"{name}: {text}")\n'
    '                for editor in list(self.monitor_windows):\n'
    '                    editor.appendPlainText(f"{timestamp} {name}: {text}")\n'
    "                continue  # don't write status messages to RAW log or update sentence values\n"
    '\n'
    '            self.latest_values[name] = text\n'
    '            if self.log_file_handle is not None and self.logging_active:\n'
    '                safe_text = text.replace("\\r", " ").replace("\\n", " ")\n'
    '                self.log_file_handle.write(f"{name},{timestamp},{safe_text}\\n")\n'
    '                self.raw_record_count += 1\n'
    '                now = time.monotonic()\n'
    '                if now - self.last_flush_time >= 1.0:\n'
    '                    self.log_file_handle.flush()\n'
    '                    self.last_flush_time = now\n'
    '            # Archive first: processing preferences must never suppress raw data.\n'
    '            self.update_latest_from_sentence(name, text)\n'
    '            if self.shared_gnss_sbes_port:\n'
    '                self.update_latest_from_sentence("SBES" if name == "GNSS" else "GNSS", text)\n'
    '            for editor in list(self.monitor_windows):\n'
    '                editor.appendPlainText(f"{timestamp} {name}: {text}")\n'
    '        if self.log_file_handle is not None and processed:\n'
    '            self.log_file_handle.flush()\n'
    '        if status_changed:\n'
    '            self._update_connection_status_display()\n'
    '\n'
    '    def _is_sentence_enabled(self, text: str) -> bool:\n'
    '        """Check if a GNSS/NMEA sentence is enabled in the Advanced GNSS Settings."""\n'
    '        header = text.strip().upper().split("*", 1)[0].split(";", 1)[0].split(",")\n'
    '        token = header[0].lstrip("$!#")\n'
    '        key = token[-3:] if len(token) == 5 and not token.startswith("P") else token\n'
    '        if token == "PTNL" and len(header) > 1:\n'
    '            key = token + "," + header[1]\n'
    '        return self.enabled_nmea_sentences.get(key, True)\n'
    '\n'
    '    def update_latest_from_sentence(self, name: str, text: str) -> None:\n'
    '        upper = text.upper()\n'
    '        if name == "GNSS" and ("GGA" in upper or "RMC" in upper or "GLL" in upper or "GNS" in upper or "BESTPOS" in upper):\n'
    '            if not self._is_sentence_enabled(text):\n'
    '                return\n'
    '            self.latest_values["POSITION"] = text\n'
    '            # Extract accuracy from GST/BESTPOS for accuracy monitor\n'
    '            self._extract_accuracy_from_sentence(text)\n'
    '            lat_lon = self.parse_gnss_position(text)\n'
    '            if lat_lon:\n'
    '                lat, lon = lat_lon\n'
    '                self.current_lat_lon = (lat, lon)\n'
    '                self.latest_values["LAT"] = f"{lat:.8f}"\n'
    '                self.latest_values["LON"] = f"{lon:.8f}"\n'
    '                xy = ll_to_utm42(lat, lon)\n'
    '                if xy:\n'
    '                    self.current_xy = xy\n'
    '                    self.latest_values["EASTING"] = f"{xy[0]:.3f}"\n'
    '                    self.latest_values["NORTHING"] = f"{xy[1]:.3f}"\n'
    '                    self.live_track_points.append(xy)\n'
    '                    if len(self.live_track_points) > 20000:\n'
    '                        self.live_track_points = self.live_track_points[-20000:]\n'
    '                    self.refresh_live_survey_layer()\n'
    '        if name == "GNSS" and "GST" in upper:\n'
    '            if self._is_sentence_enabled(text):\n'
    '                self._extract_accuracy_from_sentence(text)\n'
    '        if name == "SBES":\n'
    '            depth_value = self.extract_depth_value(text)\n'
    '            if depth_value is not None:\n'
    '                self.latest_values["DEPTH"] = f"{depth_value:.3f} m"\n'
    '                if self.current_xy is not None:\n'
    '                    x, y = self.current_xy\n'
    '                    self.live_soundings.append((x, y, float(depth_value)))\n'
    '                    if len(self.live_soundings) > 20000:\n'
    '                        self.live_soundings = self.live_soundings[-20000:]\n'
    '                    self.refresh_live_survey_layer()\n'
    '\n'
    '    def _extract_accuracy_from_sentence(self, text: str) -> None:\n'
    '        """Extract X, Y, Z accuracy from GST or BESTPOSA sentences."""\n'
    '        upper = text.upper().strip()\n'
    '        try:\n'
    '            if "GST" in upper and self.enabled_nmea_sentences.get("GST", True):\n'
    '                # $xxGST,time,rms,smaj,smin,orient,lat_err,lon_err,alt_err*cs\n'
    '                body = text.split("*")[0] if "*" in text else text\n'
    '                parts = body.split(",")\n'
    '                if len(parts) >= 8:\n'
    '                    lat_sigma = parse_float(parts[6])\n'
    '                    lon_sigma = parse_float(parts[7])\n'
    '                    alt_sigma = parse_float(parts[8]) if len(parts) > 8 else None\n'
    '                    if lat_sigma is not None:\n'
    '                        self.latest_accuracy["y"] = float(lat_sigma)\n'
    '                    if lon_sigma is not None:\n'
    '                        self.latest_accuracy["x"] = float(lon_sigma)\n'
    '                    if alt_sigma is not None:\n'
    '                        self.latest_accuracy["z"] = float(alt_sigma)\n'
    '            elif "BESTPOS" in upper:\n'
    '                body = text.split("*")[0] if "*" in text else text\n'
    '                if ";" in body:\n'
    '                    data = body.split(";", 1)[1]\n'
    '                    fields = [p.strip() for p in data.split(",")]\n'
    '                    # BESTPOSA fields: ..., lat_sigma(idx 7), lon_sigma(idx 8), hgt_sigma(idx 9)\n'
    '                    if len(fields) >= 10:\n'
    '                        lat_sigma = parse_float(fields[7])\n'
    '                        lon_sigma = parse_float(fields[8])\n'
    '                        hgt_sigma = parse_float(fields[9])\n'
    '                        if lat_sigma is not None:\n'
    '                            self.latest_accuracy["y"] = float(lat_sigma)\n'
    '                        if lon_sigma is not None:\n'
    '                            self.latest_accuracy["x"] = float(lon_sigma)\n'
    '                        if hgt_sigma is not None:\n'
    '                            self.latest_accuracy["z"] = float(hgt_sigma)\n'
    '        except Exception:\n'
    '            pass\n'
    '\n'
    '    def show_accuracy_monitor(self) -> None:\n'
    '        """Open (or bring to front) the Accuracy Monitor showing X, Y, Z accuracy values."""\n'
    '        if self.accuracy_monitor_window is not None:\n'
    '            try:\n'
    '                if self.accuracy_monitor_window.isVisible():\n'
    '                    self.accuracy_monitor_window.raise_()\n'
    '                    return\n'
    '            except Exception:\n'
    '                pass\n'
    '\n'
    '        win = QMainWindow(self)\n'
    '        win.setWindowTitle("Accuracy Monitor")\n'
    '        win.resize(340, 220)\n'
    '        root = QWidget()\n'
    '        layout = QVBoxLayout(root)\n'
    '        layout.addWidget(QLabel("GNSS Position Accuracy"))\n'
    '        x_label = QLabel("X (Easting) σ:  —")\n'
    '        y_label = QLabel("Y (Northing) σ:  —")\n'
    '        z_label = QLabel("Z (Height) σ:  —")\n'
    '        for lbl in (x_label, y_label, z_label):\n'
    '            lbl.setFont(QFont("Consolas", 13, QFont.Weight.Bold))\n'
    '            lbl.setStyleSheet("padding: 6px; border: 1px solid #d1d5db; border-radius: 4px; background: #f9fafb;")\n'
    '            layout.addWidget(lbl)\n'
    '        status = QLabel("Waiting for accuracy data from GNSS (GST / BESTPOSA)…")\n'
    '        status.setWordWrap(True)\n'
    '        layout.addWidget(status)\n'
    '        win.setCentralWidget(root)\n'
    '\n'
    '        def update_accuracy() -> None:\n'
    '            x = self.latest_accuracy.get("x")\n'
    '            y = self.latest_accuracy.get("y")\n'
    '            z = self.latest_accuracy.get("z")\n'
    '            x_label.setText(f"X (Easting) σ:  {x:.4f} m" if x is not None else "X (Easting) σ:  —")\n'
    '            y_label.setText(f"Y (Northing) σ:  {y:.4f} m" if y is not None else "Y (Northing) σ:  —")\n'
    '            z_label.setText(f"Z (Height) σ:  {z:.4f} m" if z is not None else "Z (Height) σ:  —")\n'
    '            any_value = x is not None or y is not None or z is not None\n'
    '            if any_value:\n'
    '                status.setText("Accuracy values are live from the GNSS stream.")\n'
    '                # Color code: green if < 0.05m, yellow < 0.1, red otherwise\n'
    '                for val, lbl in [(x, x_label), (y, y_label), (z, z_label)]:\n'
    '                    if val is not None:\n'
    '                        color = "#166534" if val < 0.05 else "#92400e" if val < 0.10 else "#991b1b"\n'
    '                        lbl.setStyleSheet(f"padding: 6px; border: 1px solid #d1d5db; border-radius: 4px; background: #f9fafb; color: {color};")\n'
    '\n'
    '        timer = QTimer(win)\n'
    '        timer.timeout.connect(update_accuracy)\n'
    '        timer.start(500)\n'
    "        win.destroyed.connect(lambda _obj=None: setattr(self, 'accuracy_monitor_window', None))\n"
    '        self.accuracy_monitor_window = win\n'
    '        win.show()\n'
    '\n'
    '    def extract_depth(self, text: str) -> str:\n'
    '        value = self.extract_depth_value(text)\n'
    '        return f"{value:.3f} m" if value is not None else ""\n'
    '\n'
    '    def extract_depth_value(self, text: str) -> Optional[float]:\n'
    '        upper = text.upper().strip()\n'
    '        parts = upper.split(",")\n'
    '        if upper.startswith(("$SDDPT", "$INDPT", "$IIDPT", "$YXDPT")) and len(parts) > 1:\n'
    '            value = parse_float(parts[1])\n'
    '            return float(value) if value is not None else None\n'
    '        if upper.startswith(("$SDDBT", "$INDBT", "$IIDBT")) and len(parts) > 3:\n'
    '            value = parse_float(parts[3])\n'
    '            return float(value) if value is not None else None\n'
    '        value = parse_float(text)\n'
    '        return float(value) if value is not None else None\n'
    '\n'
    '    def parse_gnss_position(self, text: str) -> Optional[tuple[float, float]]:\n'
    '        upper = text.upper()\n'
    '        if "BESTPOS" in upper:\n'
    '            bestpos_height = self.parse_bestpos_position_height(text)\n'
    '            bestpos = (bestpos_height[0], bestpos_height[1]) if bestpos_height else None\n'
    '            if bestpos:\n'
    '                return bestpos\n'
    '        return self.parse_nmea_position(text)\n'
    '\n'
    '    def parse_gnss_position_height(self, text: str) -> Optional[tuple[float, float, Optional[float]]]:\n'
    '        upper = text.upper()\n'
    '        if "BESTPOS" in upper:\n'
    '            return self.parse_bestpos_position_height(text)\n'
    '        pos = self.parse_nmea_position(text)\n'
    '        return (pos[0], pos[1], None) if pos else None\n'
    '\n'
    '    def parse_nmea_position(self, text: str) -> Optional[tuple[float, float]]:\n'
    '        body = text.strip()\n'
    '        if "*" in body:\n'
    '            body = body.split("*", 1)[0]\n'
    '        parts = body.split(",")\n'
    '        if not parts:\n'
    '            return None\n'
    '        sentence = parts[0].upper()\n'
    '        if sentence.endswith(("GGA", "GNS")) and len(parts) >= 7:\n'
    '            if sentence.endswith("GGA") and parts[6] in {"", "0"}:\n'
    '                return None\n'
    '            if sentence.endswith("GNS") and not parts[6].strip("N"):\n'
    '                return None\n'
    '            lat = self.nmea_coord_to_decimal(parts[2], parts[3])\n'
    '            lon = self.nmea_coord_to_decimal(parts[4], parts[5])\n'
    '            if lat is not None and lon is not None:\n'
    '                return lat, lon\n'
    '        if sentence.endswith("GLL") and len(parts) >= 7 and parts[6] == "A":\n'
    '            lat = self.nmea_coord_to_decimal(parts[1], parts[2])\n'
    '            lon = self.nmea_coord_to_decimal(parts[3], parts[4])\n'
    '            if lat is not None and lon is not None:\n'
    '                return lat, lon\n'
    '        if sentence.endswith("RMC") and len(parts) >= 7 and parts[2] == "A":\n'
    '            lat = self.nmea_coord_to_decimal(parts[3], parts[4])\n'
    '            lon = self.nmea_coord_to_decimal(parts[5], parts[6])\n'
    '            if lat is not None and lon is not None:\n'
    '                return lat, lon\n'
    '        return None\n'
    '\n'
    '    def parse_bestpos_position(self, text: str) -> Optional[tuple[float, float]]:\n'
    '        parsed = self.parse_bestpos_position_height(text)\n'
    '        return (parsed[0], parsed[1]) if parsed else None\n'
    '\n'
    '    def parse_bestpos_position_height(self, text: str) -> Optional[tuple[float, float, Optional[float]]]:\n'
    '        body = text.strip()\n'
    '        if not body:\n'
    '            return None\n'
    '        if "*" in body:\n'
    '            body = body.split("*", 1)[0]\n'
    '        if ";" in body:\n'
    '            data = body.split(";", 1)[1]\n'
    '            fields = [part.strip() for part in data.split(",")]\n'
    '            # NovAtel BESTPOS(A): sol status, pos type, lat, lon, height, ...\n'
    '            if len(fields) >= 4:\n'
    '                lat = parse_float(fields[2])\n'
    '                lon = parse_float(fields[3])\n'
    '                height = parse_float(fields[4]) if len(fields) >= 5 else None\n'
    '                if lat is not None and lon is not None:\n'
    '                    return float(lat), float(lon), float(height) if height is not None else None\n'
    '        fields = [part.strip() for part in body.lstrip("#").split(",")]\n'
    '        for index, field in enumerate(fields):\n'
    '            if field.upper() in {"SOL_COMPUTED", "INSUFFICIENT_OBS", "NO_CONVERGENCE"} and index + 3 < len(fields):\n'
    '                lat = parse_float(fields[index + 2])\n'
    '                lon = parse_float(fields[index + 3])\n'
    '                height = parse_float(fields[index + 4]) if index + 4 < len(fields) else None\n'
    '                if lat is not None and lon is not None:\n'
    '                    return float(lat), float(lon), float(height) if height is not None else None\n'
    '        # Fallback for simple text: BESTPOSA,lat,lon,height or BESTPOS,lat,lon,height.\n'
    '        if fields and fields[0].upper().startswith("BESTPOS") and len(fields) >= 3:\n'
    '            lat = parse_float(fields[1])\n'
    '            lon = parse_float(fields[2])\n'
    '            height = parse_float(fields[3]) if len(fields) >= 4 else None\n'
    '            if lat is not None and lon is not None and abs(float(lat)) <= 90 and abs(float(lon)) <= 180:\n'
    '                return float(lat), float(lon), float(height) if height is not None else None\n'
    '        return None\n'
    '\n'
    '    def nmea_coord_to_decimal(self, value: str, hemisphere: str) -> Optional[float]:\n'
    '        raw = parse_float(value)\n'
    '        if raw is None:\n'
    '            return None\n'
    '        degrees_part = int(raw // 100)\n'
    '        minutes = raw - degrees_part * 100\n'
    '        decimal = degrees_part + minutes / 60.0\n'
    '        if str(hemisphere).upper() in {"S", "W"}:\n'
    '            decimal *= -1.0\n'
    '        return float(decimal)\n'
    '\n'
    '    def refresh_live_survey_layer(self) -> None:\n'
    '        self.view.update_live(self.live_track_points, self.live_soundings)\n'
    '\n'
    '    def closeEvent(self, event) -> None:  # type: ignore[override]\n'
    '        if self.logging_active:\n'
    '            self.stop_logging_and_save()\n'
    '        else:\n'
    '            self.stop_device_readers(join_timeout=0.2)\n'
    '        event.accept()\n'
    '\n'
    '    def zoom_view(self, factor: float) -> None:\n'
    '        self.push_view_history()\n'
    '        self.view.zoom_by(float(factor))\n'
    '        self.update_status_from_view()\n'
    '\n'
    '    def pan_view(self, dx_fraction: float, dy_fraction: float) -> None:\n'
    '        self.push_view_history()\n'
    '        self.view.pan_fraction(float(dx_fraction), float(dy_fraction))\n'
    '        self.update_status_from_view()\n'
    '\n'
    '    def set_mode(self, mode: str) -> None:\n'
    '        self.view.set_mode(mode)\n'
    '        self.mode_label.setText(mode)\n'
    '        if mode == "Edit DXF":\n'
    '            self.status.showMessage("Edit DXF mode: click and drag a river bank/channel line vertex, then use Save Edited DXF.", 8000)\n'
    '        elif mode == "Measure":\n'
    '            self.status.showMessage("Measure mode: click and drag on the map to measure distance and bearing.", 8000)\n'
    '        else:\n'
    '            self.clear_edit_marker()\n'
    '\n'
    '    def clear_edit_marker(self) -> None:\n'
    '        self.edit_selection = None\n'
    '        if self.edit_marker is not None:\n'
    '            try:\n'
    '                self.view.removeItem(self.edit_marker)\n'
    '            except Exception:\n'
    '                pass\n'
    '            self.edit_marker = None\n'
    '\n'
    '    def edit_pick_tolerance(self) -> float:\n'
    '        rect = self.view.visible_bounds()\n'
    '        return max(5.0, min(150.0, max(rect.width(), rect.height()) / 120.0))\n'
    '\n'
    '    def select_edit_vertex(self, x: float, y: float) -> bool:\n'
    '        tolerance = self.edit_pick_tolerance()\n'
    '        best: Optional[tuple[float, Layer, Shape, int]] = None\n'
    '        for layer in self.layers:\n'
    '            if not layer.visible:\n'
    '                continue\n'
    '            for shape in layer.shapes:\n'
    '                if shape.kind != "line" or not shape.points:\n'
    '                    continue\n'
    '                for index, (px, py) in enumerate(shape.points):\n'
    '                    distance = math.hypot(float(px) - x, float(py) - y)\n'
    '                    if distance <= tolerance and (best is None or distance < best[0]):\n'
    '                        best = (distance, layer, shape, index)\n'
    '        if best is None:\n'
    '            self.status.showMessage(f"No editable DXF/line vertex within {tolerance:.1f} m.", 4000)\n'
    '            return False\n'
    '        _distance, layer, shape, index = best\n'
    '        self.edit_selection = (layer, shape, index)\n'
    '        self.show_edit_marker(float(shape.points[index][0]), float(shape.points[index][1]))\n'
    '        self.status.showMessage(f"Selected vertex {index + 1} in {layer.name}. Drag to adjust.", 6000)\n'
    '        return True\n'
    '\n'
    '    def show_edit_marker(self, x: float, y: float) -> None:\n'
    '        if self.edit_marker is None:\n'
    '            self.edit_marker = pg.ScatterPlotItem(pxMode=True, pen=pg.mkPen("#ffffff", width=2), brush=pg.mkBrush(239, 68, 68, 230), size=14)\n'
    '            self.view.addItem(self.edit_marker)\n'
    '        self.edit_marker.setData(x=[x], y=[y])\n'
    '\n'
    '    def move_selected_vertex(self, x: float, y: float) -> None:\n'
    '        if self.edit_selection is None:\n'
    '            return\n'
    '        layer, shape, index = self.edit_selection\n'
    '        if index < 0 or index >= len(shape.points):\n'
    '            return\n'
    '        old_point = shape.points[index]\n'
    '        shape.points[index] = (float(x), float(y))\n'
    '        if len(shape.points) > 2:\n'
    '            if index == 0 and old_point == shape.points[-1]:\n'
    '                shape.points[-1] = (float(x), float(y))\n'
    '            elif index == len(shape.points) - 1 and old_point == shape.points[0]:\n'
    '                shape.points[0] = (float(x), float(y))\n'
    '        self.redraw_layer(layer)\n'
    '        self.show_edit_marker(float(x), float(y))\n'
    '        self.set_coordinate_status(float(x), float(y))\n'
    '\n'
    '    def finish_edit_vertex(self) -> None:\n'
    '        if self.edit_selection is None:\n'
    '            return\n'
    '        layer, _shape, index = self.edit_selection\n'
    '        self.status.showMessage(f"Adjusted vertex {index + 1} in {layer.name}. Save Edited DXF to write changes.", 7000)\n'
    '\n'
    '    def redraw_layer(self, layer: Layer) -> None:\n'
    '        self.view.remove_layer_items(layer.group)\n'
    '        layer.group = self.view.add_shapes_layer(layer.shapes)\n'
    '\n'
    '    def line_layers(self) -> list[Layer]:\n'
    '        return [layer for layer in self.layers if any(shape.kind == "line" and len(shape.points) >= 2 for shape in layer.shapes)]\n'
    '\n'
    '    def write_line_layers_to_dxf(self, layers: list[Layer], target: Path) -> None:\n'
    '        target.parent.mkdir(parents=True, exist_ok=True)\n'
    '        ezdxf = get_ezdxf()\n'
    '        if ezdxf is None:\n'
    '            raise RuntimeError("ezdxf is required to save edited DXF files.")\n'
    '        doc = ezdxf.new("R2010")\n'
    '        msp = doc.modelspace()\n'
    '        for layer in layers:\n'
    '            layer_name = re.sub(r"[^A-Za-z0-9_ -]+", "_", layer.name)[:80] or "EDITED"\n'
    '            if layer_name not in doc.layers:\n'
    '                doc.layers.add(layer_name)\n'
    '            for shape in layer.shapes:\n'
    '                if shape.kind == "line" and len(shape.points) >= 2:\n'
    '                    msp.add_lwpolyline([(float(x), float(y)) for x, y in shape.points], dxfattribs={"layer": layer_name})\n'
    '        doc.saveas(str(target))\n'
    '\n'
    '    def show_dxf_edit_window(self) -> None:\n'
    "        existing = getattr(self, '_cad_edit_window', None)\n"
    '        if existing is not None:\n'
    '            existing.show(); existing.raise_(); existing.activateWindow()\n'
    '            return existing\n'
    '        line_layers = self.line_layers()\n'
    '        win = QMainWindow(self)\n'
    '        self._cad_edit_window = win\n'
    '        win.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)\n'
    "        win.destroyed.connect(lambda: setattr(self, '_cad_edit_window', None))\n"
    '        win.setWindowTitle("DXF On-Screen Edit Window")\n'
    '        root = QWidget()\n'
    '        layout = QVBoxLayout(root)\n'
    '        top = QHBoxLayout()\n'
    '        layer_box = QComboBox()\n'
    '        for layer in line_layers:\n'
    '            layer_box.addItem(layer.name)\n'
    '        select_btn = QPushButton("Select Vertex")\n'
    '        pan_btn = QPushButton("Pan")\n'
    '        zoom_window_btn = QPushButton("Zoom Window")\n'
    '        fit_btn = QPushButton("Fit")\n'
    '        save_btn = QPushButton("Save DXF")\n'
    '        close_btn = QPushButton("Close")\n'
    '        status = QLabel("Select a layer, then click and drag a vertex.")\n'
    '        top.addWidget(QLabel("Layer"))\n'
    '        top.addWidget(layer_box)\n'
    '        top.addWidget(select_btn)\n'
    '        top.addWidget(pan_btn)\n'
    '        top.addWidget(zoom_window_btn)\n'
    '        top.addWidget(fit_btn)\n'
    '        top.addWidget(save_btn)\n'
    '        top.addWidget(close_btn)\n'
    '        load_btn = QPushButton("Load backgrounds")\n'
    '        load_btn.clicked.connect(lambda: self.show_background_manager())\n'
    '        top.addWidget(load_btn)\n'
    '        top.addStretch(1)\n'
    '        layout.addLayout(top)\n'
    '        plot = pg.PlotWidget()\n'
    '        plot.setBackground("#ffffff")\n'
    '        plot.showGrid(x=True, y=True, alpha=0.2)\n'
    '        plot.setAspectLocked(True)\n'
    '        layout.addWidget(plot, 1)\n'
    '        layout.addWidget(status)\n'
    '        win.setCentralWidget(root)\n'
    '\n'
    '        state: dict[str, Any] = {"layer": None, "items": [], "vertex_item": None, "marker": None, "selected": None, "edit_enabled": True}\n'
    '\n'
    '        def current_layer() -> Layer:\n'
    '            index = layer_box.currentIndex()\n'
    '            return line_layers[index] if 0 <= index < len(line_layers) else None\n'
    '\n'
    '        def clear_plot() -> None:\n'
    '            plot.clear()\n'
    '            state["items"] = []\n'
    '            state["vertex_item"] = None\n'
    '            state["marker"] = None\n'
    '\n'
    '        def draw_layer() -> None:\n'
    '            clear_plot()\n'
    '            layer = current_layer()\n'
    '            state["layer"] = layer\n'
    '            state["selected"] = None\n'
    '            for button in (select_btn, pan_btn, zoom_window_btn, fit_btn, save_btn):button.setEnabled(layer is not None)\n'
    '            if layer is None:\n'
    '                status.setText("No editable linework loaded. Use Load backgrounds to add a DXF file.")\n'
    '                return\n'
    '            xs_all: list[float] = []\n'
    '            ys_all: list[float] = []\n'
    '            for shape_index, shape in enumerate(layer.shapes):\n'
    '                if shape.kind != "line" or len(shape.points) < 2:\n'
    '                    continue\n'
    '                arr = np.asarray(shape.points, dtype=float)\n'
    '                state["items"].append((shape, None))\n'
    '                xs_all.extend(arr[:, 0].tolist())\n'
    '                ys_all.extend(arr[:, 1].tolist())\n'
    '            state["batch_items"] = PyQtGraphSurveyMap.add_shapes_layer(plot, [shape for shape, _ in state["items"]])\n'
    '            if xs_all:\n'
    '                vertex_item = pg.ScatterPlotItem(x=np.asarray(xs_all), y=np.asarray(ys_all), pxMode=True, pen=None, brush=pg.mkBrush(239, 68, 68, 140), size=4)\n'
    '                plot.addItem(vertex_item)\n'
    '                state["vertex_item"] = vertex_item\n'
    '                plot.setRange(xRange=(min(xs_all), max(xs_all)), yRange=(min(ys_all), max(ys_all)), padding=0.08)\n'
    '            marker = pg.ScatterPlotItem(pxMode=True, pen=pg.mkPen("#ffffff", width=2), brush=pg.mkBrush(220, 38, 38, 230), size=14)\n'
    '            plot.addItem(marker)\n'
    '            marker.setVisible(False)\n'
    '            state["marker"] = marker\n'
    '            status.setText(f"Loaded {layer.name}. Click-drag a red vertex marker.")\n'
    '\n'
    '        def fit_edit_layer() -> None:\n'
    '            xs: list[float] = []\n'
    '            ys: list[float] = []\n'
    '            for shape, _item in state["items"]:\n'
    '                for x, y in shape.points:\n'
    '                    xs.append(float(x))\n'
    '                    ys.append(float(y))\n'
    '            if xs and ys:\n'
    '                plot.setRange(xRange=(min(xs), max(xs)), yRange=(min(ys), max(ys)), padding=0.08)\n'
    '\n'
    '        def map_xy(event) -> tuple[float, float]:\n'
    '            scene_pos = plot.mapToScene(event.position().toPoint())\n'
    '            point = plot.plotItem.vb.mapSceneToView(scene_pos)\n'
    '            return float(point.x()), float(point.y())\n'
    '\n'
    '        def tolerance() -> float:\n'
    '            x_range, y_range = plot.plotItem.vb.viewRange()\n'
    '            return max(2.0, min(100.0, max(x_range[1] - x_range[0], y_range[1] - y_range[0]) / 160.0))\n'
    '\n'
    '        def refresh_vertices() -> None:\n'
    '            xs: list[float] = []\n'
    '            ys: list[float] = []\n'
    '            for shape, _item in state["items"]:\n'
    '                for x, y in shape.points:\n'
    '                    xs.append(float(x))\n'
    '                    ys.append(float(y))\n'
    '            vertex_item = state.get("vertex_item")\n'
    '            if vertex_item is not None:\n'
    '                vertex_item.setData(x=np.asarray(xs), y=np.asarray(ys))\n'
    '\n'
    '        def mouse_press(event) -> None:\n'
    '            if not state.get("edit_enabled", True):\n'
    '                pg.PlotWidget.mousePressEvent(plot, event)\n'
    '                return\n'
    '            if event.button() != Qt.MouseButton.LeftButton:\n'
    '                pg.PlotWidget.mousePressEvent(plot, event)\n'
    '                return\n'
    '            x, y = map_xy(event)\n'
    '            best: Optional[tuple[float, Shape, int, Any]] = None\n'
    '            tol = tolerance()\n'
    '            for shape, item in state["items"]:\n'
    '                for index, (px, py) in enumerate(shape.points):\n'
    '                    dist = math.hypot(float(px) - x, float(py) - y)\n'
    '                    if dist <= tol and (best is None or dist < best[0]):\n'
    '                        best = (dist, shape, index, item)\n'
    '            if best is None:\n'
    '                status.setText(f"No vertex within {tol:.1f} m.")\n'
    '                return\n'
    '            _dist, shape, index, item = best\n'
    '            item = pg.PlotDataItem([p[0] for p in shape.points], [p[1] for p in shape.points], pen=pg.mkPen("#dc2626", width=2))\n'
    '            plot.addItem(item)\n'
    '            state["selected"] = (shape, index, item)\n'
    '            marker = state.get("marker")\n'
    '            if marker is not None:\n'
    '                marker.setData(x=[shape.points[index][0]], y=[shape.points[index][1]])\n'
    '                marker.setVisible(True)\n'
    '            status.setText(f"Selected vertex {index + 1}. Drag to adjust.")\n'
    '\n'
    '        def mouse_move(event) -> None:\n'
    '            if not state.get("edit_enabled", True):\n'
    '                pg.PlotWidget.mouseMoveEvent(plot, event)\n'
    '                return\n'
    '            selected = state.get("selected")\n'
    '            if selected is None:\n'
    '                pg.PlotWidget.mouseMoveEvent(plot, event)\n'
    '                return\n'
    '            x, y = map_xy(event)\n'
    '            shape, index, item = selected\n'
    '            old = shape.points[index]\n'
    '            shape.points[index] = (float(x), float(y))\n'
    '            if len(shape.points) > 2:\n'
    '                if index == 0 and old == shape.points[-1]:\n'
    '                    shape.points[-1] = (float(x), float(y))\n'
    '                elif index == len(shape.points) - 1 and old == shape.points[0]:\n'
    '                    shape.points[0] = (float(x), float(y))\n'
    '            arr = np.asarray(shape.points, dtype=float)\n'
    '            item.setData(arr[:, 0], arr[:, 1])\n'
    '            marker = state.get("marker")\n'
    '            if marker is not None:\n'
    '                marker.setData(x=[float(x)], y=[float(y)])\n'
    '            status.setText(f"E {x:,.3f}  N {y:,.3f}")\n'
    '\n'
    '        def mouse_release(event) -> None:\n'
    '            if not state.get("edit_enabled", True):\n'
    '                pg.PlotWidget.mouseReleaseEvent(plot, event)\n'
    '                return\n'
    '            if state.get("selected") is not None:\n'
    '                state["selected"] = None\n'
    '                bounds = plot.viewRange()\n'
    '                draw_layer()\n'
    '                plot.setRange(xRange=bounds[0], yRange=bounds[1], padding=0)\n'
    '                layer = state.get("layer")\n'
    '                if isinstance(layer, Layer):\n'
    '                    self.redraw_layer(layer)\n'
    "                    if hasattr(self, '_send_layers_to_survey'):self._send_layers_to_survey()\n"
    '                status.setText("Vertex adjusted. Continue editing or Save DXF.")\n'
    '                return\n'
    '            pg.PlotWidget.mouseReleaseEvent(plot, event)\n'
    '\n'
    '        def save_layer() -> None:\n'
    '            layer = current_layer()\n'
    '            if layer is None:return\n'
    '            name, _ = QFileDialog.getSaveFileName(win, "Save edited DXF", str(self.project_folder / "CAD" / f"{layer.name}_edited.dxf"), "DXF files (*.dxf);;All files (*.*)")\n'
    '            if not name:\n'
    '                return\n'
    '            try:\n'
    '                self.write_line_layers_to_dxf([layer], Path(name))\n'
    '                status.setText(f"Saved edited DXF: {name}")\n'
    '                self.log_event(f"Saved edited DXF: {name}")\n'
    '            except Exception as exc:\n'
    '                QMessageBox.warning(win, APP_TITLE, f"Could not save edited DXF:\\n{exc}")\n'
    '\n'
    '        plot.mousePressEvent = mouse_press  # type: ignore[method-assign]\n'
    '        plot.mouseMoveEvent = mouse_move  # type: ignore[method-assign]\n'
    '        plot.mouseReleaseEvent = mouse_release  # type: ignore[method-assign]\n'
    '        layer_box.currentIndexChanged.connect(draw_layer)\n'
    '        select_btn.clicked.connect(lambda: (state.update({"edit_enabled": True}), plot.plotItem.vb.setMouseMode(pg.ViewBox.PanMode), status.setText("Select Vertex mode: click-drag a vertex.")))\n'
    '        pan_btn.clicked.connect(lambda: (state.update({"edit_enabled": False}), plot.plotItem.vb.setMouseMode(pg.ViewBox.PanMode), status.setText("Pan mode.")))\n'
    '        zoom_window_btn.clicked.connect(lambda: (state.update({"edit_enabled": False}), plot.plotItem.vb.setMouseMode(pg.ViewBox.RectMode), status.setText("Zoom Window mode: drag a rectangle.")))\n'
    '        fit_btn.clicked.connect(fit_edit_layer)\n'
    '        save_btn.clicked.connect(save_layer)\n'
    '        close_btn.clicked.connect(win.close)\n'
    '        def refresh_layers():\n'
    '            nonlocal line_layers\n'
    '            latest = self.line_layers()\n'
    '            if [id(l) for l in latest] == [id(l) for l in line_layers]:return\n'
    '            current = current_layer()\n'
    '            line_layers = latest\n'
    '            layer_box.blockSignals(True);layer_box.clear()\n'
    '            for layer in line_layers:layer_box.addItem(layer.name)\n'
    '            layer_box.setCurrentIndex(next((i for i,l in enumerate(line_layers) if l is current), 0 if line_layers else -1))\n'
    '            layer_box.blockSignals(False);draw_layer()\n'
    '        timer = QTimer(win);timer.timeout.connect(refresh_layers);timer.start(200)\n'
    '        win._plot = plot;win._state = state;win._layers = layer_box;win._status = status\n'
    '        win._refresh_layers = refresh_layers\n'
    '        available = win.screen().availableGeometry()\n'
    '        win.resize(min(1100, int(available.width()*.9)), min(760, int(available.height()*.85)))\n'
    '        win.show()\n'
    '        draw_layer()\n'
    '        return win\n'
    '\n'
    '    def save_edited_linework(self) -> None:\n'
    '        line_layers = self.line_layers()\n'
    '        if not line_layers:\n'
    '            QMessageBox.warning(self, APP_TITLE, "No editable DXF/line layers are loaded.")\n'
    '            return\n'
    '        name, _ = QFileDialog.getSaveFileName(self, "Save edited linework DXF", str(self.project_folder / "CAD" / "edited_river_banks_channel.dxf"), "DXF files (*.dxf);;All files (*.*)")\n'
    '        if not name:\n'
    '            return\n'
    '        try:\n'
    '            target = Path(name)\n'
    '            self.write_line_layers_to_dxf(line_layers, target)\n'
    '            self.log_event(f"Saved edited linework DXF: {target}")\n'
    '        except Exception as exc:\n'
    '            QMessageBox.warning(self, APP_TITLE, f"Could not save edited DXF:\\n{exc}")\n'
    '\n'
    '    def set_coordinate_status(self, x: float, y: float) -> None:\n'
    '        text = f"E: {x:,.3f}  N: {y:,.3f}"\n'
    '        transformer_class = get_transformer_class() if self.crs_box.currentText().startswith("EPSG:32642") else None\n'
    '        if transformer_class is not None:\n'
    '            try:\n'
    '                if self.transformer is None:\n'
    '                    self.transformer = transformer_class.from_crs("EPSG:32642", "EPSG:4326", always_xy=True)\n'
    '                lon, lat = self.transformer.transform(x, y)\n'
    '                text += f"   Lat: {lat:.8f}  Lon: {lon:.8f}"\n'
    '            except Exception:\n'
    '                pass\n'
    '        self.coord_label.setText(text)\n'
    '\n'
    '    def update_status_from_view(self) -> None:\n'
    '        rect = self.view.visible_bounds()\n'
    '        self.scale_label.setText(f"View: {rect.width():,.1f} x {rect.height():,.1f} m")\n'
    '\n'
    '    def push_view_history(self) -> None:\n'
    '        rect = self.view.visible_bounds()\n'
    '        if rect.width() <= 0 or rect.height() <= 0:\n'
    '            return\n'
    '        entry = (float(rect.left()), float(rect.top()), float(rect.right()), float(rect.bottom()))\n'
    '        if self.view_history and all(abs(a - b) < 1e-6 for a, b in zip(self.view_history[-1], entry)):\n'
    '            return\n'
    '        self.view_history.append(entry)\n'
    '        if len(self.view_history) > 30:\n'
    '            self.view_history = self.view_history[-30:]\n'
    '\n'
    '    def zoom_previous(self) -> None:\n'
    '        if not self.view_history:\n'
    '            self.status.showMessage("No previous zoom view is available.", 4000)\n'
    '            return\n'
    '        left, top, right, bottom = self.view_history.pop()\n'
    '        self.view.fit_bounds((left, top, right, bottom))\n'
    '        self.update_status_from_view()\n'
    '\n'
    '    def add_layer(self, layer: Layer) -> None:\n'
    '        if layer.path is not None and layer.path.exists():\n'
    '            try:\n'
    '                layer.path = self.project_copy_for_background(layer.path)\n'
    '            except Exception as exc:\n'
    '                self.log_event(f"Could not copy layer into project folder: {exc}")\n'
    '        layer.group = self.view.add_shapes_layer(layer.shapes)\n'
    '        self.layers.append(layer)\n'
    '        if not layer.hidden:\n'
    '            item = QListWidgetItem(layer.name)\n'
    '            item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable)\n'
    '            item.setCheckState(Qt.CheckState.Checked)\n'
    '            self.layer_list.addItem(item)\n'
    '        self.status.showMessage(f"Loaded {layer.name}: {len(layer.shapes)} item(s)", 5000)\n'
    '        if not layer.hidden:\n'
    '            self.save_background_state()\n'
    '\n'
    '    def layer_for_list_row(self, row: int) -> Optional[Layer]:\n'
    '        visible_layers = [layer for layer in self.layers if not layer.hidden]\n'
    '        if 0 <= row < len(visible_layers):\n'
    '            return visible_layers[row]\n'
    '        return None\n'
    '\n'
    '    def load_files(self) -> None:\n'
    '        names, _ = QFileDialog.getOpenFileNames(\n'
    '            self,\n'
    '            "Load map files",\n'
    '            str(Path.home() / "Desktop"),\n'
    '            "Map files (*.dxf *.dwg *.ktd *.KTD *.hpktd *.ktdp *.xyz *.csv *.txt);;All files (*.*)",\n'
