    '            for key,value in saved.items():\n'
    "                if key=='enabled' and isinstance(value,bool):self.filter_config[key]=value\n"
    "                elif key in FILTER_DEFAULTS and key!='enabled' and finite(value) is not None and float(value)>0:self.filter_config[key]=float(value)\n"
    "            self.filter_config['smoothing']=min(1.0,max(0.05,self.filter_config['smoothing']))\n"
    '        except (OSError,ValueError,TypeError,AttributeError):pass\n'
    '        self.input_filter=IntelligentInputFilter(self.filter_config);self.filter_handle=None\n'
    '        self.sensor_events=queue.Queue();self.incoming_handle=None;self.event_handle=None;self.event_second=None;self.event_point=None;self.event_count=0\n'
    '    def attach(self,ctx):self.ctx=ctx\n'
    '    def checkpoint(self,force=False):\n'
    '        if not self.session or not self.session_path:return\n'
