    '        self.last_checkpoint=time.monotonic()\n'
    '        try:\n'
    '            for handle in (self.incoming_handle,self.event_handle,self.filter_handle):\n'
    '                if handle:handle.flush();os.fsync(handle.fileno())\n'
    '            if self.writer and self.writer.handle and not self.writer.handle.closed:\n'
    '                self.writer.handle.flush();os.fsync(self.writer.handle.fileno())\n'
    '            self.session.update(updated_utc=datetime.now(timezone.utc).isoformat(),metrics=dict(self.metrics),filter_counts=dict(self.input_filter.counts),pending_records=self.queue.qsize(),last_error=self.last_error)\n'
    "            existing={f['name']:f for f in self.session.get('files',[])}\n"
    "            self.session['files']=[dict(existing.get(p.name,{}),name=p.name,bytes=p.stat().st_size if p.exists() else 0) for p in self.paths]\n"
    "            atomic_json(self.session_path,self.session);self.metadata_error=''\n"
    '        except OSError as exc:\n'
    '            self.metadata_error=str(exc)\n'
    '            # A metadata failure must not discard an otherwise writable RAW stream.\n'
    "            if self.ctx:self.ctx['status_var'].set('Session checkpoint failed: '+str(exc))\n"
    '    def finish_session(self,status):\n'
    "        if not self.session or self.session.get('status') not in ('recording','stopping','error') or self.session.get('ended_utc'):return\n"
    "        self.session['status']=status;self.session['ended_utc']=datetime.now(timezone.utc).isoformat()\n"
    '        files=[]\n'
    '        for path in self.paths:\n'
