    '        while not folder.exists() and folder!=folder.parent:folder=folder.parent\n'
    '        try:free=shutil.disk_usage(folder).free\n'
    '        except OSError:free=None\n'
    "        return {'recording':self.writer is not None,'files':[str(p) for p in self.paths],\n"
    "                'session':str(self.session_path or ''),'metrics':dict(self.metrics),'queue':self.queue.qsize(),\n"
