    "        self.metrics=dict.fromkeys(self.metrics,0);self.last_received=None;self.last_error='';self.metadata_error=''\n"
    '        self.event_second=None;self.event_point=None;self.event_count=0\n'
    '        self.input_filter=IntelligentInputFilter(self.filter_config)\n'
