    '\n'
    '    def metadata_mouse(self,label,event):\n'
    "        if not hasattr(self,'move_information') or not self.move_information.isChecked():return False\n"
    '        kind=event.type()\n'
    '        if kind not in (C.QEvent.Type.MouseButtonPress,C.QEvent.Type.MouseMove,C.QEvent.Type.MouseButtonRelease):return False\n'
    '        pix=label.pixmap()\n'
    '        if pix is None or pix.isNull():return False\n'
    '        rect=label.contentsRect();pw=pix.width()/pix.devicePixelRatio();ph=pix.height()/pix.devicePixelRatio()\n'
    '        pos=event.position();x=(pos.x()-rect.x()-(rect.width()-pw)/2)/pw;y=1-(pos.y()-rect.y()-(rect.height()-ph)/2)/ph\n'
    '        point=np.array([x*self.figure.bbox.width,y*self.figure.bbox.height])\n'
    '        if kind==C.QEvent.Type.MouseButtonPress:\n'
    '            if event.button()!=C.Qt.MouseButton.LeftButton:return False\n'
    '            for key,artist in reversed(list(self._metadata_artists.items())):\n'
    '                if artist.get_window_extent(self.canvas.get_renderer()).expanded(1.1,1.2).contains(*point):\n'
    '                    self._drag_metadata=(key,np.array(artist.get_position())-np.array([x,y]));label.setCursor(C.Qt.CursorShape.ClosedHandCursor);return True\n'
    '            return False\n'
