    '            target=np.array([x,y])+offset;target[0]=np.clip(target[0],w/2+.005,1-w/2-.005);target[1]=np.clip(target[1],h+.005,.995)\n'
    '            self.metadata_positions[key]=tuple(target);artist.set_position(target)\n'
    '            self.canvas.draw();image=G.QImage(self.canvas.buffer_rgba(),*self.canvas.get_width_height(),G.QImage.Format.Format_RGBA8888).copy();self._preview_pixmap=G.QPixmap.fromImage(image);self.refresh_preview_image()\n'
    '            if label is not self.preview_image:label.setPixmap(self._preview_pixmap.scaled(label.contentsRect().size(),C.Qt.AspectRatioMode.KeepAspectRatio,C.Qt.TransformationMode.SmoothTransformation))\n'
    '        if kind==C.QEvent.Type.MouseButtonRelease:\n'
