    '        return True\n'
    '\n'
    '    def start_map_limits_pick(self):\n'
    '        import re\n'
    "        owner=self.parentWidget();view=getattr(owner,'view',None)\n"
    "        if view is None or not hasattr(view,'plotItem'):\n"
    "            raise ValueError('Open plotting from the main MAP window to pick plot limits.')\n"
    '        source=owner.crs_box.currentText().strip()\n'
    "        match=re.search(r'EPSG:\\s*(\\d+)',source,re.I)\n"
    "        if hasattr(owner,'engine') and 'settings' in getattr(owner,'context',{}):\n"
    "            g=owner.context['settings'].geodetic\n"
    '            if not g.use_projection:self._map_limits_crs=CRS.from_epsg(4326)\n'
    '            else:\n'
    "                if not g.use_tm_projection:raise ValueError('MAP selection requires the supported survey TM/UTM projection.')\n"
