    "        else:self._map_limits_crs=CRS.from_user_input('EPSG:'+match.group(1) if match else source)\n"
    '        self._pick_map_view=view;self._map_first_corner=None\n'
    '        self._map_old_cursor=view.viewport().cursor();self._map_old_tracking=view.viewport().hasMouseTracking()\n'
    "        self._map_outline=self.modern.pg.PlotDataItem([],[],pen=self.modern.pg.mkPen('#dc2626',width=2))\n"
    '        self._map_outline.setZValue(100000);view.addItem(self._map_outline)\n'
    "        self._map_pick_hint=W.QLabel('PLOT LIMITS: click two opposite corners • Escape / right-click cancels');owner.statusBar().addPermanentWidget(self._map_pick_hint)\n"
    '        self.preview_timer.stop()\n'
