    '        view.viewport().setMouseTracking(True);view.viewport().setCursor(C.Qt.CursorShape.CrossCursor)\n'
    '        self.hide();owner.showMaximized();owner.raise_();owner.activateWindow();view.setFocus()\n'
    "        owner.statusBar().showMessage('Plot limits: click the first corner, then the opposite corner. Right-click or Escape cancels.')\n"
    '\n'
    '    def map_limits_point(self,position):\n'
    '        view=self._pick_map_view;scene=view.mapToScene(position.toPoint())\n'
    '        if not view.plotItem.vb.sceneBoundingRect().contains(scene):return None\n'
    '        point=view.plotItem.vb.mapSceneToView(scene)\n'
    '        return float(point.x()),float(point.y())\n'
    '\n'
    '    def update_map_limits_outline(self,point):\n'
    '        x,y=self._map_first_corner;xx,yy=point\n'
    '        self._map_outline.setData([x,xx,xx,x,x],[y,y,yy,yy,y])\n'
    '\n'
    '    def map_limits_click(self,position):\n'
    '        point=self.map_limits_point(position)\n'
    '        if point is None:return\n'
    '        if self._map_first_corner is None:\n'
    '            self._map_first_corner=point\n'
    "            self.parentWidget().statusBar().showMessage('Plot limits: click the opposite corner. Right-click or Escape cancels.')\n"
    '            return\n'
    '        x,y=self._map_first_corner;xx,yy=point\n'
    '        if abs(xx-x)<1e-10 or abs(yy-y)<1e-10:\n'
    "            self.parentWidget().statusBar().showMessage('Choose an opposite corner with non-zero width and height.');return\n"
    "        transform=Transformer.from_crs(self._map_limits_crs,'EPSG:4326',always_xy=True)\n"
    '        west,south,east,north=transform.transform_bounds(min(x,xx),min(y,yy),max(x,xx),max(y,yy),densify_pts=41,errcheck=True)\n'
    '        if not all(math.isfinite(v) for v in (west,south,east,north)) or not -180<=west<east<=180 or not -85<south<north<85:\n'
    "            raise ValueError('Selected area lies outside the supported Mercator limits or crosses the antimeridian. Choose another area.')\n"
    '        self.import_map_selection((min(x,xx),min(y,yy),max(x,xx),max(y,yy)))\n'
    "        for key,value in [('West',west),('East',east),('South',south),('North',north)]:\n"
    '            widget=self.bounds[key];widget.blockSignals(True);widget.setValue(value);widget.blockSignals(False)\n'
    "        self.options['placement'].blockSignals(True);self.options['placement'].setCurrentIndex(0);self.options['placement'].blockSignals(False)\n"
    '        self.finish_map_limits_pick(True)\n'
