    '    def draw_map_feature(self,ax,kind,points,label,x,y):\n'
    "        if not kind.startswith('map_'):return False\n"
    "        color=self._map_styles.get(id(points),'#111827')\n"
    "        if kind=='map_fill':\n"
    '            from matplotlib.path import Path as MPath\n'
    '            from matplotlib.patches import PathPatch\n'
    '            codes=[]\n'
    '            for length in self._map_fill_lengths.get(id(points),[len(points)]):codes.extend([MPath.MOVETO]+[MPath.LINETO]*(length-2)+[MPath.CLOSEPOLY])\n'
    "            ax.add_patch(PathPatch(MPath(np.column_stack((x,y)),codes),facecolor=color,edgecolor='none',zorder=1))\n"
    "        elif kind=='map_line':ax.plot(x,y,color=color,lw=.7,zorder=2)\n"
    "        elif kind=='map_text':\n"
    "            text=ax.text(x[0],y[0],label,color=color,ha='left',va='bottom',clip_on=True,zorder=4)\n"
    '            self._int2_texts.append(text)\n'
    '        else:\n'
    '            ax.scatter(x,y,s=4,color=color,zorder=3)\n'
