    '\n'
    '    def import_map_selection(self,limits):\n'
    '        """Take an independent, clipped snapshot of visible MAP geometry."""\n'
    '        from shapely.geometry import box, LineString, Polygon\n'
    '        owner=self.parentWidget();view=self._pick_map_view\n'
    '        region=box(*limits);west,south,east,north=limits\n'
    "        transformer=Transformer.from_crs(self._map_limits_crs,'EPSG:4326',always_xy=True)\n"
    '        snapshots=[];seen_items=set();has_labels=False\n'
    "        def convert(kind,points,label='',color='#111827',rings=None):\n"
    '            points=np.asarray(points,dtype=float)\n'
    '            if points.ndim!=2 or points.shape[1]<2 or len(points)==0:return []\n'
    '            points=points[:,:2];result=[]\n'
    '            def append(pts,mode):\n'
    '                lon,lat=transformer.transform(pts[:,0],pts[:,1],errcheck=True)\n'
    '                data=np.column_stack((lon,lat))\n'
    "                if not np.isfinite(data).all():raise ValueError('Visible MAP data could not be transformed. Check survey projection settings.')\n"
    '                data=data.copy();self._map_styles[id(data)]=color\n'
    "                result.append((mode,data,str(label or '')))\n"
    "            if kind=='cad_fill':\n"
    '                from shapely.geometry.polygon import orient\n'
    '                polygon=Polygon((rings or [points])[0],(rings or [points])[1:])\n'
    '                if not polygon.is_valid:polygon=polygon.buffer(0)\n'
    '                clipped=polygon.intersection(region)\n'
    "                polygons=[clipped] if clipped.geom_type=='Polygon' else list(getattr(clipped,'geoms',[]))\n"
    '                for poly in polygons:\n'
    "                    if poly.is_empty or poly.geom_type!='Polygon':continue\n"
    '                    poly=orient(poly,sign=1)\n'
    '                    arrays=[np.asarray(ring.coords) for ring in [poly.exterior]+list(poly.interiors)]\n'
    "                    append(np.concatenate(arrays),'map_fill');self._map_fill_lengths[id(result[-1][1])]=[len(a) for a in arrays]\n"
    '                return result\n'
    "            if kind in ('point','text','ktd') or len(points)==1:\n"
    '                for pt in points:\n'
    "                    if np.isfinite(pt).all() and west<=pt[0]<=east and south<=pt[1]<=north:append(pt.reshape(1,2),'map_text' if kind=='text' else 'map_point')\n"
    '            else:\n'
    '                # Split non-finite line separators; clip crossing segments even when both vertices are outside.\n'
    '                runs=[];start=0\n'
    '                for i in range(len(points)+1):\n'
    '                    if i==len(points) or not np.isfinite(points[i]).all():\n'
    '                        if i-start>=2:runs.append(points[start:i])\n'
    '                        start=i+1\n'
    '                def collect(geometry):\n'
    '                    if geometry.is_empty:return\n'
    "                    if geometry.geom_type=='LineString':append(np.asarray(geometry.coords),'map_line')\n"
    "                    elif hasattr(geometry,'geoms'):\n"
    '                        for child in geometry.geoms:collect(child)\n'
    '                for run in runs:collect(LineString(run).intersection(region))\n'
    '            return result\n'
    "        for layer in getattr(owner,'layers',[]):\n"
    "            group=list(getattr(layer,'group',None) or []);seen_items.update(id(item) for item in group)\n"
    "            if not getattr(layer,'visible',True) or (group and not any(item.isVisible() for item in group)):continue\n"
    '            converted=[]\n'
    '            for shape in layer.shapes:\n'
    "                if not getattr(shape,'cad_visible',True):continue\n"
    "                if not getattr(layer,'cad_visibility',{}).get(getattr(shape,'cad_layer',''),True):continue\n"
    "                label=getattr(shape,'label','')\n"
    "                if not label and getattr(shape,'value',None) is not None:label=f'{shape.value:g}'\n"
    "                if shape.kind=='ktd' and self.modern.is_ktd_nodata(getattr(shape,'value',None)):continue\n"
    "                color=getattr(shape,'color','#111827') or '#111827'\n"
    "                if getattr(shape,'cad_auto_color',False):color='#111827' if view.backgroundBrush().color().lightness()>128 else '#ffffff'\n"
    "                converted.extend(convert(shape.kind,shape.points,label,color,getattr(shape,'rings',None)))\n"
    "            snapshots.append(('MAP — '+layer.name,converted))\n"
    '        # Soundings retain their actual depth values, independently of screen label thinning.\n'
    "        live_item=getattr(view,'live_depth_scatter',None)\n"
    '        if live_item is not None:\n'
    '            seen_items.add(id(live_item));converted=[]\n'
    '            if live_item.isVisible():\n'
    "                for x,y,depth in getattr(owner,'live_soundings',[]):converted.extend(convert('point',[(x,y)],f'{depth:g}'))\n"
    "            if converted:snapshots.append(('MAP — Live soundings',converted))\n"
    '        # Include other visible map graphics (track, runlines and navigation overlays).\n'
    '        for index,item in enumerate(view.plotItem.items):\n'
    '            if id(item) in seen_items or item is self._map_outline or not item.isVisible():continue\n'
    '            if isinstance(item,self.modern.pg.TextItem):\n'
    "                position=item.pos();converted=convert('text',[(position.x(),position.y())],item.toPlainText(),item.color.name())\n"
    "                if converted:snapshots.append((f'MAP — Annotation {index+1}',converted))\n"
    '            elif isinstance(item,(self.modern.pg.PlotDataItem,self.modern.pg.ScatterPlotItem)):\n'
    '                x,y=item.getData()\n'
    '                if x is None or y is None or len(x)==0:continue\n'
    '                pts=np.column_stack((x,y))\n'
    "                kind='point' if isinstance(item,self.modern.pg.ScatterPlotItem) or item.opts.get('pen') is None else 'line'\n"
    "                style=item.opts.get('pen') if kind=='line' else item.opts.get('brush')\n"
    "                color=style.color().name() if hasattr(style,'color') else '#111827'\n"
    '                converted=convert(kind,pts,color=color)\n'
    '                if converted:snapshots.append((f\'MAP — {item.name() or "Visible graphics "+str(index+1)}\',converted))\n'
    '        self.files.blockSignals(True)\n'
    '        try:\n'
    '            for i in range(self.files.count()-1,-1,-1):\n'
    "                if self.files.item(i).data(C.Qt.ItemDataRole.UserRole)=='map_snapshot':self.files.takeItem(i);self.datasets.pop(i)\n"
    '            for name,shapes in snapshots:\n'
    '                self.datasets.append((name,self._map_limits_crs.to_string(),shapes))\n'
    '                item=W.QListWidgetItem(name);item.setFlags(item.flags()|C.Qt.ItemFlag.ItemIsUserCheckable)\n'
    "                item.setCheckState(C.Qt.CheckState.Checked);item.setData(C.Qt.ItemDataRole.UserRole,'map_snapshot')\n"
    "                item.setToolTip('Snapshot of visible MAP data clipped to the selected rectangle. Pick limits again to refresh.');self.files.addItem(item)\n"
    '                has_labels=has_labels or any(label for _,_,label in shapes)\n'
    '        finally:self.files.blockSignals(False)\n'
    '        if has_labels:self.labels.setChecked(True)\n'
    '        self._map_snapshot_count=len(snapshots)\n'
    '\n'
    '    def finish_map_limits_pick(self,accepted):\n'
    '        if not self._map_pick_active:return\n'
    '        self._map_pick_active=False;W.QApplication.instance().removeEventFilter(self)\n'
    '        self.parentWidget().statusBar().removeWidget(self._map_pick_hint);self._map_pick_hint.deleteLater()\n'
    '        view=self._pick_map_view;view.removeItem(self._map_outline)\n'
    '        view.viewport().setCursor(self._map_old_cursor);view.viewport().setMouseTracking(self._map_old_tracking)\n'
    "        self.parentWidget().statusBar().showMessage('Plot limits transferred to plotting.' if accepted else 'Plot limit selection cancelled.',5000)\n"
    '        self.showMaximized();self.raise_();self.activateWindow()\n'
    '        if accepted:self.render_plot()\n'
    '\n'
    "    def make_sheet_series(self,scale=25000,overlap=10,orientation='A0 landscape',crs_text='EPSG:32642',skip_empty=True,font_size=8):\n"
    '        from shapely.geometry import Point,LineString,box\n'
    '        from shapely.strtree import STRtree\n'
    '        crs=CRS.from_user_input(crs_text);self.validate_origin_crs(crs)\n'
    '        transform=Transformer.from_crs(4326,crs,always_xy=True)\n'
    '        geometry=[]\n'
    '        for _,_,shapes in self.checked():\n'
    '            for kind,points,label in shapes:\n'
    '                x,y=transform.transform(points[:,0],points[:,1],errcheck=True);xy=np.column_stack((x,y))\n'
    "                if not np.isfinite(xy).all():raise ValueError('A selected dataset cannot be transformed to the series CRS.')\n"
    "                if len(xy)==1 or kind in ('point','map_point','map_text'):geometry.extend(Point(p) for p in xy)\n"
    '                else:geometry.append(LineString(xy))\n'
    "        if not geometry:raise ValueError('Load and check the full survey/corridor data first. A MAP selection contains only the selected area.')\n"
    '        bounds=np.asarray([g.bounds for g in geometry]);xmin,ymin=bounds[:,:2].min(axis=0);xmax,ymax=bounds[:,2:].max(axis=0)\n'
    "        sw,sh=(1189,841) if orientation.endswith('landscape') else (841,1189)\n"
    "        margin=self.opt('margin');lim=(1100,750) if sw>sh else (750,1100)\n"
    '        width=min(lim[0],sw-2*(margin+14));height=min(lim[1],sh-2*(margin+14)-22)\n'
    "        if min(width,height)<=5:raise ValueError('Reduce the sheet margins.')\n"
    '        dx,dy=width*scale/1000,height*scale/1000;stepx=dx*(1-overlap/100);stepy=dy*(1-overlap/100)\n'
    '        # A small edge allowance keeps edge soundings clear of the neatline.\n'
    '        pad=min(dx,dy)*.02;xmin-=pad;xmax+=pad;ymin-=pad;ymax+=pad\n'
    '        nx=max(1,math.ceil(max(0,xmax-xmin-dx)/stepx)+1);ny=max(1,math.ceil(max(0,ymax-ymin-dy)/stepy)+1)\n'
    "        if nx*ny>10000:raise ValueError(f'This requires {nx*ny:,} grid blocks. Increase the scale denominator or reduce the selected data extent.')\n"
    '        tree=STRtree(geometry);sheets=[]\n'
    '        for row in range(ny):\n'
    '            for col in range(nx):\n'
    '                x=xmin+col*stepx;y=ymax-dy-row*stepy\n'
    "                if skip_empty and len(tree.query(box(x,y,x+dx,y+dy),predicate='intersects'))==0:continue\n"
    '                sheets.append(dict(number=len(sheets)+1,row=row+1,column=col+1,x=x,y=y,width=width,height=height,dx=dx,dy=dy))\n'
    '        return dict(sheets=sheets,scale=scale,overlap=overlap,orientation=orientation,crs=crs.to_string(),font_size=font_size,title=self.title.text(),geometry=geometry,dataset_ids=[id(data) for data in self.checked()])\n'
    '\n'
    '    def preview_series_sheet(self,series,index):\n'
