    "        if pattern=='M' and scale<4750000:self._warnings.append('Pattern M is a very-small-scale example; review this override.')\n"
    '        self.draw_graduation(ax,geometry,numbering,lat_numbering,dicing)\n'
    '        self.draw_graticule(ax,geometry,numbering,lat_numbering)\n'
    '        self.draw_utm_graduation(ax,geometry,CRS.from_user_input(MERCATOR))\n'
    '        self.draw_rectangular_grid(ax,geometry)\n'
    '        self.draw_linear_scale(ax,geometry)\n'
    "        if self.opt('corner_coords'):\n"
    "            corners=[(x0,y0,west,south,'left','top'),(x1,y1,east,north,'right','bottom')]\n"
    "            if self.opt('corner_positions')=='All four corners':corners += [(x1,y0,east,south,'right','top'),(x0,y1,west,north,'left','bottom')]\n"
    '            for x,y,lon,lat,ha,va in corners:\n'
    "                precision=self.opt('corner_precision')\n"
