    '\n'
    '    def draw_graduation(self,ax,g,numbering,lat_numbering,dicing):\n'
    '        from matplotlib.patches import Rectangle\n'
    "        west,east,south,north=g['bounds'];x0,x1,y0,y1=(g[k] for k in ('x0','x1','y0','y1'));ux,uy=g['ux'],g['uy']\n"
    "        degree,inter,minute,minor,_=g['profile'];sides=self.opt('sides')\n"
    "        enabled={'bottom','left'} if sides.startswith('Bottom') else {'top','right'} if sides.startswith('Top') else set() if sides.startswith('None') else {'bottom','top','left','right'}\n"
    "        if not enabled and self.opt('kind')!='Very small plan':self._warnings.append('Ungraded borders are an exception for very small plans, not a chart default.')\n"
    "        if len(enabled)==2 and self.opt('kind')=='Chart':self._warnings.append('Two-sided graduation is intended for plans.')\n"
    '        offset=2 if dicing else 0\n'
    '        for longitude,lo,hi,num in [(True,west,east,numbering),(False,south,north,lat_numbering)]:\n'
    '            values=tick_values(lo,hi,num)\n'
    "            full_indices=set(range(len(values))) if self.opt('numbering').startswith('Full') else {i for i,v in enumerate(values) if abs(v-round(v))<1e-8}\n"
    '            if len(values):\n'
    '                # A full degree reference in both halves also covers degree-near-corner cases.\n'
    '                full_indices.add(0);full_indices.add(len(values)//2)\n'
    '            label_positions=[]\n'
    '            for i,value in enumerate(values):\n'
    '                pos=self.projection.transform(value,south)[0] if longitude else self.projection.transform(west,value)[1]\n'
    '                label_positions.append(pos)\n'
    "                for side in (('bottom','top') if longitude else ('left','right')):\n"
    '                    if side not in enabled:continue\n'
    "                    direction=-1 if side in ('bottom','left') else 1\n"
    "                    coordinate=(y0 if side=='bottom' else y1) if longitude else (x0 if side=='left' else x1)\n"
    '                    text=self.border_label(value,num,longitude,i in full_indices)\n'
    "                    if longitude:self.chart_text(ax,pos,coordinate+direction*(offset+4.4)*uy,text,'border',ha='center',va='center')\n"
    "                    else:self.chart_text(ax,coordinate+direction*(offset+4.4)*ux,pos,text,'border',ha='center',va='center',rotation=90)\n"
    "            multiplier=int(self.opt('longitude_multiplier').split()[0]) if longitude else 1\n"
    "            if multiplier!=1 and max(abs(south),abs(north))<=70:self._warnings.append('Different longitude tick intervals are intended for latitudes beyond 70°. Dicing remains equal.')\n"
    "            levels=[(degree*multiplier,g['inner']-offset),(inter*multiplier,self.opt('long_tick')),(minute*multiplier,self.opt('mid_tick'))]\n"
    "            minor_mode=self.opt('minor_mode')\n"
    "            if minor_mode!='None':levels.append((minor*multiplier,self.opt('short_tick')))\n"
    '            ticks={}\n'
    '            for interval,length in levels:\n'
    '                if not interval:continue\n'
    '                if (hi-lo)*60/interval>4000:\n'
    "                    self._warnings.append('A graduation level exceeds 4,000 ticks and was omitted; choose a coarser scale pattern.');continue\n"
    '                for value in tick_values(lo,hi,interval):\n'
    "                    if interval==minor*multiplier and minor_mode=='Near numbered ticks only':\n"
    '                        nearest=round(value*60/num)*num/60\n'
    '                        direction=1 if value>=0 else -1\n'
    '                        if not 0<=direction*(value-nearest)*60<=minute:continue\n'
    '                    key=round(float(value),10);ticks[key]=max(ticks.get(key,0),length)\n'
    "            if minor_mode=='Hundredths near centre':\n"
    '                centre=round((lo+hi)*30*10)/10/60\n'
    "                for value in tick_values(max(lo,centre),min(hi,centre+.1/60),.01):ticks[round(float(value),10)]=self.opt('short_tick')\n"
    "            for side in (('bottom','top') if longitude else ('left','right')):\n"
    '                if side not in enabled:continue\n'
    "                direction=-1 if side in ('bottom','left') else 1\n"
    "                coordinate=(y0 if side=='bottom' else y1) if longitude else (x0 if side=='left' else x1)\n"
    '                for value,length in ticks.items():\n'
    '                    pos=self.projection.transform(value,south)[0] if longitude else self.projection.transform(west,value)[1]\n'
    '                    if longitude:xs=[pos,pos];ys=[coordinate+direction*offset*uy,coordinate+direction*(offset+length)*uy]\n'
    '                    else:xs=[coordinate+direction*offset*ux,coordinate+direction*(offset+length)*ux];ys=[pos,pos]\n'
    "                    ax.plot(xs,ys,color='black',lw=.35,clip_on=False,zorder=3)\n"
    '                if dicing:\n'
    '                    values_dice=np.r_[lo,tick_values(lo,hi,dicing),hi];values_dice=np.unique(values_dice)\n'
    '                    for a,b in zip(values_dice,values_dice[1:]):\n'
    '                        p0=self.projection.transform(a,south)[0] if longitude else self.projection.transform(west,a)[1]\n'
    '                        p1=self.projection.transform(b,south)[0] if longitude else self.projection.transform(west,b)[1]\n'
    "                        fill='black' if int(math.floor(((a+b)/2)*60/dicing))%2==0 else 'white'\n"
    "                        band=self.opt('band_mm')\n"
    '                        if longitude:r=Rectangle((p0,coordinate+min(0,direction*band*uy)),p1-p0,band*uy)\n'
    '                        else:r=Rectangle((coordinate+min(0,direction*band*ux),p0),band*ux,p1-p0)\n'
    "                        r.set_facecolor(fill);r.set_edgecolor('black');r.set_linewidth(.3);r.set_clip_on(False);ax.add_patch(r)\n"
    "        hemi=self.opt('hemisphere')\n"
    "        if hemi.startswith('Central') or hemi.startswith('Full'):\n"
    '            lon=(west+east)/2;lat=(south+north)/2\n'
    "            ew='East' if lon>=0 else 'West';ns='North' if lat>=0 else 'South'\n"
    "            label='Longitude '+ew+' from Greenwich' if hemi.startswith('Full') else ew[0]\n"
    "            label_lat='Latitude '+ns+' from Equator' if hemi.startswith('Full') else ns[0]\n"
    "            self.chart_text(ax,(x0+x1)/2,y0-(g['inner']-1.5)*uy,label,ha='center',va='center')\n"
    "            self.chart_text(ax,x0-(g['inner']-1.5)*ux,(y0+y1)/2,label_lat,ha='center',va='center',rotation=90)\n"
    '\n'
    '    def draw_graticule(self,ax,g,numbering,lat_numbering):\n'
    "        west,east,south,north=g['bounds'];x0,x1,y0,y1=(g[k] for k in ('x0','x1','y0','y1'))\n"
    "        mode=self.opt('graticule')\n"
    "        if mode!='Off':\n"
    "            if mode.startswith('Automatic'):\n"
    "                required=max((east-west)*60*100/g['width'],(north-south)*60*100/g['height'])\n"
    '                interval=next((v for v in (.01,.02,.05,.1,.2)+INTERVALS if v>=required),300)\n'
    "            else:interval=self.opt('graticule_int')\n"
    '            lon=tick_values(west,east,interval);lat=tick_values(south,north,interval)\n'
    '            if not len(lon):lon=np.array([(west+east)/2])\n'
    '            if not len(lat):lat=np.array([(south+north)/2])\n'
    '            xx=self.projection.transform(lon,np.full(len(lon),south))[0];yy=self.projection.transform(np.full(len(lat),west),lat)[1]\n'
    "            spacing_x=g['width']*interval/((east-west)*60);spacing_y=g['height']*interval/((north-south)*60)\n"
    "            if len(xx)>1 and not 100<=spacing_x<=230 or len(yy)>1 and not 100<=spacing_y<=230:self._warnings.append('Graticule spacing is outside 100–230 mm; review interval or sheet extents.')\n"
    "            if mode=='Intersections only':\n"
    "                if len(xx)*len(yy)>5000:raise ValueError('Too many graticule intersections.')\n"
    '                for x in xx:\n'
    "                    for y in yy:ax.plot([x-1*g['ux'],x+1*g['ux']],[y,y],color='.6',lw=.3);ax.plot([x,x],[y-g['uy'],y+g['uy']],color='.6',lw=.3)\n"
    '            else:\n'
    "                for x in xx:ax.axvline(x,color='.6',lw=.3,zorder=0)\n"
    "                for y in yy:ax.axhline(y,color='.6',lw=.3,zorder=0)\n"
    '            # A graticule line not already numbered receives an explicit coordinate.\n'
    '            for longitude,values,positions,number in ((True,lon,xx,numbering),(False,lat,yy,lat_numbering)):\n'
    '                for value,pos in zip(values,positions):\n'
