    '\n'
    '    def draw_utm_graduation(self,ax,g,sheet_crs,world=None,local=None):\n'
    '        """Intersect UTM coordinate lines with the actual (possibly rotated) sheet."""\n'
    "        if not self.opt('dual_graduation') or self.opt('utm_display')=='Off':return\n"
    '        from shapely.geometry import LineString,box\n'
    "        zone=int(self.opt('utm_zone'))\n"
    "        utm=CRS.from_epsg((32700 if self.opt('utm_hemisphere')=='South' else 32600)+zone)\n"
    "        primary=self.opt('utm_purpose').startswith('Primary')\n"
    "        if primary and not sheet_crs.equals(utm):raise ValueError('Primary UTM grid must match the plot projection. Use Secondary for a Mercator plot, or select the matching UTM Origin / CAD CRS.')\n"
    '        forward=Transformer.from_crs(sheet_crs,utm,always_xy=True)\n'
    '        inverse=Transformer.from_crs(utm,sheet_crs,always_xy=True)\n'
    "        x0,x1,y0,y1=(g[k] for k in ('x0','x1','y0','y1'))\n"
    '        xx=np.r_[np.linspace(x0,x1,100),np.full(100,x1),np.linspace(x1,x0,100),np.full(100,x0)]\n'
    '        yy=np.r_[np.full(100,y0),np.linspace(y0,y1,100),np.full(100,y1),np.linspace(y1,y0,100)]\n'
    '        wx,wy=world(xx,yy) if world else (xx,yy)\n'
    '        ee,nn=forward.transform(wx,wy,errcheck=True)\n'
    "        if not np.isfinite(ee).all() or not np.isfinite(nn).all():raise ValueError('Selected UTM zone cannot cover this plot.')\n"
    "        scale=float(g.get('scale',max((x1-x0)/g['width'],(y1-y0)/g['height'])*1000))\n"
    "        if scale>100000 and self.opt('utm_small_scale'):self._warnings.append('Survey override: UTM grid shown below 1:100,000.')\n"
    "        if scale>100000 and not self.opt('utm_small_scale'):\n"
    "            self._warnings.append('UTM grid omitted below 1:100,000 per IHO S-4 B-215. Enable the survey override to show it.')\n"
    '            return\n'
    "        if self.opt('utm_spacing').startswith('Automatic'):\n"
    "            ground_per_mm=max((max(ee)-min(ee))/g['width'],(max(nn)-min(nn))/g['height'])\n"
    '            if primary:\n'
    '                target=ground_per_mm*100\n'
    '                quantum=10**math.floor(math.log10(max(target,1)))/2\n'
    '                step=max(1,round(target/quantum)*quantum)\n'
    '            else:step=max(1000,math.ceil(ground_per_mm*25/1000)*1000)\n'
    '        else:\n'
    "            step=float(self.opt('utm_interval'))\n"
    "            if not primary and step%1000:self._warnings.append('Manual UTM interval is not a 1000 m multiple; this is a survey-plan override of B-215.2.')\n"
    '        boundary=box(x0,y0,x1,y1)\n'
    '        emin,emax,nmin,nmax=min(ee),max(ee),min(nn),max(nn)\n'
    '        eastings=np.arange(math.ceil(emin/step)*step,emax+step*.000001,step)\n'
    '        northings=np.arange(math.ceil(nmin/step)*step,nmax+step*.000001,step)\n'
    "        if len(eastings)+len(northings)>1000:raise ValueError('UTM graduations are too dense; increase the metre interval.')\n"
    "        selection=self.opt('sides') if self.opt('utm_sides')=='Same as geographic' else self.opt('utm_sides')\n"
    "        sides={'All four':{0,1,2,3},'Bottom and left':{0,2},'Top and right':{1,3},'None':set(),'None (small plans only)':set()}[selection]\n"
    "        colour='black' if primary or self.opt('utm_colour')!='Magenta' else '#8f005d'\n"
    "        length=self.opt('utm_tick_mm');linewidth=self.opt('utm_tick_lw')*72/25.4\n"
    "        offset=max(self.opt('utm_offset_mm'),6.4+(self.opt('geo_font_pt')+self.opt('utm_font_pt'))*.352778/2+self.opt('dual_gap_mm'))\n"
    '        self._warnings.append(f\'UTM {zone}{"S" if self.opt("utm_hemisphere")=="South" else "N"}: {step:g} m ticks, {self.opt("utm_font_pt"):g} pt labels.\')\n'
    '        primary_labels={side:[] for side in sides}\n'
    '        for east,values in ((True,eastings),(False,northings)):\n'
    '            for value in values:\n'
    '                e=np.full(200,value) if east else np.linspace(emin-step,emax+step,200)\n'
    '                n=np.linspace(nmin-step,nmax+step,200) if east else np.full(200,value)\n'
    '                px,py=inverse.transform(e,n,errcheck=True)\n'
    '                if local:px,py=local(px,py)\n'
    '                line=LineString(np.column_stack((px,py))).intersection(boundary)\n'
    "                parts=[line] if line.geom_type=='LineString' else list(getattr(line,'geoms',()))\n"
    '                for part in parts:\n'
    "                    if part.geom_type!='LineString' or part.is_empty:continue\n"
    '                    coords=np.asarray(part.coords)\n'
    "                    if self.opt('utm_display')=='Full grid':\n"
    "                        artists=ax.plot(coords[:,0],coords[:,1],color=colour,lw=self.opt('utm_grid_lw')*72/25.4,zorder=1,clip_on=True)\n"
    "                        for artist in artists:artist.set_gid('utm-grid-line')\n"
    '                    for px,py in (coords[0],coords[-1]):\n'
    "                        distances=[abs(px-x0)/g['ux'],abs(px-x1)/g['ux'],abs(py-y0)/g['uy'],abs(py-y1)/g['uy']]\n"
    '                        side=int(np.argmin(distances))\n'
    '                        if side not in sides or distances[side]>.01:continue\n'
    '                        dx,dy=[(-1,0),(1,0),(0,-1),(0,1)][side]\n'
    "                        ax.plot([px,px+dx*length*g['ux']],[py,py+dy*length*g['uy']],color=colour,lw=linewidth,clip_on=False)\n"
    "                        along=(px-x0)/g['ux'] if side>=2 else (py-y0)/g['uy']\n"
    "                        span=g['width'] if side>=2 else g['height']\n"
